insert into public.sources (id, slug, name, kind, base_url, note, is_builtin, is_default, is_active, sort_order) values
  ('33333333-3333-4333-8333-000000000001', 'turath', 'موقع تراث', 'turath', 'https://app.turath.io', 'المكتبة الشاملة للتراث الإسلامي — المصدر الافتراضي للتطبيق.', true, true, true, 1),
  ('33333333-3333-4333-8333-000000000002', 'shamela', 'المكتبة الشاملة', 'external', 'https://shamela.ws', 'أصلُ نصوص «تراث» بالمُعرّفات والترقيم نفسها — تُحصد منها كتب السِّيَر وكتب ابن القيم.', true, false, true, 2)
insert into public.scholars (id, slug, name, full_name, era, death_year_hijri, bio, is_active, sort_order) values
  ('11111111-1111-4111-8111-111111111101', 'ibn-al-qayyim', 'ابن القيم', 'محمد بن أبي بكر بن أيوب، شمس الدين ابن قيّم الجوزية', 'القرن الثامن الهجري', 751, 'فقيه ومحدّث وأصولي، من كبار تلاميذ شيخ الإسلام ابن تيمية. اشتهرت كتبه في تزكية النفوس وأعمال القلوب، مثل: مدارج السالكين، وإغاثة اللهفان، وزاد المعاد، والفوائد.', true, 1),
  ('cae5d7ad-e2f6-4932-a98f-27279ca769f6', 'al-dhahabi', 'الذهبي', 'شمس الدين محمد بن أحمد بن عثمان الذهبي', 'القرن الثامن الهجري', 748, 'حافظ الإسلام ومؤرّخه، صاحب «سير أعلام النبلاء» و«تاريخ الإسلام».', true, 2),
  ('256ccd74-6eaf-442a-817a-71fd737f7fad', 'ibn-al-jawzi', 'ابن الجوزي', 'جمال الدين أبو الفرج عبد الرحمن بن علي بن محمد الجوزي', 'القرن السادس الهجري', 597, 'واعظٌ ومؤرّخ ومفسّر، من أكثر العلماء تصنيفاً، وصاحب «صفة الصفوة» و«صيد الخاطر».', true, 3),
  ('491399a5-8258-48a1-9160-100948dba640', 'abu-nuaym', 'أبو نعيم الأصبهاني', 'أحمد بن عبد الله بن أحمد الأصبهاني', 'القرن الخامس الهجري', 430, 'حافظٌ ومحدّث، صاحب «حلية الأولياء وطبقات الأصفياء» في أخبار الزهّاد والعُبّاد.', true, 4)
insert into public.quotes (id, scholar_id, source_id, genre, text, book, volume, page, tags, needs_reference_check, status) values
  ('22222222-2222-4222-8222-000000000001', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'القلب يمرض كما يمرض البدن، وشفاؤه في التوبة والحِمية، ويصدأ كما تصدأ المرآة، وجلاؤه بالذكر، ويَعرى كما يعرى الجسم، وزينته التقوى، ويجوع ويظمأ كما يجوع البدن، وطعامه وشرابه: المعرفة والمحبة والتوكل والإنابة والخدمة.', 'الفوائد', 1, 143, array['القلب', 'التزكية']::text[], false, 'published'),
  ('22222222-2222-4222-8222-000000000002', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'من عرف نفسه اشتغل بإصلاحها عن عيوب الناس.', 'الفوائد', 1, 80, array['محاسبة النفس']::text[], false, 'published'),
  ('22222222-2222-4222-8222-000000000003', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'إضاعة الوقت أشد من الموت؛ لأن إضاعة الوقت تقطعك عن الله والدار الآخرة، والموت يقطعك عن الدنيا وأهلها.', 'الفوائد', 1, 44, array['الوقت']::text[], false, 'published'),
  ('22222222-2222-4222-8222-000000000004', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'ما ضُرب عبدٌ بعقوبةٍ أعظمَ من قسوة القلب.', 'الفوائد', 1, 142, array['القلب']::text[], false, 'published'),
  ('22222222-2222-4222-8222-000000000006', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'العلم نورٌ يقذفه الله في القلب، والمعصية تُطفئ ذلك النور.', 'الجواب الكافي', 1, 132, array['العلم', 'المعاصي']::text[], false, 'published'),
  ('22222222-2222-4222-8222-000000000007', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'الدعاء من أنفع الأدوية، وهو عدو البلاء؛ يدافعه ويعالجه، ويمنع نزوله، ويرفعه أو يخففه إذا نزل.', 'الجواب الكافي', 1, 11, array['الدعاء']::text[], false, 'published'),
  ('22222222-2222-4222-8222-000000000010', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'التوكل نصف الدين، والنصف الثاني: الإنابة؛ فإن الدين استعانةٌ وعبادة.', 'مدارج السالكين', 2, 383, array['التوكل']::text[], false, 'published'),
  ('22222222-2222-4222-8222-000000000011', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'العارف لا يرى له على أحدٍ حقاً، ولا يشهد له على غيره فضلاً؛ ولذلك لا يُعاتب ولا يُطالب.', 'مدارج السالكين', 2, 198, array['الأخلاق']::text[], false, 'published'),
  ('22222222-2222-4222-8222-000000000012', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'جعل الله سبحانه الصبر جواداً لا يكبو، وصارماً لا ينبو، وجنداً غالباً لا يُهزم، وحصناً حصيناً لا يُهدم ولا يُثلم.', 'عدة الصابرين', 1, 5, array['الصبر']::text[], false, 'published'),
  ('22222222-2222-4222-8222-000000000013', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'وهذا التفاوتُ العظيمُ إنما حصلَ بالعلم وثمرته، ولو لم يكن في العلم إلا القُربُ من ربِّ العالمين، والالتحاقُ بعالَم الملائكة، وصحبةُ الملأ الأعلى؛ لكفى به فضلًا وشرفًا، فكيف وعزُّ الدُّنيا والآخرة منوطٌ به ومشروطٌ بحصوله؟', 'مفتاح دار السعادة', 1, 286, array['العلم']::text[], false, 'published'),
  ('22222222-2222-4222-8222-000000000017', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'الشكر: ظهور أثر نعمة الله على لسان عبده ثناءً واعترافاً، وعلى قلبه شهوداً ومحبة، وعلى جوارحه انقياداً وطاعة.', 'مدارج السالكين', 2, 589, array['الشكر']::text[], false, 'published'),
  ('22222222-2222-4222-8222-000000000018', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'من أراد صفاءَ قلبه فليُؤْثِر الله على شهوته.', 'الفوائد', 1, 142, array['القلب', 'المجاهدة']::text[], false, 'published'),
  ('22222222-2222-4222-8222-000000000019', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'أصل كل خير أن تعلم أن ما شاء الله كان، وما لم يشأ لم يكن.', 'الفوائد', 1, 141, array['التوحيد', 'القدر']::text[], false, 'published'),
  ('62937440-eff1-4503-aeaf-7b8f4d3d819b', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'للعبد سترٌ بينه وبين الله وسترٌ بينه وبين الناس؛ فمن هتك الستر الذي بينه وبين الله؛ هتك الله الستر الذي بينه وبين الناس.', 'الفوائد', 1, 44, '{}', false, 'published'),
  ('f003b3b9-671d-4c5a-84d8-864ade511667', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'للعبد ربٌّ هو ملاقيه وبيتٌ هو ساكنُهُ؛ فينبغي له أن يسترضيَ ربَّه قبل لقائه، ويعمُرَ بيته قبل انتقالِهِ إليه.', 'الفوائد', 1, 44, '{}', false, 'published'),
  ('7d2e483e-4df9-47af-9236-17701afd196c', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'الدُّنيا من أولها إلى آخرها لا تُساوي غمَّ ساعة؛ فكيف بغمِّ العُمر؟!', 'الفوائد', 1, 44, '{}', false, 'published'),
  ('06d6fbf2-ea4f-418a-8857-37046ec881d9', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'أعظم الرِّبْح في الدُّنيا أن تشتغل نفسك كلَّ وقتٍ بما هو أولى بها وأنفعُ لها في معادها.', 'الفوائد', 1, 45, '{}', false, 'published'),
  ('9e835cdc-0f64-4be5-810e-be1088227a25', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'يخرُجُ العارفُ من الدُّنيا ولم يقضِ وَطَرهُ من شيئين: بكاؤُهُ على نفسه، وثناؤُهُ على ربِّه.', 'الفوائد', 1, 45, '{}', false, 'published'),
  ('227ec8df-a57e-4ad8-bae6-84705d597b36', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'المخلوق إذا خِفتَه؛ استوحشتَ منه وهربتَ منه، والربُّ تعالى إذا خِفتَه؛ أنستَ به وقَرُبتَ إليه.', 'الفوائد', 1, 45, '{}', false, 'published'),
  ('01789a37-edaa-4df2-8cba-8497d15f26ef', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'لو نفع العلم بلا عمل؛ لما ذمَّ الله سبحانه أحبار أهل الكتاب، ولو نفع العمل بلا إخلاص؛ لما ذمَّ المنافقين.', 'الفوائد', 1, 45, '{}', false, 'published'),
  ('ac2d5132-687b-434d-b2ab-97e4290c0b72', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'دافع الخطرةَ؛ فإن لم تفعل صارت فكرةً؛ فدافع الفكرة؛ فإن لم تفعل صارت شهوةً؛ فحارِبْها؛ فإن لم تفعل صارت عزيمة وهمَّةً؛ فإن لم تُدافعها صارت فعلًا؛ فإن لم تتداركهُ بضدِّه صار عادةً، فيصعُبُ عليك الانتقالُ عنها.', 'الفوائد', 1, 45, '{}', false, 'published'),
  ('5566f384-fb4d-4879-a934-dc8fea5c6d0a', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'لمَّا طلب آدمُ الخلود في الجنة من جانب الشجرة؛ عُوقِب بالخُروج منها، ولما طلب يوسفُ الخروج من السجن من جهة صاحب الرُّؤيا؛ لبث فيه بضع سنين.', 'الفوائد', 1, 46, '{}', false, 'published'),
  ('6e928cb1-2663-4276-bb44-7ea1d2cfd10f', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'من عظُمَ وَقارُ الله في قلبهِ أن يعصيَهُ؛ وَقَّرَهُ الله في قلوب الخلق أن يُذِلُّوه.', 'الفوائد', 1, 49, '{}', false, 'published'),
  ('99a6a126-a313-4738-886a-f3d58c745a18', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'أرضُ الفطرة رحبةٌ قابلةٌ لما يُغرسُ فيها؛ فإن غُرِستْ شجرةُ الإيمان والتَّقْوى أورثتْ حلاوةَ الأبد، وإن غرِستْ شجرة الجهل والهوى فكلُّ الثَّمَرِ مُرٌّ.', 'الفوائد', 1, 50, '{}', false, 'published'),
  ('0650d23a-0e8a-472f-b504-b2957594c509', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'مثالُ تولُّدِ الطاعات ونُموِّها وتزايُدِها؛ كمثل نواةٍ غرستَها، فصارت شجرةً، ثم أثمرتْ، فأكلتَ ثمرها، وغَرستَ نواها، فكلَّما أثمر منها شيءٌ جَنيتَ ثمرَهُ، وغَرستَ نواهُ، وكذلك تَداعِي المعاصي. فليتدَبَّرِ اللبيبُ هذا المثال؛ فمن ثواب الحسنةِ الحسنةُ بعدها، ومن عقوبة السيئةِ السيئةُ بعدها.', 'الفوائد', 1, 50, '{}', false, 'published'),
  ('dfb9d654-5f7e-420b-9ccc-47cbcd3eea4f', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'ليس العجبُ من مملوكٍ يتذلَّلُ لله ويتعبَّدُ له ولا يملُّ من خِدْمَتِهِ مع حاجتِهِ وفقرِهِ إليه، إنَّما العجبُ من مالكٍ يتحبَّبُ إلى مملوكِهِ بصنوفِ إنعامِهِ ويتودَّدُ إليه بأنواع إحسانِهِ مع غِناهُ عنهُ.', 'الفوائد', 1, 50, '{}', false, 'published'),
  ('7ea85f92-1750-41bd-b94d-21520dbf8631', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'فرح إبليسُ بنزول آدمَ من الجنة، وما علم أنَّ هبوط الغائص في اللُّجَّة خلف الدُّرِّ صعودٌ.', 'الفوائد', 1, 51, '{}', false, 'published'),
  ('8a768812-2f58-4505-9697-0b8f707aa73f', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'يا آدم! كنت تدخلُ عليَّ دخولَ الملوك على الملوك، واليوم تدخل عليَّ دخولَ العبيد على الملوك.', 'الفوائد', 1, 51, '{}', false, 'published'),
  ('ff08d23f-8163-4ff7-9ba3-de919affd7c2', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'بحرُ الهوى إذا مَدَّ أغرق، وأخوفُ المَنافذِ على السابح فتحُ البصر في الماء.', 'الفوائد', 1, 55, '{}', false, 'published'),
  ('214587e0-00f6-4950-a785-dfd8b8e5ff06', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'لا بدَّ من سِنَةِ الغفلة ورُقادِ الهوى، ولكن كُنْ خفيفَ النوم؛ فحُرَّاسُ البلد يصيحون: دنا الصباحُ!', 'الفوائد', 1, 55, '{}', false, 'published'),
  ('987e3288-c117-4b86-80a0-54c35d6a6de1', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'نورُ العقل يُضيء في ليل الهوى، فتلُوحُ جادَّةُ الصواب، فيتلمَّحُ البصيرُ في ذلك النور عواقبَ الأمور.', 'الفوائد', 1, 56, '{}', false, 'published'),
  ('2855cf18-bb1b-42ce-97a1-127c971c70b4', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'اخرُجْ بالعزم من هذا الفِنَاء الضَّيِّق المحشُوِّ بالآفات إلى ذلك الفِنَاء الرَّحبِ الذي فيه ما لا عينٌ رأتْ؛ فهناك لا يتعذَّرُ مطلوبٌ ولا يُفْقَدُ محبوبٌ.', 'الفوائد', 1, 56, '{}', false, 'published'),
  ('a572612b-b337-482e-8e59-5c3254b686e5', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'الحربُ قائمةٌ، وأنت أعزلُ في النظَّارةِ؛ فإن حرَّكْتَ رِكابَكَ فللهزيمةِ.', 'الفوائد', 1, 57, '{}', false, 'published'),
  ('0b7fca0f-02ad-413e-9332-86594f0f2b39', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'يا مُكَرَّمًا بحُلَّةِ الإيمانِ بعد حُلَّة العافية وهو يُخْلِقُهُما في مخالفة الخالق! لا تُنْكِرِ السَّلْبَ؛ يَستحقُّ من استعمل نعمةَ المنعِم فيما يكرهُ أن يُسْلَبَها.', 'الفوائد', 1, 57, '{}', false, 'published'),
  ('5920ec35-66d5-4f9b-b278-7e879ed95448', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'كواكِبُ هِمَم العارفين في بُروجِ عَزائمِهِم سيارةٌ ليس فيها زُحَلٌ.', 'الفوائد', 1, 57, '{}', false, 'published'),
  ('6b1bdc16-12f2-42a6-afec-680ebd9b377d', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'يا مَنِ انحرفَ عن جادَّتِهِم! كنْ في أواخرِ الركب، ونَمْ إذا نِمتَ على الطريق؛ فالأميرُ يُراعِي السَّاقَةَ.', 'الفوائد', 1, 58, '{}', false, 'published'),
  ('5a912da3-755b-4be9-9cf8-d57e004e83ee', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'سبَقَ العلمُ بنبوَّةِ موسى وإيمانِ آسية، فَسِيقَ تابوتُهُ إلى بيتها، فجاء طفلٌ منفردٌ عن أمٍّ، إلى امرأةٍ خاليةٍ عن ولدٍ! فللهِ كم في هذه القصة من عبرةٍ! كم ذَبَحَ فرعونُ في طلب موسى من ولدٍ، ولسانُ القَدَرِ يقولُ: لا نُربِّيهِ إلّا في حِجْرِكَ!!', 'الفوائد', 1, 59, '{}', false, 'published'),
  ('c14745ff-f762-4125-baf0-0a579f7e0313', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'رأى بعضُ الحكماءِ بِرْذَوْنًا يُسْقَى عليه، فقال: لو هَمْلَجَ هذا لَرُكِبَ.', 'الفوائد', 1, 60, '{}', false, 'published'),
  ('99cc006d-f73d-43e2-a10b-91d985e6589f', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'القواطعُ مِحَنٌ يتبيَّنُ بها الصادقُ من الكاذبِ؛ فإذا خُضْتَها انقلبتْ أعوانًا لك توصِلُك إلى المقصودِ.', 'الفوائد', 1, 60, '{}', false, 'published'),
  ('a441449f-99ba-4921-ad92-e5bfe0c12088', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'لما رأى المتيقِّظون سطوةَ الدُّنيا بأهلها، وخداعَ الأملِ لأربابهِ، وتملُّك الشيطانِ قيادَ النُّفوس، ورأوا الدولة للنفس الأمَّارةِ؛ لجأوَا إلى حصنِ التضرُّع والالتجاءِ؛ كما يأوي العبدُ المذعورُ إلى حَرَمِ سيِّدِهِ.', 'الفوائد', 1, 63, '{}', false, 'published'),
  ('542f5a27-2a62-40f0-9b5f-d2d25fc46343', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'شهواتُ الدُّنيا كلُعَبِ الخيال، ونظرُ الجاهل مقصورٌ على الظاهر، فأمَّا ذو العقل فيرى ما وراء السِّتْرِ.', 'الفوائد', 1, 64, '{}', false, 'published'),
  ('f76423aa-e4ab-42cf-9ea3-be6eb5316cc6', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'تلمَّحَ القومُ الوجودَ، ففهِموا المقصودَ، فأجمعوا الرحيلَ قبل الرحيل، وشمَّروا للسيرِ في سواءِ السبيل؛ فالناسُ مشتغلون بالفضلاتِ، وهم في قطع الفلواتِ، وعصافيرُ الهوى في وَثاقِ الشبكةِ ينتظرونَ الذبحَ.', 'الفوائد', 1, 64, '{}', false, 'published'),
  ('25ab249d-8999-4848-8e15-e62152d79b65', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'تالله ما كانتِ الأيامُ إلا منامًا؛ فاستيقظوا وقد حصلوا على الظَّفَرِ.', 'الفوائد', 1, 64, '{}', false, 'published'),
  ('40e421c4-5c2f-4cc9-9cb7-a5226824b555', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'ما مضى من الدُّنيا أحلامٌ، وما بقي منها أمانيُّ، والوقتُ ضائعٌ بينَهما.', 'الفوائد', 1, 64, '{}', false, 'published'),
  ('0467d8c8-07d6-4a1c-b509-8fad2c4d027f', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'العملُ بغير إخلاص ولا اقتداءٍ كالمسافر يَملأُ جرابَهُ رملًا يُثْقِلُهُ ولا ينفعُهُ.', 'الفوائد', 1, 66, '{}', false, 'published'),
  ('23a9cc20-239f-47e9-ac9b-c0d88dc93856', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'إذا حملتَ على القلب همومَ الدُّنيا وأثقالهَا، وتهاونتَ بأورادِهِ التي هي قُوتُهُ وحياتُهُ؛ كنتَ كالمسافر الذي يُحمِّلُ دابَّتَهُ فوق طاقتِها، ولا يُوفيها علفَها؛ فما أسرع ما تَقِفُ به!', 'الفوائد', 1, 66, '{}', false, 'published'),
  ('3e0666b9-9eca-4ff6-b814-bfc2fb29ad47', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'الغايةُ: أولٌ في التقديرِ، آخرٌ في الوجودِ، مَبدأٌ في نظرِ العقلِ، منتهًى في منازل الوصول.', 'الفوائد', 1, 67, '{}', false, 'published'),
  ('55b05e3f-34a7-4a59-b638-bfb34fbd9d62', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'ألِفْتَ عَجْزَ العادةِ؛ فلو عَلَتْ بك هِمَّتكَ رُبا المعالي؛ لاحتْ لك أنوارُ العزائم.', 'الفوائد', 1, 67, '{}', false, 'published'),
  ('ca2cf00b-662a-49d8-8087-b7b797488731', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'بينَك وبين الفائزينَ جبلُ الهوى، نزلوا بين يديهِ ونزلْتَ خَلْفَهُ؛ فاطْوِ فَضْلَ منزل تَلْحَقْ بالقوم.', 'الفوائد', 1, 67, '{}', false, 'published'),
  ('8c4a1861-60e7-444e-a54e-ac4489d3a0c5', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'قوةُ الطَّمع في بلوغ الأمل تُوجبُ الاجتهادَ في الطلبِ وشدةَ الحَذَرِ من فَوْتِ المأمول.', 'الفوائد', 1, 68, '{}', false, 'published'),
  ('b53aa7d5-7f7d-4346-9981-045ec2b319ca', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'لا تسألْ سوى مولاكَ؛ فسؤالُ العبدِ غيرَ سيِّدِهِ تشنيعٌ عليه.', 'الفوائد', 1, 68, '{}', false, 'published'),
  ('f01471e0-df1f-4ebd-965e-bff6c6a40803', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'عزلةُ الجاهل فسادٌ، وأما عزلةُ العالِم فَمَعَها حِذاؤُها وسِقاؤُها.', 'الفوائد', 1, 68, '{}', false, 'published'),
  ('676513dc-80ef-4f0e-b2f4-ed02a44e9155', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'إذا خَرَجَتْ مِن فِي عَدُوِّكَ لفظةُ سَفَهٍ فلا تُلْحِقْها بمِثْلِها؛ تُلَقِّحْها، ونَسْلُ الخصام نَسْلٌ مذمومٌ.', 'الفوائد', 1, 68, '{}', false, 'published'),
  ('bdcf0890-e3e7-42d4-91f0-4dcae27ba2c1', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'إذا اقْتَدَحَتْ نارُ الانتقام من نارِ الغَضَبِ؛ ابْتَدَأتْ بإحراقِ القادح.', 'الفوائد', 1, 69, '{}', false, 'published'),
  ('c006b636-a142-436b-9bdf-1d79a4b580ed', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'أوْثِقْ غضبَكَ بسلسلة الحِلْم؛ فإنَّه كلبٌ؛ إنْ أَفْلَتَ أَتلفَ.', 'الفوائد', 1, 69, '{}', false, 'published'),
  ('1d674dca-2701-46af-b798-0ea20ce8755e', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'إذا طَلَعَ نجمُ الهِمَّةِ في ظلام ليل البَطالةِ، ورَدِفَهُ قمرُ العزيمةِ؛ أشرقتْ أرضُ القلبِ بنورِ ربِّها.', 'الفوائد', 1, 69, '{}', false, 'published'),
  ('efd6ce93-8ccd-4380-9812-559cd5ae555d', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'إذا جَنَّ الليلُ تغالبَ النومُ والسهرُ؛ فالخوفُ والشوقُ في مقدَّم عسكرِ اليَقَظَةِ، والكسلُ والتَّواني في كتيبةِ الغفلةِ؛ فإذا حَمَلَ العزمُ حَمَلَ على الميمنةِ، فانهزمتْ جنود التفريطِ؛ فما يَطْلُعُ الفجرُ؛ إلا وقد قُسِمَتِ السُّهْمانُ وبَرَدَتِ الغنيمةُ لأهلِها.', 'الفوائد', 1, 69, '{}', false, 'published'),
  ('3d401b56-c4d6-48fb-9069-179a73139f7f', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'الأرواحُ في الأشباح كالأطيار في الأبراج، وليسَ ما أُعِدَّ للاستفراخ كمن هُيِّئَ للسِّباق.', 'الفوائد', 1, 70, '{}', false, 'published'),
  ('f8d6fe30-94c0-4e50-a017-b9791e2ba1e5', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'من أراد من العمَّالِ أن يَعرِفَ قدرَه عند السلطان فلينظر ماذا يُوليهِ مِن العمل؟ وبأيِّ شُغْلٍ يَشْغَلُهُ؟', 'الفوائد', 1, 70, '{}', false, 'published'),
  ('a7929f85-fe0c-400e-b0b4-c0e042e87386', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'كنْ من أبناءِ الآخرةِ، ولا تكُنْ من أبناءِ الدُّنيا؛ فإنَّ الولد يَتْبَعُ الأمَّ.', 'الفوائد', 1, 70, '{}', false, 'published'),
  ('1b7b3492-663f-4be2-abcd-963f877cb7b7', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'الدُّنيا مجازٌ، والآخرةُ وطنٌ، والأوطارُ إنَّما تُطلَبُ في الأوطان.', 'الفوائد', 1, 71, '{}', false, 'published'),
  ('76bd746b-fafc-43d2-87da-2dcf8646f1e1', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'لا بدَّ أن تَجْذِبَكَ الجواذبُ؛ فاعْرِفْها وكنْ منها على حذرٍ، ولا تَضُرَّكَ الشواغلُ إذا خَلَوْتَ منها وأنتَ فيها.', 'الفوائد', 1, 77, '{}', false, 'published'),
  ('c251bfb5-be04-4ce6-b195-11331a772ec9', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'نورُ الحقِّ أضوأُ من الشمس، فيَحِقُّ لخفافيشِ البصائرِ أن تَعْشَى عنه.', 'الفوائد', 1, 77, '{}', false, 'published'),
  ('6f2a435d-174b-4d92-a14f-aac4498323e9', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'أنفعُ العمل أنْ تغيبَ فيه عن الناس بالإخلاص، وعن نفسك بشهود المِنَّة؛ فلا ترى فيه نفسك ولا ترى الخلق.', 'الفوائد', 1, 80, '{}', false, 'published'),
  ('2c2bc46d-33e3-4aae-906a-4d68207e3e1c', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'دخل الناسُ النارَ من ثلاثة أبوابٍ: باب شبهةٍ أورثتْ شكًّا في دين الله، وباب شهوةٍ أورثتْ تقديمَ الهوى على طاعتِه ومرضاتِه وباب غضبٍ أورثت العدوان على خلقه.', 'الفوائد', 1, 80, '{}', false, 'published'),
  ('5882ee06-3778-4217-be27-beb999430ac5', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'أصولُ الخطايا كلِّها ثلاثةٌ: الكبْرُ: وهو الذي أصار إبليسَ إلى ما أصارهُ، والحِرْصُ: وهو الذي أخرج آدم من الجنَّة، والحسدُ: وهو الذي جَرَّأ أحدَ ابنَي آدمَ على أخيهِ؛ فمنْ وُقِي شَرَّ هذه الثلاثة فقد وُقِيَ الشَّرَّ؛ فالكفرُ من الكِبر، والمعاصي من الحِرْص، والبَغْيُ والظُّلْمُ من الحسد.', 'الفوائد', 1, 80, '{}', false, 'published'),
  ('61192f34-baeb-434a-97c7-b9ee81f8d81d', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'أخسرُ الناسِ صفقةً من اشْتَغَلَ عن الله بنفسِهِ، بل أخسرُ منه من اشْتَغَلَ عن نفسِهِ بالناس.', 'الفوائد', 1, 81, '{}', false, 'published'),
  ('91611368-35fd-46b8-b775-20efb7d49424', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'وأعلى الهِمَم في باب الإرادة أنْ تكونَ الهِمَّةُ متعلقةً بمحبة الله والوقوفِ مع مرادِهِ الدينيِّ الأمريِّ، وأسفلُها أن تكون الهمَّةُ واقفةً مع مرادِ صاحِبها من الله؛ فهو إنما يعبدُهُ لمُرادِهِ منه لا لمرادِ الله منه؛ فالأولُ يريدُ اللهَ ويريدُ مرادَهُ، والثاني يريدُ من الله وهو فارغٌ عن إرادتِهِ.', 'الفوائد', 1, 85, '{}', false, 'published'),
  ('8da45ebf-82c6-433a-87d2-e695c4bd7d9d', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'علماءُ السَّوْءِ جلسوا على بابِ الجنَّةِ يدعونَ إليها الناسَ بأقوالِهِم ويَدْعونَهُم إلى النار بأفعالِهِم؛ فكلَّما قَالتْ أقوالُهُم للناس: هَلُمُّوا! قالتْ أفعالُهُم: لا تَسْمَعوا منهم! فلو كان ما دَعَوْا إليه حقًّا كانوا أولَ المستجيبين له! فهم في الصورة أدِلَّاءُ وفي الحقيقةِ قُطَّاعُ الطريق.', 'الفوائد', 1, 85, '{}', false, 'published'),
  ('d00b8827-e11b-4761-88fb-cd5c913b9833', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'من أحدث قبْلَ السلام بطلَ ما مضى من صلاتِهِ، ومَنْ أفطر قبل غروب الشمس ذهب صيامُهُ ضائعًا، ومن أساءَ في آخر عُمُرِهِ لَقِيَ ربَّه بذلك الوجه.', 'الفوائد', 1, 88, '{}', false, 'published'),
  ('ed2634db-6d12-48ab-81ff-04ffc75a9a91', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'كم جاءَ الثوابُ يَسعَى إليك، فوقف بالبابِ، فردَّه بوَّابُ (سوفَ) و(لعلَّ) و(عسى).', 'الفوائد', 1, 88, '{}', false, 'published'),
  ('04384d1c-9f29-4fad-9a93-32ec79a7d0ab', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'يا مُعَرْقلًا في شَرَكِ الهوى جَمْزةُ عزمٍ وقد خرقت الشبكةَ.', 'الفوائد', 1, 95, '{}', false, 'published'),
  ('37c6995f-7e15-4a77-8b2a-d4d7fb6eaa78', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'لله ملك السماوات والأرض؛ واستقرضَ منك حبَّةً، فبَخِلْتَ بها! وخلقَ سبعة أبحُرٍ، وأحبَّ منك دمعةً، فقَحطَتْ عينُك بها!', 'الفوائد', 1, 95, '{}', false, 'published'),
  ('73fd0ce5-6c51-4251-8380-3b06c17ba6ef', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'إطلاقُ البصر يَنقُشُ في القلب صورةَ المنظور، والقلبُ كعبةٌ، والمعبودُ لا يرضى بمزاحمةِ الأصنام.', 'الفوائد', 1, 95, '{}', false, 'published'),
  ('4ebdb007-4780-476b-a808-170c8c0b973e', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'المعرفة بِساطٌ لا يَطأُ عليه إلا مقرَّبٌ، والمحبَّةُ نشيدٌ لا يطربُ عليه إلا مُحِبٌّ مُغْرَمٌ.', 'الفوائد', 1, 96, '{}', false, 'published'),
  ('c4a993ef-f1fd-4482-9187-c93a70fb794f', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'الحبُّ غديرٌ في صحراءَ، ليستْ عليه جادَّةٌ؛ فلهذا قلَّ وارِدُهُ.', 'الفوائد', 1, 96, '{}', false, 'published'),
  ('4d5e3485-3e68-4cd1-9d41-5975d9fe6f2a', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'ليس للعابد مستراحٌ إلا تحت شجرة طُوبى، ولا للمحبِّ قرارٌ إلَّا يومَ المزيد.', 'الفوائد', 1, 96, '{}', false, 'published'),
  ('cb8d21c5-3089-4d66-afcd-2e8daa6af349', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'تالله ما عَدا عليك العدوُّ إلَّا بعد أن تولَّى عنك الوليُّ؛ فلا تظنَّ أن الشيطان غلب، ولكن الحافظ أعرض.', 'الفوائد', 1, 97, '{}', false, 'published'),
  ('738c78f9-f828-4da8-827b-1e8214da649f', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'احذرْ بنفسِك! فما أصابك بلاءٌ قط إلَّا منها، ولا تُهادِنْها! فوالله ما أكرمَها من لم يُهِنْها، ولا أعزَّها من لم يُذِلَّها، ولا جَبَرَها من لم يَكسِرْها، ولا أراحَهَا من لم يُتْعِبْها، ولا أمَّنها من لمْ يُخوِّفها، ولا فرَّحها من لم يُحزِنْها.', 'الفوائد', 1, 97, '{}', false, 'published'),
  ('67578160-02e8-446a-b634-49bb875307e5', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'سبحان الله! ظاهرُك متجمِّلٌ بلباس التَّقوى، وباطنُك باطيةٌ لخمر الهوى، فكلَّما طيَّبتَ الثوبَ فاحتْ رائحةُ المسكِر من تحته، فتباعدَ منك الصادقون، وانحاز إليك الفاسقون.', 'الفوائد', 1, 97, '{}', false, 'published'),
  ('4dc736b9-5e2e-40e7-a275-5bc31e00508f', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'يدخُل عليك لصُّ الهوى وأنت في زاوية التعبُّد، فلا يَرى منك طردًا له، فلا يزالُ بك حتى يُخرِجك من المسجد.', 'الفوائد', 1, 97, '{}', false, 'published'),
  ('c54b10c1-6579-4da3-a93c-fa9ccaf60237', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'اجتنبْ من يُعادِي أهلَ الكتاب والسُّنَّة لئلَّا يُعْدِيك خُسرانُه.', 'الفوائد', 1, 105, '{}', false, 'published'),
  ('4283e8bb-f072-45de-a2b6-fe2e61ca6087', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'احترزْ من عدُوَّين هلك بهما أكثرُ الخلق: صادٍّ عن سبيل الله بشُبُهاتِه وزُخْرُفِ قوله، ومفتونٍ بدُنياه ورئاستِهِ.', 'الفوائد', 1, 105, '{}', false, 'published'),
  ('0cf60e77-0084-430c-9673-3343bf17ac4b', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'قد علمَ المشتري بعيبِ السِّلْعة قبل أن يشتريها فسلِّمْها ولك الأمانُ من الرد.', 'الفوائد', 1, 107, '{}', false, 'published'),
  ('fa79ba4b-433b-4227-9973-3908a3a51aa7', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'يا من هو من أرباب الخبرة! هل عرفتَ قيمةَ نفسِك؟ إنما خُلِقت الأكوانُ كلُّها لك.', 'الفوائد', 1, 109, '{}', false, 'published'),
  ('f1192fb1-18db-4fdf-8154-bdb07d8dbe79', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'متى رُمتَ طلبي فاطلُبْني عندك، واطلُبْني منك تجدْني قريبًا، ولا تطلُبْني من غيرك فأنا أقربُ إليك منه.', 'الفوائد', 1, 110, '{}', false, 'published'),
  ('cdadd060-ace0-45bb-a52f-7e8ef0e18f57', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'لو عرفتَ قدْرَ نفسِك عندنا ما أهنتَها بالمعاصي، إنما أبْعَدْنا إبليسَ إذْ لم يَسجُدْ لك وأنتَ في صُلبِ أبيك؛ فواعجبًا! كيف صالحتَهُ وتركتَنا؟!', 'الفوائد', 1, 110, '{}', false, 'published'),
  ('5ae40ec8-cbae-4520-bf63-152e41a72c2d', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'مَلَؤوا مراكبَ القلوب متاعًا لا يَنفقُ إلا على الملك، فلما هَبَّتْ رياحُ السَّحرِ أقلعتْ تلك المراكبُ، فما طلعَ الفجرُ إلَّا وهي بالمِيناء.', 'الفوائد', 1, 111, '{}', false, 'published'),
  ('87bf5498-6f04-4d17-9bc1-502d05ee6441', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'فَرَّغَ القومُ قُلوبَهم من الشواغل، فضُرِبَتْ فيها سُرادِقاتُ المحبة، فأقاموا العيونَ تَحْرُسُ تارةً وتَرُشُّ أخرى.', 'الفوائد', 1, 111, '{}', false, 'published'),
  ('4cd18bc5-ce86-4136-b57c-1896386b786f', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'هانَ سَهَرُ الحُرَّاسِ لمَّا علموا أن أصواتَهم بسَمْعِ الملك.', 'الفوائد', 1, 112, '{}', false, 'published'),
  ('11d6e603-1bf3-48e5-b95c-36747c6c09f4', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'الجنَّةُ تَرضَى منك بأداء الفرائض، والنارُ تَندفعُ عنك بتَرْكِ المعاصي، والمحبَّهُ لا تَقنَعُ منك إلا ببذل الرُّوح.', 'الفوائد', 1, 113, '{}', false, 'published'),
  ('f221971e-24d1-46fe-8ec6-d95d5458c129', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'عَلَّمْتَ كلبَك فهو يترُكُ شهوتَه في تناوُل ما صادَهُ؛ احترامًا لنعمتك، وخوفًا من سطوتك، وكم عَلَّمك معلِّمُ الشرعِ وأنتَ لا تقبلُ.', 'الفوائد', 1, 113, '{}', false, 'published'),
  ('6c92aef8-902e-4359-8203-023f06bfff64', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'حُرِّم صيدُ الجاهلِ والممسكِ لنفسه؛ فما ظنُّ الجاهلِ الذي أعمالُهُ لهوى نفسِه.', 'الفوائد', 1, 113, '{}', false, 'published'),
  ('a32c284b-b083-4d24-a059-ae22bdc47841', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'لمَّا صَادَ الكلبُ لربِّهِ أُبِيحَ صيدُهُ، ولما أمْسَكَ على نفسه حَرُمَ ما صادَهُ.', 'الفوائد', 1, 114, '{}', false, 'published'),
  ('41ca887f-6c0b-4047-9f60-a557e1049d3f', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'مصدرُ ما في العبد من الخير والشرِّ والصفاتِ الممدوحة والمذمومة من صفة المُعطِي المانع؛ فهو سبحانه يُصرِّفُ عبادَه بين مقتضى هذين الاسمين؛ فحظُّ العبدِ الصادقِ من عبوديَّتِهِ بهما الشُّكْرُ عند العطاء، والافتقارُ عند المنع؛ فهو سبحانه يُعطِيه ليشكُرهُ، ويَمنعُهُ ليفتقرَ إليه، فلا يَزالُ شكورًا فقيرًا.', 'الفوائد', 1, 114, '{}', false, 'published'),
  ('1ad3ff26-4d03-449a-bfa1-7a225e19c399', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'أصولُ المعاصي كلِّها -كبارها وصغارها- ثلاثةٌ: تعلُّقُ القلبِ بغير الله، وطاعةُ القوة الغضبيَّة، والقوة الشهوانيَّةِ. وهي: الشركُ، والظلمُ، والفواحشُ. فغايةُ التعلُّق بغير الله: الشركُ وأن يُدْعى معه إلهٌ آخرُ، وغايةُ طاعة القوَّة الغضبيَّة: القتلُ، وغايةُ طاعة القوَّةِ الشهوانيَّة: الزِّنى.', 'الفوائد', 1, 116, '{}', false, 'published'),
  ('6ea4ef34-339a-4e0b-b58e-e2f109f11865', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'قسوةُ القلب من أربعة أشياء إذا جاوزتْ قدرَ الحاجة: الأكل، والنوم، والكلام، والمخالطة.', 'الفوائد', 1, 142, '{}', false, 'published'),
  ('dc5a8947-eef3-4d1d-80bf-da8414c28ead', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'كما أن البدن إذا مرض لم ينفع فيه الطعامُ والشرابُ؛ فكذلك القلبُ إذا مرض بالشهوات لم تَنْجَعْ فيه المواعظُ.', 'الفوائد', 1, 142, '{}', false, 'published'),
  ('5251b6ff-fd7a-48ca-980e-6d27977efb54', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'القلوب المتعلقةُ بالشهوات محجوبةٌ عن الله بقدر تعلُّقها بها.', 'الفوائد', 1, 142, '{}', false, 'published'),
  ('c24301c4-a0c7-420f-8e84-20a867ebbeb5', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'القلوب آنيةُ الله في أرضه؛ فأحبُّها إليه أرقُّها وأصلبها وأصفاها.', 'الفوائد', 1, 142, '{}', false, 'published'),
  ('20694f8d-44a6-4484-aecf-234ae716a481', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'شَغلوا قلوبهم بالدُّنيا، ولو شَغلوها بالله والدار الآخرة لجالتْ في معاني كلامه وآياته المشهودة، ورَجعتْ إلى أصحابها بغرائب الحكم وطُرَفِ الفوائد.', 'الفوائد', 1, 142, '{}', false, 'published'),
  ('2321bdda-f7d3-4f03-befb-d9507f96c2eb', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'إذا غُذِيَ القلبُ بالتذكُّر، وسُقِي بالتفكُر، ونُقِّيَ من الدَّغل؛ رأى العجائبَ وأُلهِمَ الحكمةَ.', 'الفوائد', 1, 143, '{}', false, 'published'),
  ('b9f4ddc9-053a-4898-90d6-9322a16696a9', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'ليس كلُّ من تَحلَّى بالمعرفة والحكمة وانتحلها كان من أهلها، بل أهلُ المعرفة والحكمة الذين أَحيَوا قلوبَهم بقتل الهوى، وأما من قتل قلبه فأحيا الهوى؛ فالمعرفة والحكمة عاريَّةٌ على لسانه.', 'الفوائد', 1, 143, '{}', false, 'published'),
  ('84d54f96-16cb-40fb-b253-90525e0cac3d', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'خَرابُ القلبِ من الأمن والغفلة، وعِمارتُهُ من الخشية والذِّكْرِ.', 'الفوائد', 1, 143, '{}', false, 'published'),
  ('e0f526cd-b10c-4132-8160-6bdc326e3545', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'إذا زَهِدَت القلوبُ في موائد الدُّنيا؛ قعدتْ على مَوائدِ الآخرة بين أهل تلك الدعوة، وإذا رَضِيتْ بموائد الدُّنيا؛ فَاتَتْها تلك الموائدُ.', 'الفوائد', 1, 143, '{}', false, 'published'),
  ('d21e7a44-09db-4f53-9f5a-622113368ebf', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'الشوقُ إلى الله ولقائه نسيمٌ يَهُبُّ على القلب يُرَوِّحُ عنه وَهَجَ الدُّنيا.', 'الفوائد', 1, 143, '{}', false, 'published'),
  ('5a4c0be9-77be-4b30-9193-1097c7e4339c', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'من وَطَّنَ قلبَه عند ربِّه سكنَ واستراح، ومن أرسله في الناس اضطربَ واشتد به القلقُ.', 'الفوائد', 1, 143, '{}', false, 'published'),
  ('019f7376-61a2-4158-a215-0fa45b0a0cf6', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'لا تَدخلُ محبةُ الله في قلب فيه حبُّ الدُّنيا إلا كما يدخل الجملُ في سَمِّ الإبرة.', 'الفوائد', 1, 143, '{}', false, 'published'),
  ('0108ccda-6e0e-4cf8-bda2-c87ee7cd5626', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'وإذا أحبَّ الله عبدًا اصطنَعه لنفسِه، واجتباهُ لمحبَّتِهِ، واستخلصه لعبادته، فشَغلَ همَّهُ به، ولسانهُ بذكره، وجوارحَهُ بخدمته.', 'الفوائد', 1, 143, '{}', false, 'published'),
  ('e4831b82-6b21-4d49-92b6-5b19af12ff48', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'المتوكِّلُ لا يسألُ غيرَ الله، ولا يرُدُّ على الله، ولا يدَّخِرُ مع الله.', 'الفوائد', 1, 144, '{}', false, 'published'),
  ('3c54e291-2cb9-4716-bbc2-2bf42b2338aa', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'من شُغل بنفسه شُغِلَ عن غيره، ومن شُغِل بربِّه شُغِل عن نفسه.', 'الفوائد', 1, 144, '{}', false, 'published'),
  ('7a766f52-73c7-40c7-bdd5-460762830a67', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'الإخلاصُ: هو ما لا يعلمه مَلَكٌ فيكتبه، ولا عدوُّ فيُفسِدهُ، ولا يُعجَبُ به صاحبه فيُبطِله.', 'الفوائد', 1, 144, '{}', false, 'published'),
  ('c4f53e07-77e3-4781-ac50-50524a61206a', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'للقلب ستة مواطنَ يجولُ فيها لا سابعَ لها؛ ثلاثةٌ سافلة، وثلاثةٌ عاليةٌ: فالسافلةُ: دنيا تتزيَّنُ له، ونفسٌ تحدِّثُه، وعدوٌّ يوسوسُ له. فهذه مواطنُ الأرواح السافلة التي لا تزالُ تجولُ فيها. والثلاثة العاليةُ: علمٌ يتبيَّنُ له، وعقلٌ يرشدُه، وإلهٌ يعبدُه. والقلوب جوَّالةٌ في هذه المواطن.', 'الفوائد', 1, 144, '{}', false, 'published'),
  ('eceed1c8-4d7f-4a5f-9687-ddcba5e2bd68', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'لا يشمُّ عبدٌ رائحةَ الصدق و[هو] يُداهِنُ نفسَه أو يُداهِنُ غيرَه.', 'الفوائد', 1, 145, '{}', false, 'published'),
  ('d2b80da8-1f70-40a9-899f-965dd0d32ad1', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'إذا أراد الله بعبدٍ خيرًا جعله معترفًا بذنبه ممسكًا عن ذنب غيره، جوادًا بما عنده زاهدًا فيما عند غيره، محتملًا لأذى غيره. وإنْ أراد به شرًّا عكس ذلك عليه.', 'الفوائد', 1, 145, '{}', false, 'published'),
  ('e2c6e45e-5295-46e8-89e1-526829c4b767', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'الهمَّةُ العليَّةُ لا تزالُ حائمةً حول ثلاثة أشياء: تعرُّفٌ لصفةٍ من الصفات العليا تزدادُ بمعرفتها محبةً وإرادةً، وملاحظةٌ لمِنَّةٍ تزدادُ بملاحظتها شُكرًا وطاعة، وتذكُّرٌ لذنبٍ تزدادُ بتذكُّرِهِ توبةً وخشية؛ فإذا تعلَّقتِ الهمةُ بسوى هذه الثلاثة جالتْ في أودية الوساوس والخطرات.', 'الفوائد', 1, 145, '{}', false, 'published'),
  ('d437c958-a350-47d0-9ae0-b6beab3adc76', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'من عَشِقَ الدُّنيا نظرتْ إلى قدرها عنده، فصيَّرتْه من خَدَمِها وعبيدِها وأذلَّتْه. ومن أعرض عنها نظرتْ إلى كبر قدره، فخدمته وذلَّت له.', 'الفوائد', 1, 145, '{}', false, 'published'),
  ('0fae74c2-73a2-44c6-b541-f38ea054c80e', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'العقولُ المؤيَّدةُ بالتوفيق تَرى أنَّ ما جاء به الرسولُ هو الحقُّ الموافقُ للعقل والحكمة، والعقولُ المضروبة بالخِذْلانِ ترى المعارضة بين العقل والنقل وبين الحكمة والشرع.', 'الفوائد', 1, 157, '{}', false, 'published'),
  ('ae36009e-0e2c-4eec-9d02-a3e62a6eb8fb', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'أقربُ الوسائل إلى الله ملازمةُ السُّنَّة والوقوفُ معها في الظاهر والباطن، ودوامُ الافتقار إلى الله، وإرادةُ وجهه وحده بالأقوال والأفعال. وما وصلَ أحدٌ إلى الله إلَّا من هذه الثلاثة، وما انقطع عنه أحدٌ إلّا بانقطاعه عنها أو عن أحدها.', 'الفوائد', 1, 157, '{}', false, 'published'),
  ('cbdcc260-34b8-4fb6-9fe0-22205bbb3479', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'إذا استغنى الناسُ بالدُّنيا فاستغنِ أنت بالله، وإذا فرحوا بالدُّنيا فافرح أنت بالله، وإذا أَنِسُوا بأحبابهم فاجعلْ أنسَك بالله، وإذا تعرَّفوا إلى ملوكهم وكبرائهم وتقربوا إليهم لينالوا بهم العزَّ والرفعة؛ فتعرَّفْ أنت إلى الله وتودَّدْ إليه؛ تنالُ بذلك غاية العز والرفعة.', 'الفوائد', 1, 170, '{}', false, 'published'),
  ('7023a088-f29c-4c28-a694-f4ed873d195d', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'اطلبْ قلبك في ثلاثة مواطن: عند سماع القرآن، وفي مجالِس الذِّكر، وفي أوقات الخلوة؛ فإن لم تجدهُ في هذه المواطن فسَلِ الله أن يَمُنَّ عليك بقلبٍ؛ فإنه لا قلبَ لك.', 'الفوائد', 1, 218, '{}', false, 'published'),
  ('f50e7ce5-fae4-48d8-9e19-7ab9e2ae8467', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'السَّنة شجرةٌ، والشهور فروعها، والأيام أغصانها، والساعات أوراقها، والأنفاس ثمرها، فمن كانت أنفاسه في طاعته فثمرة شجرته طيبةٌ، ومن كانت في معصيةٍ فثمرته حنظلٌ، وإنما يكون الجَدَادُ يوم المعاد؛ فعند الجَدَاد يتبينُ حلو الثمار من مُرّها.', 'الفوائد', 1, 240, '{}', false, 'published'),
  ('74832c56-dbcc-4b3a-bc2c-a282955fa252', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'والإخلاص والتوحيد شجرةٌ في القلب؛ فروعها الأعمال، وثمرها طيب الحياة في الدنيا والنعيم المقيم في الآخرة، وكما أن ثمار الجنة لا مقطوعةٌ ولا ممنوعةٌ؛ فثمرة التوحيد والإخلاص في الدُّنيا كذلك.', 'الفوائد', 1, 240, '{}', false, 'published'),
  ('7cdf8662-dea3-4335-bda3-cc4d221b05b4', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'سئل سهل التستري: الرجل يأكل في اليوم أكلةً؟ قال: أكل الصديقين. قيل له: فأكلتين؟ قال: أكل المؤمنين. قيل له: فثلاث أكلاتٍ؟ فقال: قل لأهله يَبنُوا له مِعْلفًا.', 'الفوائد', 1, 261, '{}', false, 'published'),
  ('44ce5918-ef3a-49fe-b3cb-952ba315656d', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'العارف في الأرض ريحانةٌ من رياحين الجنة، إذا شمَّها المريد اشتاقتْ نفسُه إلى الجنة.', 'الفوائد', 1, 262, '{}', false, 'published'),
  ('02314136-86a9-4703-be20-ba1859c24d1b', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'لا تُبدِ فاقةً إلى غيري فأضاعفَها عليك، مكافأةً لخروجك عن حدك في عبوديتك.', 'الفوائد', 1, 285, '{}', false, 'published'),
  ('5d65464a-436f-4e12-b3fc-0e329f30d811', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'ابتليتُك بالفقر لتصير ذهبًا خالصًا؛ فلا تَزِيْفَنَّ بعد السبك.', 'الفوائد', 1, 285, '{}', false, 'published'),
  ('f986eb89-29e7-47ec-9131-1d9d2d0d4059', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'الطلب لِقاحُ الإيمان؛ فإذا اجتمع الإيمان والطلب أثمرا العملَ الصالح.', 'الفوائد', 1, 289, '{}', false, 'published'),
  ('e1784287-ae88-4eb9-a33e-2fa5594edaef', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'وحسن الظن بالله لِقاح الافتقار والاضطرار إليه؛ فإذا اجتمعا أثمرا إجابةَ الدعاء.', 'الفوائد', 1, 289, '{}', false, 'published'),
  ('60e858a4-0c74-4f52-9353-191ab1aa6b26', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'والخشية لِقاح المحبة؛ فإذا اجتمعا أثمرا امتثالَ الأوامر واجتناب المناهي.', 'الفوائد', 1, 289, '{}', false, 'published'),
  ('9b1cbbc8-4365-4561-a946-bbaa671842b9', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'وصحة الاقتداء بالرسول لِقاح الإخلاص؛ فإذا اجتمعا أثمرا قبولَ العمل والاعتداد به.', 'الفوائد', 1, 289, '{}', false, 'published'),
  ('fe22d322-1922-4614-b005-1218bf37dd56', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'والحلم لِقاح العلم؛ فإذا اجتمعا حصلتْ سيادة الدنيا والآخرة وحصل الانتفاع بعلم العالم، وإن انفرد أحدهما عن صاحبه فات النفع والانتفاع.', 'الفوائد', 1, 290, '{}', false, 'published'),
  ('14451f84-db2c-46c2-8b47-94e68cf996a8', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'والعزيمة لِقاحُ البصيرة؛ فإذا اجتمعا نال صاحبهما خيرَ الدنيا والآخرة، وبلغتْ به همتُه من العلياء كلَّ مكان؛ فتخلُّف الكمالاتِ إما من عدم البصيرة وإما من عدم العزيمة.', 'الفوائد', 1, 290, '{}', false, 'published'),
  ('4048db07-0825-4ec2-9c1a-d779a3b8faff', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'وحسن القصد لِقاحٌ لصحة الذهن؛ فإذا فُقِدا فُقِد الخيرُ كلُّه، وإذا اجتمعا أثمرا أنواع الخيرات.', 'الفوائد', 1, 290, '{}', false, 'published'),
  ('7e00d5b1-f6ea-46e4-a87e-8e6a550dff26', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'وصحة الرأي لِقاح الشجاعة؛ فإذا اجتمعا كان النصرُ والظفر، وإن فُقِدا فالخذلان والخيبة، وإن وُجد الرأي بلا شجاعة فالجبنُ والعجز، وإن حصلت الشجاعة بلا رأي؛ فالتهور والعطب.', 'الفوائد', 1, 290, '{}', false, 'published'),
  ('ff3397f7-2de6-4f8a-ba7f-e60c8a01bd54', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'والصبر لِقاح البصيرة؛ فإذا اجتمعا فالخير في اجتماعهما؛ قال الحسن: إذا شئتَ أن ترى بصيرًا لا صبرَ له رأيتَه، وإذا شئت أن ترى صابرًا لا بصيرةَ له رأيتَه، فإذا رأيتَ صابرًا بصيرًا فذاك.', 'الفوائد', 1, 290, '{}', false, 'published'),
  ('d3b8a69e-cdcd-4e6a-aa7a-f38226ffd408', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'والنصيحة لِقاح العقل، فكلما قويتِ النصيحةُ قوي العقلُ واستنار.', 'الفوائد', 1, 290, '{}', false, 'published'),
  ('935d96f9-c22c-433c-9b5c-8333f9317653', '11111111-1111-4111-8111-111111111101', '33333333-3333-4333-8333-000000000001', 'saying', 'والتذكُّر والتفكر كل منهما لِقاح الآخر، إذا اجتمعا أنتجا الزهدَ في الدنيا والرغبة في الآخرة.', 'الفوائد', 1, 290, '{}', false, 'published'),
  ('750fe8e7-f6e5-45fd-87d0-48385984e820', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان أبو الدرداء إذا كتب إلى سلمان - أو سلمان كتب إلى أبي الدرداء - كتب إليه يذكره بآية الصحفة.', 'حلية الأولياء', 1, 224, '{}', false, 'published'),
  ('62436498-c33c-4f4f-bfd4-4f71e2bfe8f9', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'فكان أبو موسى يتوخى ذلك اليوم الحار الشديد الحر الذي يكاد ينسلخ فيه الإنسان فيصومه.', 'حلية الأولياء', 1, 260, '{}', false, 'published'),
  ('ea928a4b-b0c2-4069-869a-d5cc0c7ed7d2', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان ابن عمر إذا اشتد عجبه بشيء من ماله قربه لربه ﷿.', 'حلية الأولياء', 1, 294, '{}', false, 'published'),
  ('d14a95ac-c7c5-4e37-a197-5d1b16adaa7a', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان ابن عمر إذا مر بربعهم - وقد هاجر منه - غمض عينيه ولم ينظر إليه ولم ينزله قط.', 'حلية الأولياء', 1, 303, '{}', false, 'published'),
  ('8852d4d6-c085-4c0e-96ae-a059abc97b84', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان ابن عمر كلما استيقظ من الليل صلى.', 'حلية الأولياء', 1, 304, '{}', false, 'published'),
  ('a34a3709-553b-4208-bf64-cdff86a97751', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان عبد الله بن الزبير إذا قام في الصلاة كأنه عود، وكان يقول ذلك من الخشوع في الصلاة.', 'حلية الأولياء', 1, 335, '{}', false, 'published'),
  ('eb0410df-6a2b-44ec-aad8-a033e3c1d263', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان ابن الزبير إذا صلى كأنه كعب راتب.', 'حلية الأولياء', 1, 335, '{}', false, 'published'),
  ('3c9fa184-1e79-4304-a6ce-4bd99f25ae04', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان ابن الزبير يواصل سبعة أيام ويصبح يوم السابع وهو أليثنا.', 'حلية الأولياء', 1, 335, '{}', false, 'published'),
  ('0c87f4b1-b15a-4918-92db-364f50b42914', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان الأسود يختم القرآن في رمضان في كل ليلتين، وكان ينام بين المغرب والعشاء وكان يختم القرآن في غير رمضان في كل ست ليال.', 'حلية الأولياء', 2, 103, '{}', false, 'published'),
  ('86e01a13-e6f0-43d7-a1ff-470722b7a1cd', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان الربيع بن خيثم إذا سجد كأنه ثوب مطروح، فتجئ العصافير فتقع عليه.', 'حلية الأولياء', 2, 114, '{}', false, 'published'),
  ('c741b910-6c40-4c9f-ad29-17f94df9c4c8', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان الربيع ابن خيثم لا يعطي السائل أقل من رغيف، ويقول إني لأستحي من ربي ﷿ أن أرى غدا في ميزاني نصف رغيف.', 'حلية الأولياء', 2, 116, '{}', false, 'published'),
  ('732633a0-5433-4642-aef1-4dbf3bf1d0bf', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان أبو مسلم الخولاني يكثر أن يرفع صوته بالتكبير حتى مع الصبيان، وكان يقول اذكروا الله حتى يرى الجاهل أنكم مجانين.', 'حلية الأولياء', 2, 124, '{}', false, 'published'),
  ('542ce1eb-7bce-4762-8fc6-2462925dffef', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان سعيد بن المسيب يماري غلاما له في ثلثي درهم وأتاه ابن عمه بأربعة آلاف درهم فأبى أن يأخذها.', 'حلية الأولياء', 2, 166, '{}', false, 'published'),
  ('833d6001-393b-4134-b405-c36e56eb6fb3', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان عروة بن الزبير إذا كان أيام الرطب يثلم حائطه ثم يأذن للناس فيه فيدخلون ويأكلون ويحملون.', 'حلية الأولياء', 2, 180, '{}', false, 'published'),
  ('6fbdb287-462b-44df-96fa-bb8802eee2e5', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان مطرف ابن عبد الله يبدو فاذا كان ليلة الجمعة ادلج على فرسه فربما نور له سوطه.', 'حلية الأولياء', 2, 205, '{}', false, 'published'),
  ('6a8572fb-38d7-485e-9576-1c80144968f1', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان أبو العالية إذا جلس إليه أكثر من أربعة قام.', 'حلية الأولياء', 2, 218, '{}', false, 'published'),
  ('7e971b35-096c-4a5f-9939-6c9a965476d7', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان محمد بن سيرين إذا سئل عن شيء من الفقه الحلال والحرام تغير لونه وتبدل، حتى كأنه ليس بالذي كان.', 'حلية الأولياء', 2, 264, '{}', false, 'published'),
  ('e3e7da3e-73dd-482f-9043-89a1f8859677', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان محمد بن سيرين يقول لا تكرم أخاك بما يشق عليك.', 'حلية الأولياء', 2, 264, '{}', false, 'published'),
  ('b2c9d540-265f-47ff-a4d9-46a1307a0575', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان محمد بن سيرين إذا ذكر الموت مات كل عضو منه على حدته.', 'حلية الأولياء', 2, 272, '{}', false, 'published'),
  ('7a69e63a-cc7b-4e8b-89ca-d270d02d4561', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان محمد بن سيرين يتمثل الشعر، ويذكر الشئ ويضحك، حتى إذا جاء الحديث من السنة كلح وانضم بعضه إلى بعض.', 'حلية الأولياء', 2, 274, '{}', false, 'published'),
  ('361b7e70-6baf-4640-b84e-f6eaccd8c03f', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان ابن سيرين يمازح أصحابه، ويقول مرحبا بالمدرفشين - يعني أنكم تشهدون الجنائز، وتحملون الموتى.', 'حلية الأولياء', 2, 274, '{}', false, 'published'),
  ('dfe9e1a7-0a97-446f-ba78-b3a084dfad38', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان محمد بن واسع إذا انتبه من منامه ضرب بيده إلى دبره.', 'حلية الأولياء', 2, 349, '{}', false, 'published'),
  ('d4a44e2d-2a37-4ceb-9005-706ce2b15968', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان محمد بن واسع يقول اللهم إن كان أخلق وجهي كثرة ذنوبي فهبني لمن أحببت من خلقك.', 'حلية الأولياء', 2, 353, '{}', false, 'published'),
  ('019260e7-cea2-4a74-89c9-17125489b7b2', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان مالك بن دينار يلبس إزار صوف وعباءة خفيفة فإذا كان الشتاء ففرو.', 'حلية الأولياء', 2, 368, '{}', false, 'published'),
  ('2e0d80ac-0ae9-4b28-8092-97b78b50cd0f', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان ابن عون يصوم يوما ويفطر يوما.', 'حلية الأولياء', 3, 40, '{}', false, 'published'),
  ('a946bb55-bf7e-4d24-9603-5add7e70cc40', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان الحسن يقعد مع أصحابه، فلا يقوم حتى يختم منصور بن زاذان القرآن.', 'حلية الأولياء', 3, 58, '{}', false, 'published'),
  ('1ed50513-55f2-4b12-b448-5f6e6db5015b', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان منصور بن زاذان يختم القرآن في كل يوم وليلة.', 'حلية الأولياء', 3, 58, '{}', false, 'published'),
  ('b856fef8-fd86-4662-9a4d-242df4ec7863', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان جابر بن زيد لا يماكس في كل شيء يتقرب به إلى الله ﷿.', 'حلية الأولياء', 3, 87, '{}', false, 'published'),
  ('2d6b67e4-a95e-413e-811d-1201f3b6e9c1', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان علي بن الحسين إذا فرغ من وضوئه للصلاة، وصار بين وضوئه وصلاته أخذته رعدة ونفضة.', 'حلية الأولياء', 3, 133, '{}', false, 'published'),
  ('e83e1d40-5730-45ad-addc-696b74c71294', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان علي بن الحسين لا يضرب بعيره من المدينة إلى مكة.', 'حلية الأولياء', 3, 133, '{}', false, 'published'),
  ('45b1d99e-4b51-424a-a6d4-e41c68c7317d', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان علي بن الحسين يبخل، فلما مات وجدوه يقوت مائة أهل بيت بالمدينة.', 'حلية الأولياء', 3, 136, '{}', false, 'published'),
  ('4260c7b9-5df9-4e06-810d-1b310b866d79', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان علي بن الحسين يتخطى حلق قومه حتى يأتي زيد بن أسلم فيجلس عنده.', 'حلية الأولياء', 3, 138, '{}', false, 'published'),
  ('1dafe5f5-7d5e-4879-b319-1602bd890a8a', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان سعد بن إبراهيم يصوم الدهر.', 'حلية الأولياء', 3, 169, '{}', false, 'published'),
  ('2e4f1352-92cd-4b6d-b744-996dcc608e05', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان جعفر بن محمد يطعم حتى لا يبقى لعياله شيء.', 'حلية الأولياء', 3, 194, '{}', false, 'published'),
  ('b619a8cc-6d0f-47e6-aad4-d17f39ea1f41', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان عمرو بن عتبة يصلي والسبع حوله يضرب بذنبه يحميه.', 'حلية الأولياء', 4, 157, '{}', false, 'published'),
  ('5bbb40c3-f0f2-4943-84a4-0da0229cffc9', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان عمرو بن عتبة يرعى ركاب أصحابه وغمامة تظله.', 'حلية الأولياء', 4, 157, '{}', false, 'published'),
  ('e99b6c0a-0506-4cc3-a1f8-d8d904b84d0e', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان سويد بن غفلة يؤمنا في شهر رمضان في القيام، وقد أتى عليه عشرون ومائة سنة.', 'حلية الأولياء', 4, 175, '{}', false, 'published'),
  ('39a32df5-7f57-4d06-9594-38cc63185ef0', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان سعيد بن جبير يبكي بالليل حتى عمش.', 'حلية الأولياء', 4, 272, '{}', false, 'published'),
  ('8c2e7889-3b96-4eec-a009-ebb1b7f7b1ff', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان سعيد بن جبير يؤمنا يرجع صوته بالقرآن.', 'حلية الأولياء', 4, 273, '{}', false, 'published'),
  ('1f197350-1423-468a-a88e-11608e3a82e2', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان سعيد بن جبير يختم القرآن فيما بين المغرب والعشاء في شهر رمضان.', 'حلية الأولياء', 4, 273, '{}', false, 'published'),
  ('a133c81e-f6fa-4925-9255-3ec5ab84707f', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان طلحة بن مصرف يقول في دعائه اللهم اغفر لى ريائى وسمعتي.', 'حلية الأولياء', 5, 16, '{}', false, 'published'),
  ('7e60a4c4-d33b-441b-9ad0-89f41a917915', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان عبد الرحمن بن أبي نعم يواصل خمسة عشر يوما لا يأكل ولا يشرب.', 'حلية الأولياء', 5, 69, '{}', false, 'published'),
  ('340fe6e5-a01b-4838-ab22-5fca31cef11c', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان ابن أبي نعم يحرم من السنة إلى السنة، وكان يقول فى تلبيته لبيك، لو كان رياء لاضمحل لبيك.', 'حلية الأولياء', 5, 70, '{}', false, 'published'),
  ('c03e79c3-3de7-434b-9e54-ad6beeb9807b', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان ابن أبي نعم يحرم من السنة إلى السنة، فآذاه القمل فدعا ربه ﷿، فوقعت كبة بين يديه.', 'حلية الأولياء', 5, 70, '{}', false, 'published'),
  ('52a42128-7ba3-4bb7-bbf2-641722c8cbf4', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'وكان محمد بن طارق يطوف في كل يوم وليلة سبعين أسبوعا؛ وكان كرز يختم القرآن في كل يوم وليلة ثلاث ختمات.', 'حلية الأولياء', 5, 81, '{}', false, 'published'),
  ('2ff34b75-63af-44e8-94d0-bfcf487111eb', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'وكان ابن ابجر يعالج من نفسه شدة شديدة، ولكن لا يتكلم بشيء.', 'حلية الأولياء', 5, 84, '{}', false, 'published'),
  ('0123dd13-e784-4c70-8fa0-6de4b1d730e6', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان عمرو بن قيس الملائي يقرئ الناس القرآن، فكان يجلس بين يدي رجل رجل حتى يفرغ منهم، وكان إذا مشى لا يمشي أمامهم فيقول تعالوا نمشي جميعا.', 'حلية الأولياء', 5, 102, '{}', false, 'published'),
  ('a640d273-56de-4071-948f-7c27ac2a58a3', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان عمرو بن قيس إذا بكى حول وجهه إلى الحائط، ويقول لأصحابه إن هذا زكام.', 'حلية الأولياء', 5, 103, '{}', false, 'published'),
  ('72bbe3d3-ce72-4ba9-8c82-f1f482a6c9ba', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان عبد الله بن زكريا إذا قدم فلسطين فرأى ابن محيريز صغرت إليه نفسه لما يرى من فضله.', 'حلية الأولياء', 5, 143, '{}', false, 'published'),
  ('7d4cd1c8-7f24-446c-a407-9622b8d78bd0', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان ابن محيريز يجئ إلى عبد الملك بصحيفة فيها النصيحة يقرئه ما فيها، فإذا فرغ منها أخذ الصحيفة.', 'حلية الأولياء', 5, 144, '{}', false, 'published'),
  ('ecf90ca0-5e81-474f-abf4-bdcc48465895', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان ابن محيريز إذا غزا كان أعجب النفقة إليه في علف الدواب.', 'حلية الأولياء', 5, 144, '{}', false, 'published'),
  ('e4d2d17c-9aae-4650-b1f0-8e400728d679', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان ابن عون إذا ذكر من يعجبه ذكر رجاء بن حيوة.', 'حلية الأولياء', 5, 170, '{}', false, 'published'),
  ('d85ddbd6-d9ce-431d-866e-171a2ba3445e', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان خالد ابن معدان يسبح في اليوم أربعين ألف تسبيحة، سوى ما يقرأ من القرآن، فلما مات ووضع على سريره ليغسل، جعل بإصبعه كذا يحركها - يعني بالتسبيح-.', 'حلية الأولياء', 5, 210, '{}', false, 'published'),
  ('3e3a0780-32a7-4f97-9e2d-d87aad495e98', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'وكان عمر بن عبد العزيز يجعل كل يوم درهما من خاصة ماله في طعام المسلمين ثم يأكل معهم.', 'حلية الأولياء', 5, 270, '{}', false, 'published'),
  ('f1767f33-99cb-496c-86e5-5f565f890276', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان عمر بن عبد العزيز يلبس الفرو الغليظ، وكان سراجه على ثلاث قصبات فوقهن طين.', 'حلية الأولياء', 5, 323, '{}', false, 'published'),
  ('10aa8d30-6f82-4812-b169-830c5e0b7eb2', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان عمر بن عبد العزيز يعلم العلماء.', 'حلية الأولياء', 5, 340, '{}', false, 'published'),
  ('c63d2ebf-b96f-483d-a40b-51c93a67bb2d', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان حسان بن عطية يتنحى إذا صلى العصر في ناحية المسجد فيذكر الله حتى تغيب الشمس.', 'حلية الأولياء', 6, 70, '{}', false, 'published'),
  ('041c02e3-c852-49ca-8cd7-7eb52b9a9408', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان الأوزاعي لا يكلم أحدا بعد صلاة الفجر حتى يذكر الله، فإن كلمه أحد أجابه.', 'حلية الأولياء', 6, 143, '{}', false, 'published'),
  ('0d8e4f77-f639-49d2-8321-1e3bd0cde55a', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'وكان بشر بن منصور يستحب أن يصلي بالأوقات ولا يتحرى.', 'حلية الأولياء', 6, 239, '{}', false, 'published'),
  ('2d5cc963-af9f-4b12-ac68-d524993ff6b0', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان ابن مسعود يقرأ القرآن من الجمعة إلى الجمعة ويقرأه في رمضان في ثلاث.', 'حلية الأولياء', 7, 166, '{}', false, 'published'),
  ('64c7decc-027d-45b0-ac82-78faa1f7a185', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان ابن السماك يقول في آخر كلامه ألا متأهب فيما يوصف له أمامه مستعد ليوم فقره وفاقته، ألا شاب عادم مبادر لمنيته ليس يغره شبابه ولا شدة قوته.', 'حلية الأولياء', 8, 210, '{}', false, 'published'),
  ('3ea92c29-33ed-4331-af4e-c8e6c4a58aa7', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان محمد بن النضر إذا ذكر الموت اضطربت مفاصله حتى تتبين الرعدة فيها.', 'حلية الأولياء', 8, 218, '{}', false, 'published'),
  ('927c55dc-7a68-4cb4-9bfc-32233188847a', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان عبد الرحمن يحج كل سنة، فمات أخوه وأوصى إليه وقبل وصيته، وقام على أيتامه وترك الحج.', 'حلية الأولياء', 9, 14, '{}', false, 'published'),
  ('8c959e0b-f7bd-47f3-989e-f74f4c1d78c9', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'وكان الشافعي يصنع كتابا من غدوة إلى الظهر من حفظه من غير أن يكون في يده أصل.', 'حلية الأولياء', 9, 129, '{}', false, 'published'),
  ('96c507e1-cbad-4c9c-9acf-89687efed0e9', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان الشافعي يختم القرآن ستين ختمة.', 'حلية الأولياء', 9, 134, '{}', false, 'published'),
  ('7562b237-fd5f-4785-aa3b-7177b9bebf81', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000001', 'biography', 'كان أبو أمامة يحب الصدقة ويجمع لها، وما يرد سائلا ولو ببصلة أو بتمرة أو بشيء مما يؤكل.', 'حلية الأولياء', 10, 129, '{}', false, 'published'),
  ('a6ae4875-5637-43ac-95b5-0bbbd002b8b5', '491399a5-8258-48a1-9160-100948dba640', '33333333-3333-4333-8333-000000000002', 'biography', 'كان زيد بن أخرم يسميه عابد أهل أصبهان.', 'حلية الأولياء', 10, 391, '{}', false, 'published'),
  ('fa6214a1-2c8c-4b43-b07a-0fb64fc67bbf', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان زيد بن الخطاب يحمل راية المسلمين يوم اليمامة وقد انكشف المسلمون حتى غلبت بنو حنيفة عن الرحال، فجعل زيد يقول أما الرحال فلا رحال، وأما الفرار فلا فرار.', 'صفة الصفوة', 1, 168, '{}', false, 'published'),
  ('df2e3446-b6a0-40b0-b1c2-bd8485a7a842', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان معاذ بن عفراء لا يدع شيئاً إلا تصدق به.', 'صفة الصفوة', 1, 178, '{}', false, 'published'),
  ('0d58e19d-ec67-4715-92a9-b926a454a98b', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان ابن عباس يقوم على منبرنا هذا فيقرأ البقرة وآل عمران فيفسرهما آية آية.', 'صفة الصفوة', 1, 295, '{}', false, 'published'),
  ('968d7cdc-5719-4bbf-9281-05d04063b90b', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان ابن الزبير، إذا قام في الصلاة، كأنه عود؛ من الخشوع.', 'صفة الصفوة', 1, 302, '{}', false, 'published'),
  ('6d0deef4-c2c8-4e14-b0de-ed6f98274080', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان عبد الله بن الزبير يحيي الدهر أجمع، ليلةً قائماً حتى يصبح، وليلةً يحييها راكعاً حتى الصباح، وليلةً يحييها ساجداً حتى الصباح.', 'صفة الصفوة', 1, 303, '{}', false, 'published'),
  ('17dc1bd5-b50e-44a3-91a1-67c1d8dbb28f', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان ابن الزبير يواصل سبعة أيام، ويصبح اليوم السابع وهو اليثا.', 'صفة الصفوة', 1, 303, '{}', false, 'published'),
  ('b15b5299-4100-4120-bd95-b05909efd2c8', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان سعيد بن المسيب يُسرُد الصومَ.', 'صفة الصفوة', 1, 346, '{}', false, 'published'),
  ('443b3254-5830-4911-b5e4-5e9b7d49e815', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان عروة بن الزبير إذا كان أيام الرطب ثلم حائطه فيدخل الناس فيأكلون ويحملون.', 'صفة الصفوة', 1, 349, '{}', false, 'published'),
  ('ff558f82-304b-40b6-80e4-764647f7ccb3', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان محمد بن علي يجيز بالخمسمائة والتسمائة إلى الألف، وكان (لا) يملّ من مجالسة إخوانه غنيّاً.', 'صفة الصفوة', 1, 364, '{}', false, 'published'),
  ('ec70c0b4-e190-4eee-b2ea-88d9ac5047f0', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان عبد الرحمن بن أبان يشتري أهل البيت ثم يأمر بهم فيكسون ويدهنون ثم يعرضون عليه فيقول انتم أحرار لوجه الله استعين بكم على غمرات الموت.', 'صفة الصفوة', 1, 382, '{}', false, 'published'),
  ('8d358bf4-450a-431b-b041-8802f87cda21', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'وكان ابن مهدي يقول ما نظرت إليه الا ذكرت به سفيان الثوري ولقد كاد هذا الغلام ان يكون إماما في بطن أمه.', 'صفة الصفوة', 1, 479, '{}', false, 'published'),
  ('2e5761b9-cba4-44a0-a0f3-3d8ac5c20d89', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'وكان الشبلي ينوح يوما ويقول مكر بك في احسانه فتناسيت وامهلك في غيك فتماديت واسقطك من عينه فما دريت ولا باليت.', 'صفة الصفوة', 1, 541, '{}', false, 'published'),
  ('b908516b-41d6-48a6-b36d-3f0988b49d2d', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'وكانت الضجة تمنع التبليغ للتكبير فصلى اكثر الناس وحدانا ورأيت عدة بنانيك فيها من المداسات الكثيرة ينادي عليها لياخذها اربابها.', 'صفة الصفوة', 1, 558, '{}', false, 'published'),
  ('4fad33bf-f4b1-4298-902e-0be8ab809d04', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان الحسن يقعد مع أصحابه ولا يقوم حتى يختم منصور بن زاذان القرآن.', 'صفة الصفوة', 2, 7, '{}', false, 'published'),
  ('391b0c9f-ef52-44cb-b345-48dbe873d939', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان الأسود يختم القرآن في رمضان في ليلتين، وكان ينام بين المغرب والعشاء، وكان يختم القرآن في غير رمضان، في كل ست ليال.', 'صفة الصفوة', 2, 14, '{}', false, 'published'),
  ('1ed7e32d-c8a1-44d5-8b22-4139dedb72fd', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان أبو وائل إذا خلا يسبح، ولو جعلت له الدنيا على أن يفعل ذلك وأحد يراه لم يفعل.', 'صفة الصفوة', 2, 17, '{}', false, 'published'),
  ('e6b30013-cce0-480d-8a30-3b6ad4b2cc6c', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان شقيق بن سلمة يدخل المسجد يصلي ثم ينشج كما تنشج المرأة.', 'صفة الصفوة', 2, 17, '{}', false, 'published'),
  ('b7c8ba7b-ca0a-482c-a5f4-fac20919fc05', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان عمرو بن ميمون إذا دخل المسجد فرئي ذكر الله عز وجل.', 'صفة الصفوة', 2, 21, '{}', false, 'published'),
  ('46fecab6-d320-49f3-95ed-6067e3d689d8', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'وكان الربيع إذا أتى عبد الله لم يكن عليه إذن حتى يفرغ كل واحد منهما من صاحبه.', 'صفة الصفوة', 2, 34, '{}', false, 'published'),
  ('2104e2a6-6ebc-43a2-808d-294fb9be8354', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان الربيع بن خثيم يقول السرائر التي تختفي على الناس وهي لله بواد، التمسوا دواءهن التمسوا دواءهن.', 'صفة الصفوة', 2, 35, '{}', false, 'published'),
  ('98965866-ec7e-40c1-8cc8-81e5b15cae1a', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان الربيع ابن خثيم إذا سجد كأنه ثوب مطروح فتجيء العصافير فتقع عليه.', 'صفة الصفوة', 2, 36, '{}', false, 'published'),
  ('8111c14f-d10f-478f-a8e8-7b54ab517709', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان عمرو بن عتبة يصلي والحمام فوق رأسه، والسباع حوله، تحرك أذنابها.', 'صفة الصفوة', 2, 40, '{}', false, 'published'),
  ('97c4c917-a5ab-4671-b17a-4b004d9e5b1a', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان سعيد بن جبير إذا قام إلى الصلاة كأنه وتد.', 'صفة الصفوة', 2, 44, '{}', false, 'published'),
  ('c8a605ac-2195-414c-b488-e8911f403cc5', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان أبو إسحاق يقوم ليل الصيف كله، وأما الشتاء فأوله وآخره، وبين ذلك هجعة.', 'صفة الصفوة', 2, 60, '{}', false, 'published'),
  ('322ac754-e3a1-4a02-ad50-cd2ba4258048', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'فكانت المسئلة تجيء وأنا أشد شهوة للجواب فيها من العطشان إلى الماء فلا أجيب فيها.', 'صفة الصفوة', 2, 76, '{}', false, 'published'),
  ('39d185f7-efdf-49e2-8947-74c28fcc017d', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان الحسن بن حي إذا أراد أن يعظ أخا له كتبه في لوح وناوله.', 'صفة الصفوة', 2, 88, '{}', false, 'published'),
  ('98c6e86b-961c-43e5-9ced-375af2352cb0', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان حسن بن صالح إذا صعد إلى المنارة أشرف على المقابر فإذا نظر إلى الشمس تحوم على القبور صرخ حتى يحمل مغشياً عليه فينزل به.', 'صفة الصفوة', 2, 89, '{}', false, 'published'),
  ('df832b16-4100-40ee-a6db-b0f208444789', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان أبو بكر بن عياش يقوم الليل في قباء صوف وسراويل وعكازة يضعها في صدره فيتكئ عليها حين كبر فيحيي ليلته.', 'صفة الصفوة', 2, 95, '{}', false, 'published'),
  ('4f6a75a4-3238-4ccc-9b8b-e9a75b444a82', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان حجير بن الربيع يصلي حتى ما يأتي فراشه إلا زحفاً، وما يعدونه من أعبدهم.', 'صفة الصفوة', 2, 119, '{}', false, 'published'),
  ('d1397d39-17c3-4105-af16-5d829e80d686', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان أبو العالية إذا جلس غليه أكثر من أربعة قام.', 'صفة الصفوة', 2, 124, '{}', false, 'published'),
  ('b6a000cd-4583-4855-a0ea-860f05a607e6', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان صلة بن أشيم يخرج إلى الجبان فيتعبد فيها فكان يمر عليه شباب يلهون ويلعبون.', 'صفة الصفوة', 2, 127, '{}', false, 'published'),
  ('7086b19d-6e33-4597-bc79-ca5a2659e54c', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان أبو الصهباء يصلي حتى ما يستطيع أن يأتي فراشه إلا زحفاً.', 'صفة الصفوة', 2, 128, '{}', false, 'published'),
  ('797f8582-a1a7-4a8d-b6db-a3044c9060eb', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان مطرف بن عبد الله إذا دخل بيته سبحت معه آنية بيته.', 'صفة الصفوة', 2, 131, '{}', false, 'published'),
  ('aa39b9a3-d5fb-45fd-9318-c7a0d57e743e', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان محمد بن سيرين إذا حدث كأنه يتقي شيئاً، كأنه يحذر شيئاً.', 'صفة الصفوة', 2, 143, '{}', false, 'published'),
  ('774475ee-849a-4e66-b1c6-fb0422cb6d4d', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'وكان اليوم الذي يفطر فيه يتغدى ولا يتعشى، ثم يتسحر ويصبح صائماً.', 'صفة الصفوة', 2, 144, '{}', false, 'published'),
  ('5578f6f5-489d-412a-9724-c597c54950ee', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان ابن سيرين يصوم يوماً ويفطر يوماً.', 'صفة الصفوة', 2, 144, '{}', false, 'published'),
  ('3617bfa9-e64e-49eb-acb6-4e8619c7f883', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان ابن سيرين يحيي الليل في رمضان.', 'صفة الصفوة', 2, 146, '{}', false, 'published'),
  ('0772edaa-af6e-487e-ad15-0c36f4de968d', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان ابن سيرين إذا ذكر الموت مات كل عضو منه على حدته.', 'صفة الصفوة', 2, 146, '{}', false, 'published'),
  ('32948820-929c-4b95-9e42-f07fca42270f', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان أبو الجوزاء يواصل في الصوم بين سبعة أيام ثم يقبض على ذراع الشاب فيكاد يحطمها.', 'صفة الصفوة', 2, 152, '{}', false, 'published'),
  ('cc4d58ec-d371-4353-9e42-09cdb5ce091b', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان أبو عمران الجوني إذا سمع الأذان تغير لونه وفاضت عيناه.', 'صفة الصفوة', 2, 157, '{}', false, 'published'),
  ('d4e3b71b-3ec8-4fa9-88e1-e3552270d49b', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'وكان النساك يومئذ يشمرون ثيابهم وكان أيوب لا يفعل.', 'صفة الصفوة', 2, 173, '{}', false, 'published'),
  ('959ea230-c0f3-44ca-b036-cfec10762ff0', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان عبد العزيز بن سلمان إذا ذكر القيامة والموت صرخ كما تصرخ الثكلى ويصرخ الخائفون من جوانب المسجد.', 'صفة الصفوة', 2, 223, '{}', false, 'published'),
  ('ba70800a-a40e-4ed7-b6ab-740e1d772479', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان عبد الرحمن بن مهدي يختم في كل ليلتين، وكان ورده في كل ليلة نصف القرآن.', 'صفة الصفوة', 2, 227, '{}', false, 'published'),
  ('6cd03667-6bb2-41b7-a5bf-c1d6923609f0', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان أبو الحسن المكي يسف الخوص وكان لا يملك إلا داراً فلما ضعف عن سف الخوص باعها على شرط أن يكريه المشتري إياها وأودع الثمن عند المشتري، وكان يأخذ منه في كل شهر خمسة دراهم لنفقته ويعطي المشتري أجرة الدار.', 'صفة الصفوة', 2, 232, '{}', false, 'published'),
  ('c4f15c42-8bbb-4ea8-9393-7faee0fcde85', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كانت حفصة بنت سيرين تسرج سراجها من الليل ثم تقوم في مصلاها فربما طفئ السراج فيضيء لها البيت حتى تصبح.', 'صفة الصفوة', 2, 243, '{}', false, 'published'),
  ('c2d0d14e-9028-47d7-9939-4c9567a2e97e', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كانت أم حيان تقرأ القرآن في كل يوم وليلة، وكانت لا تتكلم إلا بعد العصر فإنها تأمر بالحاجة والشيء تريده.', 'صفة الصفوة', 2, 251, '{}', false, 'published'),
  ('44554d43-1e22-40ae-92a8-69eec192f1be', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'وكان أحمد بن حنبل يشبه بوكيع، وكان أبو داود يشبه بأحمد بن حنبل -رضي الله عنهم.', 'صفة الصفوة', 2, 276, '{}', false, 'published'),
  ('ee9e33fa-0296-48f6-a9ff-bbc93fb57d29', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان المعلى بن منصور الرازي يوماً يصلي فوقع على رأسه كور الزنابير فما التفت ولا انفتل حتى أتم صلاته فنظروا فإذا رأسه قد صار هكذا من شدة الانتفاخ.', 'صفة الصفوة', 2, 289, '{}', false, 'published'),
  ('e25384ed-02ca-4300-b1b8-2f2456cead52', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كانت أم ابن المبارك تركية، وكان الشبه لهم بيناً فيه، وكان ربما خلع قميصه فلا أرى على صدره وجسده كثير شعر.', 'صفة الصفوة', 2, 323, '{}', false, 'published'),
  ('1edfa8d3-3f8b-49e9-a67a-bd998de2658a', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'وكان عبد الله بن منير إذا قام من المجلس يخرج إلى البرية مع قوم مع أصحابه يجمع شيئاً مثل الأشنان وغيره فيدخل السوق فيبيع ذلك فيتعيش به.', 'صفة الصفوة', 2, 332, '{}', false, 'published'),
  ('dfcc4840-271e-41a0-a99f-37c29c506394', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان ابن محيريز يجيء بالكتاب إلى عبد الملك فيه النصيحة فيقرئه إياه ثم لا يقره في يده.', 'صفة الصفوة', 2, 368, '{}', false, 'published'),
  ('40942cd5-2074-470a-b83e-366b49d19a53', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان ابن زكريا يقدم فلسطين فيلقى ابن محيريز فتتقاصر إليه نفسه لما يرى من فضل ابن محيريز.', 'صفة الصفوة', 2, 369, '{}', false, 'published'),
  ('1477acbb-3d91-41b8-9441-1f000d0230ba', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان خالد بن معدان إذا عظمت حلقته قام فانصرف.', 'صفة الصفوة', 2, 374, '{}', false, 'published'),
  ('6297c6cc-e4cb-40c8-8528-fe315c558af8', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان عبد الله بن أبي زكريا إذا خاض جلساؤه في غير ذكر الله كأنه ساه، وإذا خاضوا في ذكر الله كان من أحسن الناس استماعاً.', 'صفة الصفوة', 2, 375, '{}', false, 'published'),
  ('fc4a49d1-6eee-4b51-b5e3-2a30fbfa3096', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كانت أم البنين تعتق في كل جمعة رقبة، وتحمل على فرس في سبيل الله عز وجل.', 'صفة الصفوة', 2, 431, '{}', false, 'published'),
  ('0bafc195-45ce-4a63-b505-454856df1043', '256ccd74-6eaf-442a-817a-71fd737f7fad', '33333333-3333-4333-8333-000000000002', 'biography', 'كان أبو أمامة يحب الصدقة ويجمع لها، ولا يرد سائلاً ولو ببيضة، ولو بتمرة أو بشيء مما يؤكل، فأتاه سائل ذات يوم وقد أقفر من ذلك كله وما عنده إلا ثلاثة دنانير.', 'صفة الصفوة', 2, 436, '{}', false, 'published'),
  ('99d0d0c1-dbfd-4bf0-b42e-a1440f26ee9e', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وجزى الله عنا خير الجزاء علماء هذه الأمة المحمدية، الذين كانت سيرهم طيبة، وأعمالهم الصالحة، وعلومهم النافعة، وأوقاتهم الرابحة: خير قدوة وحافز للمستفيدين والطالبين، في حياتهم وبعد مما تهم، فالله مسئول أن يغدق عليهم شآبيب الرحمة والرضوان، ويسكنهم رفيع غرف الجنان، ويحبب إلينا الاقتداء بهم في صالح القول والعمل والعلم والسلوك.', 'قيمة الزمن عند العلماء', null, 5, '{}', false, 'published'),
  ('50060e06-89d0-4d7e-81a8-dbf577c13132', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وأبقيت ترتيب الأخبار فيه على تسلسل سني الوفيات، ولم أرتبه على الموضوعات، ليتجلى فيه تعاقب الخالف للسالف على رعاية هذه الصفة الرفيعة: (حفظ الوقت) عند العلماء.', 'قيمة الزمن عند العلماء', null, 5, '{}', false, 'published'),
  ('bbba61cd-6ed7-4203-9a4b-23b0a9810a13', null, '33333333-3333-4333-8333-000000000002', 'saying', 'فكتب فيه الأستاذ الدكتور عبد الستار نوير في سنة ١٤٠٦، كتابه الذي تناول فيه الوقت من جوانب شتى ونواحي متعددة، وسماه بعنوان: (الوقت هو الحياة).', 'قيمة الزمن عند العلماء', null, 6, '{}', false, 'published'),
  ('bdeac404-4605-4ccf-bcc6-087ae892315e', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وإنه ليسرني أن ينتفع هذا المحب - أحد أبنائي في الطلب والتحصيل - بكتابي، ويقتبسه بجملته وجمهرته، وكنت أود أن يذكر من أين اقتبس هذه النصوص التي ألف كتابه منها، أداء لأمانة، فقد قال العلماء: من الأمانة في العلم عزوه إلى قائله أو ناقله.', 'قيمة الزمن عند العلماء', null, 6, '{}', false, 'published'),
  ('d9a6238c-163d-4582-98b0-30ef94b73b9c', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وليس هذا مني - علم الله - حرصا على الشهرة أو الفخفخة، ولكن هي الأمانة والأدب الذي علمناه الإسلام، وصاغه الإمام الشافعي رضي الله عنه بأدبه وبيانه الرفيع، الذي أوردته آنفا، والله الهادي، وصلى الله على نبينا محمد وعلى آله وصحبه وسلم، والحمد لله رب العالمين.', 'قيمة الزمن عند العلماء', null, 7, '{}', false, 'published'),
  ('d2bf32ad-a797-4141-a439-4f3f196d2572', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقد رسم الشرع الحنيف: التوقيت في تكاليف كثيرة غير الصلاة، فوقت في أحكام الحج، والزكاة، والصوم، وزكاة الفطر، والأضحية، والسفر، والتيمم، والمسح على الخفين، والرضاع، والطلاق، والعدة، والرجعة، والنفقة، والدين، والرهن، والضيافة، والعقيقة، والحيض، والنفاس، وغيرها. وما ذلك إلا لمعنى هام رتب الشرع التوقيت عليه، ولحظ المصلحة والنفع به.', 'قيمة الزمن عند العلماء', null, 10, '{}', false, 'published'),
  ('f47a595e-4731-4a7f-a86b-cd21873ec5d3', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقد غفل كثير من المسلمين اليوم عن هذا التوجيه الإسلامي الدقيق لهم من جانب الشرع الأغر، فجعلوا يأخذن ويتعلمون أهمية ربط الأعمال بالتوقيت المناسب، من غيرهم! وكأنهم لم يمرنوا أو يربوا على ذلك من أول يوم كلفوا فيه بأحكام الشريعة الغراء، وفي أولها الصلاة.', 'قيمة الزمن عند العلماء', null, 11, '{}', false, 'published'),
  ('1cd66ac3-6d3a-4abf-9466-5cd959474e61', null, '33333333-3333-4333-8333-000000000002', 'saying', 'فيجب على المسلم أن ينتبه إلى الوقت في حياته، وإلى تنفيذ كل عمل من أعماله في توقيته المناسب، فالوقت من حيث هو معيار زمني: من أغلى ما وهب الله تعالى للإنسان، وهو في حياة العالم وطالب العلم رأس المال والربح جميعا، فلا يسوغ للعاقل أن يضيعه سدى، ويعيش فيه هملا سبهللا، ومن أجل هذا دونت هذه الصفحات حافزا لنفسي ولأبناء جنسي، رجاء الانتفاع بما فيها من أخبار آبائنا وسلفنا الماضين، والله ولي التوفيق.', 'قيمة الزمن عند العلماء', null, 11, '{}', false, 'published'),
  ('c9828655-897e-4a1f-b4ed-98b920b75136', null, '33333333-3333-4333-8333-000000000002', 'saying', 'الحمد لله وكفى، وصلاة وسلام على عباده الذين اصطفى، وفي مقدمتهم سيدنا ورسولنا محمد المصطفى، وعلى آله وصحبه وتابعيه ومن بهم اهتدى واقتفى.', 'قيمة الزمن عند العلماء', null, 13, '{}', false, 'published'),
  ('e8ee1355-decc-4370-ae57-9b4abb9dbfd7', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وبعد فهذه الصفحات وجيزة، كتبتها في بيان (قيمة الزمن عند العلماء)، وأردت بها التعريف بقيمة هذه النعمة العظيمة التي هي ميدان الحياة، في محيط العلم وأهله، وكيف يمكن أن تأتى بالعجائب المدهشات، إذا أحسن المرء الاستفادة منها، ونظم حياته وأوقاته بنظام، وبعد عن الوقوع في الفضول في الكلام والطعام والمجالس والاجتماعات واللقاءات..، فتكون له أوفر الآثار الزاكيات، وأطيب الحسنات الباقيات، ويخلد ذكره - بنفعه ومآثره - مع الخالدين المحسنين.', 'قيمة الزمن عند العلماء', null, 13, '{}', false, 'published'),
  ('f1ecbada-a45b-4c96-922a-4978512ff666', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وجزى الله عنا خير الجزاء سلفنا الصالح وعلماءنا السابقين الأبرار، فقد كانوا لنا قدوة في كل خير، نموذجا لكل فضيلة، فاللهم ارزقنا انتهاج سبيلهم في جميع الشؤون، ووفقنا للاستفادة من أعمارنا وأوقاتنا، واجعلنا نشغلها بما يرضيك عنا، وجنبنا الفضول في كل شيء، إنك على كل شيء قدير، وصلى الله على سيدنا محمد وعلى آله وصحبه وسلم، والحمد لله رب العالمين.', 'قيمة الزمن عند العلماء', null, 13, '{}', false, 'published'),
  ('20478b33-f569-493b-b4ff-51d8db849e6a', null, '33333333-3333-4333-8333-000000000002', 'saying', 'في الرياض ١٨ من جمادى الأولى سنة ١٤٠٢ لهذا العنوان الصغير أطراف كثيرة وكبيرة من المعاني والمواضيع، تتجاذب الكلام فيها، فللزمن قيمة عند الفلاسفة غير قيمته عند التجار، وغيرها عند الزراع، وغيرها عند الصناع، وغيرها عند العسكريين، وغيرها عند السياسيين، وغيرها عند الشباب، وغيرها عند الشيوخ، وغيرها عند طلبة العلم وأهل العلم.', 'قيمة الزمن عند العلماء', null, 14, '{}', false, 'published'),
  ('8e081cc8-164f-4469-bbde-b0272f97e73d', null, '33333333-3333-4333-8333-000000000002', 'saying', 'إن نعم الله تعالى على عباده كثيرة لا تحصى، ولا يمكن للبشر أن يحصوها أو يدركوها على حقيقتها، وذلك لكثرتها، واستمرارها، ويسرها، وتتابع إنعام الله بها، وتفاوت مدارك الناس بها؛ وصدق الله العظيم إذ يقول: (وإن تعدوا نعمة الله لا تحصوها إن الإنسان لظلوم كفار).', 'قيمة الزمن عند العلماء', null, 15, '{}', false, 'published'),
  ('4f89fc74-c5de-450a-96b7-2d41b26bf371', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ومن أصول النعم أيضاً: نعمة الصحة والعافية، التي منها سلامة السمع والبصر والفؤاد والجوارح، وهي محور حركة الإنسان وقوام استفادته من وجوده.', 'قيمة الزمن عند العلماء', null, 16, '{}', false, 'published'),
  ('2a5e8703-4d4b-4ab7-9a72-876ddd3fdb7a', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وهناك أمثلة كثيرة لأصول النعم، لا أطيل بذكرها مراعاة لقيمة الزمن.', 'قيمة الزمن عند العلماء', null, 16, '{}', false, 'published'),
  ('a4c3e846-2cf5-4f49-b3c4-aa2906fbf1db', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ومن أصول النعم أيضاً، بل من أجل أصولها وأغلاها: نعمة (الزمن)، الذي جمعت هذه الصفحات للحديث عن قيمته، في جنب طلبة العلم وأهل العلم خاصة.', 'قيمة الزمن عند العلماء', null, 17, '{}', false, 'published'),
  ('777762a2-39dd-43ee-b8ed-8e8588c59791', null, '33333333-3333-4333-8333-000000000002', 'saying', 'فالزمن هو عمر الحياة، وميدان وجود الإنسان، وساحة ظله وبقائه ونفعه وانتفاعه. وقد أشار القرآن الكريم إلى عظم هذا الأصل في أصول النعم، وألمع إلى علو مقداره على غيره، فجاءت آيات كثيرة ترشد إلى قيمة الزمن، ورفيع قدره وكبير أثره.', 'قيمة الزمن عند العلماء', null, 17, '{}', false, 'published'),
  ('bd6a342b-7a8c-4cad-ad97-d56bbc1c6eef', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وسخر لكم الأنهار. لكم الشمس والقمر دائبين، وسخر لكم الليل والنهار. وآتاكم من كل ما سألتموه، وإن تعدوا نعمة الله لا تحصوها إن الإنسان لظلوم كفار).', 'قيمة الزمن عند العلماء', null, 17, '{}', false, 'published'),
  ('7aee1d5d-c1fe-445e-a64e-e06ca1dda2b1', null, '33333333-3333-4333-8333-000000000002', 'saying', 'فامتن سبحانه في جلائل نعمه بنعمة الليل والنهار، وهما الزمن الذي نتحدث عنه ونتحدث فيه، ويمر به هذا العالم الكبير من أول بدايته، إلى نهاية نهايته.', 'قيمة الزمن عند العلماء', null, 17, '{}', false, 'published'),
  ('c71238e3-4d84-4f49-b1d3-d456ff791c3c', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وتمدح سبحانه بأنه مالك الزمان والمكان وما يحل فيهما من زمانيات ومكانيات، فقال: (وله ما سكن في الليل والنهار وهو السميع العليم).', 'قيمة الزمن عند العلماء', null, 18, '{}', false, 'published'),
  ('30369ee3-939c-45de-91eb-137fe7bf9723', null, '33333333-3333-4333-8333-000000000002', 'saying', 'فجعل سبحانه (التعمير) موجبا للتذكر والاستبصار، وميدانا للإيمان والاستذكار، وأقام (العمر) الذي هو الزمن بحياة الإنسان: حُجْة على الإنسان، كما أقام وجود الرسالة والنذارة حجة عليه أيضاً.', 'قيمة الزمن عند العلماء', null, 19, '{}', false, 'published'),
  ('072e10dd-0ed3-4b0b-8eed-1817cc127b9e', null, '33333333-3333-4333-8333-000000000002', 'saying', 'أقسم بالله تعالى بالعصر - الذي هو الزمن -، لما فيه من الأعاجيب، لأنه يحصل فيه السراء والضراء، والصحة والسقم، والغنى والفقر، ولأن العمر لا يقوم بشيء نفاسة وغلاء.', 'قيمة الزمن عند العلماء', null, 21, '{}', false, 'published'),
  ('a115f773-26b6-4840-b6c5-63f81ce4c65f', null, '33333333-3333-4333-8333-000000000002', 'saying', 'فلو ضيعت ألف سنة فيما لا يعني، ثم تبت وثبتت لك السعادة في اللمحة الأخيرة من العمر، بقيت في الجنة أبد الآباد، فعلمت أن أشرف الأشياء حياتك في تلك اللمحة، فكان الزمان من جملة أصول النعم، فلذلك أقسم الله به، ونبه سبحانه على أن الليل والنهار فرصة يضيعها الإنسان! وأن الزمان أشرف من المكان فأقسم به، لكون الزمان نعمة خالصة لا عيب فيها، إنما الخاسر المعيب هو الإنسان)) انتهى.', 'قيمة الزمن عند العلماء', null, 21, '{}', false, 'published'),
  ('ebb75904-85f5-4a29-95bb-0d624c02e463', null, '33333333-3333-4333-8333-000000000002', 'saying', 'الغيرة على وقت فات! وهي غيرة قاتلة، فإن الوقت وحي التقضي -أي سريع الانقضاء- أبي الجانب، بطيء الرجوع. والوقت عند العابد: هو وقت العبادة والأوراد، وعند المريد: هو وقت الإقبال على الله، والجمعية عليه، والعكوف عليه بالقلب كله. والوقت أعز شيء عليه، يغار عليه أن ينقضي بدون ذلك! فإذا فاته الوقت لا يمكنه استدراكه البتة، لأن الوقت الثاني قد استحق واجبه الخاص، فإذا فاته وقت فلا سبيل له إلى تداركه.', 'قيمة الزمن عند العلماء', null, 23, '{}', false, 'published'),
  ('ce51f7de-0454-4c07-8bcf-a70e75110449', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ومعنى أنها (غيرة قاتلة) أي أن أثرها يشبه القتل، لأن حسرة الفوت قاتلة، ولا سيما إذا علم المتحسر: أنه لا سبيل إلى الاستدراك. وأيضاً فالغيرة على التفويت تفويت آخر، كما يقال: الاشتغال بالندم على الوقت الفائت تضييع للوقت الحاضر! ولذلك يقال: الوقت كالسيف إن لم تقطعه قطعك.', 'قيمة الزمن عند العلماء', null, 23, '{}', false, 'published'),
  ('780526a8-b47b-4dad-aa82-04c719df7906', null, '33333333-3333-4333-8333-000000000002', 'saying', 'فالوقت منقض بذاته، منصرم بنفسه، فمن غفل عن نفسه تصرمت أوقاته، وعظم فواته، واشتدت حسراته، فكيف حاله إذا علم عند تحقق الفوت مقدار ما أضاع! وطلب الرجعى فحيل بينه وبين الاسترجاع! وطلب تناول الفائت، وكيف يرد الأمس في اليوم الجديد؟! (وأنى لهم التناوش من مكان بعيد)؟! ومنع مما يحبه ويرتضيه، وعلم أ، ما اقتناه ليس مما ينبغي للعاقل أن يقتنيه، وحيل بينه وبين ما يشتهيه!', 'قيمة الزمن عند العلماء', null, 24, '{}', false, 'published'),
  ('90bdb333-8b90-4b52-bed4-1d6b0cbbcd23', null, '33333333-3333-4333-8333-000000000002', 'saying', 'قال الشافعي رضي الله عنه: صحبت الصوفية، فلم أستفد منهم سوى حرفين، أحدهما قولهم: الوقت سيف، فإن لم تقطعه قطعك، وذكر الكلمة الأخرى، و: نفسك إن شغلتها بالحق وإلا شغلتك بالباطل.', 'قيمة الزمن عند العلماء', null, 25, '{}', false, 'published'),
  ('8cb93b84-7ecf-4b96-a63b-9e453814f676', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقد كان السلف الصالح ومن سار على نهجهم من الخلف أحرص الناس على كسب الوقت وملئه بالخير، سواء في ذلك عالمهم وعابدهم، فقد كانوا يسابقون الساعات، ويبادرون اللحظات، ضنا منهم بالوقت، وحرصا على أن لا يذهب منهم هدرا.', 'قيمة الزمن عند العلماء', null, 26, '{}', false, 'published'),
  ('0615c599-4735-4704-b9ef-588c379be06e', null, '33333333-3333-4333-8333-000000000002', 'saying', 'نقل عن عامر بن عبد قيس أحد التابعين الزهاد: أن رجلا قال له: كلمني، فقال له: عامر بن عبد قيس: أمسك الشمس. يعني أوقف لي الشمس واحبسها عن المسير حتى أكلمك، فإن الزمن متحرك دائب المضي، لا يعود بعد مروره، فخسارته خسارة لا يمكن تعويضها واستدراكها، لأن لكل وقت ما يملؤه من العمل.', 'قيمة الزمن عند العلماء', null, 26, '{}', false, 'published'),
  ('46a8d277-27f3-4fb4-b41d-0767a82f8e97', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقال الخليفة الصالح عمر بن عبد العزيز رضي الله عنه: إن الليل والنهار يعملان فيك، فاعمل فيهما.', 'قيمة الزمن عند العلماء', null, 27, '{}', false, 'published'),
  ('adfa5d05-c222-4af3-a2c7-f6d5c8e9e334', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقال الحسن البصري رضي الله عنه: يا ابن آدم، إنما أنت أيام، فإذا ذهب يوم ذهب بعضك. وقال أيضا: أدركت أقواما كانوا على أوقاتهم أشد منكم حرصا على دراهمكم ودنانيركم.', 'قيمة الزمن عند العلماء', null, 27, '{}', false, 'published'),
  ('20327628-3468-40bf-b36c-89bda330f6fe', null, '33333333-3333-4333-8333-000000000002', 'saying', 'قال تلميذه عبد الرحمن بن مهدي: لو قيل لحماد بن سلمة: إنك تموت غدا ما قدر أن يزيد في العمل شيئا. وقال موسى بن إسماعيل التبوذكي: لو قلت لكم: إني ما رأيت حماد بن سلمة ضاحكا لصدقت، كان مشغولا: إما أن يحدث أو يقرأ، أو يسبح، أو يصلي، وقد قسم النهار على ذلك. قال يونس المؤدب: مات حماد بن سلمة وهو في الصلاة، رحمه الله تعالى عليه)).', 'قيمة الزمن عند العلماء', null, 27, '{}', false, 'published'),
  ('9212e3a1-db87-421b-85d4-51250f02a03b', null, '33333333-3333-4333-8333-000000000002', 'saying', 'يباحث - وهو في النزع والذماء: النفس الأخير من الحياة - بعض عواده في مسألة فقهية، رجاء النفع بها لمستفيد أو متعلم، ولا يخلي اللحظة الأخيرة من لحظات حياته من كسبها في مذاكرة علم وإفادة واستفادة.', 'قيمة الزمن عند العلماء', null, 28, '{}', false, 'published'),
  ('5fd3d587-8b45-4dca-a54e-ba8926147c29', null, '33333333-3333-4333-8333-000000000002', 'saying', 'قال تلميذه القاضي إبراهيم بن الجراح الكوفي ثم المصري: مرض أبو سيف، فأتيته أعوده، فوجدته مغمى عليه، فلما أفاق قال لي: يا إبراهيم، ما تقول في مسألة؟ قلت: في مثل هذه الحالة؟! قال: ولا بأس بذلك، ندرس لعله ينجو به ناج؟', 'قيمة الزمن عند العلماء', null, 29, '{}', false, 'published'),
  ('e02f35e2-c2ad-43a0-a595-795921ccfe79', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وحكى الحافظ الذهبي في ((سير أعلام النبلاء))، في ترجمة المحدث الكبير عبيد بن يعيش شيخ البخاري ومسلم، ما يلي: ((هو الحافظ الحجة الأوحد، أبو محمد عبيد بن يعيش الكوفي، المحاملي العطار.', 'قيمة الزمن عند العلماء', null, 32, '{}', false, 'published'),
  ('9e48290d-4359-4bac-ac9e-82d9a3d40bcc', null, '33333333-3333-4333-8333-000000000002', 'saying', 'حدث عنه البخاري في جزء رفع اليدين، ومسلم في الصحيح، والنسائي بواسطة، وأبو زرعة الرازي، ومحمد بن أيوب البجلي،... وخلق. ومات في رمضان سنة تسع وعشرين ومئتين.', 'قيمة الزمن عند العلماء', null, 32, '{}', false, 'published'),
  ('0ca4f581-4c54-44f1-b95d-2047735ea729', null, '33333333-3333-4333-8333-000000000002', 'saying', 'قال عمار بن رجاء: سمعت عبيد بن يعيش يقول: أقمت ثلاثين سنة ما أكلت بيدي بالليل، كانت أختي تلقمني وأنا أكتب الحديث)).', 'قيمة الزمن عند العلماء', null, 32, '{}', false, 'published'),
  ('2e1e28a1-6620-4f8a-8f69-039cca1ecc18', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وروى الإمام أحمد والإمام أبو عيسى الترمذي، ولفظ الحديث وإسناده المسوق هنا هو للترمذي.', 'قيمة الزمن عند العلماء', null, 33, '{}', false, 'published'),
  ('6bef7e6e-5d84-4a8c-b38b-628f71cabdc8', null, '33333333-3333-4333-8333-000000000002', 'saying', 'سمع الحديث من عبد الله بن المبارك، وهشيم بن بشير، وإسماعيل بن عياش، وسفيان بن عيينة، وعبد الرزاق الصنعاني باليمن، ووكيع بن الجرح، ويحيى بن سعيد القطان، وعبد الرحمن بن مهدي، وخلق كثير سواهم، بالعراق والشام والجزيرة ومصر والحجاز.', 'قيمة الزمن عند العلماء', null, 34, '{}', false, 'published'),
  ('21a00aae-d763-428f-8e91-9c45ebd45b07', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وروى عنه الحديث الإمام أحمد بن حنبل، والبخاري، ومسلم، وأبو داود، وعباس الدوري البغدادي وهو راوية علمه، وأبو زرعة الرازي، وأبو حاتم الرازي، وعثمان بن سعيد الدرامي، وأبو يعلى الموصلي، وخلائق لا يحصون كثرة.', 'قيمة الزمن عند العلماء', null, 34, '{}', false, 'published'),
  ('f2148c1d-3dfb-447b-8b13-340ddae7e6ca', null, '33333333-3333-4333-8333-000000000002', 'saying', 'كل حديث لا يعرفه ابن معين فليس بحديث وقال الإمام أحمد بن حنبل: كل حديث لا يعرفه يحيى بن معين فليس بحديث، يحيى بن معين رجل خلقه الله لهذا الشأن، يظهر كذب الكذابين.', 'قيمة الزمن عند العلماء', null, 35, '{}', false, 'published'),
  ('41fb2334-63a3-452e-8352-d8799bf95643', null, '33333333-3333-4333-8333-000000000002', 'saying', 'قول ابن معين: إذا كتبت فقمش وإذا حدثت ففتش ويحيى بن معين هو صاحب المنهج العظيم في تلقي العلم ونشره، إذ يقول كلمته التي صارت دستور المحدثين والعلماء، في التحصيل والأداء: إذا كتبت فقمش -أي اكتب كل ما تسمع واجمعه- وإذا حدثت ففتش.', 'قيمة الزمن عند العلماء', null, 36, '{}', false, 'published'),
  ('78e11376-4ec1-4f51-8f94-e8fd5adab697', null, '33333333-3333-4333-8333-000000000002', 'saying', 'قال صالح بن أحمد الحافظ: سمعت أبا عبد الله محمد بن عبد الله قال، سمعت أبي يقول: خلف يحيى بن معين من الكتب مئة قمطر، وأربعة عشر قمطرا، وأربعة حباب شرابية مملوءة كتباً.', 'قيمة الزمن عند العلماء', null, 36, '{}', false, 'published'),
  ('29d6437f-7ae3-4feb-b139-af33bc56d5fc', null, '33333333-3333-4333-8333-000000000002', 'saying', 'قلت: في تلقي يحيى بن معين لهذا الحديث من شيخه محمد بن الفضل لطائف غالية، وفوائد ثمينة، وذلك أن يحيى بن معين الذي عرفنا طرفا من ترجمته فيما تقدم، طلب من شيخه محمد بن الفضل السدوسي البصري الملقب بعارم: أ، يحدثه بهذا الحديث أول ما جلس إليه يحيى، فلما بدأ يحدثه واستهل التحديث بقوله: حدثنا حماد بن سلمة، قال له يحيى: لو كان من كتابك.', 'قيمة الزمن عند العلماء', null, 37, '{}', false, 'published'),
  ('f00b41e9-b5b8-4a2a-a63a-0ea5a047c436', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وإنما طلب يحيى هذا منه زيادة في التوثق والتثبت، فإن محمد بن الفضل حافظ ثبت صدوق مأمون أحد الثقات المعروفين، ولكن أراد يحيى زيادة الاستيثاق والضبط.', 'قيمة الزمن عند العلماء', null, 37, '{}', false, 'published'),
  ('d87b776d-ea96-451b-862c-e4fc9bc8c711', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وكان من عادة المحدثين قبل إنشاء المدارس في القرن الخامس الهجري أن يحدث الشيخ طلابه في المسجد، أو في مكان فسيح إذا كانوا لا يسعهم المسجد، أو على باب داره إذا كان العدد قليلا، وكان الفضل بن محمد يحدث يحيى بن معين هذا الحديث على باب داره.', 'قيمة الزمن عند العلماء', null, 37, '{}', false, 'published'),
  ('d383f8e9-d02f-4cd8-9fb6-7634c70d3396', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقال له: أمله علي الآن من حفظك، فإني أخاف أن لا ألقاك، فإن الحياة لها قواطعها، فأخاف أن يحال بيني وبينك فلا ألقاك، فأملى محمد بن الفضل: الحديث على يحيى بن معين من حفظه أولاً، ثم دخل داره فجاء بالكتاب فقرأه عليه منه ثانياً.', 'قيمة الزمن عند العلماء', null, 38, '{}', false, 'published'),
  ('87c22020-8732-45a2-891c-05a028096a61', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وبهذه الواقعة الصغيرة التي جاء تسجيلها عرضا، عرفنا ما كان عليه الإمام يحيى بن معين من حفظ الوقت وكسب الزمن، وأدركنا كيف تسنى ليحيى بن معين أن يكتب بيده ألف ألف حديث، ويطوف البلدان، ويسمع من الشيوخ، ويحدث بما سمعه وتلقاه ألوف المحدثين والطالبين.', 'قيمة الزمن عند العلماء', null, 38, '{}', false, 'published'),
  ('a2347101-a880-4dc6-9616-bab34c5d6612', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وليس الإمام يحيى بن معين في هذه المنقبة نسيج وحده وفريد نوعه، بل قل مثل ذلك في الإمام علي بن المديني وأحمد بن حنبل والبخاري ومسلم وأبي داود والترمذي والنسائي وأمثالهم.', 'قيمة الزمن عند العلماء', null, 38, '{}', false, 'published'),
  ('bc088e86-f522-45f1-913d-66fd0159ee78', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وكان سبب وفاته أنه خرج من الجامع يوم الجمعة بعد العصر، وكان قد لحقه صمم لا يسمع إلا بعد تعب، وكان في يده كتاب ينظر فيه في الطريق، فصدمته فرس فألقته في هوة، فأخرج منها وهو كالمختلط - أي المشوه العقل -، فحمل إلى منزله على تلك الحال وهو يتأوه من رأسه، فمات ثاني يوم، رحمه الله تعالى.', 'قيمة الزمن عند العلماء', null, 41, '{}', false, 'published'),
  ('fb84113f-5e03-4f12-807c-2513d2aabaf2', null, '33333333-3333-4333-8333-000000000002', 'saying', 'حدث علي بن عبيد الله اللغوي السمسمي، عن القاضي أبي عمر عبيد الله بن أحمد السمسار وأبي القاسم بن عقيل الوراق: أن أبا جعفر الطبري قال لأصحابه: أتنشطون لتفسير القرآن؟ قالوا: كم يكون قدره؟ قال: ثلاثون ألف ورقة، فقالوا: هذا مما تفنى الأعمار قبل تمامه! فاختصره في نحو ثلاثة آلاف ورقة، وأملاه في سبع سنين، من سنة ثلاث وثمانين ومئتين إلى سنة تسعين.', 'قيمة الزمن عند العلماء', null, 42, '{}', false, 'published'),
  ('2b0e28e6-4172-41ae-8c81-3305b727574d', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقد ولد ابن جرير سنة ٢٢٤، وتوفي سنة ٣١٠، فعاش ٨٦ سنة، وإذا طرحنا منها سنه قبل البلوغ وقدرناها بأربع عشرة سنة، يكون قد بقي ابن جرير ثنتين وسبعين سنة يكتب كل يوم ١٤ ورقة، فإذا حسبنا أيام الاثنين والسبعين سنة، وجعلنا لكل يوم منها ١٤ ورقة تصنيفا، كان مجموع ما صنفه الإمام ابن جرير نحو ٣٥٨ ألف ورقة.', 'قيمة الزمن عند العلماء', null, 43, '{}', false, 'published'),
  ('a377c9d1-77cf-4c84-9846-3454a4c968b7', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقد اعتبروا كلاً من ((تاريخه)) و ((تفسيره)) نحو ثلاثة آلاف ورقة، فيكون الكتابان مجموعهما نحو سبعة آلاف ورقة أو ثمانية آلاف ورقة. وقد جاء التاريخ مطبوعا في أحد عشر جزءا كبيراً، وجاء التفسير مطبوعاً في ثلاثين جزءا كبيراً، من الأجزاء الكبار التي يكون كل جزء منها مجلداً.', 'قيمة الزمن عند العلماء', null, 43, '{}', false, 'published'),
  ('137999d1-8653-494f-85d6-e5402c09852f', null, '33333333-3333-4333-8333-000000000002', 'saying', 'فاحسب حساب الباقي من أوراق مصنفاته، وهو ٣٥١ ألف ورقة، لتعرف كم تبلغ مؤلفات هذا الإمام، الذي كان في علومه بمثابة مجمع علمي واسع الفنون، وفي كثرة تآليفه بمثابة دار للنشر، وهو فرد واحد بنفسه، يكتب بقلمه لنفسه، ويؤلف على ورقة بنفسه، ويخرج للناس فكره وعلمه: عسلا مصفى وزبدا شهيا، وما كان يكون له كل ذلك، لولا أنه كان يكسب وقته، ويدري كيف يملؤه بالاستفادة والتأليف.', 'قيمة الزمن عند العلماء', null, 43, '{}', false, 'published'),
  ('77595718-bf4c-4fdf-9190-4ab4b911ac3c', null, '33333333-3333-4333-8333-000000000002', 'saying', 'كان إذا أكل نام في الخيش - ثياب في نسجها رقة، وخيوطها غلاظ، تتخذ من مشاقة الكتان، تلبس في الحر عند النوم لبرودتها على الجسم -، في قميص قصير الأكمام، مصبوغ بالصندل وماء الورد.', 'قيمة الزمن عند العلماء', null, 44, '{}', false, 'published'),
  ('18853588-fcee-4977-bf2f-db0dccbaa5ba', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ذكر أبو عبد الله بن الحاكم الشهيد، قال: عهدت الحاكم وهو يصوم يوم الإثنين والخميس، ولا يدع صلاة الليل في السفر والحضر، وكان يقعد والسفط والكتب والمحبرة بين يديه، وهو وزير السلطان، فيأذن لمن لا يجد بدا من الإذن له، ثم يشتغل بالتصنيف، فيقوم الداخل. ولقد شكاه أبو العباس بن حمويه، قال: ندخل عليه ولا يكلمنا، ويأخذ القلم بيده ويدعنا ناحية!', 'قيمة الزمن عند العلماء', null, 46, '{}', false, 'published'),
  ('360c9655-a55c-4d6f-bb43-59e719df2b88', null, '33333333-3333-4333-8333-000000000002', 'saying', 'قال الحاكم أبو عبد الله الحافظ صاحب ((المستدرك)): ولقد حضرت عشية الجمعة مجلس الإملاء للحاكم أبي الفضل، ودخل أبو علي بن أبي بكر بن المظفر الأمير، فقام له قائما ولم يتحرك من مكانه، ورده من باب الصفة، وقال: انصرف أيها الأمير، فليس هذا يومك)).', 'قيمة الزمن عند العلماء', null, 46, '{}', false, 'published'),
  ('f47c3aeb-07c4-4fc0-9e8d-f9ffa3a16b52', null, '33333333-3333-4333-8333-000000000002', 'saying', 'قال أبو الحسين بن المهتدي بالله - تلميذه -: قال لنا ابن شاهين: صنفت ثلاث مئة مصنف وثلاثين مصنفا، منها ((التفسير الكبير)) ألف جزء، ومنها ((المسند)) ألف وثلاث مئة جزء، و ((التاريخ)) مئة وخمسون جزءا، و ((الزهد)) مئة جزء.', 'قيمة الزمن عند العلماء', null, 47, '{}', false, 'published'),
  ('3feed626-e7d3-434e-a709-8c52e7b5ebcd', null, '33333333-3333-4333-8333-000000000002', 'saying', 'قال محمد بن عمر الداودي القاضي: سمعت ابن شاهين يقول: حسبت ما اشتريت من الحبر إلى هذا الوقت، فكان سبع مئة درهم، قال ابن أبي الفوارس: صنف ابن شاهين ما لم يصنفه أحد)). انتهى.', 'قيمة الزمن عند العلماء', null, 47, '{}', false, 'published'),
  ('7aaa82bb-25de-4ab8-a1cb-cf6d9a172258', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وكان بعض أئمة اللغة العربية يلقب: (المذاكرة)، لشدة تعلقه بمذاكرة على العربية مع كل من يراه من العلماء، قال الحافظ ابن حجر في ((نزهة الألباب في الألقاب)) - مخطوط -: ((المذاكرة، هو المنذر بن عبد الرحمن بن معاوية بن محمد بن عبد الله بن المنذر بن عبد الرحمن بن معاوية بن هشام بن عبد الملك، الأندلسي المرواني.', 'قيمة الزمن عند العلماء', null, 47, '{}', false, 'published'),
  ('82fc08ea-8730-4be8-a20b-4c98c6c65899', null, '33333333-3333-4333-8333-000000000002', 'saying', 'قال أحمد بن مردويه: كان أبو نعيم في وقته مرحولا إليه، لم يكن في أفق من الآفاق أحد أحفظ منه، ولا أسند منه، كان حفاظ الدنيا قد اجتمعوا عنده، وكل يوم نوبة واحد منهم، يقرأ ما يريده إلى قريب الظهر، فإذ قام إلى داره ربما يقرأ عليه في الطريق جزء، وكان لا يضجر، لم يكن له غذاء سوى التسميع والتصنيف)).', 'قيمة الزمن عند العلماء', null, 48, '{}', false, 'published'),
  ('a00ecd24-55dd-4c61-9aec-e66d25986317', null, '33333333-3333-4333-8333-000000000002', 'saying', 'كان أبو الريحان مع الفسحة في التعمير، وجلالة الحال في عامة الأمور، مكبا على تحصيل العلوم، منصبا إلى تصنيف الكتب، يفتح أبوابها، ويحيط بشواكلها وأقرابها - أي بغوامضها وجلياتها -، ولا يكاد يفارق يده القلم، وعينه النظر، وقلبه الفكر، إلا في يومي النيروز والمهرجان من السنة، لإعداد ما تمس إليه - الحاجة - في المعاش، من بلغة الطعام وعلقة الرياش، ثم هجيراه في سائر الأيام من السنة علم يسفر عن وجهه قناع الإشكال، ويحسر عن ذراعيه كمام الإغلاق.', 'قيمة الزمن عند العلماء', null, 49, '{}', false, 'published'),
  ('e8967f66-998e-47f1-b371-7e6012120e25', null, '33333333-3333-4333-8333-000000000002', 'saying', 'حدث الفقيه أبو الحسن علي بن عيسى الولوالجي، قال: دخلت على أبي الريحان وهو يجود بنفسه، قد حشرج نفسه، وضاق به صدره، - قد بلغ من العمر ٧٨ سنة -، فقال لي في تلك الحال: كيف قلت لي يوما: حساب الجدات الفاسدة - وهي التي تكون من قبل الأم -؟', 'قيمة الزمن عند العلماء', null, 49, '{}', false, 'published'),
  ('02315f62-e6e3-43cf-8332-1008450677d6', null, '33333333-3333-4333-8333-000000000002', 'saying', 'فقلت له إشفاقا عليه: أفي هذه الحالة؟ قال لي: يا هذا! أودع الدنيا وأنا عالم بهذه المسألة، ألا يكون خيرا من أن أخليها وأنا جاهل بها، فأعدت ذلك عليه، وحفظ، وعلمني ما وعد، وخرجت من عنده وأنا في الطريق فسمعت الصراخ!)). انتهى.', 'قيمة الزمن عند العلماء', null, 49, '{}', false, 'published'),
  ('c1ecfc46-022e-4c7b-9489-a685e5d734c0', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وجاء في كتاب ((تبيين كذب المفتري)) للحافظ ابن عساكر، و ((طبقات الشافعية الوسطى)) لتاج الدين السبكي، في ترجمة الإمام سليم الرازي، أحد أئمة السادة الشافعية في عصره، المتوفي سنة ٤٤٧ رحمه الله تعالى، قول التاجي السبكي فيه: ((كان رحمه الله من الورع على جانب قوي، يحاسب نفسه على الأوقات، لا يدع وقتا يمضي بغير فائدة، إما ينسخ أو يدرس أو يقرأ، وينسخ شيئا كثيراً.', 'قيمة الزمن عند العلماء', null, 50, '{}', false, 'published'),
  ('94d4411b-722f-44e1-873d-2a0184aa40cd', null, '33333333-3333-4333-8333-000000000002', 'saying', 'قال الحافظ ابن عساكر: ولقد حدثني عنه شيخنا أبو الفرج الأسفراييني أنه نزل يوما إلى داره ورجع، فقال: قد قرأت جزءا في طريقي. قال أبو الفرج: وحدثني المؤمل بن الحسن أنه رأى سليما حفي عليه القلم، فإلى أن قطة جعل يحرك شفتيه، فعلم أنه يقرأ بإزاء إصلاحه القلم، لئلا يمضي عليه زمان وهو فارغ)). انتهى. أي لما شغلت يداه حرك شفتيه بذكر الله، لئلا يذهب الزمان فارغا، بغير عمل وطاعة، فلله دره ما أعرفه بالغنائم.', 'قيمة الزمن عند العلماء', null, 50, '{}', false, 'published'),
  ('160b3709-d24f-4e19-b8f4-4cbb8a671b54', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقال الحافظ الذهبى في ((تذكرة الحفاظ)) في ترجمة الخطيب البغدادي مؤرخ بغداد ومحدثها، المولود سنة ٣٩٢ والمتوفي سنة ٤٦٣ رحمه الله تعالى: ((كان الخطيب يمشي وفي يده جزء يطالعه)). وما ذلك إلا للحفاظ على الوقت وكسب الزمن أن يهب فارغا أثناء المشي دون استفادة وانتفاع به في جنب العلم.', 'قيمة الزمن عند العلماء', null, 51, '{}', false, 'published'),
  ('e4bc08cb-21f3-415b-bbc9-65143e4b9a61', null, '33333333-3333-4333-8333-000000000002', 'saying', 'قال عبد الغافر الفارسي في كتابه: ((سياق نيسابور)): إمام الحرمين، فخر الإسلام، إمام الأئمة على الإطلاق، حبر الشريعة المجمع على إمامته شرقا وغربا، من لم تر العيون مثله ولا ترى بعده...', 'قيمة الزمن عند العلماء', null, 51, '{}', false, 'published'),
  ('2c3da3f8-e423-4f2d-8f7d-4b508d248d45', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وكان يقول: إني لا يحل لي أن أضيع ساعة من عمري، حتى إذا تعطل لساني عن مذاكرة أو مناظرة، وبصري عن مطالعة، أعملت فكري في حال راحتي وأنا منطرح، فلا أنهض إلا وقد خطر لي ما أسطره، وإني لأجد من حرصي على العلم وأنا في عشر الثمانين أشد مما كنت أجده وأنا ابن عشرين سنة.', 'قيمة الزمن عند العلماء', null, 53, '{}', false, 'published'),
  ('57d8a3e8-a5d6-4a67-b2ba-2fd739e9e035', null, '33333333-3333-4333-8333-000000000002', 'saying', 'قال الشيخ ابن الجوزي: كان الإمام ابن عقيل دائم الاشتغال بالعلم، وكان له الخاطر العاطر، والبحث عن الغوامض والدقائق، وجعل كتابه المسمى ب ((الفنون)) مناطا لخواطره وواقعاته.', 'قيمة الزمن عند العلماء', null, 54, '{}', false, 'published'),
  ('62d49a24-9268-4655-95ea-0e1a67bf1e97', null, '33333333-3333-4333-8333-000000000002', 'saying', 'قال الحافظ الذهبي: لم يصنف في الدنيا أكبر من هذا الكتاب، حدثني من رأى منه المجلد الفلاني بعد الأربع مئة. قال ابن رجب: وقال بعضهم: هو ثماني مئة مجلدة)). انتهى.', 'قيمة الزمن عند العلماء', null, 54, '{}', false, 'published'),
  ('3bb8a96a-f4f2-4830-ac26-8e6f183a59b2', null, '33333333-3333-4333-8333-000000000002', 'saying', 'فما أزال أعلق ما أستفيده من ألفاظ العلماء، ومن بطون الصحائف، ومن صيد الخواطر التي تنثرها المناظرات والمقابسات، في مجالس العلماء، ومجامع الفضلاء، طمعا في أن يعلق بي طرف من الفضل، أبعد به عن الجهل، لعلي أصل إلى بهض ما وصل إليه الرجال قبلي؟!', 'قيمة الزمن عند العلماء', null, 55, '{}', false, 'published'),
  ('405948c8-8e4d-46ac-af7e-512c068cd2cb', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ولو لم يكن من فائدته عاجلا إلا تنظيف الوقت عن الاشتغال برعونات الطباع، التي تنقطع بها أوقات الرعاع، لكفى، وعلى الله قصد السبيل، وهو حسبي ونعم الوكيل)). انتهى.', 'قيمة الزمن عند العلماء', null, 55, '{}', false, 'published'),
  ('480648ac-e3ad-45cc-bcc5-e3189937ad15', null, '33333333-3333-4333-8333-000000000002', 'saying', 'قال ابن الجوزي: ولما أدركت الوفاة الإمام أبا الوفاء ابن عقيل واحتضر بكى النساء! فقال أبو الوفاء: قد وقعت عن الله خمسين سنة - يعني أنه كان يوقع الفتاوى التي يبين فيها أحكام الله في الوقائع والحوادث التي تقع للناس، فكان يوقع فيها نيابة عن الله تعالى -، فدعوني أتهنأ بلقائه.', 'قيمة الزمن عند العلماء', null, 55, '{}', false, 'published'),
  ('7f8ea27f-a492-4072-81a5-dfe29dc77e48', null, '33333333-3333-4333-8333-000000000002', 'saying', 'فانظر أيها القارئ الكريم - رعاك الله وإياي - كيف يثمر إعمال الخاطر، وحفظ الوقت، ودأب النفس في الخير والعلم، إنه ليثمر ثمرات لا تكاد تصدق وإنها لصدق، يثمر (ثماني مئة مجلدة): أكبر كتاب في الدنيا، يؤلفه فرد واحد من الناس أبو الوفاء ابن عقيل، إلى جانب تآليف كثيرة غيره، ألفها، تبلغ نحو العشرين مؤلفا، وبعضها في عشر مجلدات.', 'قيمة الزمن عند العلماء', null, 56, '{}', false, 'published'),
  ('149d7789-4199-4a3d-ac5a-0111263e11f4', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ابن الجوزي أربت تآليفه على ٥٠٠ مؤلف بحفظ الوقت وأما الإمام أبو الفرج ابن الجوزي (عبد الرحمن بن علي الحنبلي البغدادي)، فقد ولد سنة ٥٠٨، وتوفي سنة ٥٩٧، وعاش تسعا وثمانين سنة، وألف تآليف أربت على خمس مئة كتاب.', 'قيمة الزمن عند العلماء', null, 56, '{}', false, 'published'),
  ('31756447-0038-4d58-b8ed-cc353271012f', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ينبغي للإنسان أن يعرف شرف زمانه وقدر وقته، فلا يضيع منه لحظة في غير قربة، ويقدم - فيه - الأفضل فالأفضل من القول والعمل. ولتكن نيته في الخير قائمة من غير فتور، بما لا يعجز عنه البدن من العمل، كما جاء في الحديث الشريف: ((نية المؤمن خير من عمله))، وقد كان جماعة من السلف يبادرون اللحظات، فنقل عن عامر بن عبد قيس - أحد التابعين العباد الزهاد - أن رجلا قال له: (كلمني) فقال له عامر: أمسك الشمس.', 'قيمة الزمن عند العلماء', null, 57, '{}', false, 'published'),
  ('ff6610a4-d123-4855-a0a2-d094cea86fdd', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقد رأيت عموم الخلائق يدفعون الزمان دفعا عجيبا! إن طال الليل فبحديث لا ينفع، أو بقراءة كتاب فيه عزل وسمر، وإن طال النهار فبالنوم، وهم في أطراف النهار على دجلة أو في الأسواق - وكان ابن الجوزي يعيش في بغداد - فشبهتهم بالمتحدثين في سفينة وهي تجري بهم، وما عندهم خبر!! ورأيت النادرين قد فهموا معنى الوجود، فهم في تعبئة الزاد والتهيؤ للرحيل، فالله الله في مواسم العمر، والبدار البدار قبل الفوات، ونافسوا الزمان.', 'قيمة الزمن عند العلماء', null, 57, '{}', false, 'published'),
  ('c8aac113-835a-41fa-b76d-7e636800f509', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وأعوذ بالله من صحبة البطالين! لقد رأيت خلقا كثيرا يجرون معي فيما اعتاده الناس من كثرة الزيارة، ويسمون ذلك التردد: خدمة! ويطيلون الجلوس، ويجرون فيه أحاديث الناس وما لا يعني، ويتخلله غيبة. وهذا شيء يفعله في زماننا كثير من الناس، وربما طلبه المزور، وتشوق إليه، واستوحش من الوحدة، وخصوصا في أيام التهاني والأعياد، فتراهم يمشي بعضهم إلى بعض، ولا يقتصرون على الهناء والسلام، بل يمزحون ذلك بما ذكرته من تضييع الزمان!', 'قيمة الزمن عند العلماء', null, 58, '{}', false, 'published'),
  ('d934cf7b-d17d-4d2a-8652-3e6c995b116c', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقد كان القدماء - يعنى السلف - يحذرون من تضييع الزمان، قال الفضيل بن عياض: أعرف من يعد كلامه من الجمعة إلى الجمعة. ودخلوا على رجل من السلف، فقالوا: لعلنا شغلناك؟ فقال: أصدقكم، كنت أقرأ فتركت القراءة لأجلكم! وجاء عابد إلى السري السقطي، فرأى عنده جماعة، فقال: صرت مناخ البطالين! ثم مضى ولم يجلس. ومتى لان المزور طمع فيه الزائر فأطال الجلوس، فلم يسلم من أذى. وقد كان جماعة قعدوا عند معروف الكرخي، فأطالوا، فقال: إن ملك الشمس لا يفتر عن سوقها، فمتى تريدون القيام؟!', 'قيمة الزمن عند العلماء', null, 59, '{}', false, 'published'),
  ('365f77d9-ea9f-49aa-8144-86bfb498ef23', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وكان جماعة من السلف يحفظون اللحظات، وكان داود الطائي يستف الفتيت، ويقول: بين سف الفتيت وأكل الخبز قراءة خمسين آية. وكان عثمان الباقلاوي دائم الذكر لله تعالى، فقال: إني وقت الإفطار أحس بروحي كأنها تخرج! لأجل اشتغالي بالأكل عن الذكر. وأوصى بعض السلف أصحابه فقال: إذا خرجتم من عندي فتفرقوا، لعل أحدكم يقرأ القرآن في طريقه، ومتى اجتمعتم تحدثتم.', 'قيمة الزمن عند العلماء', null, 59, '{}', false, 'published'),
  ('27dde02e-0a50-4a0d-9251-248e4378fb23', null, '33333333-3333-4333-8333-000000000002', 'saying', 'والذي يعين على اغتنام الزمان: الانفراد والعزلة مهما أمكن، والاختصار على السلام أو حاجة مهمة لمن يلقي، وقلة الأكل، فإن كثرته سبب النوم الطويل وضياع الليل. ومن نظر في سير السلف، وآمن بالجزاء، بان له ما ذكرته.', 'قيمة الزمن عند العلماء', null, 60, '{}', false, 'published'),
  ('59e8a144-370b-475e-b7d7-f9c5c30ecde1', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ولقد كانت همم القدماء من العلماء علية، تدل عليها تصانيفهم، التي هي زبدة أعمارهم، إلا أن أكثر تصانيفهم دثرت، لأن همم الطلاب ضعفت، فصاروا يطلبون المختصرات، ولا ينشطون للمطولات، ثم اقتصروا على ما يدرسون به من بعضها، فدثرت الكتب ولم تنسخ!', 'قيمة الزمن عند العلماء', null, 60, '{}', false, 'published'),
  ('edf57413-e53b-429a-b3b5-13ae5f0908f4', null, '33333333-3333-4333-8333-000000000002', 'saying', 'فسبيل طالب الكمال في طلب العلم: الاطلاع على الكتب التي قد تخلفت من المصنفات، فليكثر من المطالعة، فإنه يرى من علوم القوم وعلو هممهم ما يشحذ خاطره، ويحرك عزيمته للجد. وما يخلو كتاب من فائدة.', 'قيمة الزمن عند العلماء', null, 61, '{}', false, 'published'),
  ('8187d2e8-32d3-4e05-9cec-874df5c9ca81', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وإني أخبر عن حالي، ما أشبع من مطالعة الكتب، وإذا رأيت كتابا لم أره فكأني وقعت على كنز.', 'قيمة الزمن عند العلماء', null, 61, '{}', false, 'published'),
  ('a3a814a8-6e6e-4d4c-bc01-49f2fa60b912', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ولقد نظرت في ثبت الكتب - أي فهرس الكتب - الموقوفة في المدرسة النظامية، فإذا به يحتوي على نحو ستة آلاف مجلد، وفي ثبت كتب أبي حنيفة، وكتب الحميدي: - محمد بن فتوح الأندلسي البغدادي صاحب ابن حزم -، وكتب شيخنا عبد الوهاب الأنماطي، وابن ناصر، وكتب أبي محمد الخشاب وكانت أحمالا، وغير ذلك من كل كتاب أقدر عليه، ولو قلت: إني قد طالعت عشرين ألف مجلد - أي كتاب - كان أكثر، وأنا بعد في الطلب.', 'قيمة الزمن عند العلماء', null, 61, '{}', false, 'published'),
  ('7be05f88-7dda-48be-abf7-9f35b8b47b18', null, '33333333-3333-4333-8333-000000000002', 'saying', 'فاستفدت بالنظر فيها من ملاحظة سير القوم، وقدر هممهم وحفظهم، وعباداتهم، وغرائب علومهم، ما لا يعرفه من لم يطالع، فصرت أستزري ما الناس فيه، وأحتقر همم الطلاب، ولله الحمد)). انتهى.', 'قيمة الزمن عند العلماء', null, 62, '{}', false, 'published'),
  ('372c62eb-ba52-468c-83c2-f0e0831857e4', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقال الإمام ابن الجوزي أيضا، رحمه الله تعالى، في رسالته اللطيفة التي نصح بها ولده، وسماها: ((لفتة الكبد في نصيحة الولد))، حاضا لولده على حفظ الوقت: ((واعلم يا بني، أن الأيام تبسط ساعات، والساعات تبسط أنفاسا، وكل نفس خزانة، فاحذر أن يذهب نفس بغير شيء، فترى في القيامة خزانة فارغة فتندم!', 'قيمة الزمن عند العلماء', null, 62, '{}', false, 'published'),
  ('389200c7-405a-407c-bde4-d1d1148ae6e7', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وانظر كل ساعة من ساعاتك بماذا تذهب، فلا تودعها إلا إلى أشرف ما يمكن، ولا تهمل نفسك، وعودها أشرف ما يكون من العمل وأحسنه، وابعث إلى صندوق القبر ما يسرك يوم الوصول إليه)). انتهى.', 'قيمة الزمن عند العلماء', null, 62, '{}', false, 'published'),
  ('512fea59-1079-47da-afbc-63b7984c6dc6', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ونقل في مقدمته ما يلي: ((ذكر الحافظ ابن رجب الحنبلي في ((ذيل طبقات الحنابلة)) أن الإمام ابن تيمية، قال في ((أجوبته المصرية)): كان الشيخ أبو الفرج ابن الجوزي كثير التصنيف والتأليف، وله مصنفات في أمور كثيرة، حتى عددتها فرأيتها أكثر من ألف مصنف، ورأيت بعد ذلك ما لم أره)).', 'قيمة الزمن عند العلماء', null, 64, '{}', false, 'published'),
  ('1f236dda-e37d-47a9-ac82-42c54e1d21c4', null, '33333333-3333-4333-8333-000000000002', 'saying', 'قال الضياء المقدسي (تلميذه): وكان لا يضيع شيئا من زمانه، كان يصلي الفجر، ويلقن القرآن، وربما لقن الحديث، ثم يقوم فيتوضأ ويصلي ثلاث مئة ركعة بالفاتحة والمعوذتين إلى قبيل الظهر، فينام نومة فيصلي الظهر، ويشتغل بالتسميع أو النسخ إلى المغرب، فيفطر إن كان صائما، ويصلي العشاء ثم ينام إلى نصف الليل أو بعده.', 'قيمة الزمن عند العلماء', null, 65, '{}', false, 'published'),
  ('a90b403f-f3c1-464f-8b37-9fb4ab61665b', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وجاء في ((عيون الأنباء في طبقات الأطباء)) للطبيب المؤرخ ابن أبي أصيبعة في ترجمة الإمام فخر الدين الرازي المفسر الأصولي المتكلم (محمد بن عمر) المولود سنة ٥٤٣، والمتوفي سنة ٦٠٦ رحمه الله تعالى، عن ٦٣ سنة من العمر، وقد ترك من التآليف نحو مئتي كتاب، ما بين كتاب في اثنين وثلاثين جزءا كالتفسير المشهور له ورسالة في صفحات.', 'قيمة الزمن عند العلماء', null, 65, '{}', false, 'published'),
  ('cccbaf08-5d80-4879-9354-9b4a294f5847', null, '33333333-3333-4333-8333-000000000002', 'saying', 'مد الله له في العمر حتى حدث بجيمع مروياته مرارا، وقصده طلاب العلم من سائر الأقطار، وكانت أوقاته محفوظة، وكلماته معدودة، فلا تمضي له ساعة إلا في قراءة قرآن، أو ذكر، أو تهجد، أو قراءة الناس عليه، وكان يمنع الناس من التحديث في مجلسه بلغو أو غيبة إنسان أو ما لا فائدة فيه. لا يخرج من بيته إلا لحضور جمعة أو عيد أو جنازة، ولا يحضر دور أبناء الدنيا في هناء ولا عزاء.', 'قيمة الزمن عند العلماء', null, 66, '{}', false, 'published'),
  ('27ad8779-2e10-41ef-a4ef-8b13416705ae', null, '33333333-3333-4333-8333-000000000002', 'saying', 'قال ابن النجار تلميذه: لقد طفت الأرض شرقاً وغرباً، ورأيت الأئمة والعلماء والزهاد، فما رأيت أكمل منه ولا أكثر عبادة ولا أحسن سمتا، صحبته قريبا من عشرين سنة ليلا ونهارا، وتأدبت به وخدمته، وقرأت عليه القرآن بجميع مروياته وقراءاته، وسمعت منه أكثر مروياته في الحديث، وقرأت عليه الكتب المطولات واستفدت منه كثيراً.', 'قيمة الزمن عند العلماء', null, 67, '{}', false, 'published'),
  ('1e724c34-4803-4245-aa9c-8358f745e5f9', null, '33333333-3333-4333-8333-000000000002', 'saying', 'قال يحيى بن القاسم مدرس النظامية: كان ابن سكينة عالما عاملا، لا يضيع شيئا من وقته، وكنا إذا دخلنا عليه يقول: لا تزيدوا على (سلام عليكم) مسألة، لكثرة حرصه على المباحثة وتقرير الكلام)). انتهى. والمدرسة النظامية أرقى معاهد العلم في بغداد آنئذ.', 'قيمة الزمن عند العلماء', null, 67, '{}', false, 'published'),
  ('d08cf9e0-ab8d-4a57-9c50-c22a4d492ce7', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وممن حافظوا على الاستفادة من الوقت بشكل عجيب، وحال لا تخطر على بال: الإمام ابن تيمية الجد: مجد الدين أبو البركات عبد السلام بن عبد الله بن تيمية الحراني الحنبلي، المولود في حدود سنة ٥٩٠، والمتوفي سنة ٦٥٣ رحمه الله تعالى.', 'قيمة الزمن عند العلماء', null, 67, '{}', false, 'published'),
  ('3fa99d1a-4e67-475a-9d7d-ca17682ff983', null, '33333333-3333-4333-8333-000000000002', 'saying', 'قلت - القائل ابن رجب -: يشير بذلك إلى قوة حرصه على العلم وحصوله، وحفظه لأوقاته)).', 'قيمة الزمن عند العلماء', null, 68, '{}', false, 'published'),
  ('6b886687-43a2-44b1-aa92-13dfb1bd0eca', null, '33333333-3333-4333-8333-000000000002', 'saying', 'سمعت الشيخ عبد العظيم رحمه الله تعالى يقول: (كتبت بيدي تسعين مجلدة، وكتبت سبع مئة جزء). كل ذلك من علوم الحديث تصنيف غيره، وكتب من مصنفاته وغيرها أشياء كثيرة.', 'قيمة الزمن عند العلماء', null, 69, '{}', false, 'published'),
  ('45ce677a-9bb1-47f1-a83f-cbb805410752', null, '33333333-3333-4333-8333-000000000002', 'saying', 'قال شيخنا: ولم أر ولم أسمع أحدا أكثر اجتهادا منه في الاشتغال، كان دائم الاشتغال في الليل والنهار. قال: وجاورته في المدرسة، يعنى بالقاهرة حماها الله تعالى، بيتي فوق بيته اثنتي عشرة سنة، فلم أستيقظ في ليلة من الليالي، ساعة من ساعات الليل، إلا وجدت ضوء السراج في بيته وهو مشتغل بالعلم، وحتى كان في حال الأكل والكتاب والكتب عنده يشتغل فيها.', 'قيمة الزمن عند العلماء', null, 69, '{}', false, 'published'),
  ('21e95a19-a5e3-4666-bd5c-3cc16718152b', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وذكر من تحقيقه وشدة بحثه وتفننه ما أعجز عن التعبير عنه. قال: وكان لا يخرج من المدرسة لا لعزاء، ولا لهناء، ولا لفرجة، ولا لغير ذلك، إلا لصلاة الجمعة، بل يستغرق كل الأوقات في العلم، رضي الله تعالى عنه وعن والدينا والمسلمين)). انتهى.', 'قيمة الزمن عند العلماء', null, 69, '{}', false, 'published'),
  ('516ef6de-fefc-4fe1-b389-8595f2ebfc03', null, '33333333-3333-4333-8333-000000000002', 'saying', 'كان رحمه الله تعالى كثير المطالعة، سريع المراجعة، لا يكتب شيئا من محفوظه حتى يراجعه في محله، وهذه حالة المشايخ الثقات، والعلماء الأثبات، ولا يرى إلا وهو يصلي أو يتلو أو يصنف أو يقرأ.', 'قيمة الزمن عند العلماء', null, 70, '{}', false, 'published'),
  ('eb7b8f69-0b18-457b-872c-6bd630f7eb54', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وأغرب من هذا في اعتنائه بالعلم: ما مر أنه حفظ يوم موته عدة أبيات، حدها بعضهم بثمانية أبيات، لقنه إياها ابنه، وهذا مما يصدق ما قيل: بقدر ما تتعنى، تنال ما تتمنى، فجزاه الله خيرا عن هذه الهمة العلية. وتوفي بدمشق سنة ٦٧٢، ودفن بسفح جبل قاسيون، وما يزال قبره معروفا هناك، رحمه الله تعالى)). انتهى.', 'قيمة الزمن عند العلماء', null, 71, '{}', false, 'published'),
  ('9213e904-eb8c-4d06-b9da-0fbd33e2bbfe', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ولد سنة ٦٣١ - في بلدة نوا من حوران - وقدم دمشق سنة ٦٤٩، فسكن في المدرسة الرواحية يتناول خبز المدرسة، - قال: وبقيت نحو سنتين لم أضع جنبي إلى الأرض - فحفظ ((التنبيه)) في أربعة أشهر ونصف، وقرأ ربع ((المهذب)) حفظا في باقي السنة على شيخه الكمال إسحاق بن أحمد.', 'قيمة الزمن عند العلماء', null, 71, '{}', false, 'published'),
  ('55f6c4b9-5ba1-4977-a6b8-400b719b2c55', null, '33333333-3333-4333-8333-000000000002', 'saying', 'قال: وكنت اعلق جميع ما يتعلق بها من شرح مشكل، ووضوح عبارة، وضبط اللغة، وبارك الله تعالى في وقتي.', 'قيمة الزمن عند العلماء', null, 72, '{}', false, 'published'),
  ('77273c18-3db7-4209-924b-278282f2b434', null, '33333333-3333-4333-8333-000000000002', 'saying', 'قال أبو الحسن بن العطار: ذكر لي شيخنا رحمه الله تعالى أنه كان لا يضيع له وقتا، لا في ليل ولا في نهار إلا في الاشتغال بالعلم حتى في الطريق يكرر أو يطالع، وأنه دام على هذا ست سنين، ثم أخذ في التصنيف والإفادة والنصيحة وقول الحق. وكان لا يأكل في اليوم والليلة إلا أكلة بعد عشاء الآخرة، ويشرب شربة واحدة عند السحر، ويمتنع من أكل الفواكه والخيار، ويقول: أخاف أن يرطب جسمي ويجلب لي النوم، ولم يتزوج.', 'قيمة الزمن عند العلماء', null, 72, '{}', false, 'published'),
  ('4ecc1a07-b6f2-4bdb-9e88-6667ff205505', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ولازم الاشتغال والتصنيف ونشر العلم، والعبادة والأوراد والصيام والذكر، والصبر على العيش الخشن في المأكل والملبس ملازمة كلية لا مزيد عليها، ملبسه ثوب خام، وعمامته سختيانية صغيرة)). توفي سنة ٦٧٦ رحمه الله تعالى، فكانت حياته ٤٥ سنة، وترك من المؤلفات الكثيرة العظيمة ما قسموه على أيام حياته، فكان لكل يوم فيها أربعة كراريس.', 'قيمة الزمن عند العلماء', null, 72, '{}', false, 'published'),
  ('296bda79-c442-4385-8592-37536a36fdda', null, '33333333-3333-4333-8333-000000000002', 'saying', 'الإمام الفاضل الحكيم العلامة علاء الدين ابن النفيس على بن أبي حزم القرشي - نسبة إلى بلدة قرش من بلاد ما وراء النهر - المولود بدمشق في حدود سنة ٦١٠، والمتوفي بالقاهرة سنة ٦٨٧ رحمه الله تعالى.', 'قيمة الزمن عند العلماء', null, 73, '{}', false, 'published'),
  ('7c212922-5468-4fb5-8b3a-4b4249ea551a', null, '33333333-3333-4333-8333-000000000002', 'saying', 'كان إماما في علم الطب، أوحد، لا يضاهي في ذلك ولا يداني استحضارا ولا استنباطا، وله في الطب التصانيف الفائقة، والتواليف الرائقة.', 'قيمة الزمن عند العلماء', null, 73, '{}', false, 'published'),
  ('bf9f83ba-71c7-4737-bc39-aae2f266b179', null, '33333333-3333-4333-8333-000000000002', 'saying', 'صنف كتاب ((الشامل)) في الطب، وتدل فهرسة هذا الكتاب على أنه يكون في ثلاث مئة سفر، ذكر ذلك بعض أصحابه، وبيض منها ثمانين سفراً. وألف كتاب ((المهذب في الكحل))، و ((شرح القانون لابن سينا)) في عدة أسفار، وغير ذلك في الطب.', 'قيمة الزمن عند العلماء', null, 73, '{}', false, 'published'),
  ('85498afc-d4fb-4703-9b05-bbd9bd535d82', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقال الإمام برهان الدين إبراهيم الرشيدي: كان العلاء بن النفيس، إذا أراد التصنيف، توضع له الأقلام مبرية، ويدير وجهه إلى الحائط، ويأخذ في التصنيف إملاء من خاطره، ويكتب مثل السيل إذا انحدر، فإذا كل القلم وحفى، رمى به وتناول غيره، لئلا يضيع عليه الزمان في بري القلم. وكان يكتب - إذا صنف - من صدره، من غير مراجعة حالة التصنيف.', 'قيمة الزمن عند العلماء', null, 74, '{}', false, 'published'),
  ('7b8328e3-3ae1-4b64-9a1a-6f787b1480b8', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقال السديد الدمياطي الحكيم بالقاهرة، وكان من تلاميذه: اجتمع ليلة هو والقاضي جمال الدين بن واصل، وأنا نائم عندهما، فلما فرغا من صلاة العشاء الآخرة، شرعا في البحث، وانتقلا من علم إلى علم، والشيخ علاء الدين في كل ذلك يبحث برياضة ودون انزعاج، وأما القاضي جمال الدين فإنه كان ينزعج، ويعلو صوته، وتحمر عيناه، وتنتفخ عروق رقبته، ولم يزالا كذلك إلى أن سفر الصبح.', 'قيمة الزمن عند العلماء', null, 74, '{}', false, 'published'),
  ('e0fc9e19-e373-41cb-a4d6-d34f1b2df9e8', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقال آخر: دخل الشيخ علاء الدين مرة إلى الحمام التي في باب الزهومة، فلما كان في بعض تغسيله خرج إلى مسلخ الحمام - موضع نزع الثياب وخلعها - واستدعى بدواة وقلم وورق، وأخذ في تصنيف مقالة في النبض إلى أن أنهاها، ثم عاد ودخل الحمام وكمل تغسيله.', 'قيمة الزمن عند العلماء', null, 75, '{}', false, 'published'),
  ('b88b51d2-7fb4-4625-a9f6-67eeae5006f8', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وكان ذا مروءة، وكان لا يحجب نفسه عن الإفادة ليلا ولا نهارا، وكان يحضر مجلسه في داره جماعة من الأمراء، ومهذب الدين بن أبي حليقة رئيس الأطباء، وشرف الدين الصغير، وأكابر الأطباء، ويجلس الناس على طبقاتهم. وعليه وعلى عماد الدين النابلسي تخرج الأطباء بمصر والقاهرة، وكان قد ابتنى فيها دارا، وفرشها بالرخام حتى إيوانها.', 'قيمة الزمن عند العلماء', null, 75, '{}', false, 'published'),
  ('39522400-1f50-4ef7-9fd0-84e7fb7598bc', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وفي علته التي توفي فيها، أشار عليه بعض أصدقائه الأطباء، بتناول شيء من الخمر، إذ كانت علته تناسب أن يتداوى بها على ما زعموا، فأبى أن يتناول شيئا من ذلك، وقال: لا ألقى الله تعالى وفي باطني شيء من الخمر. ولم يكن متزوجا. ووقف داره هذه، وكتبه، وأمواله على البيمارستان المنصوري.', 'قيمة الزمن عند العلماء', null, 75, '{}', false, 'published'),
  ('639e4a0c-f4bd-41ac-9c2d-97283ca91288', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وبالجملة: كان إماما عظيما، وكان كثير من الأفاضل يقولون: هو ابن سينا الثاني)). انتهى. ولا تنس أن ابن النفيس هو كاشف (الدورة الدموية) في البدن، منذ أكثر من سبعة قرون، ذلك الكشف العظيم الهائل في عالم الطب.', 'قيمة الزمن عند العلماء', null, 76, '{}', false, 'published'),
  ('1098d93f-0baa-4d8e-ae90-d28d6ab301ec', null, '33333333-3333-4333-8333-000000000002', 'saying', 'قال عبد الفتاح: وكان مع هذا الفضل العظيم والنبوغ الباهر في الطب وغيره، يتواضع فيصف نفسه في إجازاته للمستفيدين والمتخرجين به، باسم (المتطبب)، وهو إمام الطب والأطباء في عصره، كما تراه في نموذج من خطه الجميل، المصور في ترجمته في كتاب ((الأعلام)) للزركلي.', 'قيمة الزمن عند العلماء', null, 76, '{}', false, 'published'),
  ('f253d686-423a-4101-b493-1e425b6d9e17', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وأعجب من ذلك حال شيخ الإسلام ابن تيمية أبي العباس أحمد بن عبد الحليم الحراني الدمشقي الحنبلي، المولود سنة ٦٦١، والمتوفي سنة ٧٢٨ رحمه الله تعالى، عن ٥٧ سنة وعن نحو خمس مئة مجلد تأليفا، كان لا يمكن أن يفوت من وقته ساعة دون تعليم أو تأليف أو عبادة، حتى بلغت مؤلفاته المئات، بل لم يمكن حصرها للمتتبعين حتى ولا للشيخ نفسه رحمه الله.', 'قيمة الزمن عند العلماء', null, 76, '{}', false, 'published'),
  ('d8a7967c-f5dc-46fc-a3a8-9d1bc2968636', null, '33333333-3333-4333-8333-000000000002', 'saying', 'جاء في ترجمته عند ابن شاكر الكتبي في ((فوات الوفيات)): ((إن تصانيفه تبلغ ثلاث مئة مجلد، قال الذهبي: وما يبعد أن تصانيفه إلى الآن تبلغ خمس مئة مجلد)). انتهى. وقد ألف تلميذه الإمام ابن القيم في أسماء كتبه رسالة، بلغت صفحاتها ٢٢ صفحة، وذكر فيها ما يقارب ٣٥٠ مؤلف، بين كتاب كبير ورسالة وقاعدة.', 'قيمة الزمن عند العلماء', null, 77, '{}', false, 'published'),
  ('ba0b6028-fbc6-479a-b326-92aa4f824a5a', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وحدثني شيخنا - ابن تيمية - قال: ابتدأني مرض، فقال لي الطبيب: إن مطالعتك وكلامك في العلم يزيد المرض، فقلت له: لا أصبر على ذلك، وأنا أحاكمك إلى علمك، أليست النفس إذا فرحت وسرت قويت الطبيعة، فدفعت المرض، فقال: بلى، فقلت له: فإن نفسي تسر بالعلم، فتقوى به الطبيعة، فأجد راحة، فقال: هذا خارج عن علاجنا)).', 'قيمة الزمن عند العلماء', null, 78, '{}', false, 'published'),
  ('87291929-2a34-435d-a4ab-a3c47bde805b', null, '33333333-3333-4333-8333-000000000002', 'saying', 'اشتغل في بلاده، ومهر وتقدم في الفنون، وقدم دمشق بعد زيارة القدس في صفر سنة ٧٢٥، فبهرت أهلها فضائله، وسمع كلامه الشيخ تقي الدين ابن تيمية، فبالغ في تعظيمه، قال مرة: اسكتوا حتى نسمع كلام هذا الفاضل الذي ما دخل البلاد مثله. ثم انتقل إلى القاهرة، وفيها توفى.', 'قيمة الزمن عند العلماء', null, 79, '{}', false, 'published'),
  ('9204033a-2d20-45f1-aaff-0ff4652597b9', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ومما يحكى عنه من حرصه على العلم وشحه أوقاته، أن بعض أصحابه كان يذكر أنه كان يمتنع كثيرا من الأكل، لئلا يحتاج إلى الشرب، فيحتاج إلى دخول الخلاء، فيضيع عليه الزمان)). انتهى.', 'قيمة الزمن عند العلماء', null, 79, '{}', false, 'published'),
  ('f3bdd710-d62a-43f1-81c0-7c25fc7e583d', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقد كان من زمن قراءته على الشيوخ وإقرائه لتلامذته: قائما بالإفتاء للمستفتين من أهل صنعاء وغيرها حو عشرين سنة، ثم ولي قضاء صنعاء في سنة ١٢٢٩، إلى وفاته ٢١ سنة، وكات رحمه الله تعالى وله ١١٤ مؤلف، سمى هو كثيرا منها في ترجمته.', 'قيمة الزمن عند العلماء', null, 80, '{}', false, 'published'),
  ('7ebcd9d7-4617-4381-8454-55b904c9076f', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وكان يدرس في اليوم أربعة وعشرين درسا - كذا -، وكان أيام اشتغاله بالتفسير والإفتاء يدرس في اليوم ثلاثة عشر درسا في كتب مطولة، وكان يؤلف حتى في مرضه الأخير)).', 'قيمة الزمن عند العلماء', null, 81, '{}', false, 'published'),
  ('73369a02-4866-4a70-889e-bee9cf0f8466', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ولا نبعد بعيداً، فهذا الإمام عبد الحي اللكنوي الهندي المتوفي من نحو مئة سنة، عام ١٣٠٤ عن ٣٩ سنة من العمر، قد زادت مؤلفاته على مئة وعشرة كتب، ما بين كتاب في عدة مجلدات كبار ورسالة في صفحات، وكل كتبه في المباحث المفيدة والمشكلات العصبية.', 'قيمة الزمن عند العلماء', null, 82, '{}', false, 'published'),
  ('f7307fcf-e827-4188-98ba-0ad335893e91', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وأذكر هنا كلمة لشيخنا العلامة محمد زاهد الكوثري رحمه الله تعالى، تعرض فيها لبيان جملة من التفاسير الكبيرة الضخمة للقرآن الكريم خاصة دون سائر العلوم، تدل بضخامتها على اهتمام أصحابها بالعلم ومحافظتهم على الوقت، فتمكنوا من التآليف الكبيرة، بحيث يدهش الإنسان لسماع أخبارها فضلا عن رؤية ذواتها، وكم لله في خلقه من عجائب؟', 'قيمة الزمن عند العلماء', null, 82, '{}', false, 'published'),
  ('9d9e4175-74e9-4087-8af1-71b50c256a06', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وما ألفه أهل العلم في اجتلاء روائع المعاني من القرآن الكريم، مما لا يكاد يحصيه العد، على اختلاف مسالكهم في العناية بالرواية أو الدراية، وفنون الأفنان من علوم القرآن، وعلى تفاوت أذواقهم ومشاربهم في الاهتمام بجهة خاصة من مزايا القرآن المجيد.', 'قيمة الزمن عند العلماء', null, 83, '{}', false, 'published'),
  ('a700fe86-67c9-49f7-99fc-c97856e94f53', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وأرجو القارئ الكريم أن يسمح لي أن أذكر بعض مؤلفات علماء هذه الأمة في هذا الصدد، مما يكون أنموذجا لمساعيهم الجبارة في مضمار تدوين المؤلفات، فها هو تفسير الإمام أبي الحسن الأشعري، المسمى: ((المختزن)) في سبعين مجلدا على ما يذكره المقريزي في ((الخطط))، وتفسير القاضي عبد الحبار الهمذاني، المسمى: ((المحيط)) في مئة سفر.', 'قيمة الزمن عند العلماء', null, 83, '{}', false, 'published'),
  ('0baaa851-e420-4500-9399-6a9b146f7152', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وتفسير أبي يوسف عبد السلام القزويني، المسمى: ((حدائق ذات بهجة))، أقل ما يقال فيه: إنه في ثلاث مئة مجلد، وكان مؤلفه وقفه وجعل مقره مسجد الإمام أبي حنيفة ببغداد، ثم صار في عداد الكتب التي ضاعت في أثناء استيلاء المغول على دار الخلافة ببغداد! إلا أني سمعت من أحد أدباء الهند، أنه رأى قطعة منه في أحد فهارس الخزانات.', 'قيمة الزمن عند العلماء', null, 83, '{}', false, 'published'),
  ('c7381dc2-af61-4934-be8a-f14204207c65', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وللحافظ ابن شاهين تفسير في ألف جزء حديثي، وللقاضي أبي بكر بن العربي ((أنوار الفجر)) في التفسير، في نحو ثمانين ألف ورقة، والمعروف أنه موجود في بلادنا - أي في مكتبات إصطنبول وتركيا -، إلا أني لم أظفر به مع طول بحثي عنه. ولابن النقيب المقدسي أحد مشايخ أبي حيان تفسير يقارب مئة مجلد، يوجد بعض مجلدات منه في خزانات إصطنبول، ويوجد من تلك التفاسير بعض مجلدات في بعض الخزانات فيما أعلم.', 'قيمة الزمن عند العلماء', null, 84, '{}', false, 'published'),
  ('2328a710-0158-4d4a-a860-d86d0fe6c666', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وللعلامة محمد الزاهد البخاري نحو مئة مجلد في التفسير، كما في ((المنهج الصافي)). ولعلماء هذه الأمة تفاسير لا تحصى سوى ما تقدم، على اختلاف مسالكهم. ولهم أيضا مثل هذه الخدمة المشكورة، في تدوين السنن الشارحة للكتاب، المبينة لوجوه الإجمال فيه)). انتهى.', 'قيمة الزمن عند العلماء', null, 84, '{}', false, 'published'),
  ('cdaf4bba-5541-4cc5-9633-5dd6a8a3b9a3', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ابن جرير أعظم مؤلف في الإسلام كثرة تأليف وحسن تصنيف أحرز الإمام ابن جرير الطبري قصب بالسبق في التصنيف، كثرة في إتقان، مع عموم النفع، وقد خلف في مصنفاته ما يقرب من ثلاث مئة ألف ورقة وخمسين ألف ورقة. وهذه أغنى التركات العلمية فيما بلغنا، فتبارك الله أحسن الخالقين.', 'قيمة الزمن عند العلماء', null, 85, '{}', false, 'published'),
  ('ff43ba3d-bff5-4e9a-b22f-656fa82b5813', null, '33333333-3333-4333-8333-000000000002', 'saying', 'فبذلك حاز المعلي والرقيب، فلم يكن أحد من المتقدمين يبلغ مداه في الكثرة مع الإتقان وعموم النفع لوقتنا هذا، فلم يتفق هذا لغيره فيما أظن، فيصح أن يقال: إنه أعظم مؤلف في الإسلام.', 'قيمة الزمن عند العلماء', null, 86, '{}', false, 'published'),
  ('44422f0b-dc57-4b05-9a7c-263778cd3142', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وترك ابن أبي الدنيا ألف تأليف، وابن عساكر ألف تاريخه في ثمانين مجلدا، وقال السيوطي: منتهى التصانيف في الكثرة ابن شاهين، صنف ثلاث مئة وثلاثين مصنفا، منها ((التفسير)) في ألف جزء، و ((المسند)) خمسة عشر مئة - أي ألف وخمس مئة جزء -، قال السيوطي: وهذا من بركات طي الزمان كالمكان، من وراثة الإسراء وليلة القدر. نقله في ((المنح البادية)).', 'قيمة الزمن عند العلماء', null, 87, '{}', false, 'published'),
  ('74874f59-fedd-4792-ac75-019f1e2bb056', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقد ترك الإمام أبو محمد علي بن حزم أربع مئة مجلد، تشتمل على قريب من ثمانين ألف ورقة. وألف الإمام أبو محمد عبد الرحمن بن أبي حاتم الرازي عدة كتب، في الفقه والحديث والتاريخ، منها كتابه ((المسند)) في ألف جزء، ذكره في ((الطبقات السبكية)).', 'قيمة الزمن عند العلماء', null, 87, '{}', false, 'published'),
  ('799762a4-d5a2-4354-affe-be1c55c40260', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وألف أبو عبد الله الحاكم المعروف بابن البيع صاحب ((المستدرك على الصحيحين))، ما يبلغ ألفا وخمس مئة جزء، منها ((تخريج الصحيحين))، و ((العلل) و ((الأماني))، و ((فوائد الشيوخ)) - و ((تاريخ نيسابور)) - وغيرها.', 'قيمة الزمن عند العلماء', null, 87, '{}', false, 'published'),
  ('84b6f191-b890-42e3-9114-71fa41c73148', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وألف تقي الدين ابن تيمية ثلاث مئة مؤلف، في فنون مختلفة، ضمن نحو خمس مئة مجلد. وتلميذه ابن قيم الجوزية نحو الخمسين مجلدا بين ضخم ولطيف.', 'قيمة الزمن عند العلماء', null, 88, '{}', false, 'published'),
  ('c40a41c3-8c2c-43c3-b330-c580971780b0', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وألف الإمام البيهقي ألف جزء، كلها تآليف محررة نادرة المثال، كثيرة الفوائد، وأقام يصوم ثلاثين سنة.', 'قيمة الزمن عند العلماء', null, 88, '{}', false, 'published'),
  ('ca04195d-ca10-4ed3-9ac9-5cda45bf8934', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وترك محمد بن سحنون الإفريقي الشهير كتابه الكبير في مئة جزء، في الفقه والسير والتاريخ وفنون من العلم، وكتاب ((أحكام القرآن)) أيضا، وغيره من الكتب. كثرة مؤلفات أبي بكر بن العربي المعافري وألف الإمام أبو بكر بن العربي المعافري دفين فاس: تفسيره الكبير في ثمانين جزءا، وله تآليف أخرى كشرح ((الترمذي)) و ((الموطأ))، و ((أحكام القرآن)) الكبرى والصغرى، و ((القواصم والعواصم))، و ((المحصول في الأصول))، كلها تصانيف من أعلى طبقة، وغريب الوجود.', 'قيمة الزمن عند العلماء', null, 88, '{}', false, 'published'),
  ('ce3fbf6e-46ce-4f2e-9d0f-db84e66c0dc4', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وألف الإمام أبو جعفر الطحاوي تآليف كثيرة، وكتب في مسألة واحدة، وهي: هل كان حجة عليه الصلاة والسلام بقران أو إفراد أو تمتع: ألف ورقة. وكم لهذا من نظير في علماء الإسلام.', 'قيمة الزمن عند العلماء', null, 88, '{}', false, 'published'),
  ('51b94263-ccf8-431e-85c8-be1f96ba416e', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وكانت تواليفهم تحوي مجلدات، فكانت ((مرآة الزمان)) في التاريخ لسبط بن الجوزي أربعون مجلدا، و ((تاريخ بغداد)) للخطيب أربعة عشر مجلدا، و ((الأغاني)) عشرون مجلدا، و ((كامل)) ابن الأثير ١٢ مجلدا، و ((شرح النبات)) لأبي حنيفة الدينوري بلغ ستين مجلدا. وبلغت تآليف يعقوب بن إسحاق الكندي فيلسوف العرب ٢٣١ كتاب - بل تزيد على ثلاث مئة كتاب -، في الفلسفة والطب والهندسة وعلوم كثيرة.', 'قيمة الزمن عند العلماء', null, 89, '{}', false, 'published'),
  ('9c0e4d27-8260-4988-9fdb-0b2835a1ad9b', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وأكثر منه الشيخ أبو الفيض محب الدين محمد مرتضى الحسيني الواسطي الزبيدي الحنفي - الهندي المولد والمنشأ - نزيل مصر، وكفى ((شرح القاموس)) و ((شرح الإحياء))، دليلا على ذلك، وقد عم نفعهما، ووقع إقبال العالم الإسلامي عليهما، مع تحرير وإتقان)). انتهى كلام العلامة الحجوي باختصار.', 'قيمة الزمن عند العلماء', null, 89, '{}', false, 'published'),
  ('8983b7d0-77c5-49f5-a962-ff387b25f993', null, '33333333-3333-4333-8333-000000000002', 'saying', 'قال عبد الفتاح: هذه كلمة عجلي بشأن المكثرين من التأليف، غير محررة ولا مستوفاة، كتبها العلامة الحجوي رحمه الله تعالى، استطرادا دون تتبع واستقراء، بمناسبة ذكره: كثرة مؤلفات الإمام ابن جرير الطبري.', 'قيمة الزمن عند العلماء', null, 90, '{}', false, 'published'),
  ('acf7f16b-1c7a-41ff-a0c9-430a0474fe2e', null, '33333333-3333-4333-8333-000000000002', 'saying', 'والذي دعاني إلى إيرادها بيان هذا السيل الضخم من التآليف الكثيرة المدهشة، كيف كتبت؟ ومتى جمعت؟ إنما كان ذلك كله بمراعاة الوقت وكسبه واهتباله، دون أن تضيع منه ساعة أو سويعة. وبالحفاظ على الوقت تزخر الآثار، وتطول الأعمار، ويبارك الله تعالى في الأزمان الوجيزة والأعمار القصيرة، والله يؤتي فضله من يشاء، وهو ذو الفضل العظيم.', 'قيمة الزمن عند العلماء', null, 90, '{}', false, 'published'),
  ('722dc785-7aa0-4b72-b299-da135c6fbefb', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وأسوق هنا طرفا وجيزا من ترجمته عن ثلاثة كتب، مقتصرا منها على ما يتعلق بكثرة التطواف، ووفرة المؤلفات، وشدة الحافظ على الأوقات واللحظات.', 'قيمة الزمن عند العلماء', null, 93, '{}', false, 'published'),
  ('7fafeb7d-1ee5-4771-a4cb-84e40aa32b23', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وكان حافظاً ديناً، جمع بين المتون والأسانيد، سمع ببغداد، ثم رجع إلى دمشق، ثم رحل إلى خراسان، ودخل نيسابور وهراة وأصبهان والجبال، وصنف التصانيف المفيدة، وخرج التخاريج، وكان حسن الكلام على الأحاديث، محظوظا في الجمع التأليف، صنف ((التاريخ لدمشق)) في ثمانين مجلدا، أتى فيه بالعجائب، وهو على نسق ((تاريخ بغداد)) - للخطيب البغدادي، من حيث شرطه فيمن ذكرهم فيه، ولكنه أضعافه حجما واتساعا وشمولا وإفادات متنوعة -.', 'قيمة الزمن عند العلماء', null, 94, '{}', false, 'published'),
  ('d46edfe2-eba5-4bb7-815d-5ffa6f3f256f', null, '33333333-3333-4333-8333-000000000002', 'saying', 'قال لي شيخنا الحافظ العلامة زكي الدين أبو محمد عبد العظيم المنذري حافظ مصر، وقد جرى ذكر هذا التاريخ، وأخرج لي منه مجلدا، وطال الحديث في أمره واستعظامه: ما أظن هذا الرجل إلا عزم على وضع هذا التاريخ من يوم عقل على نفسه، وشرع في الجمع من ذلك الوقت، وإلا فالعمر يقصر عن أن يجمع فيه الإنسان مثل هذا الكتاب بعد الاشتغال والتنبه.', 'قيمة الزمن عند العلماء', null, 94, '{}', false, 'published'),
  ('bcfeaf26-d493-4dfc-9ed2-c3b8e756327e', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقال الحافظ الذهبي في ((تذكرة الحفاظ))، في ترجمته: ((الإمام الحافظ الكبير، محدث الشام، فخر الأئمة، أبو القاسم بن عساكر، صاحب التصانيف و ((التاريخ الكبير))، ولد في أول سنة ٤٩٩، وسمع في سنة ٥٠٥، باعتناء أبيه وأخيه الإمام ضياء الدين هبة الله، فسمع... بدمشق، ورحل في سنة عشرين، فسمع... ببغداد، و... بمكة، و... بالكوفة، و... بنيسابور، و... بأصبهان، و...', 'قيمة الزمن عند العلماء', null, 95, '{}', false, 'published'),
  ('64f75cc5-e439-4120-99f2-cf7bcd48be71', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وحدث عنه خلق كثير، ومنهم صاحبه في الرحلة أبو أسعد السمعاني، - ثم عدد الذهبي تواليفه، فبلغت نحو خمسين كتاباً -، وأملي في أبواب العلم أربع مئة مجلس وثمانية - وكل إملاء مجلس منها بمثابة تأليف -.', 'قيمة الزمن عند العلماء', null, 96, '{}', false, 'published'),
  ('8fdcbe51-a187-4db9-9d1f-819548e0f53b', null, '33333333-3333-4333-8333-000000000002', 'saying', 'قال ولده المحدث بهاء الدين القاسم: كان أبي رحمه الله مواظبا على الجماعة والتلاوة، يختم كل جمعة، ويختم في رمضان كل يوم، ويعتكف في المنارة الشرقية - من جامع دمشق -، وكان كثير النوافل والأذكار، ويحيى ليلة النصف - من شعبان - والعيدين بالصلاة والذكر، وكان يحاسب نفسه على لحظة تذهب! لم يشتغل منذ أربعين سنة أي منذ أذن له شيوخه بالرواية والتحديث - إلا بالجمع والتسميع حتى في نزهته وخلواته.', 'قيمة الزمن عند العلماء', null, 96, '{}', false, 'published'),
  ('75d8a413-d4cc-4161-b643-f6a43a0763d3', null, '33333333-3333-4333-8333-000000000002', 'saying', 'جمع نفسه على أشتات العلوم، لا يتخذ غير العلم والعمل، صاحبين له، وهما منتهى أربه، حفظ لا تغيب عنه شاردة، وضبط استوت لديه الطريفة الوتالدة، وإتقان ساوى به من سبقه إن لم يكن فاقه، وسعة علم أثرى بها وترك الناس كلهم بين يديه ذوي فاقة.', 'قيمة الزمن عند العلماء', null, 97, '{}', false, 'published'),
  ('7c3bd72f-fd8e-4683-aaf8-32fd832c365c', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وسمع بالأنبار، والرافقة، والرحبة، وماردين، وماكسين، وغيرها من البلاد الكثيرة، والمدن الشاسعة، والأقاليم المتفرقة، لا ينفك نائي الدار، يعمل مطيه في أقاصي القفار، وحيدا لا يصحبه إلا تقى اتخذه أنيسه، وعزم لا يرى غير بلوغ المآرب درجة نفيسة.', 'قيمة الزمن عند العلماء', null, 98, '{}', false, 'published'),
  ('854cbf8f-2de2-46ca-9142-d52890a2d2ff', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقال شيخه الخطيب أبو الفضل الطوسي: ما نعرف من يستحق هذا اللقب اليوم سواه، يعني لقب (الحافظ). وقال ابن النجار: هو إمام المحدثين في وقته، ومن انتهت إليه الرياسة في الحفظ والإتقان، والمعرفة التامة بعلوم الحديث، والثقة والنبل، وحسن التصنيف والتجويد، وبه ختم هذا الشأن.', 'قيمة الزمن عند العلماء', null, 98, '{}', false, 'published'),
  ('157a992f-2506-4172-a2a4-23f9b1432555', null, '33333333-3333-4333-8333-000000000002', 'saying', 'قال ابن النجار: وسمعت شيخنا عبد الوهاب بن الأمين، يقول: كنت يوما مع الحافظ أبي القاسم بن عساكر وأبي سعد بن السمعاني، نمشي في طلب الحديث ولقاء الشيوخ، فلقينا شيخا، فاستوقفه ابن السمعاني ليقرأ عليه شيئا، وطاف على الجزء الذي هو سماعه في خريطته، فلم يجده وضاق صدره، فقال له ابن عساكر: ما الجزء الذي هو سماعه؟ فقال: كتاب ((البعث والنشور)) لابن أبي داود، سمعه من أبي نصر الزينبي، فقال له: لا تحزن، وقرأه عليه من حفظه أو بعضه. قال ابن النجار: الشك من شيخنا.', 'قيمة الزمن عند العلماء', null, 98, '{}', false, 'published'),
  ('9246e3d0-a6f1-4ef3-bf42-f85768fb2792', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقال فيه الشيخ محيى الدين النووي، ومن خطه نقلت: هو حافظ الشام بل هو حافظ الدنيا، الإمام مطلقا، الثقة الثبت.', 'قيمة الزمن عند العلماء', null, 99, '{}', false, 'published'),
  ('90d46d6b-6449-4407-80c7-7569f99a3270', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وحكى ولده الحافظ أبو محمد القاسم، قال: كان أبي قد سمع كتبا كثيرة لم يحصل منها نسخا، اعتمادا منه على نسخ رفيقه الحافظ أبي علي بن الوزير، وكان ما حصله ابن الوزير لا يحصله أبي، وما حصله أبي لا يحصله ابن الوزير.', 'قيمة الزمن عند العلماء', null, 99, '{}', false, 'published'),
  ('c8fb9c30-149f-4605-ba5c-5cd93cf27da4', null, '33333333-3333-4333-8333-000000000002', 'saying', 'فسمعته ليلة من الليالي، وهو يتحدث مع صاحب له في ضوء القمر في الجامع، فقال: رحلت وما كإني رحلت! وحصلت وما كأني حصلت! كنت أحسب أن رفيقي ابن الوزير يقدم بالكتب التي سمعتها، مثل ((صحيح البخاري)) و ((مسلم))، وكتب ((البيهقي))، وعوالي الأجزاء، فاتفقت يكناه بمرو وإقامته بها.', 'قيمة الزمن عند العلماء', null, 99, '{}', false, 'published'),
  ('8a9cbbab-40a6-44d4-b26a-a642db1e3c62', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وكنت أؤمل وصول رفيق آخر، يقال له: يوسف بن فاروا الجياني، ووصول رفيقنا أبي الحسن المرادي، فإنه يقول لي: ربما وصلت إلى دمشق، وتوجهت منها إلى بلدي الأندلس، وما أرى واحدا منهم جاء إلى دمشق، فلابد من الرحلة ثالثا، وتحصيل الكتب الكبار، والمهمات من الأجزاء والعوالي.', 'قيمة الزمن عند العلماء', null, 99, '{}', false, 'published'),
  ('90e0bd70-aa5e-48bb-9de0-3f61bdbddb9c', null, '33333333-3333-4333-8333-000000000002', 'saying', 'المسموعات، ففرح أبي بذلك فرحا شديدا، وشكر الله سبحانه على ما يسره له من وصول مسموعاته إليه، من غير تعب، وكفاه مؤونة السفر، وأقبل على تلك الكتب فنسخ واستنسخ، حتى أتى على مقصودة منها، وكان كلما حصل على جزء منها، كأنه حصل على ملك الدنيا، رحمه الله تعالى ورضي عنه)).انتهى.', 'قيمة الزمن عند العلماء', null, 100, '{}', false, 'published'),
  ('282169bf-ce39-4f66-a94f-798f8017c0be', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ومما يحسن لفت النظر إليه في شأن الزمن: أن العمل العلمي ينزل منزلته من الوقت الملائم له، فمن الأعمال العلمية ما يصلح له كل وقت وذهن، لخفته ويسر القيام به، مثل النسخ والمطالعة الخفيفة والقراءة العابرة ونحوها، مما لا يحتاج إلى ذهن صاف ويقظة تامة وتفكير دقيق عميق.', 'قيمة الزمن عند العلماء', null, 100, '{}', false, 'published'),
  ('3a680eab-a221-4c4c-a082-cf0be98affc6', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ومن الأعمال العلمية ما لا يكتمل حصوله على وجهه الأتم، إلا في الوقات التي تصفو فيها الأذهان، وتنشط فيها القرائح والأفهام، وتكثر فيها البركات والنفحات، كساعات الأسحار والفجر والصباح، وساعات هدأة الليل والفراغ التام والسكون الكامل للمكان.', 'قيمة الزمن عند العلماء', null, 100, '{}', false, 'published'),
  ('9b6d3bad-d832-4f27-8023-63debf5f3bb0', null, '33333333-3333-4333-8333-000000000002', 'saying', 'قال الحافظ الخطيب البغدادي في كتابه ((الفقيه والمتفقه))، وهو يتحدث عن أفضل أوقات الحفظ، وأجود الأماكن المساعدة عليه: ((اعلم أن للحفظ ساعات ينبغي لمن أراد التحفظ أن يراعيها، وأن للحفظ أماكن ينبغي للمتحفظ أن يلزمها.', 'قيمة الزمن عند العلماء', null, 102, '{}', false, 'published'),
  ('eea01b18-4932-46b9-8ffb-64a65f9353ed', null, '33333333-3333-4333-8333-000000000002', 'saying', 'فأجود الأوقات: الأسحار، ثم بعدها وقت انتصاف النهار، وبعدها الغدوات دون العشيات. وحفظ الليل أصلح من حفظ النهار، وأوقات الجوع أحمد للتحفظ من أوقات الشبع. وينبغي للمتحفظ أن يتفقد من نفسه حال الجوع، فإن بعض الناس إذا أصابه شدة الجوع والتهابه لم يحفظ، فليطفئ ذلك عن نفسه بالشيء الخفيف اليسير، ولا يكثر الأكل.', 'قيمة الزمن عند العلماء', null, 102, '{}', false, 'published'),
  ('c1ebc303-b2a0-436d-9abc-ffc80f4a4d36', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وأجود أماكن الحفظ: الغرف دون السفل، وكل موضع بعيد مما يلهي، وخلا القلب فيه مما يقرعه فيشغله، أو يغلب عليه فيمنعه. وليس بالمحمود أ، يتحفظ الرجل بحضرة النبات والخضرة، ولا على شطوط الأنهار، ولا على قوارع الطرق، فليس يعدم في هذه المواضع غالبا ما يمنع من خلو القلب وصفاء السر)). انتهى كلام الخطيب.', 'قيمة الزمن عند العلماء', null, 102, '{}', false, 'published'),
  ('9b74ba40-aab0-437e-9904-a3a152322d63', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وإنما استحبوا لطلبة العلم: الخلوة والبعد عن الناس والضوضاء، لأن الخلوة تعين على صفاء الفكر، وإذا صفا الفكر صح النظر والفهم في طلب المعلومات، وهم يطلبون العلم من ميزان العقل، وهذا الميزان في غاية اللطافة، يتأثر بأدنى هوى أو شاغل، فيخرج عن الاستقامة، فلذا راعوا في تحصيل دقيق العلم والمسائل وصعابها: الزمان والمكان، ليتم لهم الفهم، ويستقيم منهم التصور والحكم.', 'قيمة الزمن عند العلماء', null, 103, '{}', false, 'published'),
  ('2a07c34a-422c-4853-be5c-a2ce589d20e3', null, '33333333-3333-4333-8333-000000000002', 'saying', 'فينبغي للعاقل أن يصرف ذلك الذهن القوي، والوقت الغالي النفيس، في العمل الأفضل والمحصول الأطيب، ليكسب الأغنم والأمثل.', 'قيمة الزمن عند العلماء', null, 104, '{}', false, 'published'),
  ('df39a226-c2e5-40b0-942b-53a505c543f7', null, '33333333-3333-4333-8333-000000000002', 'saying', 'جاء في كتاب ((الحث على طلب العلم)) لأبي هلال العسكري: قال ابن جرو الموصلي: ينبغي أن يؤخر الإنسان درسه للأخبار والأشعار لوقت ملله. وقال ابن المراغي: ينبغي أن يخادع الإنسان نفسه في الدرس. انتهى.', 'قيمة الزمن عند العلماء', null, 104, '{}', false, 'published'),
  ('426be85c-3617-4b40-bf67-5917f51ee6a6', null, '33333333-3333-4333-8333-000000000002', 'saying', 'قلت: يعني بهذا أن الإنسان إذا أدركه ملل أو لحقه فتور، فلا يحسن به أن يستجيب له ويقف عن متابعة الدرس والتحصيل، بل يعالج فتوره ويغالب ملله حتى يتغلب عليه، فينقشع الفتور والملل، ويأتي النشاط والانبساط.', 'قيمة الزمن عند العلماء', null, 105, '{}', false, 'published'),
  ('c4f022e9-73ba-41e5-bf9b-a537d7467cef', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ويحصل ذلك حينا بمضغ اللبان، أو الخروج قليلا من المكان المسقوف إلى الفضاء والهواء، أو بالانتقال والتحول من غرفة إلى غرفة، أو الاستحمام الخفيف بالماء البارد أو الحار، أو تناول شراب لطيف، أو طعام خفيف، أو المحادثة مع صديق أو جليس، أو إنشاد شعر، أو تلاوة قرآن بصوت جاهر، أو تغيير هيأة الجلوس، أو بالمشي أو الصعود، أو تبديل الكتاب المقروء أو الموضوع، أو نحو ذلك من صوارف الفتور والملل، ولكل جسم صلاح، ولكل نشاط مفتاح، ولا يخفى ذلك على الحريصين النبهاء.', 'قيمة الزمن عند العلماء', null, 105, '{}', false, 'published'),
  ('581c557a-d0a2-4184-8628-23b1466c0abe', null, '33333333-3333-4333-8333-000000000002', 'saying', 'فذكر ابن جرير الطبري، وابن الجوزي، والنووي، وابن سينا، والغزالي، وابن حجر العسقلاني، والبدر العيني، والسيوطي، وابن تيمية، وابن القيم، وعلى القاري، والمناوي، وعبد الغني النابلسي، وعبد الحي اللكنوي، وآخرين ممن زادت مؤلفات الواحد منهم على مئة كتاب أو على الخمسين كتاباً.', 'قيمة الزمن عند العلماء', null, 108, '{}', false, 'published'),
  ('cb15de1d-142b-430b-b2a4-aa114cd9fbaa', null, '33333333-3333-4333-8333-000000000002', 'saying', 'فإذا وقفت على تراجم هؤلاء الأفاضل الأعلام وأمثالهم، حفزتك تراجمهم إلى أن تحس بقيمة الوقت والزمن، فتلحق بهم إن كنت من أهل الهمم، فلا تبرح من هذه الدار، إلا وقد خلفت من بنات الأفكار، ما يزيد على الثلاثين والأربعين والخمسين... ويزيد الله في الخلق ما يشاء، ويختص برحمته من يشاء، والله واسع عليم.', 'قيمة الزمن عند العلماء', null, 108, '{}', false, 'published'),
  ('b0cec5a8-42e6-4713-ba12-6f65dcccb17c', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ولحفظ الوقت وكسبه ذكروا قديما في أوصاف طالب العلم الذي يؤهل لتحصيل العلم، ويرجى له النبوغ فيه: أنه ينبغي أن يكون سريع الكتابة، سريع القراءة، سريع المشي.', 'قيمة الزمن عند العلماء', null, 108, '{}', false, 'published'),
  ('f4c0896b-54ff-4e23-96ad-3fb7817b88ec', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وكنت زدت عليها وصفا رابعا، وهو: أن يكون سريع الأكل، لأنه إذا لم يكن كذلك، وكان بطيء الطعام طويل الغرام به! فاته الوقت الذي جمعه بسرعة القراءة والكتابة والمشي، بطول وقت دخول الطعام وخروجه! ولم يحسن التصرف في وقته، ولا عرف كيف يستفيد من امتثال النصيحة على وجهها.', 'قيمة الزمن عند العلماء', null, 109, '{}', false, 'published'),
  ('c36c9a68-4b2b-4847-9da8-23cc9c51e483', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وشيخه الكناني المشار إليه هنا هو: الإمام قاضي القضاة عز الدين أحمد بن إبراهيم الكناني المصري الحنبلي، رحمهما الله تعالى.', 'قيمة الزمن عند العلماء', null, 111, '{}', false, 'published'),
  ('89ae7559-3628-4570-b496-afb6da533694', null, '33333333-3333-4333-8333-000000000002', 'saying', 'فاحرص على كسب الزمان والانتفاع به بتنظيم نفسك وأعمالك وأوقاتك: متعلما أو معلما أو مؤلفا أو مطالعا أو مستمعا أو قارئا تاليا أو عابدا زاكيا، ولا تكن ظالم نفسك في قتل الوقت، مبددا لساعات حياتك ولحظات وجودك! غابنا مغبونا في عمرك!! تصبوا إلى الراحة والكسل، وتزهد في الفضائل والمقام الجلل.', 'قيمة الزمن عند العلماء', null, 111, '{}', false, 'published'),
  ('06b3db9e-4368-4e27-b702-ee7bbc6147ee', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وإنما تقصر الهمم في بعض الأوقات، فإذا حثت سارت، وما تقف همة إلا لخساستها! وإلا فمتى علت الهمة فلا تقنع بالدون.', 'قيمة الزمن عند العلماء', null, 112, '{}', false, 'published'),
  ('0515d834-1b4f-479d-b4fe-6c15a8579dc7', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وعلى الحقيقة فليست الفضائل الكاملة إلا الجمع بين العلم والعمل، فإذا حصلا رفعا صاحبهما إلى المقام الأسمى، فتلك الغاية المقصودة، وعلى قدر أهل العزم تأتي العزائم، فينبغي أن تسمو همتك إلى الكمال، فإن خلقا وقفوا مع الزهد، وخلقا تشاغلوا بالعلم، وندر أقوام جمعوا بين العلم الكامل والعمل الكامل.', 'قيمة الزمن عند العلماء', null, 112, '{}', false, 'published'),
  ('89d4ba56-3d35-458d-a605-c1261c24bb5b', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وليس كل ما يراد مرادا، ولا كل طالب واجدا، ولا كل مبتدئ بأمر محمود مكملا ما بدأ به! وما كل ما يهوى امرؤ هو نائله، وكما قال أبو الطيب: وما كل هاو للجميل بفاعل... ولا كل فعال له بمتمم!', 'قيمة الزمن عند العلماء', null, 112, '{}', false, 'published'),
  ('d2a9f489-82f8-4852-8d01-79a73ab47aeb', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ولكن على العبد الاجتهاد، وكل ميسر لما خلق له، والله المستعان سبحانه)). انتهى بزيادة يسيرة وتصرف يسير.', 'قيمة الزمن عند العلماء', null, 113, '{}', false, 'published'),
  ('cbe2ad54-96b2-4fe9-b49f-84228c4b3915', null, '33333333-3333-4333-8333-000000000002', 'saying', 'إذا كان رأس المال عمرك فاحترز... عليه من الإنفاق في غير واجب فبين اختلاف الليل والصبح معرك... يكر علينا جيشه بالعجائب!', 'قيمة الزمن عند العلماء', null, 113, '{}', false, 'published'),
  ('8636ca66-303a-4e59-8e98-f0f8e069b56a', null, '33333333-3333-4333-8333-000000000002', 'saying', 'والعمر الحقيقي الفعال هو في سن الشباب، ذلك أن الشباب هو ميدان العمل والتحصيل، كما هو ميدان الإنتاج والإعطاء، فالقوة وافية، والهمة عالية، والأمراض والعلل والعوائق - لقلة العلائق - نائية، وقد كانت التابعية الجليلة حفصة بنت سيرين تقول: يا معشر الشباب، خذوا من أنفسكم وأنتم شباب، فإني ما رأيت العمل إلا في الشباب.', 'قيمة الزمن عند العلماء', null, 114, '{}', false, 'published'),
  ('17e973f6-4f32-4f05-99c8-178397b6deda', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وكان العلامة الكبير أبو المعالي محمود شكري الآلوسي البغدادي، الحفيد الأديب المتوفي سنة ١٣٤٢ رحمه الله تعالى، يمتاز بالجد الشديد والحرص على الوقت، فكان لا يثنيه عن دروسه حمارة القيظ، ولا يؤخره عنها قرص برد الشتاء، وكثيرا ما تعرض تلاميذه - بسبب تأخرهم عن موعد الدرس - إلى النقد والتعنيف.', 'قيمة الزمن عند العلماء', null, 116, '{}', false, 'published'),
  ('645cb262-83f3-4cdb-9de5-1a1b7bf6d3a7', null, '33333333-3333-4333-8333-000000000002', 'saying', 'كلما كبرت سنك، كبرت مسئولياتك، وزادت علاقاتك، وضاقت أوقاتك، ونقصت طاقاتك، فالوقت في الكبر أضيق، والجسم فيه أضعف، والصحة فيه أقل، والنشاط فيه أدنى، والواجبات والشواغل فيه أكثر وأشد! فبادر ساعات العمر وهي سانحة، ولا تتعلق بالغائب المجهول، فكل ظرف مملوء بشواغله وأعماله ومفاجآته.', 'قيمة الزمن عند العلماء', null, 117, '{}', false, 'published'),
  ('892e5533-7fee-4b83-931e-0a059dea16e6', null, '33333333-3333-4333-8333-000000000002', 'saying', 'فالعاقل الموفق من يملأ كل لحظة وثانية من حاضر عمره ووقته بفائدة أو عمل صالح، وقد كره سيدنا عمر بن الخطاب رضي الله عنه التعطل والبطالة وإضاعة الزمن سدى! فقال: إني لأكره أن أرى أحدكم سبهللا - أي فارغا - لا في عمل دنيا ولا في عمل آخرة!', 'قيمة الزمن عند العلماء', null, 118, '{}', false, 'published'),
  ('4b45de48-1945-463d-ba19-4619dcee591f', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقد وقفت على مقالة للأستاذ أحمد أمين الكاتب الأديب المصري، المتوفي سنة ١٣٧٣، بعنوان (أوقات الفراغ)، أوردها في كتابه ((فيض الخاطر))، فرأيت إيرادها في ختام هذه الرسالة - باختصار مع تصرف وزيادة كلمات يسيرة - لمناسبتها المقام رجاء الانتفاع بها.', 'قيمة الزمن عند العلماء', null, 118, '{}', false, 'published'),
  ('7128006e-9ae8-44a1-8280-d29538de6d0f', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ومن نتائج ضياع الزمن ضياع كثير من منابع الثروة، كان يمكن أن تستغل لولا إهمال الزمان والجهل باستعماله، فكم من الأراضي البور كان يمكن أن تصلح، ومن الشركات يمكن أن تؤسس، ومن المؤسسات المختلفة يمكن أن تنشأ وتدار بجزء من الزمان الفارغ.', 'قيمة الزمن عند العلماء', null, 119, '{}', false, 'published'),
  ('76ca926e-d280-49cb-b214-98d964d9d8ed', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ولست أريد من المحافظة على الزمن أن يملأ كله بالعمل، وأن تكون الحياة كلها جدا ودأبا، لا راحة فيها ولا مرح، وأن تكون عابسة لا ضحك فيها ولا بشر، وإنما أريد ألا تكون أوقات الفراغ طاغية على أوقات العمل، وألا تكون أوقات الفراغ هي صميم الحياة، وأوقات العمل على حاشيتها وطرفها.', 'قيمة الزمن عند العلماء', null, 119, '{}', false, 'published'),
  ('9ec57bcd-6b11-4e6b-827e-e8ee610ba018', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ومفتاح العلاج لهذه المشكلة: الاعتقاد بأن الإنسان يستطيع أن يغير موضوعات حبه وكرهه كما يشاء، ويستطيع أن يغير ذوقه كما يشاء، فيستطيع أن يمرن ذوقه على أشياء لم يكن يتذوقها من قبل، وعلى كراهية أشياء كان يحبها من قبل، ففي استطاعة أغلب الناس - إذا قويت إرادتهم - أن يقسموا أوقات فراغهم إلى ما ينفعهم صحيا، وإلى ما ينفعهم عقليا، وإلى ما ينفعهم دينيا.', 'قيمة الزمن عند العلماء', null, 120, '{}', false, 'published'),
  ('2adc935a-d7f6-41d0-a107-d14a9c21bcd0', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ومن الأسف أن عامة الناس يعتقدون أن قراءة القصص الحقيقة والمجلات الرخيصة كافية لغذاء عقولهم، فهم يلتهمونها التهاما، ويكتفون بها في لذتهم العقلية، وهي ليست إلا مخدرا للعقل، أو منبها للغرائز الجنسية. وقليل من الصبر وقوة الإرادة يجعل المتعلم صالحا للدراسة الجدية والقراءة المفيدة.', 'قيمة الزمن عند العلماء', null, 120, '{}', false, 'published'),
  ('345e9aa2-8f59-45ec-adae-da476a10432a', null, '33333333-3333-4333-8333-000000000002', 'saying', 'فإذا هو إنسان آخر، له ناحية من نواحي القوة، وله شخصيته المحترمة، وله نفعه لنفسه ولأبناء جنسه وسواهم.', 'قيمة الزمن عند العلماء', null, 121, '{}', false, 'published'),
  ('4a07f65c-6215-4e5b-ba87-adf94d920d5a', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وإذا الأمة غنية بأبنائها في شتى فروع العلم والمعارف والفنون، تعتمد على كل فيما تخصص فيه من نواحي الحياة.', 'قيمة الزمن عند العلماء', null, 121, '{}', false, 'published'),
  ('9c11a877-c8fd-45c2-b221-f4317585ed08', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وإذا الناس في مجالسهم يرقى حديثهم، ويسمو تفكيرهم، وتنضر حياتهم، ويكتسب بعضهم من بعض ثقافة وعلما وأدبا وسلوكا وتقديرا للزمن.', 'قيمة الزمن عند العلماء', null, 121, '{}', false, 'published'),
  ('0019949d-ae03-441d-99fc-cceb6d02a39f', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وإذا الثقافة ارتقت، والعقول اتسعت، والحياة سمت، والقوة ازدادت، وسبل المعيشة تيسرت وازدهرت.', 'قيمة الزمن عند العلماء', null, 121, '{}', false, 'published'),
  ('79730e3c-27a6-431a-8e81-0465cbbaaae9', null, '33333333-3333-4333-8333-000000000002', 'saying', 'فقليل من الزمن يخصص كل يوم لشيء معين، قد يغير عندك مجرى الحياة، ويجعلك أقوم مما تتصور، وأرقى مما تخيل.', 'قيمة الزمن عند العلماء', null, 122, '{}', false, 'published'),
  ('9b49c078-86a6-41cf-b2a4-e545976ef203', null, '33333333-3333-4333-8333-000000000002', 'saying', 'إن الأمة تعيش عشر ما ينبغي أن تعيش! أو أقل من ذلك!! سواء في إنتاجها المالي، أو ثقافتها العقلية، أو حالتها الصحية، وباقي حياتها هدر، في كسل أو خمول! أو بين نرد وشطرنج ولهو ولغز! أو في لا شيء! ولا ينقصها لتعيش كما ينبغي إلا أن تكتشف طريقة ملء الزمن وخضوعه لحكم الشرع والعقل)). انتهى.', 'قيمة الزمن عند العلماء', null, 122, '{}', false, 'published'),
  ('67a91e84-0aa9-4848-bd89-fb7bc6636dd0', null, '33333333-3333-4333-8333-000000000002', 'saying', 'يقال: الوقت من ذهب!! وها صحيح من حيث القيم المادية للذين لا يقيسون الوجود إلا بها، ولكن الوقت هو الحياة للذين ينظرون إلى أبعد من ذلك.', 'قيمة الزمن عند العلماء', null, 122, '{}', false, 'published'),
  ('7f11e1b3-099f-4f7e-b312-8ebaa39da93f', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وليس النجاح متوقفا على الخطة الدقيقة، والظروف المواتية فحسب، ولكنه متوقف على اللحظة المناسبة كذلك، وقد كانوا يحذرون من الرأي الفطير، ومن الرأي المتأخر أيضا، والتوفيق أن يقع العمل في لحظته المناسبة (والله يقدر الليل والنهار).', 'قيمة الزمن عند العلماء', null, 123, '{}', false, 'published'),
  ('2a2ca62a-5cba-406d-b620-8fc22fcb99b4', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وفقنا الله وإياك أيها القارئ الكريم إلى حفظ الوقت وملئه بالعمل الصالح والعلم النافع، وجعلنا من الذين يعرفون قيمة الزمن والحياة، فلا يبغون أنفسهم ولا أمتهم وبلادهم، وأولئك هم الراشدون.', 'قيمة الزمن عند العلماء', null, 124, '{}', false, 'published'),
  ('f0c109dd-1498-4354-8b7c-1e52b588a813', null, '33333333-3333-4333-8333-000000000002', 'saying', 'الحمد لله حمدًا كثيرًا طيبًا مباركًا فيه كما يحب ربُّنا ويرضى، والشكر له على ما أولى من نِعَمٍ سابغةٍ، وأسدى، أحمده سبحانه، وهو الوليُّ الحميد، وأتوب إليه جل شأنه، وهو التواب الرشيد.', 'علو الهمة', null, 5, '{}', false, 'published'),
  ('3acd1709-3fd9-44f0-a4d9-531145b9532e', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وأشهد أن لا إله إلا الله وحده، لا شريك له شهاده نستجلب بها نِعَمَه، ونَستدفع بها نِقَمَه، ونَدَّخِرُها عُدَّةً لنا {يَومَ لا يَنفع مَالٌ وَلَا بَنونَ إِلَّا مَنْ أتى اللَّه بقَلْب سلِيم}.', 'علو الهمة', null, 5, '{}', false, 'published'),
  ('3648af35-ba10-4109-a320-cb14b8abef6c', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وأشهد أن محمدًا عبده ورسولُه، وصَفِيُّه من خلقه وخليلُه، صلى الله عليه، وعلى آله نجوم المهتدين، ورجوم المعتدين.', 'علو الهمة', null, 5, '{}', false, 'published'),
  ('5bbe3d1b-7616-44a2-ba09-819c6e66b86f', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ورضي الله عن صحابته الأبرار الذين قاموا بحق صحبته، وحِفظ شريعته، وتبليغ دينه إلى سائر أمته، فكانوا خير أمة أخرجت للناس.', 'علو الهمة', null, 5, '{}', false, 'published'),
  ('a6dbdab2-9277-4855-a502-4b9c04d44d6c', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ففي قرنٍ وبعض قرنٍ، وثب المسلمون وثبةً ملأوا بها الأرضَ قوةً وبأسًا، وحكمة وعلمًا، ونورًا وهداية، فراضوا الأممَ، وهاضُوا الممالك، وركزوا ألويتَهم في قلب آسيا، وهامات أفريقية، وأطراف أوربة، وتركوا دينَهم، وشرعتَهم، ولغتَهم، وعلمَهم، وأدبَهم، تَدِينُ لها القلوب، وتتقلب بها الألسنةُ، وتَحقَّق فيهم الأنموذج الفريد، والمثال الأعلى للبشرية باعتبارهم "خير أمة أخرجت للناس"، بعد أن كانوا فرائق بَددًا، لا نظام، ولا قوام، ولا علم، ولا شريعة.', 'علو الهمة', null, 5, '{}', false, 'published'),
  ('e82cbce1-b588-4ce7-942f-85473e517218', null, '33333333-3333-4333-8333-000000000002', 'saying', 'لقد قطع المسلمون تلك المرحلة التي سَهَم لها الدهر، ووجم لروعتها التاريخ، وهم يعرفون معالم طريق المجد، ونهج السعادة في الدارين، وأمعنوا بكل ثقة في هذا السبيل مدفوعين بطاقةٍ خارقة، وقوةٍ دافعة، كانوا إذن يدركون بكل دقة معالمَ الطريق كأن معهم "خارطة" مفصلة أودَعُوها "قوتهم العلمية"، وكان الوقود الذى يتزودون به لبلوغ غاياتهم هو "القوة العملية "، ولا حول ولا قوة إلا بالله.', 'علو الهمة', null, 6, '{}', false, 'published'),
  ('f673a586-8262-43de-8797-8089189762dc', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ولن نفيض في ذكر فضائل العلم فذاك حديث يطول، وكم صنف المتقدم والمتأخر في شرفه والحث عليه، ولكن المقصود من هذا المبحث إلقاء الضوء على قسيم العلم وشريكه في صناعة المجد، وإحياء الأمة، ألا وهو "القوة العملية" أو "الإرادة" أو "الهمة".', 'علو الهمة', null, 6, '{}', false, 'published'),
  ('08c9aaf5-4677-417c-aa9b-dcd9891c401c', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وفي "المصباح": الهمة بالكسر: أول العزم، وقد تطلق على العزم القوي، فيقال: له همة عالية.', 'علو الهمة', null, 7, '{}', false, 'published'),
  ('98b6d6e8-8063-4d67-bc4e-6c51ec11506c', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقيل: علو الهمة: "هو استصغار ما دون النهاية من معالي الأمور ".', 'علو الهمة', null, 7, '{}', false, 'published'),
  ('cd47d84c-56b6-4a8a-b669-95253d100a9b', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقيل: "خروج النفْس إلى غاية كمالها الممكن لها في العلم والعمل".', 'علو الهمة', null, 7, '{}', false, 'published'),
  ('864d461f-f9f0-4261-983a-54e840761bed', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وسمعت شيخ الإسلام ابن تيمية -رحمه الله- يقول: في بعض الآثار الِإلهية قول الله تعالى: "إني لا أنظر إلى كلام الحكيم، وإنما أنظر إلى همته".', 'علو الهمة', null, 8, '{}', false, 'published'),
  ('42db2512-0fa9-45ad-a483-24217ea5d278', null, '33333333-3333-4333-8333-000000000002', 'saying', 'قال: والعامة تقول: قيمة كل امرىءٍ ما يحسن. والخاصة تقول: "قيمة كل امرىءٍ ما يطلب"، يريد: أن قيمة المرء همته ومطلبه.', 'علو الهمة', null, 8, '{}', false, 'published'),
  ('ecc1a8f0-fad4-4d38-a4c8-c855756dd835', null, '33333333-3333-4333-8333-000000000002', 'saying', 'الهمة: ما يملك الانبعاث للمقصود صِرفًا، لا يتمالك صاحبها، ولا يلتفت عنها".', 'علو الهمة', null, 8, '{}', false, 'published'),
  ('c3176f90-3b13-4904-b496-72f71a1a4088', null, '33333333-3333-4333-8333-000000000002', 'saying', 'قوله: "يملك الانبعاث للمقصود" أي: يستولي عليه كاستيلاء المالك على المملوك، و "صرفًا" أي: خالصًا صرفًا.', 'علو الهمة', null, 8, '{}', false, 'published'),
  ('4bf3e845-c4b4-45ad-a71c-2356b9005830', null, '33333333-3333-4333-8333-000000000002', 'saying', 'والمراد: أن همة العبد إذا تعلقت بالحق تعالى طلبًا صادقًا خالصًا محضًا، فتلك هي الهمة العالية، التي "لا يتمالك صاحبها" أي: لا يقدر على المهلة، ولا يتمالك صبره، لغلبة سلطانه عليه، وشدة إلزامها إياه بطلب المقصود "ولا يلتفت عنها" إلى ما سوى أحكامها، وصاحب هذه الهمة: سريع وصوله وظفره بمطلوبه، ما لم تعقه العوائق، وتقطعه العلائق، والله اعلم) اهـ.', 'علو الهمة', null, 8, '{}', false, 'published'),
  ('71c20f8e-88c7-47ad-9a74-4350a02996cb', null, '33333333-3333-4333-8333-000000000002', 'saying', 'والهمة طليعة الأعمال ومقدمتها، قال أحد الصالحين: "همتك فاحفظها، فإن، الهمة مقدمة الأشياء، فمن صلحت له همته وصدق فيها، صلح له ما وراء ذلك من الأعمال"، وعن عبيد الله بن زياد بن ظبيان قال: (كان لي خال من "كلب"، فكان يقول لي: "يا عبيد هِمَّ؛ فإن الهمة نصف المروءة ").', 'علو الهمة', null, 9, '{}', false, 'published'),
  ('0abb76f4-9808-4537-8717-13311de86187', null, '33333333-3333-4333-8333-000000000002', 'saying', 'والعادة، يُرى أحدهم أعمى عن مطلوبه لا يدري من يعبد؟ ولا بماذا يعبده؟ فتارة يعبده بذوقه ووَجده، وتارة يعبده بعادة قومه وأصحابه من لبس معين، وكشف رأس أو حلق لحية ونحوها، وتارة يعبده بالأوضاع التي وضعها بعض المتحذلقين وليس لها أصل في الدين، وتارة يعبده بما تحبه نفسه وتهواه كائنًا ما كان، وهنا طرق ومتاهات لا يحصيها إلا رب العباد.', 'علو الهمة', null, 15, '{}', false, 'published'),
  ('5f71ce7b-705b-4cdd-b845-7ff373e5f594', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ذو الهمة إن حُطَّ، فنفسه تأبى إلا عُلُوًّا، كالشعلة من النار يُصَوِّبُها صاحبها، وتأبى إلا ارتَفاعًا".', 'علو الهمة', null, 16, '{}', false, 'published'),
  ('e85150a0-23ac-492a-a4a2-7e0619c03bbb', null, '33333333-3333-4333-8333-000000000002', 'saying', 'كثير من الناس همُّه من دنياه همُّ هذا الشاعر المسكين، شَربة خمر، والتمتع بامرأة حسناء، وقليل من النَّاس تنهض همته إلى الدفاع عن الخائف المستجير.', 'علو الهمة', null, 21, '{}', false, 'published'),
  ('9e043fe4-183b-4aad-b18f-69b929cd07a7', null, '33333333-3333-4333-8333-000000000002', 'saying', 'لقد ضيَّع حياته أولاً في المتع والشهوات، وقضى شطر عمره الثاني في طلب الملك الضائع، وانتهت حياته، ولم يحصِّل مطلوبه، ومات كما مات المتنبي من بعده، طلبًا الملك والإمارة، فأعياهما الطلب) اهـ. بتصرف.', 'علو الهمة', null, 22, '{}', false, 'published'),
  ('a16587cf-652d-4abf-bfc8-ae41745b3824', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وما أكثر الذين طلبوا الملك للرياسة، وألحوا في طلبه، فحامت حوله همتهم، وطافت به عزيمتهم: كان "الأبيوردي" يدعو عقب كل صلاة: "اللهم مَلِّكني مشارق الأرض ومغاربها"، وله في ذلك الأشعار الفائقة، التي تكشف عن شخصية ونفسية شديدة الشبه بشخصية المتنبي.', 'علو الهمة', null, 22, '{}', false, 'published'),
  ('52c822de-2595-44cf-917a-bfbc3c0d17c9', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقيل ليزيد بن المهلب: "ألا تّبني دارًا؟ "، فقال: "منزلي دار الإمارة أو الحبس".', 'علو الهمة', null, 22, '{}', false, 'published'),
  ('48f797fa-e92a-40a5-89f4-729f6135a541', null, '33333333-3333-4333-8333-000000000002', 'saying', 'فالعنكبوت من حين يولد ينسج لنفسه بيتًا، ولا يقبل مِنَّة الأم، والحية تطلب ما حفر غيرها، إذ طبعها الظلم، والغراب يتبع الجيف، والصقر لا يقع إلا على الحِّي، والأسد لا يأكل البايت، والفيل يتملق حتى يأكل، والخنفساء تُطردُ فتعود.', 'علو الهمة', null, 23, '{}', false, 'published'),
  ('1773fb1e-5943-479d-89bb-e4118f90ca15', null, '33333333-3333-4333-8333-000000000002', 'saying', 'والهمة رزق من الله عز رجل، والله يبسط الرزق لمن يشاء ويقدر، ومن حكمته سبحانه أن فاضل بين خلقه في قواهم العملية، كما فاضل بينهم في قواهم العلمية.', 'علو الهمة', null, 24, '{}', false, 'published'),
  ('b4f4fee6-b12d-47a0-81ff-31ba1841c9de', null, '33333333-3333-4333-8333-000000000002', 'saying', 'اجتمع عبد الله بن عمر، وعروة بن الزبير، ومصعب بن الزبير، وعبد الملك بن مروان بفناء الكعبه، فقال لهم مصعب: "تمنَّوا"، فقالوا: "ابدأ أنت"، فقال: "وِلاية العراق، وتزوُّج سكَِينة ابنة الحسين، وعائشة بنت طلحهَ بن عبيد الله"، فنال ذلك، وأصدق كل واحدة خمسمائة ألف درهم، وجهَّزها بمثلها، وتمنى عروة بن الزبير الفقه، وأن يُحمل عنه الحديثُ، فنال ذلك، وتمنى عبد الملك الخلافة، فنالها"، وتمنى عبد الله بن عمر الجنة.', 'علو الهمة', null, 24, '{}', false, 'published'),
  ('ac6c6542-4083-49a4-9498-0892a6c913b2', null, '33333333-3333-4333-8333-000000000002', 'saying', 'لما ولي أمير المؤمنين عمر بن عبد العزيز -رحمه الله- الخلافة خيَّر امرأته "فاطمة" بين أن تقيم معه على أنه لا فراغ له إليها، وبين أن تلحق بأهلها، فبكت، وبكى جواريها لبكائها، فسمعت ضجة في داره، ثم اختارت مقامها معه على كل حال -رحمها الله.', 'علو الهمة', null, 25, '{}', false, 'published'),
  ('b490081d-52b9-4bf9-b36c-5efd1acb8261', null, '33333333-3333-4333-8333-000000000002', 'saying', 'كان أبو موسى الأشعري -رضي الله عنه- يصوم حتي يعود كالخلال -العود الذي يخلل به الأسنان- فقيل له: "لو أجْمَمْتَ نفسك؟ " -أي: تركتها تستريح- فقال: "هيهات! إنما يسبق من الخيل المُضَمَّرة".', 'علو الهمة', null, 27, '{}', false, 'published'),
  ('d778cc6c-52e2-4f71-9061-220a3e5a4063', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ولا ريب عند كل عاقل أن كمال الراحة بحسب التعب، وكمال النعيم بحسب تحمل المشاق في طريقه، وإنما تخلص الراحة واللذة والنعيم في دار السلام، فأما في هذه الدار فكلا ولمَّا) اهـ.', 'علو الهمة', null, 28, '{}', false, 'published'),
  ('00f4cc7c-d0ab-4c0b-98da-f80078c8a61a', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقالت فاطمة بنت عبد الملك في أمير المؤمنين عمر بن عبد العزيز رحمه الله: "ما أعلم أنه اغتسل من جنابة ولا احتلام منذ استُخلِف".', 'علو الهمة', null, 29, '{}', false, 'published'),
  ('cd311ba0-c64c-4083-8836-3bc160dc38d2', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقال الِإمام أحمد لابنه في المحنة: "يا بنى! لقد أعطيتُ المجهود من نفسي".', 'علو الهمة', null, 29, '{}', false, 'published'),
  ('384c4065-bb96-47fb-9423-4c5301648596', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقد قيل للإمام أحمد: "متى يجد العبد طعم الراحة؟ "، فقال: "عند أول قدم في الجنة".', 'علو الهمة', null, 30, '{}', false, 'published'),
  ('108a3fa9-74e0-45ce-9d8c-94977d2d9019', null, '33333333-3333-4333-8333-000000000002', 'saying', 'قال الأمير شمس المعالي قابوس: "ابتناء المناقب باحتمال المتاعب، وإحراز الذكر الجميل بالسعي في الخطب الجليل".', 'علو الهمة', null, 30, '{}', false, 'published'),
  ('3f4472c9-510d-4933-84d1-06625a05b0d4', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقال أحدهم لما عوتب لشدة اجتهاده: "إن الدنيا كانت ولم أكن فيها، وستكون ولا أكون فيها، ولا أحب أن أُغبَنَ أيامى".', 'علو الهمة', null, 30, '{}', false, 'published'),
  ('222de555-be25-4ecb-bada-d18de556bf01', null, '33333333-3333-4333-8333-000000000002', 'saying', 'فترى عالي الهمة منطلقًا بثقة وقوة وإقدام نحو غايته التي حددها على بصيرة وعلم، فيقتحم الأهوال، ويستهين بالصعاب، قال عمرو بن العاص -رضي الله عنه-: "عليكم بكل أمير مَزْلَقة مَهْلَكَة" أي: عليكم بجسام الأمور دون خسائسها.', 'علو الهمة', null, 30, '{}', false, 'published'),
  ('c3a2fb6b-8223-412b-8e27-6db2c8c7f593', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقال أمير المؤمنين معاوية -رضي الله عنه-: "من طلب عظيمًا، خاطر بعظمته".', 'علو الهمة', null, 31, '{}', false, 'published'),
  ('90198c87-1b27-4c71-a1d9-6f97c2ba7e6c', null, '33333333-3333-4333-8333-000000000002', 'saying', 'إذا أنا أبلغت الرسالة جاهدًا... ولم أجد السمع المجيب فما ذنبي (*)؟', 'علو الهمة', null, 33, '{}', false, 'published'),
  ('4fa6f5da-a982-499c-89a4-74bdd6b7c5bc', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وحين جاءه عمر في حروب الردة يقول: "تألف الناس، وارفق بهم"، فقال أبو بكر: "رجوت نصرتك، وجئتني بخذلانك!! أجبار في الجاهلية، وخوار في الِإسلام؟! إنه قد انقطع الوحي، وتم الدين، أوَ يَنْقُص وأنا حي!! ".', 'علو الهمة', null, 36, '{}', false, 'published'),
  ('e8c6f1b0-01ab-48d6-b103-30baf2c5ed86', null, '33333333-3333-4333-8333-000000000002', 'saying', 'قال عمر: "فما هو إلا أن رأيت أن الله شرح صدر أبي بكر للقتال حتى عرفت أنه الحق".', 'علو الهمة', null, 36, '{}', false, 'published'),
  ('cedd0e44-6a1f-485b-81dd-aad78a011c6e', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وكان هذا المبدأ -وهو عدم نقص العزم- هو ما اعتمده فريق من الهاجرين -رضي الله عنهم- حين استشارهم أمير المؤمنين عمر رضي الله عنه، وأخبرهم أن الوباء وقع بالشام، فاختلفوا، فقال بعضهم: "خرجتَ لأمرٍ، ولا نرى أن ترجع عنه".', 'علو الهمة', null, 36, '{}', false, 'published'),
  ('de788477-319b-41a7-bbe1-866f72703e76', null, '33333333-3333-4333-8333-000000000002', 'saying', 'لقد شهدت كذا، وكذا زحفًا، وما في جسدي موضع إلا وفيه ضربة سيف أو طعنة رمح، أو رمية سهم، ثم هأنذا أموت على فراشي حتفَ أنفي كما يموت البعير، فلا نامت أعين الجبناء".', 'علو الهمة', null, 38, '{}', false, 'published'),
  ('b3bc89a3-de8d-49e8-94ae-c2df64bffc9d', null, '33333333-3333-4333-8333-000000000002', 'saying', 'فقالت له أمُّ ولد سعدٍ: "أتَجْعَلُ لي إنْ أنا أطلقتُك أن ترجعَ حتَّى ْأُعيدَكَ في الوَثاق؟! " قال: "نعم"، فأطلقَتْه، وركب فرسًا لسعْدٍ بَلْقاءَ، وحَمَل على المشركين، فجعل سعد يقول: "لولَا أنَ أبا مِحْجَن في الوَثاق لظننتُ أنَّه أبو محجن وأنَّها فَرسي"، وانكشف المشركون، وجاءَ أبو محجن فأعادتْه في الوَثاق، وأتت سعدًا فأخبرتْه، فأرسل إلى أي محجن فأطلقَه، وقال: "والله لا حبستُك فيها أبدًا"، قال أبو محجن: "وأنا واللهِ لا أشربُها بعدَ اليوم أبدًا".', 'علو الهمة', null, 39, '{}', false, 'published'),
  ('d8e853c8-8c3e-47c8-aa13-f6d26a9f8121', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وعن قتادة أن عامر بن قيس لما حُضِر جعل يبكي، فقيل له: ما يبكيك؟ قال.: "ما أبكي جزعًا من الموت، ولا حرصًا على الدنيا، ولكن أبكي على ظمإ الهواجر، وعلى قيام ليالي الشتاء".', 'علو الهمة', null, 39, '{}', false, 'published'),
  ('d2551c54-43c7-415d-a902-f7dad41eff11', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وذكروا لشعبة حديثًا لم يسمعه، فجعل يقول: "واحزناه! "، وكان يقول: "إني لأذكر الحديث، فيفوتني، فأمرض".', 'علو الهمة', null, 39, '{}', false, 'published'),
  ('7ca4242c-5241-4eec-ad1e-02bb8a567cdc', null, '33333333-3333-4333-8333-000000000002', 'saying', 'واقتنى الشيخ جمال الدين بن القفطي نسخة حميلة من كتاب "الأنساب" للسمعاني حُرِّرت بيد المؤلف، إلا أن فيها نقصًا، وبعد الاطِّلاب المديد، والافتقاد الطويل حصل على الناقص، إلا على أوراق بلغه أن قلانسيًّا قد استعملها في شغله، وجعلها قوالب للقلانس، فضاعت، فتأسف غاية التأسف على هذا الضياع، حتى كاد يمرض، وامتنع أيامًا عن خدمة الأمير في قصره، فصارت عِدَّة من الأفاضل والأعيان يزورونه تعزية له، كأنه قد مات أحدُ أقاربه المحبوبين.', 'علو الهمة', null, 40, '{}', false, 'published'),
  ('94ab753d-244e-4a6c-90c0-5c62faf70e73', null, '33333333-3333-4333-8333-000000000002', 'saying', 'إن كبير الهمة على الإطلاق من يتحرى الفضائل، لا للذة، ولا لثروة، ولا لاستشعار نخوة، واستعلاء على البرية، بل يتحرى مصالح العباد شاكرًا بذلك نعمة الله، وطالبًا به مرضاته غير مكترث بقلة مصاحبيه، فإنه إذا عظم المطلوب قلَّ المساعد، وطرق العلاء قليلة الِإيناس.', 'علو الهمة', null, 40, '{}', false, 'published'),
  ('b4800367-00d1-48c0-9bf0-5a7522e0fa7c', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقال الفضيل بن عياض -رحمه الله-: "الزم طريق الهدى، ولا يضرك قلة السالكين، وإياك وطرق الضلالة، ولا تغتر بكثرة الهالكين".', 'علو الهمة', null, 41, '{}', false, 'published'),
  ('32ccc538-a45c-4dc0-a627-17b65e77544a', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقال بعض الصالحين: "انفرادك في طريق طلبك، دليل على صدق الطلب".', 'علو الهمة', null, 42, '{}', false, 'published'),
  ('6b2622da-4065-4a19-aa88-976d4067cf93', null, '33333333-3333-4333-8333-000000000002', 'saying', 'فعالي الهمة ترقى في مدارج الكمال بحيث صار لا يأبه بقلة السالكين، ووحشة الطريق لأنه يُحَصِّل مع كل مرتبة يرتقي إليها من الأنس بالله ما يزيل هذه الوحشة، وإلا انقطع به السبيل.', 'علو الهمة', null, 42, '{}', false, 'published'),
  ('aac5d736-23eb-4579-b836-040502553afe', null, '33333333-3333-4333-8333-000000000002', 'saying', 'والملتفت لنعيق الباطل كالظبي، و "الظبي أشد سعيًا من الكلب، ولكنه إذا أحسَّ به؛ التفت إليه، فيضعف سعيه، فيدركه الكلبُ، فيأخذه".', 'علو الهمة', null, 44, '{}', false, 'published'),
  ('d38eb2e6-f455-4b81-a347-fb00e9c55542', null, '33333333-3333-4333-8333-000000000002', 'saying', 'قال أحمد بن خِضرويه: "القلوب جوالة: فإما أن تجول حول العرش، وإما أن تجول حول الحُشِّ"، وقال بعضهم: "نزول همة الكسَّاح؛ دلَّاه في جُبِّ العَذِرَةِ".', 'علو الهمة', null, 45, '{}', false, 'published'),
  ('012c19d1-2c9b-459e-8e68-5b248fa0a5a4', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقال ابن القيم -رحمه الله-: "الأرواح في الأشباح كالأطيار في الأبراج، وليس ما أعدَّ للاستفراخ كمن هيىء للسباق".', 'علو الهمة', null, 45, '{}', false, 'published'),
  ('482eefae-d2ad-48f3-9a22-aae00e28e042', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وصف سعد بن معاذ -رضي الله عنه- المشركين، فقال: "رأيت قومًا ليس لهم فضل على أنعامهم، لا يهمهم إلا ما يجعلونه في بطونهم وعلى ظهورهم، وأعجب منهم: قوم يعرفون ما جهل أولئك، ويشتهون كشهوتهم".', 'علو الهمة', null, 46, '{}', false, 'published'),
  ('28e08957-474e-4e41-a342-912db9c95068', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وعن محمد بن الحنفية قال: "من كَرُمت عليه نفسه، هانت عليه الدنيا"، وقيل لمحمد بن واسع: "إنك لترضى بالدون"، قال: "إنما رضي بالدون مَن رضي بالدنيا".', 'علو الهمة', null, 46, '{}', false, 'published'),
  ('502e3dec-e061-45a6-aba8-ffc558acc772', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وسفلة الهمم هؤلاء هم الذين أخبر عنهم الصادق المصدوق بقوله: "وأهل النار خمسة: الضعيف الذي لا زَبْر له، الذين هم فيكم تبعًا، لا يبغون أهلًا ولا مالًا" الحديث، فهو قانع بكونه ذيلًا، ومسبوقًا، وتابعا، فارٌّ من المسئولية وتبعاتها.', 'علو الهمة', null, 47, '{}', false, 'published'),
  ('f150448d-9f68-42c2-abb5-ed10e7487d32', null, '33333333-3333-4333-8333-000000000002', 'saying', 'كلما همَّ أحدهم أن يسمو إلى المعالي، ختم الشيطان على قلبه: "عليك ليل طويل، فارقد"، وكلما سعى في إقالة عثرته، والارتقاء بهمته، عاجلته جيوش التسويف والبطالة والتمني، ودعثرته، ونادته نفسه الأمارة بالسوء: "أنت كبر أم الواقع؟ ".', 'علو الهمة', null, 48, '{}', false, 'published'),
  ('6131672f-28ce-4b61-bcae-bcc161a24288', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وأحسن من هذا وأبلغ وأوجز وأفصح قوله تعالى: {كمثل الحمار يحمل أسفارًا بئس مثل القوم الذين كذبوا بآيات الله والله لا يهدي القوم الظالمين}) اهـ.', 'علو الهمة', null, 51, '{}', false, 'published'),
  ('c606e2d8-eaca-4242-b3e9-6cd4557f8405', null, '33333333-3333-4333-8333-000000000002', 'saying', 'فالإنسان مجبول على أن يقصد شيئًا، ويريده، ويستعينه، ويعتمد عليه في تحصيل مطلبه، قد يكون هو الله، وقد يكون غيره، ولكن الإنسان لا يمكن إلا أن يكون كذلك، أي له مراد يقصده، ويتوجه إليه.', 'علو الهمة', null, 52, '{}', false, 'published'),
  ('9c2b8be4-d7dd-4403-8909-e3e397e8ab4b', null, '33333333-3333-4333-8333-000000000002', 'saying', 'والسبب في ذلك أن الإنسان فقير إلى غيره محتاج اليه، كي يَسُدَّ نقصه، ويكمل عجزه، ويحصل حاجته، وفقره هذا دائم لا يتوقف، ولا ينقطع.', 'علو الهمة', null, 52, '{}', false, 'published'),
  ('43fa4ff4-893e-4825-bcd1-5859a6726e5b', null, '33333333-3333-4333-8333-000000000002', 'saying', 'فمن ثم قيل: "ليس في علو الهمة إفراط في الحقيقة"، لأن الهمم العالية طموحة وثَّابة، دائمة الترقي والصعود، لا تعرف الدعة والسكون.', 'علو الهمة', null, 57, '{}', false, 'published'),
  ('3de66628-b52a-498c-8e41-ba5f7e93dbbc', null, '33333333-3333-4333-8333-000000000002', 'saying', 'قال عمر بن عبد العزيز -رحمه الله تعالى- لدُكين لما جاءه: "يا دُكين، إن لي نفسًا توَّاقة، لم تزل تتوق إلى الإمارة، فلما نلتها تاقت إلى الخلافة، فلما نِلتها تاقت إلى الجنة".', 'علو الهمة', null, 57, '{}', false, 'published'),
  ('ce608d57-3e39-4710-9bb9-21e2f9fb5337', null, '33333333-3333-4333-8333-000000000002', 'saying', 'فلو كان يُتصور للآدمي صعود السموات، لرأيت من أقبح النقائص رضاه بالأرض، ولو كانت النبوة تحصل بالاجتهاد، رأيت المقصر في تحصيلها في حضيض.', 'علو الهمة', null, 58, '{}', false, 'published'),
  ('e2373684-4588-4805-9681-9d7e5a355b17', null, '33333333-3333-4333-8333-000000000002', 'saying', 'غير أنه إذا لم يمكن ذلك، فينبغي أن يطلب الممكن، والسيرة الجميلة عند الحكماء: خروج النفس إلى غاية كمالها الممكن لها في العلم والعمل.', 'علو الهمة', null, 58, '{}', false, 'published'),
  ('e80ca363-74d9-45c8-9b5e-9fa61667028e', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ولست آمر بزيادة التقشف الذي يستعمله الموسوس، ولكن التوسط هو المحمود... ).', 'علو الهمة', null, 58, '{}', false, 'published'),
  ('0b4756cf-c450-4aac-b3be-56c883bedfc3', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ومن أقبح النقص: التقليد، فإن قويت همته رقته إلى أن يختار لنفسه مذهبًا، ولا يتمذهب لأحد، فإن المقلد أعمى يقوده مقلده.', 'علو الهمة', null, 59, '{}', false, 'published'),
  ('3b3c98a9-5098-42ef-b464-ff8fbbb4d512', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ولو أمكنك عبور كل أحد من العلماء والزهاد فافعل، فإنهم كانوا رجالًا، وأنت رجل، وما قعد من قعد إلا لدناءة الهمة وخساستها.', 'علو الهمة', null, 59, '{}', false, 'published'),
  ('badc7225-6a13-41d9-ad0e-c95f4c2edb0c', null, '33333333-3333-4333-8333-000000000002', 'saying', 'واعلم أنك في ميدان سباق، والأوقات تنتهب، ولا تخلد إلى كسل، فما فات من فات إلا بالكسل، ولا نال من نال إلا بالجد والعزم.', 'علو الهمة', null, 59, '{}', false, 'published'),
  ('c991460a-3a89-4205-8848-14a198c5b9cf', null, '33333333-3333-4333-8333-000000000002', 'saying', 'إذا ذُكِرَ المجدُ ألفيتَه... تأزَّر بالمجد ثم ارتدى وكبيرو الهمة يتسابقون إلى المكارم، لا يكلون، ولا يملون، ولا، يقنطون {وهل يقنط من رحمة ربه إلا الضالون}.', 'علو الهمة', null, 59, '{}', false, 'published'),
  ('bbbe7151-7006-4da6-a7f3-54220845489e', null, '33333333-3333-4333-8333-000000000002', 'saying', 'قال بعض السلف: "موت العالم ثُلْمَةٌ في الإسلام، لا يسدها شىء".', 'علو الهمة', null, 61, '{}', false, 'published'),
  ('f02b9a3e-1d73-468f-a403-dc36e58b7e9f', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقال أبو بكر رضي الله عنه: "صوت القعقاع -أي: ابن عمرو التيمي- في الجيش خير من ألف رجل".', 'علو الهمة', null, 61, '{}', false, 'published'),
  ('2545b506-6b18-4400-80f9-8a89d418aa01', null, '33333333-3333-4333-8333-000000000002', 'saying', 'لكل قوم نجيبةٌ، وإن نجيبة بني أمية عمر بن عبد العزيز، إنه يُبْعَث أمَةً وَحْدَهُ".', 'علو الهمة', null, 62, '{}', false, 'published'),
  ('218e57c7-9b26-4155-bf6a-0917f36d160d', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقال الأصمعي: لما صافَّ قتيبهُ بن مسلم للترك، وهاله أمرهم، سأل عن محمد بن واسع، فقيل: "هو ذاك في الميمنة جامح على قوسه، يبصبصُ بأصبعه نحوَ السماء"، قال: "تلك الأصبعُ أحبُّ إلَّي من مئة ألف سيف شهير، وشاب طرير".', 'علو الهمة', null, 62, '{}', false, 'published'),
  ('be92f3b9-45eb-4f2a-acad-cdb68c59af7c', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وسئل ابن المبارك عن الجماعة؟ فقال: "أبو بكر وعمر"، فقيل له: "قد مات أبو بكر وعمر"، قال: "فلانٌ وفلان"، قيل: "قد مات فلانٌ وفلان؟ "، قال ابن المبارك: "أبو حمزة السكري جماعة".', 'علو الهمة', null, 62, '{}', false, 'published'),
  ('1a42e961-6a2d-4283-a10e-5d6577d49222', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وإذا كانت لذة كل أحد على حسب قدره وهمته وشرف نفسه، فأشرف الناس نفسَّا، وأعلاهم همة، وأرفعهم قدرًا مَنْ لذتهم في معرفة الله ومحبته، والشوق إِلى لقائه، والتودد إِلية بما يحبه ويرضاه {قل بفضل الله وبرحمته فبذلك فليفرحوا هو خير مما يجمعون}.', 'علو الهمة', null, 64, '{}', false, 'published'),
  ('753149ff-c3e7-4bc4-89f8-8cd8e662d7cf', null, '33333333-3333-4333-8333-000000000002', 'saying', 'فكيف حال من يطلب الملك الكبير في دار النعيم الخالد المقيم؛ أيستكثر مع ذلك أن يصلي ركعتين لله تعالى أو ينفق درهمين أو يسهر ليلتين، كلا بل لو كان له ألف ألف نفس، وألف ألف روح، وألف ألف عمر كل عمر مثل الدنيا وأكبر وأكثر، فبذل ذلك كله في المطلوب العزيز؛ لكان ذلك قليلاً، ولئن ظفر بعده بما طلب، لكان ذلك غُنْمًا عظيمًا، وفضلاً من الذى أعطاه كثيرًا) اهـ.', 'علو الهمة', null, 65, '{}', false, 'published'),
  ('ee8ef803-059d-4a58-92d5-e7b2e55b45c4', null, '33333333-3333-4333-8333-000000000002', 'saying', 'من أراد الآخرة، أضَرَّ بالدنيا، ومن أراد الدنيا أضر بالآخرة، يا قوم! فأضروا بالفاني للباقي".', 'علو الهمة', null, 67, '{}', false, 'published'),
  ('de85e21d-0110-4b5a-8f40-f4beb9b098ad', null, '33333333-3333-4333-8333-000000000002', 'saying', 'فمن نظر إلى "الِإرادة"، وقطع النظر عن "المراد" وقع في هذا الخطإ البين.', 'علو الهمة', null, 68, '{}', false, 'published'),
  ('febda510-9929-4549-b51a-523225a24eae', null, '33333333-3333-4333-8333-000000000002', 'saying', 'فكيف يكون عالَي الهمة مَن أمكنه أن يكون ملِكًا في مقعد صدق عند مليك مقتدر، فتقوم الملائكة في خدمته، وتدخل عليه من كل باب: {سلام عليكم بما صبرتم فنعم عقبى الدار}، فإذا به يتنكب طريق الإيمان، ويتمرغ في وحل الكفر والفسوق والعصيان، ويزهد في جنة الرضوان، ويأبى إلا أن يكون حطبًا للنيران؟!', 'علو الهمة', null, 72, '{}', false, 'published'),
  ('55734303-8d46-4596-bcf6-51c2542d82fd', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقال -عز مِن قائل- في سورة الروم: {وعد الله لا يخلف الله وعده ولكن أكثر الناس} يعني الكفار {لا يعلمون} بحكمته تعالى، في كونه، وأفعاله المحكمة، الجارية علي وفق العدل، لجهلهم وعدم تفكرهم {يعلمون ظاهرًا من الحياة الدنيا} وهو ما يوافق شهواتهم وأهواءهم {وهم عن الآخرة} التي هي المطلب الأعلى {هم غافلون} أي: لا يخطرونها ببالهم، فهم جاهلون بها، تاركون لعملها.', 'علو الهمة', null, 74, '{}', false, 'published'),
  ('85aedee4-8884-48e5-ac47-d26897dc4c9f', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقوله سبحانه: {يعلمون} بدل من قوله: {لا يعلمون} وفي هذا الإبدال من النكتة أنه أبدله منه، وجعله بحيث يقوم مقامه، ويَسُدُّ مَسَدَّه، ليُعلمك أنه لا فرق بين عدم العلم الذي هو الجهل، وبين وجود العلم الذي لا يتجاوز الدنيا.', 'علو الهمة', null, 74, '{}', false, 'published'),
  ('c21b5176-2d3d-4c29-9bb1-191afb3c684a', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وكيف يعجب مسلم بكافر، ويمدحه بعلو الهمة بسبب أعمالٍ غايتها تعمير الدنيا وإصلاحها.', 'علو الهمة', null, 75, '{}', false, 'published'),
  ('5cfa552e-2253-4a3f-a2f6-fc515053a70c', null, '33333333-3333-4333-8333-000000000002', 'saying', 'كبير الهمة على الإطلاق: هو من لا يرضى بالهمم الحيوانية قدر وسعه، فلا يصير عبد عارية ببطنه وفرجه، بل يجتهد أن يتخصص بمكارم الشريعة، فيصير من أولياء الله وخلفائه في الدنيا، ومن مجاوريه في الآخرة، وصغير الهمة من كان على الضد من ذلك.', 'علو الهمة', null, 76, '{}', false, 'published'),
  ('d15828cf-3fdc-400c-93a3-c457dc03d4e2', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وكبير الهمة يُعَظِّمُه صِغَرُ الدنيا في عينيه، فيكون خارجًا من سلطان بطنه، فلا يشتهي ما لا يجد، ولا يُكثر إذا وجد.', 'علو الهمة', null, 76, '{}', false, 'published'),
  ('fa31323c-e082-48ba-81bd-91119cbe14bc', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وحرصوا على إزاحة كل ما قد يعوقهم عن المضِّي قدمًا نحو غايتهم، بما في ذلك فضول المباحات.', 'علو الهمة', null, 77, '{}', false, 'published'),
  ('b0f29dae-4ee9-4509-a855-2838018f8c99', null, '33333333-3333-4333-8333-000000000002', 'saying', 'قال عبد القادر الجيلاني لغلامه: "يا غلام! لايكن همك ما تأكل، وما تشرب، وما تلبس، وما تنكح، وما تسكن، وما تجمع، كل هذا: همُّ النفس والطبع، فأين هم القلب؟! هَمُّك ما أهمك، فليكن همك ربك -عز وجل- وما عنده".', 'علو الهمة', null, 77, '{}', false, 'published'),
  ('6f6a7c8d-0072-4970-b31a-2a53e76cff9d', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ورحل "يحيى بن يحيى" إلى الإمام مالك وهو صغير، وسمع منه وتفقه، (وكان مالك يعجبه سمته وعقله، روي أنه كان يومًا عند مالك في جملة أصحابه؛ إذ قال قائل: "قد حضر الفيل"، فخرج أصحاب مالك لينظروا إليه غيره، (أي: وبقي يحيى مكانه) فقال له مالك: "لم خرج فترى الفيل، لأنه لا يكون بالأندلس"، فقال له يحيى: "إنما جئت من بلدي لأنظر إليك، وأتعلمَ من هديك، وعلمك، ولم أجىء لأنظر إلى الفيل"، فأعجب به مالك، وسماه "عاقل أهل الأندلس").', 'علو الهمة', null, 77, '{}', false, 'published'),
  ('008719be-1b3b-484d-aa46-c83a3f7332da', null, '33333333-3333-4333-8333-000000000002', 'saying', 'إنه من المباح مشاهدة حيوان غريب.. ولكن وقت الداعية القدوة أضيق من أن يشغل شيئًا منه لي مباح، لا يجني من ورائه شيئًا لقضيته التي تشغله ليل نهار.', 'علو الهمة', null, 78, '{}', false, 'published'),
  ('53713fd6-7d94-4499-abf9-384fdad49957', null, '33333333-3333-4333-8333-000000000002', 'saying', 'الأندلس، أهديت إليه جارية جميلة، فنظر إليها، وقال: "إن هذه من القلب والعين بمكان، وإن أنا اشتغلت عنها بهمتي فيما أطلبه ظلمتها، وإن اشتغلت بها عما أطلبه ظلمت همتي، ولا حاجة لي بها الآن، وردَّها على صاحبها".', 'علو الهمة', null, 78, '{}', false, 'published'),
  ('297bb1a5-35cd-4010-9030-47b6c13b00b8', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ودخل أعرابي رث الهيئة بالي العباءة على أمير المؤمنين معاوية -رضى الله عنه-، فاقتحمته عينه، فعرف الأعرابي ذلك في وجه معاوية -رضي الله عنه-، فقال: "يا أمير المؤمنين إن العباءة لا تكلمك، ولكن يكلمك مَن فيها"، فأدناه فإذا به مِدْرَهُ فصاحة في القول وبلاغة، فجعله من خاصته.', 'علو الهمة', null, 79, '{}', false, 'published'),
  ('f10297b5-4b8b-4cef-bcda-dac7447e781c', null, '33333333-3333-4333-8333-000000000002', 'saying', 'لا يُعجبنَّ مُضيمًا حُسْنُ بَزَّتِهِ... وهل تروقُ دفينًا جَوْدَةُ الكَفَنِ؟', 'علو الهمة', null, 79, '{}', false, 'published'),
  ('688ee06c-6668-4658-b479-33a27c8e106b', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ورأينا العجب من صبرهم على شظف العيش، ومعاناة الفقر، إذ كانوا قد أحْصِروا في سبيل حفظ الدين، ووقفوا حياتهم على حراسة السنة، فهذا الإمام العَلَم إبراهيم بن إسحاق الحربي -رحمه الله- يقول: "أفنيت عمري ثلاثين سنة برغيفين، إن جاءتني بهما أمي أو أختي أكلت، وإلا بقيتُ جائعًا عطشان إلى الليلة الثانية، وأفنيتُ ثلاثين سنة من عمري برغيف في اليوم والليلة، إنْ جاءتني امرأتي أو إحدى بناتي به أكلتُه، وإلا بقيتُ جائعًا عطشانَ إلى الليلة الأخرى".', 'علو الهمة', null, 80, '{}', false, 'published'),
  ('1c89ea59-1cd5-4b34-9ef7-c09ff68c0091', null, '33333333-3333-4333-8333-000000000002', 'saying', 'والآن آكلُ نِصفَ رغيف وأربعَ عشرةَ تَمْرَة إن كان بُرنيًّا، أو نيِّفًا وعشرين إن كان دَقَلاً، ومَرِضَتْ ابنتي، فمضَتْ امرأتي، فأقامت عندها شهرًا، فقام إفطاري في هذا الشهر بدرهم ودانِقَين ونصف! ودخلتُ الحمَّامَ، واشتريتُ لهم صابونًا بدانِقَين، فقامَتْ نفقةُ شهر رمضان كله بدرهم وأربعة دوانق ونصف".', 'علو الهمة', null, 80, '{}', false, 'published'),
  ('644232c5-2cd1-4e00-8e9e-91b312a8e29a', null, '33333333-3333-4333-8333-000000000002', 'saying', 'إن هذا الأسود أفضلنا رأيًا وعلمًا، وهو سيدنا وخيرُنا والمقدَّم علينا، وإنما نرجع جميعًا إلى قوله ورأيه، وقد أمَّره الأمير دوننا لما أمره، وأمرنا ألا نخالفَ رأيه وقوله"، ثم قالوا -وكان قولهم عجيبًا عند المقوقس-: "إن الأسود والأبيض سواء عندنا، لا يفضل أحدٌ أحدًا إلَّا بفضله، وعقله، وليس بلونه".', 'علو الهمة', null, 82, '{}', false, 'published'),
  ('a8f24ee5-ddbb-40e9-b2db-dca18b249562', null, '33333333-3333-4333-8333-000000000002', 'saying', 'قال: "والناس بنو آدم وحواء، إخوة لأب وأم"، قال: "ما أحسن هذا! ".', 'علو الهمة', null, 88, '{}', false, 'published'),
  ('5df3822c-86c3-49b3-9361-a5119a98a161', null, '33333333-3333-4333-8333-000000000002', 'saying', 'قال: "إى والله، ثم لا نقرب بلادكم أبدًا إلا في تجارة أو حاجة"، قال: "صدقتني والله، أما إن أهل فارس منذ ولي "أردشير" لم يَدَعُوا أحدًا يخرج من عمله من السِّفْلَة كانوا يقولون: "إذا خرجوا من أعمالهم تعدوا طورهم، وعادوا أشرافهم".', 'علو الهمة', null, 89, '{}', false, 'published'),
  ('392d2474-3561-49e9-81e4-54cb8a01fdef', null, '33333333-3333-4333-8333-000000000002', 'saying', 'قال: "وما موعود الله؟ " قال: "الجنة لمن مات على قتال من أبي، والظفر لمن بقى"..', 'علو الهمة', null, 90, '{}', false, 'published'),
  ('5ccacdb1-5ac4-450b-a8d8-6562a7da60f4', null, '33333333-3333-4333-8333-000000000002', 'saying', 'كلامًا قط أوضح ولا أعز من كلام هذا الرجل؟ "، قالوا: "معاذ الله لك أن تميل إلى شيء من هذا، وتدع دينك لهذا الكلب، أما ترى إلى ثيابه؟ "، فقال: "ويحكم! لا تنظروا إلى الثياب، ولكن انظروا إلى الرأي، والكلام، والسيرة"، وأقبلوا يتناولون سلاحه، ويزهدونه فيه..', 'علو الهمة', null, 90, '{}', false, 'published'),
  ('749448ad-6d36-4274-a313-4ca5a01b3ecf', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وكان "يزدجرد" ملك الفرس قد أرسل يستنجد بملك الصين، ووصف له المسلمين، فأجابه ملك الصين: "إنه يمكنني أن أبعث لك جيشًا أوله في منابت الزيتون -أي: الشام- وآخره في الصين، ولكن إن كان هؤلاء القوم كما تقول؛ فإنه لا يقوم لهم أهل الأرض، فأرى لك أن تصالحهم، وتعيش في ظلهم، وظل عدلهم".', 'علو الهمة', null, 90, '{}', false, 'published'),
  ('ea5509eb-c10b-48df-b663-69638cba1746', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقوله: "نفس عصام سوَّدت عصامًا" صار مثلًا يُضرب في نباهة الرجل من غير قديم.', 'علو الهمة', null, 91, '{}', false, 'published'),
  ('a1804a29-23a7-4383-8996-c4217f5a9fab', null, '33333333-3333-4333-8333-000000000002', 'saying', 'قالت أم المؤمنين عائشة -رضي الله عنها-: "كل كرم دونه لؤم، فاللؤم أولى به، وكل لؤم دونه كرم، فالكرم أولى به".', 'علو الهمة', null, 93, '{}', false, 'published'),
  ('b4ad6c5a-64e2-402e-ad21-3530860bea06', null, '33333333-3333-4333-8333-000000000002', 'saying', 'تريد: أن أولى الأمور بالِإنسان خصالُ نَفسه، وإن كان كريمًا وآباؤه لئام، لم يضره ذلك، وإن كان لئيمًا وآباؤه كرام، لم ينفعه ذلك.', 'علو الهمة', null, 93, '{}', false, 'published'),
  ('cc9a6a12-442c-4f45-8e11-244c1c1b8c0b', null, '33333333-3333-4333-8333-000000000002', 'saying', 'يا أيها الناس! إني امرؤ من قريش، وما منكم من أحمرَ، ولا أسودَ يَفْضُلني بتقوى، إلا وددت أني في مِسْلاخه".', 'علو الهمة', null, 96, '{}', false, 'published'),
  ('d6b4b1cd-29fe-4246-a264-e4538cfbdc86', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وروي أنه قيل لسلمان الفارسي: "انتسب يا سلمان"، قال -رضي الله عنه-: "ما أعرف لي أبًا في الِإسلام، ولكني سلمان ابن الِإسلام".', 'علو الهمة', null, 96, '{}', false, 'published'),
  ('6bfbc1fc-ea03-47fb-83da-48b7f32a3b82', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وما أكثر هذا الافتخار البارد بين خسيسي الهمة الذين ارتكبوا كل رذيلة، وتعروا عن كل فضيلة، ومع ذلك استطالوا بآبائهم على فضلاء البريهّ، واحتقروا أناسًا فاقوهم حسبًا ونسبًا، وشرفوهم أمًّا وأبًا، وهذا هو الضلال البعيد، والحمق الذي ليس عليه مزيد.', 'علو الهمة', null, 99, '{}', false, 'published'),
  ('7689c7a0-b65d-4066-a15b-66e654dd30ad', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ولا يلومَنَّ الشريفُ إلا نفسَه إذا عومل حينئذٍ بما يكره، وقُدِّمَ عليه من هو دُونه في النسب بمراحل.', 'علو الهمة', null, 100, '{}', false, 'published'),
  ('944d65cd-36e4-460d-a398-b42d4fb5e720', null, '33333333-3333-4333-8333-000000000002', 'saying', 'بَيَّضْتُ باطني، وسوَّدتَ باطنك، فَرُؤي بياضُ قلبي فوقَ سوادِ وجهي، فَحَسُنْتُ، وسوادُ قلبِكَ فوقَ بياضِ وجهك، فَقَبُحتَ، وأخذتُ سيرةَ أبيك، وأخذتَ سيرةَ أبي، فرآني الخلقُ في سيرةِ أبيك، ورَأوْكَ في سيرةِ أبي، فظنوني ابنَ أبيك، وظنوكَ ابنَ أبي، فعملوا معك ما يُعمَلُ مع أبى، وعملوا معي ما يُعمل مع أبيك".', 'علو الهمة', null, 100, '{}', false, 'published'),
  ('5d720466-b4c4-4035-94f7-2c99f1f1c065', null, '33333333-3333-4333-8333-000000000002', 'saying', 'أهدى ملك اليمن عشر جزائر إلى مكة، وأمر أن ينحرها أعزُّ قرشي، فقدِمَتْ، وأبو سفيان عروس بهند بنت عتبة، فقالت له: "أيها الرجل، لا يَشغلنَّك النساء عن هذه المكرمة التى لعلها أن تفوتك"، فقال لها: "يا هذه، دَعي زوجَك وما يختاره لنفسه! والله ما نحرها غيرى إلا نحرتُه! "، فكانت في عُقُلِها، حتى خرج أبو سفيان في اليوم السابع، فنحرها.', 'علو الهمة', null, 102, '{}', false, 'published'),
  ('22bcf268-e1a9-46aa-8641-b98c76302c99', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ومن شرف النفس وعلو الهمة ما قالته هند بنت عتبة زوجة أبي سفيان وأم معاوية -رضي الله عنهم- حين أتاها نعي يزيد بن أبي سفيان، وقال لها بعض المُعَزِّين: "إنا لنرجو أن يكون في معاوية خلف من يزيد"، فقالت هند: "أو مثل معاوية يكون خَلَفًا من أحد؟ والله لو جمعت العرب من أقطارها، ثم رُمَي به فِيها، لخرج من أي أعراضها شاء".', 'علو الهمة', null, 102, '{}', false, 'published'),
  ('309acb14-25c4-457f-ba27-cd4d9503c24f', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وكان معاوية -رضي الله عنه- يقول: "إني لآَنَفُ من أن يكون في الأرض جهلٌ لا يسعه حِلمي، وذنب لا يسعه عفوي، وحاجة لا يَسَعها جودي".', 'علو الهمة', null, 103, '{}', false, 'published'),
  ('0c1872ad-5a6c-4363-af46-86e0eea235fc', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ومن أشرف الناس همة عقيل بن علفة المُرِّيُّ، وكان أعرابيًّا يسكن البادية، وكان يُصهر إليه الخلفاء، وخطب إليه "عبد الملك بن مروان" ابنته لأحد أولاده، فقال له: "جَنِّبْني هُجَناءَ ولدكِ".', 'علو الهمة', null, 103, '{}', false, 'published'),
  ('57007944-8693-479c-8142-c91a7f070063', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وعالي الهمة يعرف قدر نفسه، في غير كبر، ولا عجب، ولا غرور، وإذا عرف المرء قدر نفسه، صانها عن الرذائل، وحفظها من أن تُهان، ونزَّهها عن دنايا الأمور، وسفاسفِها في السر والعلن، وجنَّبها مواطن الذل بأن يحملها ما لا تطيق، أو يضعها فيما لا يليق بقدرها، فتبقى نفسه في حصن حصين، وعز منيع لا تعطى الدنية، ولا ترضى بالنقص، ولا تقنع بالدون.', 'علو الهمة', null, 103, '{}', false, 'published'),
  ('672e4ab0-50e1-418e-b2ed-71b70b785529', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ألم تر إلى شرف نفس الكريم بن الكريم بن الكريم بن الكريم نبي الله يوسف بن يعقوب بن إسحاق بن إبراهيم -عليهم وعلى نبينا الصلاة والسلام- حين دعا ربه {ربِّ السجن أحب إلَّي مما يدعونني إليه}، وحين قال لرسول المَلِك: {ارجع إلى ربك فاسأله ما بال النسوة اللاتي قطعن أيديهنَّ إن ربي بكيدهن عليم}، ولا عجب فإن من يصبر فيما له ألا يصبر فيه، وهو الخروج من السجن، مع توفر الدواعي على الخروج منه، فأولى به أن يصبر فيما يجب عليه أن يصبر فيه من الهم بامرأة العزيز.', 'علو الهمة', null, 103, '{}', false, 'published'),
  ('e111abaa-a240-46ca-9081-b21c87a7256a', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقيل لآخر: جئناك في حاجة لا ترزؤك، فقال: "هلا طلبتم لها سفاسف الناس؟ ".', 'علو الهمة', null, 104, '{}', false, 'published'),
  ('07a11f79-4b01-4908-abde-772f7c8d6564', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقد قيل لبعض العلماء: لي سؤال صغير، فقال: "اطلب له رجلًا صغيرًا".', 'علو الهمة', null, 104, '{}', false, 'published'),
  ('66728a8f-5762-4ac4-9113-600ea60da3f3', null, '33333333-3333-4333-8333-000000000002', 'saying', 'إنها لا تعرفك، وكان يرضيها اليسير"، فقال: "إن كان يرضيها اليسير، فأنا لا أرضى إلا بالكثير، وإن كانت لا تعرفني، فأنا أعرف نفسي".', 'علو الهمة', null, 104, '{}', false, 'published'),
  ('9a671344-d251-4812-894d-2c812d8bbcfd', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وسأله سائل بينا يهم بركوب ناقتِه، فنزل له عنها، وعما فوقها، وكان عليها أربعة آلاف درهم، وسيف من سيوف على بن أبي طالب. وعن سعيد بن عبد العزيز أن الحسن بن على بن أبي طالب -رضي الله عنهما- سمع رجلًا إلى جنبه يسأل الله أن يرزقه عشرة آلاف درهم، فانصرف، فبعث بها إليه.', 'علو الهمة', null, 104, '{}', false, 'published'),
  ('82b9bf97-9d2b-4fed-957c-5af048cba631', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وعن أبي سعيد عن شيخ له قال: رأيت ابن المبارك يَعَضُّ يد خادم له، فقلت له: "تعض يَدَ خادِمِكَ؟ " قال: "كم آمره أن لا يَعُدَّ الدراهم على السُّؤال، أقول له: اُحث لهم حَثْوًا".', 'علو الهمة', null, 105, '{}', false, 'published'),
  ('214a8112-1921-42b0-bb79-e13ad18c5796', null, '33333333-3333-4333-8333-000000000002', 'saying', 'أحِبُّ أن أكونَ في موضعٍ لا أُعْرَفُ، ولا أُسْتَذَلُّ"، وقال ابن مهدي: سمعت سفيان الثوري يقول: "وددتُ أني أخذتُ نعلي هذه، ثم جلست حيث شئت، لا يعرفني أحد"، ثم رفع رأسه، ثم قال: "بعد أن لا أُسْتَذَلُّ".', 'علو الهمة', null, 107, '{}', false, 'published'),
  ('d1047902-6c64-497e-8c18-a3179b84c1f6', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ولشدة حذره من الذلة، كان يسكن بين معارفه من الناس الذين يعرفون قدره، وقال -رحمه الله-: "لولا أن أُسْتَذَلَّ" لسكنتُ بين قوم لا يعرفونني".', 'علو الهمة', null, 107, '{}', false, 'published'),
  ('d1242e17-88cc-4f81-b9ee-ad579ec9df8d', null, '33333333-3333-4333-8333-000000000002', 'saying', 'يا أمير المؤمنين! أين يجلس شيخك مالك؟ "، فناداه المهدي: "عندي يا أبا عبد الله! "، فتْخطَّى الناس حتى وصل إليه، فرفع المهدي ركبته اليمنى، وأجلسه بحانبه.', 'علو الهمة', null, 108, '{}', false, 'published'),
  ('dbf3d907-4046-4a36-aed3-8b7e632a1711', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وبهذه العزة أجاب العالم الضرير المحدِّثَ أبو معاوية محمد بن خازم هارون الرشيد، لما صَّب الماء على يديه، وأعلمه بذلك بعد أن فرغ: "إنما أكرمتَ العِلمَ يا أمير المؤمنين".', 'علو الهمة', null, 108, '{}', false, 'published'),
  ('e58e493d-fb5c-43f4-aeeb-d8819b5cb52f', null, '33333333-3333-4333-8333-000000000002', 'saying', 'عزل الإمام "ابن دقيق العيد" -رحمه الله- نفسه عن القضاء في بعض المرات، ثم طُلب ليُوَلِّى، وقام السلطان الملك المنصور "لاجين" له واقفًا لما أقبل، فصار يمشى قليلًا قليلًا، وهم يقولون له: "السلطان واقف"، فيقول: "أديني بأمشى!! "، وجلس معه على الجوخ حتى لا يجلس دونه، وقبَّل السلطان يده، فقال ابن دقيق العيد: "تنتفع بهذا"!', 'علو الهمة', null, 108, '{}', false, 'published'),
  ('6ca1047f-1f89-4591-a518-4c2437297555', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقال إبراهيم بن إسحاق الحربي: كان عطاء بن أبي رباح عبدًا أسود لامرأة من أهل مكة، وكان أنفه كأنه باقلَّاة، قال: وجاء سليمان بن عبد الملك أمير المؤمنين إلى عطاء هو وابناه، فجلسوا إليه، وهو يصلي، فلما صلى، انفتل إليهم، فما زالوا يسألونه عن مناسك الحج، وقد حول قفاه إليهم، ثم قال سليمان لابنيه: "قوما"، فقاما، فقال: "يا ابنَيَّ لا تَنِيا في طلب العلم، فإني لا أنسى ذُلَّنا بين يدي هذا العبد الأسود".', 'علو الهمة', null, 112, '{}', false, 'published'),
  ('2684aeef-1efe-4909-ab1a-254a42a9bf3e', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ومن لطائف شرف النفس، والمبالغة في تنزيهها عن الدنية، أن الشيخ "عز الدين" كانْ إذا قرأ القارئ عليه من كتاب، وانتهى إلى آخر باب من أبوابه لا يقف عليه، بل يأمره أن يقرأ من الباب الذي بعده؛ ولو سطرًا، ويقول: "ما أشتهي أن أكون ممن يقف على الأبواب".', 'علو الهمة', null, 112, '{}', false, 'published'),
  ('20eed390-e9ec-49bc-bbac-f51df95b483a', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقيل: أنفذ الخليفة بمائة دينار إلى عالم، وقال لغلامه: "إن قبل ذلك، فأنت حُرٌّ"، فحملها إليه، فلم يقبل، فقال: "اقبل، ففيه عتقي"، فقال: "إن كان فيه عتقُكَ، ففيه رِقِّي".', 'علو الهمة', null, 112, '{}', false, 'published'),
  ('a465b1f5-cf78-4386-a4d9-bf9a79297562', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وكان الشيخ "سعيد الحلبي" -عالم الشام في عصره- في درسه مادًّا رجليه، فدخل عليه جبَّار الشام "إبراهيم باشا" ابن "محمد علي" صاحب مصر، فلم يتحرك له، ولم يقبض رجليه، ولم يبدل قعدته، فتألم الباشا، ولكنه كتم ألمه، ولما خرج، بعث إليه بصُرَّة فيها ألف ليرة ذهبية، فردَّها الشيخ، وقال للرسول الذي جاءه بها: "قل للباشا: إن الذي يمد رجليه، لا يمد يده".', 'علو الهمة', null, 113, '{}', false, 'published'),
  ('f1a9b03e-12ae-4a28-a2a4-40d32443acb0', null, '33333333-3333-4333-8333-000000000002', 'saying', 'كان الشيخ "عبد الوهاب الفارسي" -رحمه الله- يسِير يومًا برفقة صديقه الشيخ "محمد الجراح"، فصدمتهما سيارة، فسقطا في حفرة وجُرحا، ولما علما أن السائق كان سكران؛ صفحا عنه، وامتنعا من مقاضاته، أنفة من أن يقفا في موقف واحد مع سكران.', 'علو الهمة', null, 113, '{}', false, 'published'),
  ('d4aff330-ff87-40e5-9ff8-e338bdc19d9e', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وتعظيم مالكها وسيدها أن يكون عبده دَنِيًّا وضيعا خسيسًا، فيتولد من بين هذينَ الخلقين شرف النفس وصيانتها، وأصل هذا كله: استعداد النفس وتهيؤها، وإمداد وليها ومولاها لها، فإذا فقد الاستعداد والإمداد، فقد الخير كله) اهـ.', 'علو الهمة', null, 116, '{}', false, 'published'),
  ('c2af30fa-fc9e-47c3-8bf9-5d406db8cb7b', null, '33333333-3333-4333-8333-000000000002', 'saying', 'بخلاف صاحب العلو فإنه وإن شابه هذا في تحرزه وتجنبه؛ فهو يقصد أن يعلو رقابهم، ويجعلهم تحت قدمه، فهذا لون وذاك لون) اهـ.', 'علو الهمة', null, 117, '{}', false, 'published'),
  ('7879e18f-2a7a-4c53-8143-427304a29705', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقال: "والله ما سبقته إلى خيرٍ، إلا وجدته قد سبقني إليه"، والمتنافسان كعبدين بين يدي سيدهما يتباريان، ويتنافسان في مرضاته، ويتسابقان إلى محابه، فسيدهما يعجبه ذلك منهما، ويحثهما عليه، وكل منهما يحب الآخر، ويحرضه على مرضاة سيده.', 'علو الهمة', null, 119, '{}', false, 'published'),
  ('c12d8150-c895-40d0-b752-d464482ad577', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقال مكحول: "اجعلنا أئمة في التقوى، يقتدي بنا المتقون"، وقال القفال وغيره من المفسرين: (في الآية دليل على أن طلب الرياسة في الدين واجب) اهـ.', 'علو الهمة', null, 122, '{}', false, 'published'),
  ('efeeeb84-5ad6-4cf0-8c6a-937e678c14a9', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقال إبراهيم النخعي: "لم يطلبوا الرياسة، بل أن يكونوا قدوة في الدين".', 'علو الهمة', null, 123, '{}', false, 'published'),
  ('8d3428e8-664d-4ccc-a891-f9e8dfd8f2d2', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وعن الحسن قال: "من استطاع منكم أن يكون إمامًا لأهله، إمامًا لحيِّه، إمامًا لمن وراء ذلك، فإنه ليس شيء يؤخذ عنك إلا كان لك منه نصيب".', 'علو الهمة', null, 123, '{}', false, 'published'),
  ('f8e956e7-0104-4ed6-a817-d0026cfa4587', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وذم المنافقين المتخلفين عن الجهاد لسقوط همتهم، وقناعتهم بالدون، فقال في شأنهم: {رَضُوا بأن يكونوا مع الخوالف}، وبين أنهم لسقوط همتهم قعدوا عن الجهاد، فقال: {ولو أرادوا الخروج لأعَدُّوا له عدة ولكن كره الله انبعاثهم فثبطهم وقيل اقعدوا مع القاعدين} الآيات.', 'علو الهمة', null, 127, '{}', false, 'published'),
  ('fb77ce59-3eec-4bc8-b3a1-48fd5fa46def', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وشنع -عز وجل- على الذين يؤثرون الحياة الدنيا على الآخرة، ويجعلونها أكبر همهم، وغاية علمهم، باعتبار هذا الإيثار من أسوإ مظاهر خسة الهمة، وبيَّن أنَّ هذا الركون إلى الدنيا تَسَفُّل ونزول يترفع عنه المؤمن: {يا أيها الذين آمنوا ما لكم إذا قيل لكم انفروا في سبيل الله اثَّاقلتم إلى الأرض أرضيتم بالحياة الدنيا من الآخرة فما متاع الحياة الدنيا في الآخرة إلا قليل}.', 'علو الهمة', null, 127, '{}', false, 'published'),
  ('753a4d05-bb7f-4aa7-b29d-be19e000715b', null, '33333333-3333-4333-8333-000000000002', 'saying', 'لو يعلم الناس ما في النداء والصف الأول، ثم لم يجدوا إلا أن يستهموا عليه، لاستهموا، ولو يعلمون ما في التهجير لاستبقوا إليه، ولو يعلمون ما في العَتَمة والصبح لأتوهما ولو حَبْوًا".', 'علو الهمة', null, 131, '{}', false, 'published'),
  ('023409d4-8104-406d-bbb4-f6dd11ca8b62', null, '33333333-3333-4333-8333-000000000002', 'saying', 'احضْروا الذكر، وادنوا من الإمام، فإن الرجل لا يزال يتباعد حتى يُؤخِّرَ فى الجنة، وإن دخلها".', 'علو الهمة', null, 131, '{}', false, 'published'),
  ('fbea39d1-0018-419e-9036-f2e8b7b8871c', null, '33333333-3333-4333-8333-000000000002', 'saying', 'إذا سألتم الله فاسألوه الفردوس، فإنه أوسط الجنة، وأعلى الجنة، وفوقه عرش الرحمن، ومنه تفجَّرُ أنهار الجنة".', 'علو الهمة', null, 132, '{}', false, 'published'),
  ('c2e585d8-7c2c-451e-8454-d4bbea2a3955', null, '33333333-3333-4333-8333-000000000002', 'saying', 'فكبر الهمة يجلب لك -بإذن الله- خيرًا غير مجذوذ، ويُجري في عروقك دم الشهامة والركض في ميدان العلم والعمل، فلا تُرى واقفًا إلا على أبواب الفضائل، ولا باسطًا يديك إلا لمهمات الأمور، "إن الله يحب معالي الأمور ويكره سفسافها".', 'علو الهمة', null, 138, '{}', false, 'published'),
  ('7eac7040-11e3-4a67-9527-b4f198253adc', null, '33333333-3333-4333-8333-000000000002', 'saying', 'إن التحلي بكبر الهمة يسلب منك سفاسف الآمال والأعمال، ويجتث منك شجرة الذل، والهوان، والتملق، والمداهنة.', 'علو الهمة', null, 138, '{}', false, 'published'),
  ('b0601a46-0622-4b43-87c7-af945d2106fd', null, '33333333-3333-4333-8333-000000000002', 'saying', 'الحديث عن فضل العلم، وما يناله طالبه من مجد وكرامة حديث لا يكشف عن غامض، ولا يطرق السمع بجديد، ومقصودنا شيء غير هذا، ألا وهو لفت الأنظار إلى "القوة العملية" وهي الوسيلة التي صعدت بعلمائنا، فخدموا الدين، ونشروا العلم.', 'علو الهمة', null, 141, '{}', false, 'published'),
  ('d5c17046-eb54-4499-b94e-06b46cfd223c', null, '33333333-3333-4333-8333-000000000002', 'saying', 'فالمكارم منوطة بالمكاره، والسعادة لا يعبر إليها إلا على جسر المشقة، فلا نقطع مسافتها إلا في سفينة الجد والاجتهاد.', 'علو الهمة', null, 143, '{}', false, 'published'),
  ('7c684555-55c0-442e-a14e-9f94e7e9633f', null, '33333333-3333-4333-8333-000000000002', 'saying', 'قال مسلم في "صحيحه": قال يحيى بن أبي كثير: "لا يُنال العلم براحة الجسم"، وقد قيل: "من طلب الراحة، ترك الراحة".', 'علو الهمة', null, 143, '{}', false, 'published'),
  ('400fade0-a1bb-4796-98b5-6ab97e9f7afc', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ولولا جهل الأكثرين بحلاوة هذه اللذة وعظم قدرها لتجالدوا عليها بالسيوف، ولكن حُفَّتْ بحجاب من المكاره، وحُجِبوا عنها بحجاب من الجهل، ليختص الله لها من يشاء من عباده، والله ذو الفضل العظيم) اهـ.', 'علو الهمة', null, 143, '{}', false, 'published'),
  ('7ff49bb1-8888-4da4-a591-e06fa5694a9e', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ومن لم يُذِلِّ النَّفْسَ في طَلَب العُلى... يسيرًا يَعِشْ دهرًا طويلًا أخا ذُلِّ إنما يقطع السفر وبصل المسافر بلزوم الجادة وسير الليل، فإذا حاد المسافر عن الطريق ونام الليل كله، فمتى يصل إلى مقصده؟', 'علو الهمة', null, 143, '{}', false, 'published'),
  ('00471941-f901-423a-a0d4-d439ba240e25', null, '33333333-3333-4333-8333-000000000002', 'saying', 'فعليك يا طالب العلم أن تجد في التحصيل، فإن الأمر كما قال ابن الجنيد: "ما طلب أحد شيئًا بجد وصدق إلا ناله، فإن لم ينله كلَّه نال بعضه".', 'علو الهمة', null, 144, '{}', false, 'published'),
  ('2a2a4718-50cb-4d32-accf-8aaeccc8d9ce', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وألسنة مهذبة لا تقع في لغو ومهاترة، كيف لا وقد شغلت بالحق، فأشغلها عن الباطل.', 'علو الهمة', null, 144, '{}', false, 'published'),
  ('acdeae94-2f18-4ca6-97f7-3c3d5792b5ca', null, '33333333-3333-4333-8333-000000000002', 'saying', 'لقد كان حالُ سلف الأمة في طلب العلم، ونشره، والتصنيف فيه حالًا عجيبًا، استثمروا فيه أوقاتهم، وأفنَوْا شبابهم، فحصَّلوا ما يدهش العقول، ويبهر الألباب، ويستنهض الهمم، فهيا إلى مطالعة أحوالهم، والاقتداء بهديهم، والسير على سننهم.', 'علو الهمة', null, 144, '{}', false, 'published'),
  ('961d0d86-918f-44da-b36e-7607a116a4d0', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وحدثتني عنهم يا سعد فزدتني... بهم غرامًا، فزدني من حديثك يا سعدُ!', 'علو الهمة', null, 144, '{}', false, 'published'),
  ('aeb5f683-6cba-479a-91dc-273f2138101d', null, '33333333-3333-4333-8333-000000000002', 'saying', 'فقيل له: "كيف حرصك عليه؟ "، قال: "حرص الجموع المنوع في بلوغ لذته للمال"، فقيل له: "فكيف طلبك له؟ "، قال: "طلب المرأة المضلة ولدها ليس لها غيره".', 'علو الهمة', null, 147, '{}', false, 'published'),
  ('0940d4e7-7725-45a7-8591-f8001f0fb7e0', null, '33333333-3333-4333-8333-000000000002', 'saying', 'أول من كتبت عنه الحديث أبو يوسف" وبقي يتلقى الحديث ببغداد من سنة (١٧٩ هـ) إلى سنة (١٨٦ هـ)، ولزم عالمًا كبيرًا من علماء الحديث والآثار ببغداد أربع سنوات، وهو هشيم بن بشير بن أبي حازم الواسطي (١٨٣ هـ)، وسمع عبد الرحمن بن مهدي، وأبا بكر بن عياش، وكان في طلبه للعلم مثال الجد والحرص والنشاط، فقد حكى عن نفسه: "كنت ربما أردت البكور في الحديث، فتأخذ أمي بثيابي، حتى يؤذن الناس، أو حتى يصبحوا"، وقال: "لو كان عندي خمسون درهمًا لخرجت إلى جرير بن عبد الحميد).', 'علو الهمة', null, 148, '{}', false, 'published'),
  ('43d9dfa5-df5f-46c3-9d8f-a7461280b8f2', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وعزم على طلب العلم حتى كفلت له والدته الإنفاق عليه، فقالت: "يا بني، اطلب العلم وأنا أكفيك بمغزلي"، فأخذ يتلقى العلم عن شيوخه المتعددين، وكن كل من يحمل علمًا أو خبرًا.', 'علو الهمة', null, 148, '{}', false, 'published'),
  ('d47cc922-a3c8-4933-9015-929cf56c4289', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وكان كثير الاهتمام في طلب العلم، ذكر أبو نعيم: أنه كان إذا لقي شيخا سأله: "هل سمعت من العلم شيئا؟ "، فإن قال: "لا"؛ قال: "لا جزاك الله عن الإسلام خيرًا".', 'علو الهمة', null, 148, '{}', false, 'published'),
  ('f2fa5902-f332-480c-bebd-f1b641094438', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ومن مظاهر اهتمامه بالعلم، أنه كان يقول: "ينبغي للرجل أن يُكْرِهَ ولده على طلب الحديث، فإنه مسئول عنه".', 'علو الهمة', null, 148, '{}', false, 'published'),
  ('5ce39e05-4ec8-4194-ad91-4eefa8cbec0e', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وروى أبو نعيم أنه كان يقول: "ليس عمل بعد الفرائض أفضل من طلب العلم"، وكان يقول: "لا نزال نتعلم العلم ما وجدنا من يعلمنا".', 'علو الهمة', null, 149, '{}', false, 'published'),
  ('c631ba98-eb97-4541-927f-9b4e28d5cf7c', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقال ثعلبة: "ما فقدت إبراهيم الحربى من مجلس لغة ولا نحو خمسين سنة".', 'علو الهمة', null, 149, '{}', false, 'published'),
  ('47899ed7-811a-4741-b1ba-19004095e1f8', null, '33333333-3333-4333-8333-000000000002', 'saying', 'فكانت ثمرة تلك المحافظة النادرة على الزمن، والحرص على طلب العلم، نِتَاجا علميًّا كبيرًا، منه كتاب "الجرح والتعديل" في تسعة مجلدات، وهو من الكتب النفيسة الحافلة الرائدة في هذا العلم، وكتاب "التفسير" في عدة مجلدات، وكتاب "المسند" في ألف جزء).', 'علو الهمة', null, 149, '{}', false, 'published'),
  ('e71b85b6-e45e-4131-936b-f350c70c046f', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وحُدِّثت عنه أنه كان يحاسب نفسه على الأنفاس، لا يدع وقتًا يمضي عليه بغير فائدة، إما ينسخ، أو يدرِّس، أو يقرأ، وينسخ شيئًا كثيرًا، ولقد حدثني عنه شيخنا أبو الفرج الِإسفرايني -وهو أحد تلامذته-، أنه نزل يومًا إلى داره ورجع، فقال: "قد قرأت جزءًا في طريقي".', 'علو الهمة', null, 150, '{}', false, 'published'),
  ('2743cc04-e04e-4728-a135-43f644136d98', null, '33333333-3333-4333-8333-000000000002', 'saying', 'قال: وحدثني المؤمَّل بن الحسن: "أنه رأى سُلَيْمًا خَفِيَ عليه القلم، فإلى أن قَطَّهُ جعل يحرك شفتيه، فعلم أنه يقرأ بإزاء إصلاحه القلم، لئلا يمضي عليه زمانٌ وهو فارغ"، أو كما قال.', 'علو الهمة', null, 150, '{}', false, 'published'),
  ('d3f1000a-2c1f-4a98-85df-53df3f41426e', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ووصف ابن ناصر الحافط أبا الطاهر السلفي، فقال: "كأنه شعلة نارٍ في التحصيل".', 'علو الهمة', null, 151, '{}', false, 'published'),
  ('78d2d071-45ad-4676-8e2c-5d6a03ca95f1', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وكان الخليل بن أحمد الفراهيدي -رحمه الله- يقول: "أثقل الساعات عليَّ: ساعة آكل فيها".', 'علو الهمة', null, 151, '{}', false, 'published'),
  ('33936d27-eb4f-49f4-96a1-3c7b50b2bffe', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وكان عثمان الباقلاويُّ دائم الذكر لله تعالى، فقَال: "إني وقت الإفطار أُحِسُّ بروحي كأنها تخرج! لأجل اشتغالي بالأكل. عن الذكر".', 'علو الهمة', null, 151, '{}', false, 'published'),
  ('77ab4f3d-9ce6-4b37-8f4c-11dee03fe257', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وكان داود الطائي يَسْتَفُّ الفَتيتَ، ويقول: "بين سَفِّ الفتيت وأكل الخبز قراءةُ خمسين آية".', 'علو الهمة', null, 151, '{}', false, 'published'),
  ('8aedaaab-451c-4cec-a72d-4b3f97a0ca40', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ويخرج من نفس المشكاة قول الإمام الجليل ابن عقيل -رحمه الله-: "وأنا أقَصِّرُ بغاية جهدي أوقاتَ أكلي، حتى أختار سَفَّ الكعك وتحسِّيَه بالماء على الخبز، لأجل ما بنيهما من تفاوت المضغ، توفرًا على مطالعة، أو تسطير فائدة لم أدركها".', 'علو الهمة', null, 151, '{}', false, 'published'),
  ('5042ac88-bc49-4693-b61a-fa5c8bf5e3f2', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقيل للشعبي: "من أين لك هذا العلم كله"، قال: "بنفي الاعتماد، والسير في البلاد، وصبر كصبر الحمار، وبكور كبكور الغراب".', 'علو الهمة', null, 151, '{}', false, 'published'),
  ('fdb68a26-9992-4d37-9e40-24ead77efaac', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وكان من حرصهم على العلم ومجالسه أنك تجدهم يَعْدون فِي الطرقات، كأنهم مجانين، ولذلك يقول شعبة -رحمه الله تعالى-: "ما رأيت أحدًا قط يعدو إلا قلتُ: مجنون، أو صاحب حديث".', 'علو الهمة', null, 151, '{}', false, 'published'),
  ('729f6714-87a3-4cc2-8cff-c9866d10f586', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وعن عبد الرحمن بن تيمية قال عن أبيه: "كان الجدُّ إذا دخل الخلاء يقول لي: "اقرأ في هذا الكتاب، وارفع صوتك حتى أسمع".', 'علو الهمة', null, 152, '{}', false, 'published'),
  ('088fede8-09db-4704-8a3e-9bc5737ad0b6', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقد مضى -رحمه الله - في طلب العلم قُدُمًا، وقد ألزمه بعض مشايخه بالقِران؛ أي: أن يَقْرِنَ بين كل فنَّيْن؛ حرصًا على سرعة تحصيله، وتفرُّسًا له في القدرة على ذلك، فانصرف بهمة عالية في درس وتحصيل.', 'علو الهمة', null, 153, '{}', false, 'published'),
  ('1a8a4d2d-782b-4781-82d4-00824165e152', null, '33333333-3333-4333-8333-000000000002', 'saying', 'قال البخاري -رحمه الله-: "ورحل جابر بن عبد الله مسيرة شهر إلى عبد الله بن أنيس في حديث واحد"، ورحل أبو أيوب الأنصاري من المدينة إلى عقبة بن نافع وهو في مصر ليروي عنه حديثًا، فقدم مصر، ونزل عن راحلته، ولم يحل رحلها، فسمع منه الحديث، وركب راحلته، وقفل إلى المدينة راجعًا.', 'علو الهمة', null, 156, '{}', false, 'published'),
  ('020db377-aeb6-47b4-b05d-6e8309320be6', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقال مالك عن يحيى بن سعيد عن سعيد بن المسيَّب قال: "كنتُ أرحَلُ الأيامَ والليالَي في طلبِ الحديثِ الواحد".', 'علو الهمة', null, 157, '{}', false, 'published'),
  ('d2a4da59-d16f-4dc5-9b8d-5b00af5d0572', null, '33333333-3333-4333-8333-000000000002', 'saying', 'أول ما رحلت أقمت سبع سنين، ومشيت على قدمي زيادة على ألف فرسخ، ثم تركت العدد، وخرجت من البحرين إلى مصر ماشيًا، ثم إلى الرملة ماشيًا، ثم إلى طرسوس، ولي عشرون سنة".', 'علو الهمة', null, 157, '{}', false, 'published'),
  ('aa5a251b-c6cc-4c9d-b823-8d5c74c77cdf', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ولم ينتشر العلم في بلاد المغرب والأندلس إلا برجال رحلوا إلى الشرق، ولاقوا في رحلاتهّم عناءً ونصبًا، مثل أسد بن الفرات، وأبي الوليد الباجى، وأبي بكر بن العربي.', 'علو الهمة', null, 158, '{}', false, 'published'),
  ('1a81abd9-53fa-45a9-8640-123f9b3c9bd5', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقال عمر بن حفص الأشقر: "إنهم فقدوا البخاري أيامًا من كتابة الحديِث بالبصرة، قال: فطلبناه فوجدناه في بيتٍ وهو عُرْيان، وقد نَفِدَ ما عنده ولم يبق معه شيء، فاجتمعنا وجمعنا له الدراهم حتى اشترينا له ثوبًا وكسوناه، ثم اندفع معنا فِي كتابة الحديث".', 'علو الهمة', null, 160, '{}', false, 'published'),
  ('b87d1ea1-d928-4c85-b77d-b68c0a6909e4', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقال "مالك" -رحمه الله-: "لا يُنال هذا الأمر، حتى يُذاق فيه طعم الفقر"، وقد قال ابن القاسم: "أفضى بمالكٍ طلبُ الحديث إلى أن نقض سقف بيته، فباع خشبه".', 'علو الهمة', null, 161, '{}', false, 'published'),
  ('fa65c200-b1f0-4778-bc84-2cc7e8dc70ea', null, '33333333-3333-4333-8333-000000000002', 'saying', 'قال الوحشي أبو على الحسن: "كنت بعسقلان أسمع من ابن مصحح وغيره، فضاقت علَيَّ النفقة، وبقيت أيامًا بلا أكل، فأخذت لأكتب فعجزت، فذهبت إلى دكان خباز، وقعدت بقربه لأشم رائحة الخبز وأتقوى بها، ثم فتح الله تعالى علَيَّ".', 'علو الهمة', null, 164, '{}', false, 'published'),
  ('5ca9d08e-de46-44bc-8b3d-723d3b6e702f', null, '33333333-3333-4333-8333-000000000002', 'saying', 'كنت في زمان الصبا آخذ معى أرغفة يابسة فأخرج في طلب الحديث وأقعد على نهر عيسى فلا أقدر على أكلها إلا عند الماء.', 'علو الهمة', null, 164, '{}', false, 'published'),
  ('fa10f38d-aabb-4ea0-9ebd-8d9f86e7ee31', null, '33333333-3333-4333-8333-000000000002', 'saying', 'بم أدركت العلم؟ "، قال: "بالمصباح والجلوس إلى الصباح"، وقيل لآخر، فقال: "بالسفر، والسهر، والبكور في السحر"...', 'علو الهمة', null, 165, '{}', false, 'published'),
  ('5bcc7065-74f9-4bce-b84e-62ecea65ac57', null, '33333333-3333-4333-8333-000000000002', 'saying', 'قال الخطيب البغدادي: "وأفضل المذاكرة مذاكرة الليل، وكان جماعة من السلف يفعلون ذلك وكان جماعة منهم يبدأون من العشاء فربما لم يقوموا حتى يسمعوا أذان الصبح".', 'علو الهمة', null, 165, '{}', false, 'published'),
  ('29a6f634-e85a-4462-80d8-dc3742f1002b', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وكان محمد بن الحسن الشيباني -رحمه الله - لا ينام الليل، وكان عنده الماء يزيل نومه به، وكان يقول: "إن النوم من الحرارة فلا بد من دفعه بالماء البارد".', 'علو الهمة', null, 165, '{}', false, 'published'),
  ('0b39b30e-355c-4209-b65e-c5dd39d7e1ff', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ذكر ابن اللباد أن محمد بن عبدوس "صلى الصبح بوضوء العتمة، ثلاثين سنة، خمس عشرة من دراسة، وخمس عشرة من عبادة".', 'علو الهمة', null, 165, '{}', false, 'published'),
  ('f7974cbe-aea6-4cea-8118-747896f7f576', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وحكى الربيع عن فاطمة بنت الشافعي قالت: "أسرجت لأبي في ليلةّ سبعين مرة".', 'علو الهمة', null, 165, '{}', false, 'published'),
  ('dcb81d47-d6f5-44d4-b86c-783982ebe848', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقال الحافظ ابن كثير: "وقد كان البخاري يستيقظ في الليلة الواحدة من نومه، فيُوقدُ السراجَ ويكتب الفائدة تمُرُّ بخاطره، ثم يُطفئُ سراجَه، ثم يقوم مرةً أخرى وأخرى، حتى كان يتعدَّدُ منه ذلك قريبًا من عشرين مرة".', 'علو الهمة', null, 165, '{}', false, 'published'),
  ('7e12da9d-a1c2-43da-94f1-8de4e4612edf', null, '33333333-3333-4333-8333-000000000002', 'saying', 'فقال له محمد بن الحسن: "اسمع العراقِيِّين بالنهار، وقد جعلتُ لك الليلَ وحدَك، فتَبِيتُ عندي وأسمعك"، قال أسد: "وكنتُ أبيتُ عنده وينَزلُ إلي، ويجعلُ بين يديه قَدَحًا فيه الماء، ثم يأخذ في القراءة، فإذا طال الليل ونعَستُ، ملأ يَده ونفحَ وجهى بالماء فأنتبه، فكان ذلك دأبه ودأبي، حتى أتيتُ على ما أريدُ من السماع عليه".', 'علو الهمة', null, 166, '{}', false, 'published'),
  ('43a194dd-308f-4525-894b-fde47a2f637d', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وكان محمد بن الحسن يتعهده بالنفقة حِين علم أن نفقته نَفِدَتْ، وأعطاه مَرةً ثمانين دينارًا حين رآه يشرب من الماء السبيل، وأمَدَّه بالنفقة حين أراد الانصراف من العراق.', 'علو الهمة', null, 166, '{}', false, 'published'),
  ('fdb39434-4515-497e-8f6c-7b705094628c', null, '33333333-3333-4333-8333-000000000002', 'saying', 'فتوسَّدتُ مرَّةً عتبتَه، فغلبتنى عينى فنِمت، وخرَجَ مالك إلى المسجد ولم أشعر به، فركضتني جارية سوداء له برجلها، وقالت لي: "إن مولاك قد خرج، ليس يَغفُلُ كما تَغفُلُ أنت، اليوم له تسع وأربعون سنة، قلَّما صلى الصبح إلا بوضوء العتَمَة"، ظنَّت السوداء أنه مولاه من كثرةِ اختلافِه إليه.', 'علو الهمة', null, 166, '{}', false, 'published'),
  ('2594f09c-a4ac-45b3-a96c-1e65adf52ff7', null, '33333333-3333-4333-8333-000000000002', 'saying', 'فنورهم من جدهم وسهرهم، كالحافظ الضياء أبو محمد المقدسي: "كأن النور يخرج من وجهه، ضعف بصره من كثرة الكتابة والبكاء".', 'علو الهمة', null, 167, '{}', false, 'published'),
  ('826a6443-220e-4393-aab5-98a994e212f4', null, '33333333-3333-4333-8333-000000000002', 'saying', 'أأبِيتُ سهرانَ الدُّجَى وتبيتَه... نومًا وتبغي بعد ذاك لحاقي؟!', 'علو الهمة', null, 168, '{}', false, 'published'),
  ('7fe3360c-9330-44ac-a577-7d668529d846', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقال النووي -رحمه الله- حاكيًا عن أوائل طلبه للعلم: "وبقيت سنتين لم أضع جنبي إلى الأرض"، وحكى البدر بن جماعة أنه سأله -رحمه الله- عن نومه؛ فقال: "إذا غلبني النوم استندت إلى الكتب لحظة وأنتبه" وقال البدر: "وكنت إذا أتيته أزوره يضع بعض الكتب على بعض ليوسع لي مكانًا أجلس فيه".', 'علو الهمة', null, 168, '{}', false, 'published'),
  ('083a608c-4235-4fa4-a96e-ffa199b740a5', null, '33333333-3333-4333-8333-000000000002', 'saying', 'والعمرُ بذاك ينقضي في تعبٍ... والراحةُ ماتت فعليها الرحمهْ فهو قد أضنى فؤاده علو همته في درك العلا، ونيل المرام، فشغل فكره باستنباط الأحكام الشرعية، وخدمة الدين والأمة، والتزود بالتقوى.', 'علو الهمة', null, 169, '{}', false, 'published'),
  ('0d4caee6-4667-4882-8335-f8cfff132bc2', null, '33333333-3333-4333-8333-000000000002', 'saying', 'قال السبكي: "أما دأبه في الليل علمًا وعبادة فأمر عجاب، ربما استوعب الليل فطالع فيها المجلد أو المجلدين، وربما تلا آية واحدة فكررها إلى مطلع الفجر".', 'علو الهمة', null, 170, '{}', false, 'published'),
  ('59e8af29-a43e-496a-af7e-d426e29e34fb', null, '33333333-3333-4333-8333-000000000002', 'saying', 'إن من رحمه الله تعالى بهذه الأمة أن ألقى في قلوب سلفنا الصالح الشغف بالعلم والحرص على مجالسه ليحفظ بهم دينه، ويكونوا أسوة لمن بعدهم، فمن ثم تبوأوا مناصب الِإمامة في الدين.', 'علو الهمة', null, 172, '{}', false, 'published'),
  ('1d296e59-32c6-45f3-89c8-71eec3692c55', null, '33333333-3333-4333-8333-000000000002', 'saying', 'فدُفِعتُ إلى حلقة نبيلة، فإذا برجل يكشف عن الرجال، فيُضعِّفُ ويُقوِّي، فقلت: "من هذا"؟ لمن كان قربي، فقال: "هذا يحيى بن معين"، فرأيتُ فرجة قد انفرجت قُرْبَه، فقمت إليه فقلت له: "أبا زكريا رحمك الله، رجل غريب نائي الدار، أردتُ السؤال فلا تَستخفَّني"، فقال لي: "قُلْ"، فسألته عن بعض من لقيتُ من أهل الحديث، فبعضًا زكَّى، وبعضًا جرَّح.', 'علو الهمة', null, 174, '{}', false, 'published'),
  ('f1741001-ea1b-41f4-a43a-de5035ca567b', null, '33333333-3333-4333-8333-000000000002', 'saying', 'فسألته في آخر السؤال عن هشام بن عمار، وكنتُ قد أكثرت من الأخذ منه، فقَال: "أبو الوليد هشام بن عمار صاحبُ صلاة، دمشقي ثقة وفوق الثقة، لو كان تحت ردائه كبر وتقلد كبرًا ما ضرَّه شيئًا لخيرِه وفضلِه"، فصاح أهلُ الحلقة: "يكفيك رحمةُ الله عليك، غيرُك له سؤال".', 'علو الهمة', null, 175, '{}', false, 'published'),
  ('e5b32f92-4df3-437e-82f7-22517981be02', null, '33333333-3333-4333-8333-000000000002', 'saying', 'فقلت: وأنا واقف على قدمي: "أكشِفُك عن رجل واحد: أحمد بن حنبل؟ "، فنظر إليَّ يحيى بن معين كالمتعجِّب وقال لي: "ومثلنا نحن يكشف عن أحمد بن حنبل؟! إنَّ ذاك إمامُ المسلمين، وخيرُهم، وفاضلهم".', 'علو الهمة', null, 175, '{}', false, 'published'),
  ('e1ce0c6c-e3b3-4ad6-95dd-f4bbf3019934', null, '33333333-3333-4333-8333-000000000002', 'saying', 'فقال لي: "وأين موضعك؟ "، قلت: "المغرب الأقَصى"، فقال لي: "إفريقية؟ " فقلت: "أبعَدُ من ذلك، أجوزُ من بلدي البحرَ إلى إفريقية، الأندلس"، فقال لي: "إن موضعك لبعيد، وما كان شيء أحبَّ إليَّ من أن أحسن عَونَ مثلِك على مطلبه، غير أني في حيني هذا ممتحَن بما لعله قد بلغك"، فقلت له: "بلى قد بلغني، وأنا قريب من بلدك مقبلٌ نحوك".', 'علو الهمة', null, 175, '{}', false, 'published'),
  ('d8bb0780-9045-4139-a449-6e842f39d330', null, '33333333-3333-4333-8333-000000000002', 'saying', 'فقلت له: "أبا عبد الله هذا أول دخولي، وأنا مجهول العين عندكم، فإن أذنتَ لي أن آتي في كل يوم في زِيِّ السُّؤَّال، فأقولَ عند باب الدار ما يقولون، فتَخرُجَ إلى هذا الموضع، فلو لم تحدثني في كل يوم إلا بحديث واحد لكان فيه كفاية"، فقال لي: "نعم، على شرط أن لا تظهر في الخَلْق، ولا عند أصحاب الحديث"، فقلت: "شَرْطك".', 'علو الهمة', null, 176, '{}', false, 'published'),
  ('6e781106-f402-4d4e-8452-29e76c5eb725', null, '33333333-3333-4333-8333-000000000002', 'saying', 'فكنتُ آخذ عُودًا بيدي، وألُفُّ رأسي بخرقة، وأجعل كاغدي -أي: ورقي- ودَواتي في كُمِّي، ثم آتي بابه فأصيح: "الأجْرَ رحمكم الله"، والسُّؤَّالُ هنالك كذلك، فيَخرج إليَّ، ويغلق باب الدار، ويحدثني بالحديثين والثلاثة والأكثر.', 'علو الهمة', null, 176, '{}', false, 'published'),
  ('59caeaf1-9f4d-4ab6-8e8f-d7477dc2b27f', null, '33333333-3333-4333-8333-000000000002', 'saying', 'فالتزمتُ ذلك، حتى مات الممتحِنُ له، ووَلَي بعده من كان على مذهب السُّنَّة، فظهر أحمد بن حنبل، وسَمَا ذكره، وعظُمَ في عيون الناس، وعلَتْ إمامتُه، وكانت تُضرَب إليه آباط الإبل، فكان يَعرفُ لي حقَّ صبري.', 'علو الهمة', null, 176, '{}', false, 'published'),
  ('cf6400e4-3bc6-4ff1-8e92-4f422c4567f2', null, '33333333-3333-4333-8333-000000000002', 'saying', 'فكنت إذا أتيتُ حَلْقَتَهُ فسَحَ لي وأدناني من نفسه، ويقول لأصحاب الحديث: "هذا يقع عليه اسمُ طالب العلم"، ثم يقص كليهم قصتي معه، فكان يناولني الحديث مناولة، ويقرأه عليَّ، وأقرأه عليه.', 'علو الهمة', null, 176, '{}', false, 'published'),
  ('522077ff-0c7f-47a9-8ed7-c82d1c2cc845', null, '33333333-3333-4333-8333-000000000002', 'saying', 'فاعتللتُ أشفيتُ منها، ففقَدَني من مجلسه فسأل عني، فأعلم بعِلَّتي، فقام من فوره مقبلًا إليَّ عائدًا لي بمن معه، وأنا مضطجع في البيت الذي كنت اكتريت، ولِبْدي تحتي، وكسائي عليَّ، وكتبي عند رأسي.', 'علو الهمة', null, 176, '{}', false, 'published'),
  ('95575e17-a997-4921-b191-870b2d07df86', null, '33333333-3333-4333-8333-000000000002', 'saying', 'فدخل، فجلس عند رأسي، وقد احتَشَى البيتُ من أصحابه، فلم يسعهم، حتى صارَتْ فرقة منهم في الدار وقوفًا وأقلامُهم بأيديهم، فما زادني على هذه الكلمات؛ فقال لي: "يا أبا عبد الرحمن أبشِرْ بثواب الله، أيامُ الصحة لا سقَمَ فيها، وأيامُ السقم لا صحة فيها، أعلاك الله إلى العافية، ومَسَحَ عنك بيمينه الشافية"، فرأيت الأقلام تكتب لفظه.', 'علو الهمة', null, 177, '{}', false, 'published'),
  ('4d17c64b-db26-4c00-814c-448805915e3c', null, '33333333-3333-4333-8333-000000000002', 'saying', 'واجتهد كثير من الحفاظ في لقيا المشايخ والتلقي عنهم، حتى بلغ عدد شيوخ الِإمام أبي سعد عبد الكريم السمعاني المروزي سبعة آلاف شيخ وأستاذ، ولكثرة البلدان التي رحل إليها، ألف "معجم البلدان" التي سمع فيها، وصنف "معجم شيوخه" في عشر مجلدات.', 'علو الهمة', null, 177, '{}', false, 'published'),
  ('a22d09b2-ad44-4eb8-acad-d2fd86072705', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقال القاسم بن داود البغدادي: "كتبت عن ستة آلاف شيخ"، وبلغ عِدَّةُ شيوخ الإمام الحافظ ابن عساكر -رحمه الله - ألفًا وثلاثَ مائة شيخ، ومن النساء بضع وثمانون امرأة.', 'علو الهمة', null, 177, '{}', false, 'published'),
  ('287821d0-a42f-4206-acd7-7d39d5f76f6a', null, '33333333-3333-4333-8333-000000000002', 'saying', 'قال يحيى بن القاسم: كان "ابن سُكَيْنَة" عالمًا عاملًا، لا يُضيِّعُ شيئًا من وقته، وكنا إذا دخلنا عليه يقول: "لا تزيدوا على: (سلامٌ عليكم) مسألة، لكثرة حرصه على المباحثة، وتقرير الأحكام.', 'علو الهمة', null, 178, '{}', false, 'published'),
  ('fdcb1a38-0a85-486a-ac60-9f08477b9546', null, '33333333-3333-4333-8333-000000000002', 'saying', 'يا أبا منازل: عندك حديث حَدِّثني به؟ "، وكان خالد عليلًا، فقال له: "أنا وجع"، فقال: "إنما هو واحد؟ "، فحدثه به، فلما فرغ، قال: لا من إذا شئت".', 'علو الهمة', null, 179, '{}', false, 'published'),
  ('50517b93-cb6c-4552-80eb-140d76417957', null, '33333333-3333-4333-8333-000000000002', 'saying', 'في "إصلاح المنطق" لابن السكيت في اللغة، ودرسًا في التصريف، ودرسًا في أصول الفقه، تارة في "اللمع" لأبي إسحاق، وتارة في "المنتخب" للفخر الرازي، ودرسًا في أسماء الرجال، ودرسًا في أصول الدين -أي: التوحيد- قال النووي: "وكنت أعلق جميع ما يتعلق بها من شرح مشكل، وإيضاح عبارة، وضبط لغة، وبارك الله لي في وقتي واشتغالي، وأعانني عليه).', 'علو الهمة', null, 182, '{}', false, 'published'),
  ('2fb0b07c-fed1-4bcd-a4ef-9db331439107', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وطالع الشيخ عبد الله بن محمد بن أبي بكر الحنبلي: "المغني" للموفق ابن قدامة ثلاًثا وعشرين مرة، حتى كاد يستحضره.', 'علو الهمة', null, 182, '{}', false, 'published'),
  ('301d8f2a-f934-48ac-be68-1a8854ecb16c', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقال سليمانُ بن شُعبةَ: "كَتَبوا عن أبي داودَ أربعين ألف حديث، وليس معه كتابٌ".', 'علو الهمة', null, 183, '{}', false, 'published'),
  ('e4feef4d-91bc-4cbe-b210-4b48dc3d711a', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقال أبو زُرْعَة الرازى: "أحفظُ مائتي ألفِ حديثٍ، كما يحفظُ الإنسانُ: {قل هو الله أحد}، وفي المذاكرةِ ثلاثمائةِ ألفِ حديثٍ".', 'علو الهمة', null, 183, '{}', false, 'published'),
  ('e643ed55-6891-4beb-b5ad-bc8b4d7b5626', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وكان يحيى بن هلال بن مطر يجلس كل يوم لإسماع "المدونة" من الظهر إلى الليل، يستوعب قراءتها كل شهر.', 'علو الهمة', null, 185, '{}', false, 'published'),
  ('3bc867b9-8681-46d9-9e17-7ae267b4cb56', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وكان الشيخ أحمد بن الحسن بن أنو شروان الرومي الحنفي (٦٥٢ هـ - ٧٤٥ هـ) "يحفظ في كل يوم من أيام الدرس ثلثمائة سطر، أقام فوق السبعين سنة يدرس بدمشق".', 'علو الهمة', null, 186, '{}', false, 'published'),
  ('c525412b-9510-4e5c-85c9-7ac33c163405', null, '33333333-3333-4333-8333-000000000002', 'saying', 'عكف أبو صالح أيوب بن سليمان على كتاب "العَروض" حتى حفظه، فسأله بعضهم عن إقباله عّلى هذا العلم بعد الكبير، فقال: "حضرت قومًا يتكلمون فيه، فأخذني ذلٌّ في نفسي أن يكون باب من العلم لا أتكلم فيه".', 'علو الهمة', null, 186, '{}', false, 'published'),
  ('a91cd23b-0fee-439a-8d8b-a17d2f87c88c', null, '33333333-3333-4333-8333-000000000002', 'saying', 'كان العلماء يحرصون على الكتب، ويوثقون علاقتهم بها، فيدمنون مطالعتها باعتبارها خزائن العلم وكنوزه.', 'علو الهمة', null, 186, '{}', false, 'published'),
  ('a07b49cf-17d7-4c3e-bcf2-b9422f3b2cb3', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقال بعض الوزراء: "يا غلام! ائتني بأنس الخلوة ومجمع السلوة"، فظن جلساؤه أنه يستدعي شرابًا، فأتاه بسفط فيه كتب.', 'علو الهمة', null, 187, '{}', false, 'published'),
  ('2ad1a725-e381-43a0-b38f-119551207208', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ومن الطرائف: "أن الجاحظ كان يكتري الدكاكين من الوراقين، ويبيت فيها للنظر في الكتب".', 'علو الهمة', null, 188, '{}', false, 'published'),
  ('41c4c8b0-33a4-46b2-8ad9-9854f31a0485', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ولقد نظرت في ثبت الكتب الموقوفة في المدرسة النظامية، فإذا به يحتوي على ستة آلاف مجلد، وفي ثبت كتب أبي حنيفة، وكتب الحميدى، وكتب شيخنا عبد الوهاب بن ناصر، وكتب أبي محمد بن الخشاب، وكانت أحمالًا، وغير ذلك من كل كتاب أقدر عليه.', 'علو الهمة', null, 189, '{}', false, 'published'),
  ('4c63d1b1-ca03-4e66-b659-c6e5cf5fe14d', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ولو قلت: إني طالعت عشرين ألف مجلد كان أكثر، وأنا بعدُ في الطلب.', 'علو الهمة', null, 189, '{}', false, 'published'),
  ('8899c991-b457-4822-8bfb-3aa8f78166c0', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وخلف "يحيى بن معين" من الكتب مائة قمطر وأربعة عشر قمطرًا وأربعة حباب شرابية مملوءة كتبًا.', 'علو الهمة', null, 190, '{}', false, 'published'),
  ('0d542cec-3323-4129-827c-19419c836150', null, '33333333-3333-4333-8333-000000000002', 'saying', 'قد كنت تفعل شيئًا لا يفعله أحدٌ"، ثم خرج، فقال: "ما يجيء منه شيء"، قال له: "ما الذي كنت تفعل؟ "، قال الأنباري -رحمه الله-: "كنت أُعيد كل أسبوع عشرة آلاف ورقة".', 'علو الهمة', null, 191, '{}', false, 'published'),
  ('a9334b02-c07b-4fb3-91a0-d2008cfa4ee5', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ودخل الشيخ علاء الدين -يعني ابن النفيس- مرة إلى الحمَّام التي في باب الزهومة، فلما كان في بعض تغسيله خرج إلى مَسْلَخ الحمام، واستدعى بدواة وقلم وورق، وأخذ في تصنيف مقالة في النَّبْض إلى أن أنهاها، ثم عادَ ودخل الحمَّام وكمَّل تغسيله".', 'علو الهمة', null, 191, '{}', false, 'published'),
  ('f4a035c1-1419-4351-8d74-6411ebbb8bb4', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقال الربيع: أقام الشافعي ها هنا في الفسطاط أربع سنين فأملى ألفًا وخمسين ورقة، وخرج كتاب "الأم" ألفي ورقة، وكتاب "السنن" وأشياء كثيرة، كلها في أربع سنين، وكان مع ذلك عليلًا شديد العلة، وربما خرج الدم وهو راكب، حتى يملأ سراويله وخفه (يعني من البواسير).', 'علو الهمة', null, 194, '{}', false, 'published'),
  ('5adc5a0b-d03c-4dde-85f2-091e4c18f842', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وكان "سفيان الثوري" يقول: "لو لم يأتني أصحاب الحديث، لأتيتهم في بيوتهم"، وقال: "لو أني أعلم أن أحدًا يطلب الحديث بنية، لأتيتُه في بيته حتى أحدثه".', 'علو الهمة', null, 194, '{}', false, 'published'),
  ('b4658708-52c3-412a-9d63-57b53251eb3b', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وأوصى ابن القاسم عيسى بن دينار، فقال: "عليك بأعظم مدائن الأندلس فانزلها، ولا تنزل منزلاً يضيع ما حملت من علم".', 'علو الهمة', null, 194, '{}', false, 'published'),
  ('3a7f341b-f616-4214-926b-e0393767e9ef', null, '33333333-3333-4333-8333-000000000002', 'saying', 'قال الخطيب البغدادي: "سمعت على بن عبيد الله بن عبد الغفار اللغوى، يحكي: أن محمد بن جرير الطبري -المتوفى سنة ٣١٠ هـ عن ثلاث وثمانين سنة-، مكث أربعين سنة، يكتب في كل يوم منها أربعين ورقة".', 'علو الهمة', null, 195, '{}', false, 'published'),
  ('6e083343-8fdf-45b8-9ba1-bf27f640242c', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وابتداءً يقف المرء حائرًا مشدوهًا أمام هذا الرقم، الذي لا يُعْرَفُ لِعَالِمٍ في تاريخ البشرية، بيد أنه إذا عُلم ما كان عليه هذا الإمام الجليل من هِمةٍ عالية، وعزيمةٍ ماضية، وحرصٍ على لحظات العمر حتى في ساعة الاحتضار، وإدراكٍ لشرف الرسالة التي يحمل، مع فسحة في العمر، والبركة فيه، لما كان عليه من الإخلاص، وصدق النية، خفَّت حيرته، وأصبح أقرب إلى فهم حقيقة هذه الغزارة في الإنتاج العلمي.', 'علو الهمة', null, 196, '{}', false, 'published'),
  ('39cc1643-8b45-4468-be6b-12dd6b6eb8e6', null, '33333333-3333-4333-8333-000000000002', 'saying', 'يقول الأستاذ محمد كرد علي في ترجمة ابن جرير الطبري: "وما أُثِرَ عنه أنه أضاع دقيقة من حياته في غير الإفادة والاستفادة".', 'علو الهمة', null, 196, '{}', false, 'published'),
  ('13a34c02-30f8-4b96-99dc-5eaa4d2dd4ad', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ومصنفات إمامنا الطبري -رحمه الله - في الذروة: جِدَّةً ومنهجًا واتساعًا وعمقًا ونضجًا، مع اختلاف الفنون التي تناولها على كثرتها، حتى آلت إليه إمامة المؤرخين والمفسرين، إلى جانب كونه صاحب مذهب فقهي يختص به.', 'علو الهمة', null, 196, '{}', false, 'published'),
  ('46225a04-086c-475c-a914-3d892ee944e3', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وتفسيره المشار إليه آنفًا، والمطبوع في ثلاثين جزءًا، على ضخامته ونفاسته وريادته، أتى على غير ما كان يؤمِّل سَعَة.', 'علو الهمة', null, 197, '{}', false, 'published'),
  ('0d94a26e-e757-4aa2-9a55-89b188377e92', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وبلغ الإمام أبو الوفاء على بن عقيل الحنبلي البغدادي -المتوفى سنة ٥١٣ هـ-، الذي يقول فيه الإمام ابن تيمية: "إنه من أذكياء العالم"، في محافظته على الزمن مَبْلَغًا أثمر أكبرَ كتاب عرف في الدنيا لِعَالِم، هو كتاب "الفنون" في ثمانمائة مجلدة.', 'علو الهمة', null, 197, '{}', false, 'published'),
  ('9ef89ddc-038a-405d-9adb-a8ac52875d77', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقال سِبط ابن الجوزي: "واخْتصر منه جَدِّي عشر مجلدات فرقها في تصانيفه، وقد طالعت منه في بغداد في وقف المأمونية نحوًا من سبعين، وفيه حكايات ومناظرات، وغرائب وعجائب وأشعار".', 'علو الهمة', null, 198, '{}', false, 'published'),
  ('5fd8bdba-03e5-4c08-8936-6c364e95ac64', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقال عبد الرزاق الرسعني في "تفسيره" قال لي أبو البقاء اللغوي: سمعت الشيخ أبا حكيم النهرواني يقول: وقفت على السِّفْر الرابع بعد الثلاثمائة من كتاب "الفنون".', 'علو الهمة', null, 198, '{}', false, 'published'),
  ('a3aabde3-2d98-49e2-a082-288ee931f8a9', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقال أيضًا في "تاريخه": "لم يصنَّف في الدنيا أكبرُ من هذا الكتاب، حدثني من رأى منه المجلد الفلاني بعد الأربعمائة، قلت -القائل ابن رجب-: وأخبرني أبو حفص عمر بن على القزويني ببغداد قال: سمعت بعض مشايخنا يقول: هو ثمانمائة مجلدة".', 'علو الهمة', null, 198, '{}', false, 'published'),
  ('5f7efbd5-eef9-44f4-9a7d-e7b2e9029fd0', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وصنف الحافظ ابن عساكر كتابه "تاريخ دمشق" في ثمانين مجلدة كبيرة.', 'علو الهمة', null, 198, '{}', false, 'published'),
  ('1398c02a-f725-429f-8ee2-d9d090d72e13', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وسمعته يقول على المنبر في آخر عمره: كتبت بإصبعيَّ هاتين ألفي مجلدة، وتاب على يديَّ مائة ألف، وأسلم على يديَّ عشرون ألف يهودي ونصراني".', 'علو الهمة', null, 199, '{}', false, 'published'),
  ('7eeef165-ef43-4625-a87b-5ed173b01a9f', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقال أيضًا -رحمه الله-: "ولو قلت إني قد طالعت عشرين ألف مجلد، كان أكثر، وأنا بعد في الطلب، فاستفدت بالنظر فيها من ملاحظة سير القوم، وقدر هممهم، وحفظهم، وعباداتهم، وغرائب علومهم، ما لا يعرفه من لم يطالع، فصرت أستزري ما الناسُ فيه، وأحتقر همم الطلاب، ولله الحمد".', 'علو الهمة', null, 199, '{}', false, 'published'),
  ('87ff6dbf-4385-45e9-9c2c-2cfc9cda5c74', null, '33333333-3333-4333-8333-000000000002', 'saying', 'فإذا كان قدر ما قرأ وهو في الطلب (عشرين ألف) مجلدة، واحتسبنا أن صفحات المجلد الواحد في المتوسط صفحة، كان مقدار ما قرأ ستة ملايين صفحة!!', 'علو الهمة', null, 199, '{}', false, 'published'),
  ('b1d66f32-c775-43be-be1e-ead08382a617', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وإذا كان ما كتب بأصبعيه (ألفي) مجلدة، كان مقدار ما كتب ستمائة ألف صفحة!!', 'علو الهمة', null, 199, '{}', false, 'published'),
  ('f3639673-6894-4db9-ac0c-33e443412dd0', null, '33333333-3333-4333-8333-000000000002', 'saying', 'يقول الإمام ابن تيمية -رحمه الله - في "أجوبته المصرية": "كان الشيخ أبو الفرج مفتيًا كثير التصنيف والتأليف، وله مصنفات في أمور كثيرة، حتى عددتها فرأيتها أكثر من ألف مصنف، ورأيت بعد ذلك له ما لم أره".', 'علو الهمة', null, 199, '{}', false, 'published'),
  ('6eb68d8f-15c5-4695-9ca4-7e6f4dd45bca', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ولم يَدَعْ ابنُ الجوزي فنًّا من الفنون إلا وصنف فيه، منها ما هو عشرون مجلدًا، ومنها ما هو في رسالة صغيرة.', 'علو الهمة', null, 200, '{}', false, 'published'),
  ('55eb8922-3686-40be-aafd-ce5b24bac5e3', null, '33333333-3333-4333-8333-000000000002', 'saying', 'يقول الموفق عبد اللطيف -فيما نقله عنه الذهبي- إنه كان "لا يضيِّعُ من زمانه شيئًا".', 'علو الهمة', null, 200, '{}', false, 'published'),
  ('1947e56b-da4f-478b-8857-db0024867854', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ويقول ابن الجوزي نفسه -رحمه الله-: "لقد رأيت خلقًا كثيرًا يجرون معي فيما قد اعتاده الناس من كثرة الزيارة، ويسمون ذلك التردد خدمة، ويطلبون الجلوس، ويجرون فيه أحاديث الناس وما لا يعني، ويتخلله غيبة.', 'علو الهمة', null, 200, '{}', false, 'published'),
  ('1c8c2a8a-cdef-4cdb-b8bf-ee13d385b675', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وصنف شيخ الإسلام ابن تيميه -رحمه الله - ما يربو على أربعمائة مصنف من كنوز العلم، ودقائقه.', 'علو الهمة', null, 201, '{}', false, 'published'),
  ('a42a85ac-ff63-4861-9ba1-090d9b429545', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وعلى سنن من سبق، مشى شيخ الطِّب في زمانه: ابن النفيس -رحمه الله-، والذي يقول عنه الِإمام التاج السُّبكي: "وأما الطِّب فلم يكن على وجه الأرض مثله، قيل: ولا جاءَ بعد ابن سينا مثله، قالوا: وكان في العلاج أعظمَ من ابن سينا".', 'علو الهمة', null, 201, '{}', false, 'published'),
  ('e05c72d6-17b5-4b06-bc86-0da6fdedee2e', null, '33333333-3333-4333-8333-000000000002', 'saying', 'كان -رحمه الله- "إذا أراد التصنيف، توضع له الأقلام مبريةً، ويدير وجهه إلى الحائط، ويأخذ في التصنيف إملاءً من خاطره، ويكتب مثل السَّيل إذا انحدر، فإذا كَلَّ القلم وحَفِي، رمى به وتناول غيره، لئلا يضيع عليه الزمان في بري القلم..', 'علو الهمة', null, 201, '{}', false, 'published'),
  ('66f94332-bc53-4129-96c8-b03d5e1c4199', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وكان السيوطي يلقب "ابن الكتب"، طلب أبوه إلى أمه أن تأتيه بكتاب من المكتبة فأجاءها المخاض فيها، فولدته بين الكتب، فلذلك لقب، ولقد صدق عليه ذلك اللقب حتى صار أبا الكتب، فقد وصلت مصنفاته نحو ستمائة غير ما رجع عنه ومحاه.', 'علو الهمة', null, 201, '{}', false, 'published'),
  ('ea2e3511-cc20-4cc6-bf4f-d2151bd5cf89', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وعن نعيم بن حماد قال: قيل لابن المبارك: "إلى متى تطلب العلم"، قال: "حتى الممات إن شاء الله".', 'علو الهمة', null, 202, '{}', false, 'published'),
  ('8f41a5ce-b950-4d58-8491-56c332f0f9a4', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وعن ابن معاذ، قال: سألت أبا عمرو بن العلاء: "حتى متى يحسن بالمرء أن يتعلم" فقال: "ما دام تحسن به الحياة".', 'علو الهمة', null, 202, '{}', false, 'published'),
  ('b6dddc60-57b8-4051-97c5-d4e4397b7803', null, '33333333-3333-4333-8333-000000000002', 'saying', 'إني لا يحل لي أن أُضيِّعَ ساعة من عمري، حتى إذا تعطل لساني عن مذاكرة ومناظرة، وبصري عن مطالعة، أعملت فكري في حال راحتي وأنا مستطرح، فلا أنهض إلا وقد خطر لي ما أسطره، وإني لأجد من حرصي على العلم وأنا في عشر الثمانين أشدَّ مما كنت أجده وأنا ابن عشرين".', 'علو الهمة', null, 202, '{}', false, 'published'),
  ('95038ee4-e77a-4f04-baef-fa0c36a566a6', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وإنما اعتاضَ رأسي غير صِبغته... والشيب في الرأس غير الشيب في الهممِ وقال الزرنوجي: "دخل حسن بن زياد في التفقه وهو ابن ثمانين سنة، ولم يبت على الفراش أربعين سنة".', 'علو الهمة', null, 202, '{}', false, 'published'),
  ('acc20539-1a55-43bf-ac37-fc463ef846c0', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقد قرأ بواسط هو ابن ثمانين سنة بالعشر -أي: بالقراءات القرآنية العشرة- على ابن الباقلاني، وتلا معه ولده يوسف، نقل ذلك ابن نقطة عن القاضي محمد بن أحمد بن الحسن".', 'علو الهمة', null, 203, '{}', false, 'published'),
  ('9762e6e7-4cb4-4b09-84fb-12677bed3306', null, '33333333-3333-4333-8333-000000000002', 'saying', 'واستمر يطلب العلم، وصار إمامًا من كبار الأئمة، ومن جهابذة الدنيا.', 'علو الهمة', null, 203, '{}', false, 'published'),
  ('e0b3f9bf-1326-4d83-aa21-0503ed55c616', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وعن عمر بن واجب قال: "بينما نحن عند أبي ببلنسية وهو يدرس المذهب إذ بأبي محمد بن حزم يسمعنا ويتعجب، ثم سأل الحاضرين مسألة من الفقه جووب فيها فاعترض في ذلك، فقال له بعض الحضار: "هذا العلم ليس من منتحلاتك" فقام، وقعد، ودخل منزله، فعكف، ووكف منه وابل، فما كف، وما كان بعد أشهر قريبة حتى قصدنا إلى ذلك الموضع؛ فناظر أحسن مناظرة، وقال فيها: "أنا أتبع الحق، وأجتهد، ولا أتقيد بمذهب".', 'علو الهمة', null, 205, '{}', false, 'published'),
  ('410a8b57-b89f-4cbd-a56e-cc599933f913', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وكان الشيخ عزُّ الدين بن عبد السلام -الذي ملأ الأرض علمًا وعظمة نفس- في أوَّل أمره فقيرًا جدًّا، ولم يشتغل إلاَّ على كبر.', 'علو الهمة', null, 206, '{}', false, 'published'),
  ('3b02baae-553f-4d67-9faf-cae979ffdbea', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وعُمِّر الشيخ يوسف بن رزق الله طويلًا حتى قارب التسعين، وثقل سمعه، لكن بقيت حواسه كلها سليمة، وهمته همة ابن ثلاثين، مات وهو يباشر التوقيع بصفد سنة ٧٤٥ هـ.', 'علو الهمة', null, 206, '{}', false, 'published'),
  ('00e4e208-a1eb-4d92-9a30-8802844e18c4', null, '33333333-3333-4333-8333-000000000002', 'saying', 'روى المُعَافَى بن زكريا عن بعض الثقات، أنه كان بحضرة أبي جعفر الطبري -رحمه الله تعالى- قبل موته، وتُوفي بعد ساعة أو أقل منها، فَذُكِرَ له هذا الدعاء عن جعفر بن محمد، فاستدعى مَحْبَرَةً وصحيفة فكتبه، فقيل له: "أفي هذه الحال؟! " فقال: "ينبغي للإنسان أن لا يدع اقتباس العلم حتى الممات".', 'علو الهمة', null, 206, '{}', false, 'published'),
  ('71673706-708a-42d9-bffa-fcfc8b10fa4e', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وعن فرقد -إمام مسجد البصرة- أنهم دخلوا على سفيان في مرض موته، فحدثه رجل بحديث فأعجبه، وضرب سفيان يده إلى تحت فراشه، فأخرج ألواحًا فكتبه، فقالوا له: "على هذه الحال منك؟! " فقال: "إنه حسن، إن بقيت فقد سمعت حسنًا، وإن مت فقد كتبت حسنًا".', 'علو الهمة', null, 207, '{}', false, 'published'),
  ('6e200d5e-ae56-45c4-b074-910799772c3a', null, '33333333-3333-4333-8333-000000000002', 'saying', 'قال: "أمَّا ما كان يوقف عنده للدعاء؛ فالأفضل أن يرميه ماشيًا، وأما ما كان لا يوقف عنده؛ فالأفضل أن يرميه راكبًا".', 'علو الهمة', null, 208, '{}', false, 'published'),
  ('d34bb05c-129d-4c57-986b-e1ebec8bb27a', null, '33333333-3333-4333-8333-000000000002', 'saying', 'رأى الإمامَ أحمدَ بعضُ عارفيه في إحدى رحلاته في طلب الحديث، فقال له معترضًا مستكثرًا ما حفظ، وما كتب، وما روى: "مرة إلى الكوفة، ومرة إلى البصرة"!! إلى متى؟ فقال الإمام أحمد: "مع المحبرة إلى المقبرة".', 'علو الهمة', null, 208, '{}', false, 'published'),
  ('2f352d9a-7fb5-4f8d-a10e-39640ac6e78f', null, '33333333-3333-4333-8333-000000000002', 'saying', 'قال الحسن: "من نافسك في دينك فنافسه، ومن نافسك في دنياه فألقها في نحره".', 'علو الهمة', null, 209, '{}', false, 'published'),
  ('6c7dc6f8-c4ae-4e18-bfd8-bc21986fe6d9', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ما بلغني عن أحدٍ من الناس أنه تعبَّد عبادة إلا تعبَّدتُ نظيرها وزدت عليه".', 'علو الهمة', null, 209, '{}', false, 'published'),
  ('db67d549-d032-439e-b768-359711e9a4de', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقال أحد العباد: "لو أن رجلًا سمع برجل هو أطوع لله منه فمات ذلك الرجل غمُّا، ما كان ذلك بكثير".', 'علو الهمة', null, 209, '{}', false, 'published'),
  ('4bbbd19c-229a-4550-9291-b95c992621f6', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وكان ابن عمر إذا فاتته صلاة الجماعة صام يومًا، وأحيا ليلة، وأعتق رقبة".', 'علو الهمة', null, 209, '{}', false, 'published'),
  ('03da7060-4c6b-441d-b6aa-8473c7284396', null, '33333333-3333-4333-8333-000000000002', 'saying', 'واجتهد أبو موسى الأشعري رضي الله عنه قبل موته اجتهادًا شديدًا، فقيل له: "لو أمسكت أو رفقت بنفسك بعض الرفق؟ "، فقال: "إن الخيل إذا أرسلت فقاربت رأس مجراها أخرجت جميع ما عندها، والذي بقي من أجلي أقل من ذلك"، قال: فلم يزل على ذلك حتى مات.', 'علو الهمة', null, 209, '{}', false, 'published'),
  ('5373e2a7-7bef-4af3-a704-060598ba54c9', null, '33333333-3333-4333-8333-000000000002', 'saying', 'عن فاطمة بنت عبد الملك زوج أمير المؤمنين عمر بن عبد العزيز رحمه الله قالت: "ما رأيت أحدًا أكثر صلاة ولا صيامًا منه، ولا أحدًا أشد فَرَقًا من ربه منه، كان يصلي العشاء، ثم يجلس يبكي حتى تغلبه عيناه، ثم ينتبه، فلا يزال يبكي حتى تغلبه عيناه، ولقد كان يكون معي في الفراش فيذكر الشيء من أمير الآخرة، فينتفض كما ينتفض العصفور من الماء، ويجلس يبكي، فأطرح عليه اللحاف".', 'علو الهمة', null, 210, '{}', false, 'published'),
  ('19444c3c-608d-4ba1-ac1a-f84f00855ae8', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وعن المغيرة بن حكيم قال: قالت لي فاطمة بنت عبد الملك: "يا مغيرة! قد يكون من الرجال من هو أكثر صلاة وصيامًا من عمر بن عبد العزيز، ولكني لم أر من الناس أحدًا قط كان أشد خوفًا من ربه من عمر، كان إذا دخل البيت ألقى نفسه في مسجده، فلا يزال يبكي، ويدعو، حتى تغلبه عيناه، ثم يستيقظ، فيفعل مثلَ ذلك ليلته أجمع".', 'علو الهمة', null, 210, '{}', false, 'published'),
  ('9b184b8e-10a0-4c86-9b4c-799f7920ce64', null, '33333333-3333-4333-8333-000000000002', 'saying', 'عن أبي عُبيدة بن عقبة بن نافع أنه دخل على فاطمة بنت عبد الملك فقال: "ألا تخبريني عن عمر؟ " قالت: "ما أعلم أنه اغتسل من جنابة ولا احتلام منذ استُخِلف".', 'علو الهمة', null, 210, '{}', false, 'published'),
  ('87c45ce2-9bd8-4ae8-bd78-bb416c15e036', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وكان الأسود بن يزيد يجتهد في العبادة، ويصوم في الحر حتى يخضر جسده ويصفر، فكان علقمة بن قيس يقول له: "لم تعذب نفسك؟ "، فيقول "كرامتَها أريد" -وكان يصوم حتى يخضر جسده، ويصلي حتى يسقط، فدخل عليه أنس بن مالك والحسن فقالا له: "إن الله عز وجل لم يأمرك بكل هذا"، فقال: "إنما أنا عبد مملوك، لا أدع من الاستكانة شيئًا إلا جئت به".', 'علو الهمة', null, 210, '{}', false, 'published'),
  ('6924f84f-43d8-41d9-a7d7-e21ba21d23cc', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقيل لعامر بن عبد الله: "كيف صبرك على سهر الليل وظمأ الهواجر؟ "، فقال: "هل هو إلا أني صرفتُ طعام النهار إلى الليل، ونومَ الليل إلى النهار؟ وليس في ذلك خطيرُ أمرٍ". وكان إذا جاء الليل قال: "أذهب حَرُّ النارِ النومَ"، فما ينام حتى يصبح.', 'علو الهمة', null, 211, '{}', false, 'published'),
  ('d9fcfe1c-7d47-467b-bead-e3cd1778d7d6', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وإنكم لتهتمون؟ أما والله لئن استطعت لأجعلنهما همًّا واحدًا" قال: ففعل والله ذلك، حتى لحق بالله).', 'علو الهمة', null, 211, '{}', false, 'published'),
  ('13049e4e-d1fb-4d70-9fec-f8def4cf1d19', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وعن أحمد بن حرب قال: "يا عجبًا لمن يعرف أن الجنة تُزَيَّنُ فوقه، والنار تُسَعَّرُ تحته، كيف ينام بينهما؟ ".', 'علو الهمة', null, 211, '{}', false, 'published'),
  ('b9239a18-264b-486f-a981-9c6b3e9cff6a', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وكان منصور بن المعتمر إذا رأيتَه قلتَ: "رجل أصيب بمصيبة"، منكسر الطرف، منخفض الصوت، رطب العينين، إن حركته جاءت عيناه بأربع -ولقد قالت له أمه: "ما هذا الذي تصنع بنفسك؟', 'علو الهمة', null, 211, '{}', false, 'published'),
  ('c29560db-606c-4da6-a6bc-da0adf1fcb13', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقال هشيم تلميذ منصور بن زاذان: "كان لو قيل له: إن ملك الموت على الباب، ما كان عنده زيادة في العمل".', 'علو الهمة', null, 212, '{}', false, 'published'),
  ('3e5c87db-35c6-4107-8208-baf0a1d38ec4', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وكانت ابنة الربيع بن خثيم تقول له: "يا أبت مالي أرى الناس ينامون وأنت لا تنام؟ "، فيقول: "يا ابنتاه، إن أباك يخاف البيات"، وعن إبراهيم قال: (قال فلان: ما أرى الربيع بن خثيم تكلم بكلام منذ عشرين سنة إلا بكلمة تصعَدُ)، وعن بعضهم قال: "صحِبت الربيع عشرين عامًا ما سمعتُ منه كلمة تُعاب".', 'علو الهمة', null, 212, '{}', false, 'published'),
  ('e6918edc-abc3-4d4a-b33a-939fae2e8fdc', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقال سلمة بن علقمة: "جالست يونس بن عبيد فما استطعت أن آخذ عليه كلمة".', 'علو الهمة', null, 213, '{}', false, 'published'),
  ('02b61d2c-51d0-4a4f-b7be-e11252ec5008', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وعن أبي هارون موسى قال: "كان عون يحدثنا، ولحيته ترتش بالدموع".', 'علو الهمة', null, 213, '{}', false, 'published'),
  ('1d43ac03-3ac7-4b64-881d-f0b2e1199479', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وعن القاسم بن راشد الشيباني: كان زمعة نازلًا عندنا بالمحصب، وكان له أهل وبنات وكان يقوم فيصلي ليلًا طويلًا، فإذا كان السحر نادى بأعلى صوته: أيها الركب المعرسون أكُلَّ هذا الليل ترفدون، أفلا تقومون فترحلون؟ فيتواثبون، فيسمع من هاهنا باكٍ، ومن هاهنا داعٍ، ومن هاهنا قارئ، ومن هاهنا متوضئ - فإذا طلع الفجر نادى بأعلى صوته: عند الصباح يحمد القوم السرى.', 'علو الهمة', null, 213, '{}', false, 'published'),
  ('c5f3ffd2-cf6a-42f1-a7bb-25c034dd9190', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وعن أبي حيان، عن أبيه، قال: (كان الربيع بن خثيم يُقاد إلى الصلاة وبه الفالج -الشلل-، فقيل له: "قد رُخِّصَ لك"، قال: (إني أسمع "حيَّ على الصلاة"، فإن استطعتم أن تأتوها ولو حَبوًا).', 'علو الهمة', null, 213, '{}', false, 'published'),
  ('35b4acef-abb1-4877-bb4b-080ef34fa66c', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وكان المحدث الثقة "بشر بن الحسن" يقال له: "الصَّفِّي" لأنه كان يلزم الصف الأول في مسجد البصرة خمسين سنة.', 'علو الهمة', null, 214, '{}', false, 'published'),
  ('11933ab5-949d-4631-97f4-b24750d98ed3', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقيل للأحنف بن قيس رضي الله عنه: "إن فيك أناة شديدة"، فقال: "قد عرفت من نفسي عجلة في صلاتي إذا حضرت حتى أصليها".', 'علو الهمة', null, 214, '{}', false, 'published'),
  ('708165df-e03e-44ed-be9f-039198de46aa', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقال كبير قضاة الشام سليمان بن حمزة المقدسي وهو من ذرية ابن قدامة صاحب "المغني": "لم أصل الفريضة قط منفردًا إلا مرتين، وكأني لم أصلهما قط" مع أنه قارب التسعين رحمه الله.', 'علو الهمة', null, 215, '{}', false, 'published'),
  ('469d9ad9-c97b-47ba-ad6f-3c19be47f79f', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقال شرف الدين بن محمد رحمه الله تعالى: كان ابن دقيق العيد يقيم في منزلنا بمصر في غالب الأوقات، فكنا نراه في الليل إما مصليًا وإما ماشيًا في جوانب البيت وهو مفكر إلى طلوع الفجر، فإذا طلع الفجر صلى الصبح ثم اضطجع إلى صحوه.', 'علو الهمة', null, 215, '{}', false, 'published'),
  ('00fe785b-6d8b-444d-92bd-3f339d7692d0', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقال الصاحب شرف الدين: وسمعت الشيخ شهاب الدين أحمد بن إدريِس القرافي المالكي يقول: "قام الشيخ تقي الدين أربعين سنة لا ينام الليل إلا أنه كان إذا صلى الصبح اضطجع على جنبه إلى حيث يضحى النهار".', 'علو الهمة', null, 215, '{}', false, 'published'),
  ('7654535e-c162-4e93-85c7-a46eaab87c63', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وروى ابن عماد الحنبلي في "شذرات الذهب" أنه كان يقول: "ما تكلمت بكلمة ولا فعلت فعلًا إلا أعددت له جوابًا بين يدي الله"، كما نقل ذلك السبكي.', 'علو الهمة', null, 215, '{}', false, 'published'),
  ('48e47441-8bdd-4ae8-83ba-1e685dd47c81', null, '33333333-3333-4333-8333-000000000002', 'saying', 'لقد حفل التاريخ الإسلامي قديمه وحديثه بنماذج رائعة من المهتدين الذين ارتفعت همتهم في البحث عن الدين الحق، وبذلوا في سبيل ذلك النفس والنفيس، فصاروا مضرب الأمثال، وحجة لله على خلقه أن من انطلق باحثًا عن الحق مخلصًا لله تعالى، فإن الله عز وجل يهديه إليه، ويَمُن عليه بأعظم نعمة في الوجود نعمة الإسلام، وسنقتصر في هذا الفصل على بعض هذه النماذج المشرقة في القديم والحديث.', 'علو الهمة', null, 217, '{}', false, 'published'),
  ('e3bdde49-b001-4ff3-89cf-0b7cfe7ba20a', null, '33333333-3333-4333-8333-000000000002', 'saying', 'شجرة ملتفة وارفة الظلال، تجثم أمام دارٍ متواضعة بـ "المدائن"، يجلس تحت ظلها صاحب الدار -شيخ كبير تعلوه الهيبة، ويزينه الوقار- قد أحاط به جلساؤه الأخيار، ينصتون لحديثه الشيق، وقصته الرائعة ورحلته المباركة في البحث عن الحقيقة.', 'علو الهمة', null, 217, '{}', false, 'published'),
  ('b768068f-1405-4d7d-9a83-886d96fa60bb', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ها هو ذا يروي لهم كيف غادر دين قومه الفرس إلى النصرانية، ثم إلى الإسلام، وكيف ضحَّى في سبيل "الحقيقة الكبرى" بثراء أبيه الباذخ، ورمى نفسه في أحضان الفاقة، بحثًا عن خلاص عقله وروحه.', 'علو الهمة', null, 217, '{}', false, 'published'),
  ('b1bebed2-d835-4f82-820f-1d4eb12b653a', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ومر بي ركب -ذات يوم- فسألتهم عن بلادهم، فعلمت أنهم من جزيرة العرب، فقلت لهم: "أعطيكم بقراتي هذه وغنمي على أن تحملوني معكم إلى أرضكم؟ ".. قالوا: "نعم... ".', 'علو الهمة', null, 219, '{}', false, 'published'),
  ('355450b8-8592-4899-bda4-b02704dcf811', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وإني لفي رأس نخلة يومًا، وصاحبي جالس تحتها إذ أقبل رجل من يهود، من بني عمه، فقال يخاطبه: "قاتل الله بني قيلة إنهم ليتقاصفون على رجل بقباء، قادمٍ من مكة يزعمون أنه نبى.. ".', 'علو الهمة', null, 220, '{}', false, 'published'),
  ('29b142c9-3c37-4050-af1b-8b9b2c9c0d7b', null, '33333333-3333-4333-8333-000000000002', 'saying', 'فو اللهِ ما هو إلا أن قالها حتى أخذتني العُرَوَاء، فرجفت النخلة حتى كدت أسقط فوق صاحبي!! ثم نزلت سريعًا، أقول: "ماذا تقول...؟ ما الخبر...؟ ".', 'علو الهمة', null, 220, '{}', false, 'published'),
  ('7dc5e97c-9439-4f59-836d-c91ab1918acb', null, '33333333-3333-4333-8333-000000000002', 'saying', 'فرفع سيدى يده ولكزني لكزة شديدة، ثم قال: "مالك ولهذا..؟ أقبل على عملك"..', 'علو الهمة', null, 220, '{}', false, 'published'),
  ('8195f5cd-5368-4e72-af03-e08156e23cb1', null, '33333333-3333-4333-8333-000000000002', 'saying', 'فانطلق -أُنيَس- حتى قدم مكة، وسَمِعَ من قولِه، ثم رجع إلى أبي ذر، فقال: "رأيتُه يأمر بمكارم الأخلاق، و -سمعتُه يقول- كلامًا ما هو بالشعر"، فقال أبو ذر: "ما شَفيتَني فيما أردتُ! ".', 'علو الهمة', null, 223, '{}', false, 'published'),
  ('888d62d7-e535-4e9e-9bb6-4309ab2f44b7', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وهناك رواية أخرى في حادثةِ إسلام أبي ذر، رواها عنه ابنُ أخيه عبد الله بن الصامت الغفاري، وقد رواها مسلم أيضًا من طريق عبد الله بن الصامت الغفاري ابن أخي أبي ذر، وملخَّصُها: قال: قال أبو ذر: خرجنا من قومنا غِفار، وكانوا يُحِلون الشهر الحرام، فخرجتُ أنا وأخي أنَيْس وٍ أمُّنا، فانطلقنا حتى نزلنا بحضرةِ مكة.', 'علو الهمة', null, 224, '{}', false, 'published'),
  ('651ca54d-d975-4e11-9cb2-de99fd274af7', null, '33333333-3333-4333-8333-000000000002', 'saying', 'فقال أنَيس: إنَّ لي حاجة بمكة فاكفِني، فانطلق أنيَس حتى أتى مكة فراثَ عليَّ -أي أبطأ-، ثم جاء، فقلتُ: "ما صنعتَ؟ "، قال: "لقيتُ رجلًا بمكة يزعم أنَّ الله أرسله"، قلت: "فما يقولُ الناسُ؟ "، قال: "يقولون: شاعر كاهن ساحر"، -وكان أنيَس أحَدَ الشعراء- قال أنَيس: "لقد سمعتُ قولَ الكهنة، فما هو بقولهم، ولقد وَضَعْتُ قوله على أقراءِ الشعر -أي طرقِه- فما يلتئم على لسان أحد أنه شعر، والله إنه لصادق، وإنهم لكاذبون".', 'علو الهمة', null, 224, '{}', false, 'published'),
  ('fa4e357f-6593-4a03-b1e0-be5d3c37c233', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وكان والدى محسوبًا من أهل حاضرة "مَيورقة"، ولم يكن له ولد غيري، ولما بلغت ست سنين من عمري أسلمني إلى معلم من القسيسين، قرأت عليه الإنجيل، حتى حفظت أكثر من شطره في مدة سنتين، ثم أخذت في تعلم لغة الإنجيل، وعلم المنطق، في ست سنين.', 'علو الهمة', null, 227, '{}', false, 'published'),
  ('0d7caf09-075c-4ba2-baee-99111a140941', null, '33333333-3333-4333-8333-000000000002', 'saying', 'فسكنت في كنيسة لقسيس كبير السن عندهم، كبير القدر اسمه: "نقلاو مرتيل" وكانت منزلته فيهم بالعلم والدين والزهد رفيعة جدًّا، انفرد بها في زمنه عن جميع أهل دين النصرانية، فكانت الأسئلة في دينهم تَرِدُ عليه من الآفاق من جهة الملوك وغيرهم، وصحب الأسئلةَ من الهدايا الضخمة -ما هو الغاية في بابه، ويرغبون في التبرك به، وفي قبوله لهداياهم، ويتشرفون بذلك.', 'علو الهمة', null, 228, '{}', false, 'published'),
  ('cbea7a86-ae1a-4ecc-81d0-a5dbef585139', null, '33333333-3333-4333-8333-000000000002', 'saying', 'فقرأت على هذا القسيس علم أصول النصرانية وأحكامه، ولم أزل أتقرب إليه بخدمته والقيام بكثير من وظائفه؛ حتى صَيَّرَني من أخص خواصه، وانتهيت في خدمتي له وتقربي إليه إلى أن دفع إليَّ مفاتيح مسكنه، وخزائن مأكله ومشربه، وصَيَّرَ جميعَ ذلك كله عَلَى يدي، ولم يستثن من ذلك سوى مفتاح بيت صغير بداخل مسكنه كان يخلو فيه بنفسه، الظاهر أنه بيت خزانة أمواله التي كانت تُهْدَى إليه، والله أعلم.', 'علو الهمة', null, 228, '{}', false, 'published'),
  ('1710e6ad-5fc2-4e8c-a51f-97104369b8c0', null, '33333333-3333-4333-8333-000000000002', 'saying', 'فحضر مركب يسافر إلى مدينة "تونس"، فسافرت فيه من "صقلية"، وأقلعنا عنها قرب مغيب الشفق، فوردنا مرسى "تونس". قرب الزوال.', 'علو الهمة', null, 233, '{}', false, 'published'),
  ('00de1778-b1db-472f-8a9a-c175712c3cf7', null, '33333333-3333-4333-8333-000000000002', 'saying', 'فرتَّب لي السلطان رحمه الله ربع دينار كل يوم في دار المختص، وزوَّجني ابنةَ الحاج محمد الصفَّار.', 'علو الهمة', null, 236, '{}', false, 'published'),
  ('099a1718-bc08-4957-8f68-500c58a553a7', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وبعد: فهذا طرف من سيرة الشيخ الميورقي وجهاده بقلمه ولسانه في سبيل الله عز وجل، أما جهاده بيده فقد اشترك رحمه الله في جهاد بني جلدته من الكافرين، وفي حملة الأسطول الحفصي على جزيرة صقلية (سنة ٧٩٦ هـ تقريبًا) كان يتولى منصب القائد البحري.', 'علو الهمة', null, 237, '{}', false, 'published'),
  ('4d15ffe9-13ca-4f7b-9bd7-be0a7bf4792b', null, '33333333-3333-4333-8333-000000000002', 'saying', 'إن سيرة الشيخ الترجمان منار ينير الدرب للتائهين في لجج الظلام، ودياجير الجهل، ويحرر عقولهم من أسر التقليد الأعمى لمن لا يملكون لهم رزقًا ولا أجلًا، ويهدي الحائرين الباحثين عن الحقيقة التي هي أقرب لأحدهم من حبل الوريد، إنها حجة على الجاحدين المعاندين الذين غلَّقوا أعينهم، وجعلوا أصابعهم عليها ليقنعوا أنفسهم أن الشمس غائبة، وأن الدنيا ظلام.. {ويأبى الله إلا أن يتم نوره ولو كره الكافرون}.', 'علو الهمة', null, 238, '{}', false, 'published'),
  ('ab7b0ae3-a3a7-494c-ba29-364935981d56', null, '33333333-3333-4333-8333-000000000002', 'saying', 'إنه رجل ينتسب إلى أب هولندي وأم إندونيسية من مدينة "أمبون" الواقعة في جزيرة صغيرة في أقصى الشرق من جزر إندونيسيا، والنصرانية هي الدين الموروث لأسرته أبًّا عن جد.', 'علو الهمة', null, 238, '{}', false, 'published'),
  ('dc3cd041-169a-461b-8791-b41eea41fe5e', null, '33333333-3333-4333-8333-000000000002', 'saying', 'لعل من المناسب هنا أن نذكر ما يقولهُ القرآن الكريم في هذا المقام: {ولا تزر وازرة وزر أخرى وإن تدع مثقلة إلى حملها لا يحمل منه شيء ولو كان ذا قربى} ويقول الرسول عليه الصلاة والسلام: "يُولد ابن آدم على الفطرة، وأبواه يهودانه أو ينصرانه أو يمجسانه"، هذه هي القاعدة في الإسلام، ويوافقها ما جاء في الإنجيل، فكيف يقال: "إن خطيئة آدم تنتقل من جيل إلى جيل، وأن الإنسان يولد آثمًا؟ ".', 'علو الهمة', null, 244, '{}', false, 'published'),
  ('27a7eca1-9a35-42eb-9994-440d7f889e16', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وهنا يعلق الأخ رحمة بورنومو فيقول: لقد تأملت هذه الآية طويلًا ثم قلت: إذا لم يتدخل الله في إقامة المسيح من القبر لبقي مدفونًا تحت التراب إلى يوم القيامة، إذن مادام المسيح لم يستطع إنقاذ نفسه فكيف يكون بوسعه إنقاذ الآخرين؟ هل يليق بإله -كما يزعمون- أن يكون عاجزًا عن ذلك؟ لا أشك لحظة أن كل ذي عقل سيوافقني فيما ذهبت إليه. أليس كذلك؟', 'علو الهمة', null, 247, '{}', false, 'published'),
  ('03905196-ae0e-4083-9953-1b27ce6b12c6', null, '33333333-3333-4333-8333-000000000002', 'saying', 'قد يقول قائل: وفي الإسلام أيضًا توجد مذاهب وطوائف عدة، فهناك المذاهب الأربعة المعروفة، وهى الحنفي والشافعي والحنبلي والمالكي وغيرها......', 'علو الهمة', null, 248, '{}', false, 'published'),
  ('80537a5c-2ce5-4eb1-a47b-027fb0c5fff1', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ومهما اختلفت المذاهب في الإسلام فإنك لا تجد مسجدًا يخص مذهبًا معينًا دون سائر المساجد، بل على العكس من ذلك، فإذا نادى المنادي للصلاة تجد كل مسلم يدخل أقرب مسجد ليصلي فيه. ولكن الأمر يختلف تمامًا في الديانة النصرانية: فكل كنيسة تتبع مذهبًا معينًا، ولا يدخلها إلا أتباع ذلك المذهب فحسب، فالكاثوليكي لا يصلي في كنيسة بروتستانتية، والبروتستانتي لا يصلي هو الآخر في كنيسة كاثوليكية، وهكذا.', 'علو الهمة', null, 248, '{}', false, 'published'),
  ('8f3f7345-f4e8-4abe-9990-bad036e780ca', null, '33333333-3333-4333-8333-000000000002', 'saying', 'يقول الأخ رحمة بورنومو: لقد تذكرت ما يقرره الإسلام في ذلك؛ وهو أن البشر مهما علت رتبة أحدهم لا يمكن أن يُوكَلَ إليه غفران ذنوب العباد، كما أن التوبة والمغفرة لا تُسْقِط التكاليف والفرائض، بل لا بد للتائب من أن يؤدي الصلوات الخمس اليومية في أوقاتها، فإذا تركها فلا قيمة لتوبته وعليه إثم كبير لا يمكن أن يتحمله عنه غيره من الناس {ولا تزر وازرة وزر أخرى} صدق الله العظيم.', 'علو الهمة', null, 249, '{}', false, 'published'),
  ('a9eba87f-8459-4aac-b47f-f12424ec24a8', null, '33333333-3333-4333-8333-000000000002', 'saying', 'لقد واصلت حواري مع الكاهن الهندوسي فقلت له: "يا سيدي إذا توفيت وأنا على دينكم، فإلى أين مصيري؟ " قال: "لا أعلم، ولكن عليك أن تمتنع عن قتل الحشرات من أمثال النمل والبعوض وغيرهما"، وقال: "قد تكون هذه الحشرات آباءك وأجدادك الموتى".', 'علو الهمة', null, 253, '{}', false, 'published'),
  ('d5842374-fbbe-4ba7-b9a4-f1b9c831dfc3', null, '33333333-3333-4333-8333-000000000002', 'saying', 'إذا تأملت قوائم عظماء رجالات الِإسلام من الرعيل الأول فمن بعدهم لرأيت أن "علو الهمة" هو القاسم المشترك بين كل هؤلاء الذين اعتزوا بالإسلام، واعتز بهم الإسلام، ووقفوا حياتهم لحراسة الملة وخدمة الأمة، سواء كانوا علماء أو دعاة أو مجددين أو مجاهدين أو مربين أو عُباد صالحين، ولو لم يتحلوا بعلو الهمة لما كان لهم موضع في قوائم العظماء، ولما تربعوا في قلوب أبناء ملتهم، ولا تزينت بذكرهم صحائف التاريخ، ولا جعل الله لهم لسان صدق في الآخرين.', 'علو الهمة', null, 255, '{}', false, 'published'),
  ('12986ec3-15f6-4704-8c87-b01e001e31c1', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وعن عبد الكريم أبي أمية قال: "لأن أردَّ رجلًا عن رأي سيئ أحب إليَّ من اعتكاف شهر".', 'علو الهمة', null, 258, '{}', false, 'published'),
  ('1e4fe6e4-041a-4eac-9e7b-3aad19e984b8', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ما سألني أحد حاجة إلا قمت له بنفسي، فإن تَمَّ؛ وإلا قمت له بمالي، فإن تم؛ وإلا استعنا له بالإخوان، فإن تم؛ وإلا استعنت بالسلطان".', 'علو الهمة', null, 258, '{}', false, 'published'),
  ('587547a4-4a6a-4bc3-af4a-3fe9a41114fe', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وكان "الليث بن سعد" رحمه الله: "يجلس للمسائل، يغشاه الناس فيسألونه، ويجلس لحوائج الناس؛ لا يسأله أحد من الناس فيرده، كبرت حاجته أو صغرت".', 'علو الهمة', null, 258, '{}', false, 'published'),
  ('2c6c5983-188e-4e25-b1b3-22ef3087199d', null, '33333333-3333-4333-8333-000000000002', 'saying', 'واعتادت أم الشيخ "محمد رشيد رضا" رحمه الله أن تراه مهتمًّا لأحوال المسلمين إذا ألمَّت بهم أو بأحدهم نائبة، ورأته ذات يوم على هذه الحال، فقالت له: "مالك؟ هل مات مسلم بالصين؟ ".', 'علو الهمة', null, 258, '{}', false, 'published'),
  ('bc931d7b-4ce2-4b86-a332-9bdde18274f6', null, '33333333-3333-4333-8333-000000000002', 'saying', 'إن الحركة ولود، والسكون عقيم، والحركة في قاموس الدعاة هي الحياة، والسكون هو الموت.', 'علو الهمة', null, 259, '{}', false, 'published'),
  ('626ecd0e-1247-4c6f-bdee-2966efbf065b', null, '33333333-3333-4333-8333-000000000002', 'saying', 'قال الجيلاني: "الحركة بداية، والسكون نهاية"، والحركة هي الحد الفاصل بين عهد الرخاوة، وبين عهد حمل الأمانة بعزم وحزم ووفاء.', 'علو الهمة', null, 260, '{}', false, 'published'),
  ('9bb89008-79bf-4775-9df1-edb93e30a6bd', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وبالحركة صاروا في ظلمات الحياة سراجًا وهَاجًا، فإذا الباطل رماد بعد التهاب، وخمود بعد حركة.', 'علو الهمة', null, 260, '{}', false, 'published'),
  ('7ffdee96-5dd4-44fa-ade1-58ac2873c37a', null, '33333333-3333-4333-8333-000000000002', 'saying', 'قال الكلبي: "حق على كل من اتبعه أن يدعو إلى ما دعا إليه"، وتلا الحسن البصري قوله تعالى: {ومن أحسن قولًا ممن دعا إلى الله وعمل صالحًا وقال إنني من المسلمين} ثم قال: هو المؤمن أجاب الله في دعوته، ودعا الناس إلى ما أجاب الله فيه من دعوته، وعمل صالحًا في إجابته، فهذا حبيب الله، هذا ولي الله.', 'علو الهمة', null, 262, '{}', false, 'published'),
  ('d34d6eeb-548e-48c7-8ca9-1525003e9e09', null, '33333333-3333-4333-8333-000000000002', 'saying', 'قال إبراهيم عليه السلام: "يا إسماعيل إن الله أمرني بأمر"، قال: "فاصنع ما أمرك ربك"، قال: "وتعينني؟ "، قال: "وأعينك".', 'علو الهمة', null, 263, '{}', false, 'published'),
  ('32355483-68d9-4282-ae7b-4c8e51342cf2', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وواجب أن يكون في كل مسجد ومحلة من البلد فقيه يعلم الناس دينهم، وكذا في كل قرية، وواجب على كل فقيه -فرغ من فرض عينه وتفرغ لفرض الكفاية- أن يخرج إلى ما يجاور بلده من أهل السواد ومن العرب والأكراد وغيرهم، ويعلمهم دينهم وفرائض شرعهم) اهـ.', 'علو الهمة', null, 264, '{}', false, 'published'),
  ('0293421a-bf3e-4639-a18a-bfaa8dc178ed', null, '33333333-3333-4333-8333-000000000002', 'saying', 'إن سناء الهمة في نشدان الكمال الممكن، ومنَ أراد المنزلة العليا القصوى من الجنة، فعليه أن يكون في المنزلة القصوى في هذه الحياة الدنيا، واحدة بواحدة، ولكل سلعة ثمن.', 'علو الهمة', null, 265, '{}', false, 'published'),
  ('ecd140c1-1618-44f3-8e85-2061cd919b2f', null, '33333333-3333-4333-8333-000000000002', 'saying', 'إلا أنها حالة الجبناء. فأما الشجعان فهم يتعلمون ويعلمون. وهذه مقامات الأنبياء عليهم السلام).', 'علو الهمة', null, 266, '{}', false, 'published'),
  ('f8bb1362-94fc-47a4-8fed-6817637c3e85', null, '33333333-3333-4333-8333-000000000002', 'saying', 'من كملت معرفته لله عز وجل صار دالاًّ عليه، يصير شبكة يصطاد بها الخلق من بحر الدنيا، يعطى القوة حتى يهزم إبليس وجنده، يأخذ الخلق من أيديهم.', 'علو الهمة', null, 267, '{}', false, 'published'),
  ('d30420a1-8cb4-4449-957d-351dd4cb5497', null, '33333333-3333-4333-8333-000000000002', 'saying', 'يا من اعتزل بزهده مع جهله: تقدم واسمع ما أقول، يا زهاد الأرض تقدموا.', 'علو الهمة', null, 267, '{}', false, 'published'),
  ('1ad247eb-7a03-4fc6-b172-a24c7f380447', null, '33333333-3333-4333-8333-000000000002', 'saying', 'خربوا صوامعكم واقربوا مني، قد قعدتم في خلواتكم من غير أصل، ما وقعتم بشيء، تقدموا)...', 'علو الهمة', null, 267, '{}', false, 'published'),
  ('b79c44f9-9bca-41c6-b08a-792fcee3046e', null, '33333333-3333-4333-8333-000000000002', 'saying', 'تأمل قوله: (يا زهاد الأرض تقدموا، خربوا صوامعكم) خرب صومعتك أيها الهارب الذى ترزح تحت نير الأفكار الأرضية، وآراء طواغيت القرن العشرين.', 'علو الهمة', null, 267, '{}', false, 'published'),
  ('c5d3713a-5d32-453e-ad25-a9c541480507', null, '33333333-3333-4333-8333-000000000002', 'saying', 'لم يكن بالمنعزل المتواري الهارب من الناس، فالداعية يفتش عن الناس، ويبحث عنهم، ويسأل عن أخبارهم، ويرحل للقائهم، ويزورهم في مجالسهم ومنتدياتهم، ومن انتظر مجيء الناس إليه في مسجده أو بيته، فإن الأيام تبقيه وحيدًا، ويتعلم فن التثاؤب.', 'علو الهمة', null, 269, '{}', false, 'published'),
  ('399e98b6-faf0-487e-b800-c03bb881e5c4', null, '33333333-3333-4333-8333-000000000002', 'saying', 'والإمام الزهري "لم يكتف بتربية أجيال وتخريج أئمة في الحديث، بل كان ينزل إلى الأعراب، يعلمهم".', 'علو الهمة', null, 270, '{}', false, 'published'),
  ('2887c1e1-c08e-4c26-8ce1-efaa2971c6b8', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وكان الفقيه الواعظ أحمد الغزالي، شقيق أبي حامد الغزالي رحمهما الله كان "يدخل القرى والضياع، ويعظ لأهل البوادي، تقربًا إلى الله" اهـ.', 'علو الهمة', null, 270, '{}', false, 'published'),
  ('72ffb9be-0f88-4065-ba88-a70520b6c9fc', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ما رواه جعفر بن برقان قال: كتب إلينا عمر بن عبد العزيز، وقال في كتابه: "ومُرْ أهل الفقه من جندك، فلينشروا ما علمهم الله في مساجدهم ومجالسهم، والسلام".', 'علو الهمة', null, 271, '{}', false, 'published'),
  ('591e4407-c3e6-4a3c-a2f5-036467adfeb4', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وعن عثمان بن عطاء عن أبيه قال: "إن أوثق عملي في نفسي نشري العلم"، وعطاء بن أبي رباح مفتي مكة هو القائل: "لأن أرى في بيتي شيطانًا؛ خير من أن أرى فيه وسادة، لأنها تدعو إلى النوم".', 'علو الهمة', null, 271, '{}', false, 'published'),
  ('99b6b654-21fc-49e1-a3e8-53f6f883fa17', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقال الإمام ربيعة الرأي رحمه الله: "لا ينبغي لأحد عنده شيء من العلم أن يُضَيِّع نفسه".', 'علو الهمة', null, 271, '{}', false, 'published'),
  ('4b772f48-29c9-446c-a031-3bf05300cbe9', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ومراده أن من كان فيه فهم وقابلية للعلم، لا ينبغي له أن يهمل نفسه، فيترك الاشتغال، لئلا يؤدي ذلك إلى رفع العلم، أو مراده: الحث على نشر العلم في أهله لئلا يموت العالم قبل ذلك، فيؤدي إلى رفع العلم، أو مراده: أن يُشهر العالم نفسه، ويتصدى للأخذ عنه لئلا يضيع علمه) اهـ.', 'علو الهمة', null, 272, '{}', false, 'published'),
  ('b312aa2f-b20c-4085-bc3c-01c0d544de8d', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ووصَّى ابن القاسم عيسى بن دينار، فقال له: "عليك بأعظم مدائن الأندلس، فانزلها، ولا تنزل منزلًا يضيع ما حملت من علم".', 'علو الهمة', null, 272, '{}', false, 'published'),
  ('237228c8-ebb2-4e61-8c61-054cf9800307', null, '33333333-3333-4333-8333-000000000002', 'saying', 'قال سليمان الداراني: "لو شك الناس كلهم في الحق، ما شككت فيه وحدي" إنه يفترض حينئذ أنه خلق وحده، وكُلِّف بالحق وحده، وأنه سيحاسب عليه وحده.', 'علو الهمة', null, 273, '{}', false, 'published'),
  ('d1c3779c-cf50-4364-b3ff-b4b0abf8f38a', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وعن حزم بن أبي حزم قال: قال عمر بن عبد العزيز في كلام له: "فلو كان كل بدعة يميتها الله على يدي، وكل سنة ينعشها الله على يدي ببضعة من لحمي حتى يأتي آخر ذلك على نفسي، كان في الله يسيرًا".', 'علو الهمة', null, 273, '{}', false, 'published'),
  ('afa91e3b-efc2-48be-8ca6-36d0f236f139', null, '33333333-3333-4333-8333-000000000002', 'saying', 'عُرِضْتُ على السيف خمس مرات، لا يقال لي: ارجع عن مذهبك، لكن يقال لي: اسكت عمن خالفك، فأقول: لا أسكت".', 'علو الهمة', null, 277, '{}', false, 'published'),
  ('46061ac9-2aaf-4a71-9554-f97742833668', null, '33333333-3333-4333-8333-000000000002', 'saying', 'إن الداعية الكبير الهمة لا ينكر المنكر فحسب، بل ينكر على أهل النكر منكرهم، أي أنه لا يعرف التعميم، ولا التورية إنه يمد أصبعه يشير إلى الطاغوت بالاتهام، ويرفع صوته يعلن فضيحة الكفر الذي أمامه، باسمه، ورقمه، وعنوانه، ثم لا يلبث الإصبع الواحد حتى تنفتح معه بقية الخمس، فتكون يد التغيير من بعد إصبع الاتهام.', 'علو الهمة', null, 277, '{}', false, 'published'),
  ('be7951f4-0e80-4639-8476-6056c503957c', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقد حدث أن سألنا أميرهم: "لماذا تذهبون إلى المقاهي لدعوة الناس؟ "، قال: "أرأيتم إن كان عندكم مريض ماذا تفعلون له؟ "، قلنا: "إن كان مرضه ثقيلًا نحضر له الطبيب في المنزل، وأما إذا كان مرضه خفيفًا، فإنه يذهب بنفسه إلى الطبيب"، قال: "فكذلك الذين لم يعرفوا طريق المسجد مرضهم الإيماني ثقيل، فنحن نذهب إليهم").', 'علو الهمة', null, 281, '{}', false, 'published'),
  ('b4193862-2fdc-4951-81d6-f6d7eb1acfff', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ومن ذلك: أنه لما صعد الإنسان إلى القمر، قال أحدهم: "ولو صعد الناس إلى القمر، وتحول بعض منهم عن الأرض، لنرسلنَّ وراءهم قافلة تخرج في سبيل الله، وتصعد إلى القمر لتدعوهم".', 'علو الهمة', null, 282, '{}', false, 'published'),
  ('95670691-e5f3-42f3-b535-a727e25ffd21', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وأعرف أخًا أمريكيًّا من أصل أسباني ممن أسلم لله، وحَسُن إسلامه يعيش مع زوجته الأمريكية التي أسلمت أيضًا في مدينة "نيويورك"، وقد انتدب نفسه للدعوة إلى الله، فيخرج هو وزوجته، ويقفان أمام الكنيسة، ليلتقط روادها من الرجال، ويدعوهم إلى الإسلام، وكذلك تفعل زوجته مع النساء، وذلك كلَّ أحَدٍ.', 'علو الهمة', null, 283, '{}', false, 'published'),
  ('53959e8a-d1c3-4e17-9cb7-e44ae7da8509', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ويلفتنا الأستاذ محمد أحمد الراشد -حفظه الله تعالى- إلى ميزان غريب نقيس به تلك "الحركة الحياتية- المتفجرة".', 'علو الهمة', null, 284, '{}', false, 'published'),
  ('ea25ad57-62d3-4bbe-bcc8-ba8f0c82f899', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وافق صاحب المرقص.. وطلب منهم أن يحضروا في الغد عند بدء العرض اليومي).', 'علو الهمة', null, 286, '{}', false, 'published'),
  ('60402280-3c27-46b0-b551-bd1ffa64c7be', null, '33333333-3333-4333-8333-000000000002', 'saying', 'قال: فبكى الناس جميعًا.. وخرج الشيخ من المرقص، وخرج الجميع وراءه، وكانت توبتهم على يده، حتى صاحب المرقص تاب، وندم على ما كان منه.. ) اهـ.', 'علو الهمة', null, 287, '{}', false, 'published'),
  ('30750d19-bf06-4a82-8474-116b4aadadb7', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ومعنى ثالث هو: استثارة الشعور بالاستحياء من الله جل جلاله في قلوب جند الله المسلمين حين يرون مَن لا خلاق لهم عند الله يكدحون ويضحون لنصرة باطلهم، ويوفون مع إمامهم إبليس بالعهد الذي قطعه على نفسه: {فبعزتك لأغوينهم أجمعين إلا عبادك منهم المخلصين}، في حين يتباطأ كثير من المسلمين عن نصرة دين الحق مع أنهم عاهدوا الله على الانقياد لشرعه: {واذكروا عهد الله وميثاقه الذي واثقكم به إذ قلتم سمعنا وأطعنا}.', 'علو الهمة', null, 290, '{}', false, 'published'),
  ('9180f561-2468-4aae-992f-b8fc6299988f', null, '33333333-3333-4333-8333-000000000002', 'saying', 'قال الرئيس: "لو كان عندي مال ورجال ما دعوتك، بل تذهب منفردًا وبلا دولار واحد، وأبعثُ معك حارسًا حتى تعبر نهر المسيسبي، ويعود".', 'علو الهمة', null, 291, '{}', false, 'published'),
  ('3d658f9d-5438-4c6f-8336-ca6ba1bd367e', null, '33333333-3333-4333-8333-000000000002', 'saying', 'أرسلت الدولة اليابانية في بدء حضارتها بعوثًا دراسية إلى ألمانيا. كما بعثت الأمة العربية بعوثًا، ورجعت بعوث اليابان لتحضِّر أمتها، ورجعت بعوثُنا خاويةَ الوفاض!! فما هو السر؟ لنقرأ هذه القصة حتى نتعرف على الإجابة".', 'علو الهمة', null, 292, '{}', false, 'published'),
  ('e1fa5abf-c10f-4b65-a6b3-41997a699609', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وحملت النبأ إلى رئيس بعثتنا فقال: "حسنًا ما فعلت، الآن لا بد أن أختبرك، سآتيك بمحرك متعطل، وعليك أن تفككه، وتكشف موضع الخطأ وتصححه، وتجعل هذا المحرك العاطل يعمل"، وكلفتني هذه العملية عشرة أيام عرفت أثناءها مواضع الخلل، فقد كانت ثلاث من قطع المحرك بالية متآكلة، صنعت غيرها بيدي، صنعتها بالمطرقة والمبرد.', 'علو الهمة', null, 293, '{}', false, 'published'),
  ('960322fa-1753-4bb9-960c-e83d363e0fac', null, '33333333-3333-4333-8333-000000000002', 'saying', 'لقد تبدلت موازين البلاغة، وافتقد الجيل الأعمال الكبيرة التي يتمجد بها، فصار -كما يقول الرافعي- "تخترع له الألفاظ الكبيرة ليتلهى بها".', 'علو الهمة', null, 297, '{}', false, 'published'),
  ('feda64ec-07fa-4385-830d-553c1b2e7da6', null, '33333333-3333-4333-8333-000000000002', 'saying', 'فِمن ثَمَّ كان في الإشارة إلى بعض مناقبهم، وحسن بلائهم ما عساه يوقظ الهمم الرُّقَّد، ويُنهِضُ العزمَ المُقْعَد، ومن لم تروه الإشارة، وطمحت نفسه إلى الاستزادة، فليطلب ذلك من مظانه المبسوطة، وبالله المستعان.', 'علو الهمة', null, 298, '{}', false, 'published'),
  ('5ce0e70f-2228-4cf9-be92-e66e6779cce6', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ومنهم الفاروق ناصر الدين أمير المؤمنين عمر بن الخطاب رضي الله عنه، الذي بلغ من الشجاعة والهمة الكبرى أقصى الغايات وأعلى النهايات، والأخبار في قوته في الدين وشدته على المشركين كثيرة مشهورة.', 'علو الهمة', null, 300, '{}', false, 'published'),
  ('43ca9280-dadc-4491-8679-c326f9d34cb5', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقال سعد بن معاذ رضي الله عنه: ".. فامض لما أردت فنحن معك، فوالذي بعثك بالحق، لو استعرضت بنا البحر فخضته لَخُضْناه معك، ما تخلف منا رجل واحد، وما نكره أن نلقى عدونا غدًا، إنا لَصُبُرٌ في الحرب، صُدُق عند اللقاء، لعل الله يُريك ما تقر به عينك، فسر على بركة الله".', 'علو الهمة', null, 301, '{}', false, 'published'),
  ('ff6b00b3-5a0e-44db-ab6b-a2f064e0e642', null, '33333333-3333-4333-8333-000000000002', 'saying', 'يريد صاحبيه زيدًا وجعفرًا، ثم نزل، فلما نزل أتاه ابن عمٍّ له بِعَرْق لحمٍ، فقال: "شُدَّ بهذا صُلبك، فإنك قد لقيتَ يومك هذا"، فأخذه من يده، فانتهش منه نهشة، ثم سمع الحَطْمَة في ناحية الناس، فقال: "وأنتَ في الدنيا؟! "، فألقاه من يده، ثم تقدم فقاتل حتى قُتِل.', 'علو الهمة', null, 303, '{}', false, 'published'),
  ('feb2c57f-6ad5-4fe5-9784-b7be83ef1393', null, '33333333-3333-4333-8333-000000000002', 'saying', 'قال ابن عمر: فنظرت إلى أبي عقيل وقد قُطِعت يده المجروحة من المنكب فوقعتْ إلى الأرض وبه من الجراح أربعة عشر جرحًا كلها قد خلصت إلى مقتل، وقُتل عدوُّ الله مسيلمة.', 'علو الهمة', null, 304, '{}', false, 'published'),
  ('dcb656c4-9e68-4dcb-9f9a-09314943f36e', null, '33333333-3333-4333-8333-000000000002', 'saying', 'لقد شهدت مائة زحف أو زهاءها، وها أنا أموت على فراشي كما يموت البعير، فلا نامت أعين الجبناء".', 'علو الهمة', null, 307, '{}', false, 'published'),
  ('a8baf3c3-36bb-41d8-bd70-1f3f4859e86c', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وروى عاصم بن بهدلة: عن أبي وائل قال: لما حضرت خالدًا الوفاة قال: "لقد طلبتُ القتلَ مظانَّه، فلم يُقَدَّر لي إلا أن أموت على فراشي، وما مِن عملي شيء أرجى عندي بعد التوحيد -من ليلة بِتُّها وأنا متترس، والسماء تُهِلُّني ننتظر الصبح حتى نغير على الكفار"، ثم قال: "إذا متُّ، فانظروا إلى سلاحي وفرسي، فاجعلوه عدة في سبيل الله"، فلما توفي، خرج عمر على جنازته، فذكر قوله: "ما على آل الوليد أن يَسْفَحْن على خالد من دموعهن ما لم يكن نقعًا أو لَقْلَقة".', 'علو الهمة', null, 307, '{}', false, 'published'),
  ('8c2ea2bb-92fe-47e6-b978-c13ad79bed9b', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقد بلغ من شجاعته في بعض حروبه أنه بينما كان قائد الفرس ينظم صفوفهم، إذا بخالدٍ ينقض عليه، ويحتضنه بشدةٍ، ويخطفه كالبرق الخاطف، ويأتي به أسيرًا بين ذراعيه إلى جيش المسلمين أمام ذهول الكفار من هذه الشجاعة النادرة.', 'علو الهمة', null, 307, '{}', false, 'published'),
  ('f4b60c90-dd67-49e0-9cc3-82bc0b7bdd83', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وفي حديث عبد الله بن حذافة رضي الله عنه أنه أسره الروم، فحبسه طاغيتهم في بيت، فيه ماء ممزوج بخمر، ولحم خنزير مشوي، ليأكله ويشرب الخمر، وتركه ثلاثة، فلم يفعل، ثم أخرجوه حين خشوا موته، فقال: "والله لقد كان أحله لي لأني مضطر، ولكن لم أن لأشمتكم بدين الإسلام".', 'علو الهمة', null, 307, '{}', false, 'published'),
  ('e0a180ce-92d5-4d76-ba15-2ad4bee2c6f1', null, '33333333-3333-4333-8333-000000000002', 'saying', 'أجدر الناس بالكرامة: عبد... تلفت نفسُه، ليسلم دينُه * واستوصى "رويمًا" صاحبٌ له، فقال: "هو بذل الروح، وإلا فلا تشتغل بالترهات".', 'علو الهمة', null, 308, '{}', false, 'published'),
  ('e86002d7-111b-40d0-95e4-e19f03195430', null, '33333333-3333-4333-8333-000000000002', 'saying', 'كر الفرس كرة على غرة، فرجع المسلمين متحرفين لقتال، أو متحيزين إلى فئة، فلحقوا بأضعفهم، فاختطفوه أسيرًا، وعادوا به...', 'علو الهمة', null, 310, '{}', false, 'published'),
  ('fe511456-e8e2-42e6-8e72-293b3b3d8a98', null, '33333333-3333-4333-8333-000000000002', 'saying', 'المسلم: في موعود الله أن من قُتل منا أدخله الله الجنة، وأنجز لمن بقي منا وعده، فنحن على يقين.', 'علو الهمة', null, 311, '{}', false, 'published'),
  ('a2a83d01-6d3e-4499-ab88-bf8e0fc99751', null, '33333333-3333-4333-8333-000000000002', 'saying', 'المسلم: "ويحك يا رستم، إن أعمالكم وضعتكم، فأسلمكم الله بها، فلا يغرنك ما ترى من حولك، فإنك لست تحارب الإنس، وإنما تحارب قضاء الله وقدره، ونحن قضاء الله وقدره".', 'علو الهمة', null, 311, '{}', false, 'published'),
  ('b86255ae-4d09-4acd-abf2-ae97560f1f1e', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقد أوجز خالد بن الوليد وأبلغ حين وصف جنود الإسلام مخاطبًا الفرس: "قد أتيتكم بأقوام هم أحرص على الموت منكم على الحياة".', 'علو الهمة', null, 311, '{}', false, 'published'),
  ('7bfd47b6-b88a-49e7-82e5-d664dd04f050', null, '33333333-3333-4333-8333-000000000002', 'saying', 'التابعي الجليل أبو وائل شقيق بن سلمة الأسدي رحمه الله والذي كان نتاج تربية الأربعة الراشدين، وابن مسعود، وسعد بن أبي وقاص وغيرهم، عاف التجارات والبيوت، وبنى له في الكوفة حصنًا صغيرًا يسعه هو وفرسه وسلاحه فقط، وبقى طول عمره متحفزًا للجهاد، حتى لم يعد يعرف موازين السوق التي يتعامل بها الناس.', 'علو الهمة', null, 311, '{}', false, 'published'),
  ('a00924c6-bc60-45de-9072-785bc8375a0d', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ويُروى أن العلاء بن الحضرمي وقف على شاطئ المحيط الأطلسي، وخاض في مياهه بفرسه قائلًا: "والله أيها البحر لو أعلم أن وراءك أرضًا لخضتك، وفتحتها بإذن الله".', 'علو الهمة', null, 312, '{}', false, 'published'),
  ('7e7150ac-8d0c-49f0-ac5e-b392cc676bf0', null, '33333333-3333-4333-8333-000000000002', 'saying', 'قال ابن الأثير: قُتِل من العدو مئة ألف وستة وأربعون ألفًا، ومن المسلمين عشرون ألفًا.', 'علو الهمة', null, 316, '{}', false, 'published'),
  ('42ebe0a9-61cf-4fe7-847d-6b83eb6e4422', null, '33333333-3333-4333-8333-000000000002', 'saying', 'إنه متى يسَّر الله تعالى فتح بقية الساحل، قسَّمت البلاد، ووصيت وودَّعت، وركبتُ هذا البحر إلى جزائره، وأتبعتهم -أي الصليبيين- فيها، حتى لا أبقَي على وجه الأرض من يكفر بالله أو أموت).', 'علو الهمة', null, 316, '{}', false, 'published'),
  ('c4038e94-3afc-4ff5-ab04-e54293c684a1', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وبعد وقعة حطين باع بعض الفقراء أسيرًا بنعل، فقيل له في ذلك، فقال: "أردت هوانهم"، وحكى بعضهم أنه لقي بحوران شخصًا واحدًا ومعه طُنُب خيمة، وفيه نيف وثلاثون أسيرًا، يجرهم وحده للخذلان الذي وقع عليهم.', 'علو الهمة', null, 316, '{}', false, 'published'),
  ('a897a937-717e-407c-bfa5-93109b8ba174', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وعن عبيد الله بن واصل قال: سمعت أحمد السرماري يقول، وأخرج سيفَه، فقال: "أعلم يقينًا أني قتلت به ألفَ تركي، وإن عشت قتلتُ به ألفًا أخرى، ولولا خوفي أن يكون بدعةً لأمرت أن يُدْفَنَ معي".', 'علو الهمة', null, 319, '{}', false, 'published'),
  ('f92d9684-2038-41e7-a774-b50effe4d325', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وعن أحمد بن إبراهيم قال: نظر يونس إلى قدميه عند موته، فبكى، فقيل له: "ما يُيكيك يا أبا عبد الله؟ "، قال: "قدماي لم تغبرا في سبيل الله عز وجل".', 'علو الهمة', null, 322, '{}', false, 'published'),
  ('131f2f5c-9a4e-429c-be74-ee8cd77bce05', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وبعد أن أنشد الأبيات قال: "أرجو الله أن يُعطيني ما سألتُه في هذه الأبيات"، فأعطاه الله ما تمنى، وقُتل في نفس اليوم في موقعة "طريف" مع النصارى بعد أن أبلى في قتالهم بلاءً حسنًا، رحمه الله، وأعلى درجته في الشهداء.', 'علو الهمة', null, 323, '{}', false, 'published'),
  ('489c42df-63ea-452a-9bdf-3453b204a7b5', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وشجعان الأمة وأبطالها لا يحاط بهم كثرة، وفرسانها ورجالها لا يحصون عدة، وفيما ذكرنا كفاية ومقنع، إذ ليس في استيفاء بطولاتهم مطمع، وعن أراد الوقوف على المزيد، فليتتبع الغزوات المؤلفة، والتواريخ المصنفة، يَرَ من علو همتهم في الجهاد ما يبهر العقول، {ذلك فضل الله يؤتيه من يشاء والله ذو الفضل العظيم}.', 'علو الهمة', null, 324, '{}', false, 'published'),
  ('b29cad9c-8820-46e2-ae67-97a5ce948183', null, '33333333-3333-4333-8333-000000000002', 'saying', 'إن سقوط الهمم وخساستها حليف الهوان، وقرين الذل والصغار، وهو أصل الأمراض التي تفشت في أمتنا، فأورثتها قحطًا في الرجال، وجفافًا في القرائح، وتقليدًا أعمى، وتواكلًا وكسلًا، واستسلامًا لما يُسمى "الأمر الواقع".', 'علو الهمة', null, 325, '{}', false, 'published'),
  ('842c8d88-104a-4206-a232-026e588f5ffe', null, '33333333-3333-4333-8333-000000000002', 'saying', 'فقد رأينا في التاريخ الماضي كيف كان الجندي التتَري يأمر المسلم الذي سقطت همته بالقعود مكانه ريثما يذهب فيحضر حجرًا يقتله به، فيستسلم ذاك، ولا يحرك ساكنًا إلى أن ينجز التتري ما أوعده! ورأينا في عصرنا هذا كيف ركع الجندي العراقي أمام نعلي الجندي الأمريكى يتمسح فيهما ويقبلهما سائلًا إياه العفو والصفح، بينما يربت الأخير على كتفه، قائلًا له في مشهد تمثيلي مُخْزٍ: "لا تجزع.. لا بأس عليك! ".', 'علو الهمة', null, 325, '{}', false, 'published'),
  ('af67385a-c9c5-4e79-af97-00a064df2e27', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وفي عصرنا رأينا شبابًا ينتسبون إلى الإسلام تصاغرت هممهم فلم تنشغل إلا بسفاسف الأمور ومحقراتها، ورأيناهم يمعنون في التشبه بالكفار، بل يعلقون على صدورهم وسياراتهم أعلام الدول التي أذلت كبرياءهم، وطأطأت أعناقهم، وأهدرت كرامتهم، واستعبدت أمتهم.', 'علو الهمة', null, 326, '{}', false, 'published'),
  ('8cdfc542-9679-4c26-8cae-8aa100535140', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وعلى صعيد آخر رأينا من يسوِّغ تعبيد الأمة وتبعيتها لأعدائها بحجة أننا: "لن نفكر برأسنا، ما دمنا لا نأكل بفأسنا"! أو أن ما نحن فيه من الانحدار "تسبب فيه مَن قبلنا، وسيصلحه مَن بعدنا"! وأدركنا زمانًا لم تعد فيه "الخيانة" عارًا يُستر ولكنها "شرف" يُظهر، ووظيفة مرموقة، ومفخرة يُتهافَتُ عليها.', 'علو الهمة', null, 327, '{}', false, 'published'),
  ('cf23ab80-1bf3-4bb0-989c-edc866941793', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ويبين الأستاذ محمد أحمد الراشد -أعزه الله- ملمحًا خطيرًا من ملامح محنة المسلمين في عصر انحطاط الهمم، فيقول: إن [محنة المسلمين اليوم لا تقتصر على تسلط أئمة الضلالة فحسب، بل تعدت ذلك إلى تربية سخرت المناهج الدراسية، وكراسي الجامعات والصحف والإذاعات لمسخ الأفكار والقيم، حتى غدًا صيدُ المخططات في سرور، يحسب نفسه في انعتاق من أسر القديم، أي قديم كان.', 'علو الهمة', null, 328, '{}', false, 'published'),
  ('78fa9a3c-3d98-4454-ba16-cc3027539568', null, '33333333-3333-4333-8333-000000000002', 'saying', 'كل ذل يصيب الإنسان من غيره، ويناله من ظاهره: قريب شفاؤه، ويسير إزالته، فإذا نبع الذل من النفس، وانبثق من القلب، فهو الداء الدوي، والموت الخفي.', 'علو الهمة', null, 330, '{}', false, 'published'),
  ('88fc8dd2-440e-4945-b3cc-f1aa401b1c2a', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وأنتجت خطط التربية ذاك الظبي الجفول الذي لم يعد يقتحم، واستبدل العزم بالتفلت، والمسارعة إلى الهرب، إنهم هذا الجيل من أبناء المسلمين، شبلُ أسدٍ تحول إلى ظبي وديع، وحُرٌّ استرقُّوه ففْرح!] اهـ.', 'علو الهمة', null, 331, '{}', false, 'published'),
  ('ccbf4bbb-057a-4333-833c-4e74a30d2d8e', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقد كان أهدي إلى أحمد بن حنبل هدية -أي من المنصور- فردَّها، ثم قال بعد سنة لأولاده: "لو كنا قبلناها كانت قد ذهبت".', 'علو الهمة', null, 332, '{}', false, 'published'),
  ('d1a0a42a-7a9a-4de2-bcf9-3281271fc570', null, '33333333-3333-4333-8333-000000000002', 'saying', 'و [قال الفضيل بن عياض: "أعرف من يَعُدُّ كلامه من الجمعة إلى الجمعة".', 'علو الهمة', null, 335, '{}', false, 'published'),
  ('f5d57d77-bd0b-428a-9205-9e5d2cbed82f', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ودخلوا على رجل من السلف، فقالوا: "لعلنا شغلناك؟ "، قال: "أصدقكم، كنت أقرأ فتركتُ القراءة لأجلكم".', 'علو الهمة', null, 335, '{}', false, 'published'),
  ('1607a2bc-2d87-4a20-a76b-2054c5952c9c', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وجاء عابدٌ إلى السَّرِيِّ السَّقَطي، فرأى عنده جماعة، فقال: "صِرتَ مُناخَ البطالين! "، ثم مضى ولم يجلس.', 'علو الهمة', null, 335, '{}', false, 'published'),
  ('b861e3a2-55d6-44d3-9c4a-d3dde1a635d3', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقعد جماعة عند معروف الكرخي، فأطالوا، فقال: "إن مَلَك الشمس لا يفتر عن سوقها، فمتى تريدون القيام؟ ".', 'علو الهمة', null, 335, '{}', false, 'published'),
  ('5acc73bb-e358-45dd-864a-9e4277436967', null, '33333333-3333-4333-8333-000000000002', 'saying', 'رُويْ أن رجلًا قال لخالد بن صفوان: "ما لي إذا رأيتكم تذاكرون الأخبار، وتدارسون الآثار، وتناشدون الأشعار، وقع عليَّ النوم؟ "، فقال: "لأنك حمار في مسلاخ إنسان".', 'علو الهمة', null, 336, '{}', false, 'published'),
  ('c4525d84-d588-4a16-ac0d-d35d612c1bc8', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ولم أرَ في عيوب الناس عيبًا... كنقص القادرين على التمام * ومنها الغفلة، وشجرة الغفلة تُسْقَى بماء الجهل الذي هو عدو الفضائل كلها.', 'علو الهمة', null, 336, '{}', false, 'published'),
  ('55a8688d-e38d-4419-84bf-d066a7276960', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وسئل ابن الجوزي: "أيجوز أن أفسح لنفسي في مُباح الملاهي؟ "، فقال: "عند نفسك من الغفلة ما يكفيها".', 'علو الهمة', null, 337, '{}', false, 'published'),
  ('68e6082d-0bdd-461e-abdf-628b1fa05498', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وبضاعة رُكَّابه: مواعيد الشيطان، وخيالات المحال والبهتان، فلا تزال أمواج الأماني الكاذبة، والخيالات الباطلة، تتلاعب براكبه، كما تتلاعب الكلاب بالجيفة، وهي بضاعة كل نفس مهيِنة خسيسة سفلية، ليس لها همة تنال بها الحقائق الخارجية، بل اعتاضت عنها بالأماني الدنية.... فيتمثل المتمني صورة مطلوبة في نفسه، وقد فاز بوصلها، والتذ بالظفر بها، فبينما هو على هذه الحال"، إذ استيقظ فإذا يده والحصير.', 'علو الهمة', null, 338, '{}', false, 'published'),
  ('7940741a-c7ae-4db1-aaf9-478a57a576a9', null, '33333333-3333-4333-8333-000000000002', 'saying', 'قال رجل لابن سيرين: "إني رأيت في منامي أني أسبح في غير ماء، وأطير بغير جناح! فما تفسير هذه الرؤيا؟ "، فقال له: (أنت رجل كثير الأماني والأحلام".', 'علو الهمة', null, 339, '{}', false, 'published'),
  ('fc99965a-26ef-4ad4-a56a-0c17e44e1cf6', null, '33333333-3333-4333-8333-000000000002', 'saying', 'فحذار من مجالسة المثبطين من أهل التبطل والتعطل واللهو والعبث، فإن "طبعك يسرق منهم وأنت لا تدري، وليس إعداء الجليس جليسه بمقاله وفِعَاله فقط، بل بالنظر إليه! والنظر في الصور يورث في النفوس أخلاقًا مناسبة لخلق المنظور إليه... ومن المشاهد أن الماء والهواء يفسدان بمجاورة الجيفة، فما الظن بالنفوس البشرية؟! ".', 'علو الهمة', null, 340, '{}', false, 'published'),
  ('a3c43353-d006-4cfd-831e-da85b7881014', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وأخطر منها وأضر المناهج التربوية والتعليمية التي ارتضت العالمانية دينًا، فراحت تسمم آبار المعرفة التي يستقي منها شباب المسلمين، لتخرج أجيالًا مقطوعة الصلة بالله، تبتغى العزة في التمسح على أعتاب الغرب، وتأنف من الانتساب إلى الإسلام.', 'علو الهمة', null, 342, '{}', false, 'published'),
  ('ae8082fa-65ef-4857-8951-60af60b86301', null, '33333333-3333-4333-8333-000000000002', 'saying', 'العلم والبصيرة، فالعلم يصعد بالهمة، ويرفع طالبه عن حضيض التقليد، ويُصَفِّي النية، ذكر القُصَّاص أن رجلاً خطب امرأة ذات منصب وجمال، فأبت؛ لفقره، وقلةِ حسبه، ففكر بأيِّ الأمرين ينالها: أبالمال أم الحسب؟ فاختار الحسب، وطلب له العلم، حتى أصبح ذا مكانة، فَبَعَثَتْ إليه المرأة تعرضُ نفسها، فقال: "لا أوثر على العلم شيئًا".', 'علو الهمة', null, 344, '{}', false, 'published'),
  ('9dc5d94e-2c4d-40c9-b964-9a382154212c', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقيل لبعض الزهاد: "ما أبلغ العظات؟ " قال: "النظر إلى الأموات"، وكتب عمر بن عبد العزيز إلى الأوزاعي: "أما بعد، فإنه مَن أكثر ذكر الموت، رضي من الدنيا باليسير".', 'علو الهمة', null, 345, '{}', false, 'published'),
  ('c4697477-5e7a-4a56-8a80-6861c9b9b41b', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وكان يقول صالح المري: "إن ذكر الموت إذا فارقنى ساعة فَسَدَّ علَيَّ قلبي"، وقال الدقاق: "من أكثر ذكر الموت أكرم بثلاثة: تعجيل التوبة، وقناعة القلب، ونشاط العبادة، ومن نسي الموت عوجل بثلاثة: تسويف التوبة، وترك الرضى بالكفاف، والتكاسل في العبادة".', 'علو الهمة', null, 346, '{}', false, 'published'),
  ('6bfbd5e6-5bc6-426b-b0ae-623486b7b7c5', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ذكر عن الحسن البصري أنه دخل على مريض يعوده، فوجده في سكرات الموت، فنظر إلى كربه، وشدة ما نزل به، فرجع إلى أهله بغير اللون الذي خرج به من عندهم، فقالوا له: "الطعام يرحمكم الله"، فقال: "يا أهلاه، عليكم بطعامكم وشرابكم، فوالله رأيت مصرعًا لا أزال أعمل له حتى ألقاه").', 'علو الهمة', null, 346, '{}', false, 'published'),
  ('56cb6440-1450-406a-8393-583560ac1083', null, '33333333-3333-4333-8333-000000000002', 'saying', 'كان الخليل بن أحمد يخرج من منزله، فلا يشعر إلا وهو في الصحراء، ولم يُرِدْها من شغله بالفكر.', 'علو الهمة', null, 348, '{}', false, 'published'),
  ('96330eee-d20e-4d52-a4b5-77a2b7d90bd6', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وكان يدخل الداخل إلى أبي تمام الشاعر، وهو يعمل الشعر، فلا يشعر به. وكانت لابن سَحْنون سُرِّيَّة، فطلب منها ذات يوم أن تُعِدَّ له طعامًا، وشُغِل بالتأليف والرد على المخالفين، وأحضرت الطعام، وبعد طول انتظار أخذت تطعمه -تلقمه- حتى أتى عليه، وتمادى في عمله حتى الفجر، ثم سألها أن تحضر الطعام فأخبرته بأنه أتى عليه دون أن يشعر.', 'علو الهمة', null, 348, '{}', false, 'published'),
  ('ab14c5f6-6ba5-432a-95e9-e253f22abad5', null, '33333333-3333-4333-8333-000000000002', 'saying', 'إن للبيئة المحيطة بالإنسان أثرًا جسيمًا لا يخفى، فإذا كانت بيئة مثبطة داعية إلى الكسل والخمول وإيثار الدون فإن على المرء أن يهجرها إلى حيث تعلو همته، كي يتحرر من سلطان تأثيرها، وينعم بفرصة الترقي إلى المطالب العالية.', 'علو الهمة', null, 350, '{}', false, 'published'),
  ('e00b74d2-8ac9-48d8-ae3e-f87ac26e1405', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ولعل هذا المعنى كامن أيضًا في تشريع نفي الزاني غير المحصن وتغريبه سنة بعيدًا عن وطنه، كي تجتمع عليه عقوبة بدنية بالجلد، وعقوبة قلبية بالنفي، وفي الوقت نفسه يُبْعَد عن مسرح الجريمة كي ينسى ذكراها، ولا يبقى حيث يعامل باحتقار وإهانة، ويتعرض للمضايقات، ويُعْطَى فرصة كافية لاستئناف التوبة الصادقة والحياة الكريمة.', 'علو الهمة', null, 351, '{}', false, 'published'),
  ('e8af304c-9956-44c6-97d6-e776acabda66', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ومن أهم أسباب الارتقاء بالهمة: صحبة أولي الهمم العالية، ومطالعة أخبارهم.', 'علو الهمة', null, 352, '{}', false, 'published'),
  ('4266add1-873a-4b1d-9f2b-9c6a36abc672', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقال زين العابدين على بن الحسين بن علي رضي الله عنهم: "إنما يجلس الرجل إلى من ينفعه في دينه".', 'علو الهمة', null, 353, '{}', false, 'published'),
  ('2c8a9a9f-e2c9-450a-a3d9-67750c6e01db', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وإذا أردت أن تلمس أثر الصحبة العالية الهمة في التسابق إلى الخيرات، فتأمل ما قاله محمد بن على السلمي رحمه الله: "قمت ليلة سحرًا لآخذ النوبة على ابن الأخرم، فوجدت قد سبقني ثلاثون قارئًا، ولم تدركني النوبة إلى العصر".', 'علو الهمة', null, 354, '{}', false, 'published'),
  ('5f29fc53-61ed-4bde-91af-d4a2f5d814e4', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقال عليُّ بن الحسين بن شقيق: "قمت لأخرج مع ابن المبارك فِي ليلة باردة من السجد، فذاكرني عند الباب بحديث، أو ذاكرته، فمازلنا نتذاكر حتى جاء المؤذن للصبح".', 'علو الهمة', null, 354, '{}', false, 'published'),
  ('19de6308-b758-4142-8fa7-f4c2c819b680', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقال أمير المؤمنين عمر رضي الله عنه: "ما أعطي عبد بعد الإسلام خيرًا من أخ صالح، فإذا رأى أحدكم وُدًّا من أخيه فليتمسك به".', 'علو الهمة', null, 355, '{}', false, 'published'),
  ('202028d4-c4fd-45c8-8ac1-09542b161198', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقال الحسن البصري: "إخواننا أحب إلينا من أهلنا وأولادنا، لأن أهلنا يذكروننا بالدنيا، وإخواننا يذكروننا بالآخرة".', 'علو الهمة', null, 355, '{}', false, 'published'),
  ('45f2c93b-b3a8-46d7-9c48-2237ac3f71c7', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وصحبة هؤلاء الأمجاد المجدِّين المتيقظين للدقائق والثواني، كان له عظيم الأثر في همَّة مثل الإمام ابن جرير الطبري وابن عقيل الحنبلي وابن عساكر الدمشقي وابن تيمية وابن القيم وابن النفيس والِمزِّيُّ والذهبي وابن حجر وأضرابهم في غزارة إنتاجهم وجدِّته.', 'علو الهمة', null, 355, '{}', false, 'published'),
  ('b504e49b-d3a0-4774-bc10-04215a5c2d7a', null, '33333333-3333-4333-8333-000000000002', 'saying', 'يقول الإمام ابن عقيل الحنبلي صاحب كتاب "الفنون" -الذي مَرَّ خيره من قبل -: "وعصمني الله من عنفوان الشبيبة بأنواع من العصمة، وقصر محبتي على العلم وأهله، فما خالطتُ لعَّابًا قط، ولا عاشرت إلَّا أمثالي من طلبة العلم".', 'علو الهمة', null, 355, '{}', false, 'published'),
  ('f4e9972c-d357-453e-8e08-8c5b9333eae5', null, '33333333-3333-4333-8333-000000000002', 'saying', 'فالحريص الموفق الذي يروم المعالي، لا تراه إلا مع أهل العلم العاملين، وأولي الفضل والمجاهدة والحِكْمة والبصيرة، ليرشح عليه ما هم فيه أو بعضه، فيكون مثلهم أو قريبًا منهم.', 'علو الهمة', null, 355, '{}', false, 'published'),
  ('0892d25f-71c2-42fd-ae3e-5c3a886a3dbc', null, '33333333-3333-4333-8333-000000000002', 'saying', 'إن من أقوى البواعث على ارتفاع الهمة أن تطلب صحبة عبد من عباد الله مجتهد في العبادة والعلم، فتلاحظ أقواله وتقتدي به، وكان بعضهم يقول: "كنت إذا اعترتني فترة في العبادة نظرت إلى أحوال محمد بن واسع وإلى اجتهاده، فعملت على ذلك أسبوعًا".', 'علو الهمة', null, 356, '{}', false, 'published'),
  ('8f43ce19-23ed-4c24-b01d-837421128d6a', null, '33333333-3333-4333-8333-000000000002', 'saying', 'إلا أن هذا العلاج قد تعذر، إذ قد فُقِد في هذا الزمان من يجتهد في العبادة اجتهاد الأولين فينبغي أن يعدل من المشاهدة إلى السماع فلا شيء أنفع من سماع أحوالهم ومطالعة أخبارهم وما كانوا فيه من الجهد الجهيد، وقد انقضى تعبهم، وبقى ثوابهم ونعيمهم أبد الآباد لا ينقطع.', 'علو الهمة', null, 356, '{}', false, 'published'),
  ('b9743e98-7c7a-48e4-bd30-4b7885b49192', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وأعوذ بالله من سير هؤلاء الذين نعاشرهم، لا نرى فيهم ذا همة عالية، فيقتدي بها المبتدي، ولا صاحبَ ورع فيستفيد منه الزاهد.', 'علو الهمة', null, 357, '{}', false, 'published'),
  ('d19f5685-1b24-4f6c-b8c9-e5afd400702c', null, '33333333-3333-4333-8333-000000000002', 'saying', 'قال الإمام أحمد في وصف محنته: (صرنا إلى الرحبة، ورحلنا منها في جوف الليل، فعرض لنا رجل، فقال: "أيكم أحمد بن حنبل؟ "، فقيل له: "هذا"، فقال للجمال: "على رِسْلِك"، ثم قال: "يا هذا، ما عليك أنْ تُقتل ها هنا، وتدخل الجنة؟ "، ثم قال: "أستودعك الله"، ومضى، فسألت عنه، فقيل لي: (هذا رجل من العرب، من ربيعة، يعمل الصوف في البادية، يُقال له: "جابر بن عامر" يُذكَر بخير).', 'علو الهمة', null, 358, '{}', false, 'published'),
  ('fa9d0ae4-1628-4d58-a53c-8c7dd8c25e71', null, '33333333-3333-4333-8333-000000000002', 'saying', 'قد ضُرِب أحمد بن حنبل إلى الساعة سبعة عشر سوطًا،، فمدَّ بشر رجله، وجعل ينظر إلى ساقيه، ويقول: "ما أقبح هذا الساق أن لا يكون القيد فيه نصرة لهذا الرجل! ").', 'علو الهمة', null, 361, '{}', false, 'published'),
  ('5ca5f813-6394-4433-b93e-f7ebc4572c58', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وأملى شمس الأئمة السَّرَخْسِي كتابه "المبسوط" نحو خمسة عشر مجلدًا، وهو في السجن بـ "أوزجند"، كان محبوسًا فِي الجُبِّ بسبب كلمة نصح بها الخاقان، وكان يملي من خاطره من غير مطالعة كتاب وهو في الجبِّ، وأصحابه في أعلى الجب، وقال عند فراغه من شرح العبادات: "هذا آخر شرح العبادات بأوضح المعاني وأوجز العبارات، إملاء المحبوس عن الجمع والجماعات".', 'علو الهمة', null, 362, '{}', false, 'published'),
  ('b927ef47-7869-4582-be3f-c203e3750416', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقال في آخر شرح الإقرار: "انتهى شرح الإقرار المشتمل من المعاني على ما هو من الأسرار، إملاء المحبوس في محبس الأشرار".', 'علو الهمة', null, 362, '{}', false, 'published'),
  ('1fcf99e6-dcb1-469c-9462-2ce59caf24a1', null, '33333333-3333-4333-8333-000000000002', 'saying', 'فينبغي على المصلحين أن يصرفوا قدرًا عظيمًا من الجهد في توجيه الآباء إلى الأساليب العلمية الصحيحة لتربية أولادهم في شتى مراحل نموهم، كي يشبوا أصحاء نفسيًّا، وإلا فما أفدح الخسائر التي تتكبدها الأمة إذا هي أهملت تربية أبنائها!', 'علو الهمة', null, 364, '{}', false, 'published'),
  ('1057d11e-33c9-4645-83c2-c9e42820790f', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقال ابن خلدون: "التعليم في الصغر أشد رسوخًا، وهو أصل لما بعده".', 'علو الهمة', null, 366, '{}', false, 'published'),
  ('a8e834b2-2b29-4d43-a412-f96123960a6c', null, '33333333-3333-4333-8333-000000000002', 'saying', 'لقد اشتد حرص السلف على مباشرة هذه المهمة الجسيمة، حتى أن المنصور بعث إلى مَن في الحبس من بني أمية، يقول لهم: "ما أشدُّ ما مَرَّ بكم في هذا المحبس؟ "، فقالوا: "ما فقدنا من تربية أولادنا".', 'علو الهمة', null, 367, '{}', false, 'published'),
  ('e4321d17-3da6-495d-8db6-7db5b1007708', null, '33333333-3333-4333-8333-000000000002', 'saying', 'قال عمرو بن العاص لحلقة قد جلسوا إلى جانب الكعبة، فلما قضى طوافه جلس إليهم وقد نحوا الفتيان عن مجلسهم، فقال: "لا تفعلوا! أوسعوا لهم، وأدنوهم، وألهموهم، فإنهم اليوم صغار قوم يوشك أن يكونوا كبار قوم آخرين، قد كنا صغار قومٍ أصبحنا كبار آخرين".', 'علو الهمة', null, 367, '{}', false, 'published'),
  ('dd8ca305-2608-4ed2-9f67-522e20a0ed59', null, '33333333-3333-4333-8333-000000000002', 'saying', 'تعلم يا فتى والعود رطب... وطينك لَيْنٌ والطبع قابل تظهر علامات النجابة ومخايل العبقرية في الصغر، حتى لا يكاد يشك ذو فراسة إيمانية صادقة في صيرورة صاحبها إلى تسنم ذرا العلا، والتربع على قمة المجد، والإرتقاء إلى منصب الإمامة.', 'علو الهمة', null, 367, '{}', false, 'published'),
  ('73aef5b4-b153-41a9-bce7-a8befb809446', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ولقد اهتم المسلمون بالاجتهاد في الاكتشاف المبكر للنابغين، ووضعوا لذلك معايير دقيقة، وأوْلَوُا الصغار الذين توسَّموا فيهم النجابة رعاية خاصة ترقبًا لما تفرسوه فيهم من الصدارة.', 'علو الهمة', null, 368, '{}', false, 'published'),
  ('1b7bec76-6be9-4f2c-ba0b-ee1d4f54fe3c', null, '33333333-3333-4333-8333-000000000002', 'saying', 'فوجدته سبحانه لا يختار إلا شخصًا كامل الصورة، لا عيب في صورته، ولا نقص في خلقته، فتراه حسن الوجه، معتدل القامة، سليمًا من آفة في بدنه، ثم يكون كاملًا في باطنه، سخيًّا جوادًا، عاقلًا، غير خِبٌّ ولا خادع، ولا حقود ولا حسود، ولا فيه عيب من عيوب الباطن.', 'علو الهمة', null, 368, '{}', false, 'published'),
  ('930bd9cf-b14c-4c3f-b772-cbf67fd28a82', null, '33333333-3333-4333-8333-000000000002', 'saying', 'فذاك الذي يربيه من صغره، فتراه في الطفولة معتزلًا عن الصبيان، كأنه في الصبا شيخ، ينبو عن الرذائل، ويفزع من النقائص، ثم لا تزال شجرة همته تنمو حتى يرى ثمرها متهدِّلًا على أغصان الشباب، فهو حريص على العلم، منكمش على العمل، حافظ للزمان، مراعٍ للأوقات، ساعٍ في طلب الفضائل، خائف من النقائص.', 'علو الهمة', null, 368, '{}', false, 'published'),
  ('196ce26e-8048-4e56-9f50-aad342434a45', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ولو رأيت التوفيق والإلهام الرباني يحوطه، لرأيت كيف يأخذ بيده إن عثر، ويمنعه من الخطإ إن همَّ، ويستخدمه في الفضائل، ويستر عمله عنه حتى لا يراه منه) اهـ.', 'علو الهمة', null, 369, '{}', false, 'published'),
  ('aa925bd1-fb49-4759-a14e-d47dea677c66', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وَمرَّ به عمر بن الخطاب رضي الله عنه وهو صبي يلعب مع الصبيان فَفَرُّوا ووقف، فقال له: "ما لك لم تَفرَّ مع أصحابك؟ "، قال: "يا أمير المؤمنين! لم أجْرِم فأخاف، ولم تكن الطريق ضيقة، فأوسِّع لك".', 'علو الهمة', null, 369, '{}', false, 'published'),
  ('23bee6fc-6802-4cfb-a32b-a1c74894b2f9', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ونظر الحطيئة إلى ابن عباس يتكلم في مجلس عمر، فقال: "من هذا الذي نزل عن الناس في سنه، وعَلَاهم في قوله؟ "، فقال ابن مسعود: "لو بلغ أسناننا ما عَشَّره منا رجل".', 'علو الهمة', null, 370, '{}', false, 'published'),
  ('fb37793d-2011-4854-aace-bf54d88f0494', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ونظر رجل إلى أبي دُلَف في مجلس المأمون، فقال: "إن همته ترمي به وراء سِنِّه".', 'علو الهمة', null, 370, '{}', false, 'published'),
  ('581bb41b-f69d-4051-988e-d7dedd090057', null, '33333333-3333-4333-8333-000000000002', 'saying', 'قال الذهبي: "كان يُنَوَّهُ بذِكره في صغره من أجل فرط ذكائه وحفظه، وحدَّث وهو شاب".', 'علو الهمة', null, 370, '{}', false, 'published'),
  ('66099f5d-a4bb-42aa-8bf0-f38d80f22af6', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقال ابن مهدي: رأى أبو إسحاق السَّبيعُّي سفيان الثوريَّ مُقبلًا، فقال: {وآتيناه الحكم صبيًّا}.', 'علو الهمة', null, 371, '{}', false, 'published'),
  ('adc562b8-5a00-4b9c-88a6-d0895ff8257d', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وحفظ الإمام أحمد بن حنبل القرآن في صباه وتعلم القراءة والكتابة، ثم اتجه إلى الديوان يمرن على التحرير، ويقول عن نفسه: "كنت وأنا غليم أختلف إلى الكتَّاب، ثم اختلفت إلى الديوان وأنا ابن أربعَ عشرةَ سنة"، وكانت نشأته فيها آثار النبوغ والرشد حتى قال بعض الآباء: "وأنا أنفق على ولدي وأجيئهم بالمؤدبين على أن يتأدبوا، فما أراهم يفلحوق، وهذا أحمد بن حنبل غلام يتيم، انظروا كيف!! " وجعل يعجب من أدبه وحسن طريقته.', 'علو الهمة', null, 372, '{}', false, 'published'),
  ('d98ffb39-96d9-4c4c-b221-c6cba3c32c8d', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وكان عمه يرسل إلى بعض الولاة بأحوال بغداد ليعلم بها الخليفة، وقد أرسلها مرة مع ابن أخيه أحمد بن حنبل فتورع عن ذلك ورمى بها في الماء تأثمًا من الوشاية والتسبب لما عسى أن يكون فيه ضرر بالمسلمين، وقد لفت هذا الورع وهذه النجابة كثيرًا من أهل العلم والفراسات حتى قال الهيثم بن جميل: "إن عاش هذا الفتى فسيكون حجة على أهل زمانه".', 'علو الهمة', null, 373, '{}', false, 'published'),
  ('04ad3aa9-9d4a-4989-aef5-0d5188f99f14', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقد رُوي عن معمر في تفسير قوله تعالى: {وَآتيناه الحكم صبيًّا} أن الصبيان قالوا ليحيى: "اذهب بنا نلعب"؛ فقال: "ما لِلَّعِبِ خُلِقْتُ".', 'علو الهمة', null, 374, '{}', false, 'published'),
  ('a8c66769-37b5-4d91-a7d6-894aaf136442', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وأُدخل على الرشيد صبي له أربع سنين، فقال له: "ما تحب أن أهب لك؟ " قال: "حُسْنَ رأيك".', 'علو الهمة', null, 375, '{}', false, 'published'),
  ('27c246d2-317d-4781-8147-aa9e999dd033', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وحكى ابن الجوزي أن المعتصم ركب إلى خاقان يعوده، والفتحُ صبي يومئذ، فقال له المعتصم: "أيُّما أحسنُ: دارُ أمير المؤمنين أو دار أبيك؟ " قال: "إذا كان أمير المؤمنين في دار أبي، فدارُ أبي أحسن"، فأراه فصًّا في يده، فقال: "هل رأيت يا فتحُ أحسنَ من هذا الفصِّ؟ " قال: "نعم، اليدُ التي هو فيها".', 'علو الهمة', null, 375, '{}', false, 'published'),
  ('0b800c6f-41de-4960-9e56-a002b89400c9', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وروى أيضًا صاحب: "صفة الأولياء، ومراتب الأصفياء" بإسناده قال: ذَكر "سَهْلٌ" اللهَ، وهو ابنُ ثلاث سنين، وصام وهو ابن خمس سنين حتى مات، وساح في طلب العلم وهو ابن تسع سنين، وكانت تُلقى مشكلاتُ المسائل على العلماء، ثم لا يوجَدُ جوابُها إلَّا عنده، وهو ابن اثنتي عشرة سنة، وحينئذ ظهرت عليه الكرامات".', 'علو الهمة', null, 377, '{}', false, 'published'),
  ('6426eccb-1fb1-4acf-87af-6f9b9459e0e8', null, '33333333-3333-4333-8333-000000000002', 'saying', 'فكان أبوه بعد ذلك يقوم من الليل ويصلي، فاستيقظ أبو يزيد ليلة فإذا أبوه يصلي، فقال: "يا أبت: علِّمني كيف أتطهر وأصلي معك"، فقال أبوه: "يا بني ارقد فإنك صغير بعدُ"، قال: (يا أبت: إذا كان يومُ يصدر الناس أشتاتًا لِيُرَوْا أعمالهم أقول لربي: إني قلت لأبى: كيفي أتطهر لأصلي معك؟ فأبى، وقال لي: "ارقد، فإنك صغير بعد"، أتحب هذا؟)، فقال له أبوه: "لا والله يا بني ما أحب هذا"، وعَلَّمه فكان يصلي معه].', 'علو الهمة', null, 380, '{}', false, 'published'),
  ('f81fde43-343e-4aaa-b54d-8e49f1e479dd', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ومن أهم الخصائص: سلامة البدن، وقوة الذاكرة، وسرعة التعلم، والتفوق في التحصيل الدراسي، وحب الاستطلاع، والدافعية للإنجاز، والثقة بالنفس، والاستقلالية، والمثابرة، والتفوق في القيمة النظرية، وفي الميول العلمية، والنضوج الاجتماعي، والنشأة في ظروف اجتماعية طيبة).', 'علو الهمة', null, 381, '{}', false, 'published'),
  ('84e77d29-facc-4e20-a089-bfa70a4585f5', null, '33333333-3333-4333-8333-000000000002', 'saying', 'إن المرء لا يولد عالمًا، وإنما تربيه جماعة، وتصنعه بيئة، وتتعهده بالرعاية والتعليم، حتى يمتلك ناصية العلم الذي يطلبه.', 'علو الهمة', null, 381, '{}', false, 'published'),
  ('1a262e65-2b75-4e10-b90a-7d8b670875a5', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ومع كون المواهب استعدادات فطرية فإنها لا تؤدي إلى النبوغ إلا إذا توفرت لأصحابها الظروف البيئية المناسبة والتربة الصالحة اللازمة لتنميتها وصقلها.', 'علو الهمة', null, 382, '{}', false, 'published'),
  ('68a6e2b6-1bcc-4a06-a310-6ef1ca55f2b8', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وتعد الأسرة -وبخاصة الوالدان أو من يقوم مقامهما- أهم عناصر البيئة تأثيرًا في إظهار النبوغ، وزراعة الهمة العالية في قلوب الأطفال منذ نعومة أظفارهم، وهذا ما قد يفسر لنا سر أتصال سلسلة النابغين من أبناء أسر معينة، كآل تيميةَ مثلًا- حيث اجتمعت الاستعدادات الفطرية الموروثة، والقدرات الإبداعية، مع البيئة المساعدة التي تكشف هذه المواهب مبكرًا، وتنميها، وتوجهها إلى الطريق الأمثل.', 'علو الهمة', null, 382, '{}', false, 'published'),
  ('80786fe5-3952-42b6-83d4-0723127a67eb', null, '33333333-3333-4333-8333-000000000002', 'saying', 'فرب أم ذكية محبة للعلم، أو أب عالم مشهود بعلمه، كان سببًا فِي تيسير السبيل إلى العلم، ومجالسة العلماء، مما كان له أثر بليغ في تنمية نبوغ أبنائهم.', 'علو الهمة', null, 382, '{}', false, 'published'),
  ('0426b016-6c1c-4e3c-90c2-16abbed36cd9', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقد كان معاوية رضي الله عنه إذا نوزغ بالفحر بالمقدرة، وجوذب بالباهاة بالرأي، انتسب إلى أمه، فصدع أسماع خصمه بقوله: "أنا ابن هند".', 'علو الهمة', null, 383, '{}', false, 'published'),
  ('d0d3a178-6c70-40e2-b52e-39454cd3b1a3', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وهذ الِإمام الثقة الثبت أبو عمرو الآوزاعي نشأ يتيمًا في حجر أمه، التي تنقلت به من بلد إلى بلد، وربته تربية عجزت الملوك وأبناؤها عنها، حتى استُفتي في الفقه وله ثلاث عشرة سنة.', 'علو الهمة', null, 383, '{}', false, 'published'),
  ('8a61753e-0a7d-49ce-a451-ce0ed4f6c43f', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وكذا فعلت أم الإمام "ربيعة بن أبي عبد الرحمن" شيخ الإمام مالك، فقد كان ثمرة تربية أم فاضلة أنفقت عليه أمه ثلاثين ألف دينار خلَّفها زوجها عندها، وهي حامل به، وخرج إلى الغزو، ولم يعد لها إلا بعد أن استكمل ولده الرجولة والمشيخة.', 'علو الهمة', null, 384, '{}', false, 'published'),
  ('374fcacf-c846-4617-b960-676ea2046bbb', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وها هي أم الإمام مالك إمام دار الهجرة تؤزه على طلب العلم، وتلبسه ثياب العلم، وتقول له: "اذهب إلى ربيعة، فتعلم من أدبه قبل علمه".', 'علو الهمة', null, 384, '{}', false, 'published'),
  ('6e0a4047-3288-4f7b-8d64-e50b4b0849b1', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ومات والد الإمام الشافعي وهو جنين أو رضيع، فتولته أمه بعنايتها، وأشرقت عليه بحكمتها، وتنقلت به من "غزة" إلى "مكة" مستقر أخواله، فربته بينهم هنالك.', 'علو الهمة', null, 384, '{}', false, 'published'),
  ('c00a7e8d-6d39-4fb9-b2fb-a6c945a48104', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ونشأ الإمام الشافعي يتيمًا فقيرًا، ولم تستطع أمه دفع أجر معلِّمه، إلا أن المعلم قبل أن يعلمه بدون أجر، وتعهده بالرعاية، وجعل له منزلة خاصة بين التلاميذ، لما لمسه فيه من نباهة، وسرعة في الحفظ.', 'علو الهمة', null, 384, '{}', false, 'published'),
  ('6e23f80b-7a06-4586-9f38-631e71ce1e67', null, '33333333-3333-4333-8333-000000000002', 'saying', 'قال الشافعي رحمه الله: "كنت يتيمًا في حجر أمي، ولم يكن معها ما تعطي المعلم، وكان المعلم قد رضي أن يعلمني بدون أجر، وأن أخلفه في الدرس إذا قام".', 'علو الهمة', null, 384, '{}', false, 'published'),
  ('86522458-b1c7-4566-9553-b07e3ea8b0df', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وبغير هذا "النضوج الاجتماعي المبكر" والتربية الواعية -التي تنمي الملكات، وتغرس الثقة في النفس، وتحررها من التواكل والتبعية والطفولية- لا نستطع أن نفسر ظاهرة ارتحال العلماء في سن الصبا والشباب المبكر في أقطار الدنيا طلبًا للعلم، وقد فارقوا الأهل والأوطان، وكابدوا المخاطر والمشاق دون كلل ولا ملل ولا تبرم.', 'علو الهمة', null, 386, '{}', false, 'published'),
  ('c09f4108-66ae-4ba7-9d70-32b229c493e7', null, '33333333-3333-4333-8333-000000000002', 'saying', 'نشأ المتنبي شاعر العرب الفحل في أسرة فقيرة غير متعلمة، لكن الله قيَّض له فرصة التعليم المجاني في كُتَّاب خاص بأبناء أشراف الكوفة، وشجعه أصحاب المكتبات على قراءة الكتب دون مقابل.', 'علو الهمة', null, 387, '{}', false, 'published'),
  ('5b7dfcc0-766b-436e-b679-e28d7c02a6e7', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وذكر الكردري أيضًا أن الحسن بن زياد كان فقيرًا، وكان يلازمه -أي الِإمام- وكان أبوه يقول له: "لنا بنات، وليس لنا ابن غيرك، فاشتغل بهن"، فلما بلغ الخير الإمام أجرى عليه رزقًا، وقال: "الزم الفقه، فإني ما رأيت فقيهًا معسرًا قط".', 'علو الهمة', null, 389, '{}', false, 'published'),
  ('9ba1daeb-0de4-4f96-beca-565946b12aa9', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وربما كانت نصيحة عابرة من عالم مخلصٍ بدايةَ نقطة تحولٍ فِي حياة أحد النابغين إلى انتفاع عموم الأمة به، كذلك الِإمام الذي لقي نابغة كبير الهمة وقد جاور في الحرم المكي الشريف، وخلَّى مكانه في التعليم والدعوة في بلده، فأرشده إلى تصحيح مساره بقوله: "ليس هذا مكانك".', 'علو الهمة', null, 390, '{}', false, 'published'),
  ('e9642c5b-c0cc-4ae7-a2b2-dba2832c464a', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقد أمره بالِإفتاء شيخه أبو خالد مسلم بن خالد الزنجي إمام أهل مكة ومفتيها، وقال له: "أفت يا أبا عبد الله! فقد -والله- آن لك أن تفتي"، وكان للشافعي إذ ذاك خمسَ عشرةَ سنة، وأقاويل أهل عصره فِي هذا كثيرة مشهورة، وأخِذَ عن الشافعي العلمُ في سن الحداثة مع توفر العلماء في ذلك العصر، وهذا من الدلائل الصريحة لعظم جلالته وعلو مرتبته، وهذا كله من المشهور المعروف في كتب مناقبه وغيرها.', 'علو الهمة', null, 391, '{}', false, 'published'),
  ('5719f644-65dc-4f07-b077-d3a6a1db776e', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وحكى ابنُ العلامة القرآني الإمام محمد الأمين الشنقيطي رحمه الله تعالى أن أمارات النبوغ، وعلو الهمة لما لاحت على والده في طفولته، قال له شيخه: "يا بني إن العلماء يقولون: إن من وجد من نفسه استعدادًا وموهبة تؤهله للإمامة تعيَّن عليه طلبها، وإن طلب الإمامة في الدين متعين عليك، فلا تضيع نفسك" اهـ بمعناه.', 'علو الهمة', null, 392, '{}', false, 'published'),
  ('09337501-b3f7-4b9b-89d7-e762a013cc31', null, '33333333-3333-4333-8333-000000000002', 'saying', 'حسنًا عن قريب سيكون لي في القسطنطينية عرش أو يكون لي فيها قبر".', 'علو الهمة', null, 393, '{}', false, 'published'),
  ('acfe6d76-8ba0-4612-82b0-31887a361c6b', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وحاصر السلطان "محمد الفاتح" -أنعم به من فاتح- القسطنطينية واحدًا وخمسين يومًا، تعددت خلالها المعارك العنيفة، وبعدها سقطت المدينة الحصينة التي استعصت على الفاتحين قبله، على يد بطل شاب، له من العمر ثلاث وعشرون سنة، وحقق هذا الفاتح البطل للمسلمين أملًا غاليًا ظل يراودهم ثمانية قرون، حاولوا تحقيقه مرارًا فلم يفلحوا، وكأنَّ القدر كان قد ادَّخر هذا الشرف لهذا البطل المغوار.', 'علو الهمة', null, 393, '{}', false, 'published'),
  ('181e2eec-f00c-42b8-92d5-0d0d6c55d97f', null, '33333333-3333-4333-8333-000000000002', 'saying', 'رفع الإسلام شأن التشجيع إلى حَدِّ أنه جعله فريضة على غير القادر علي إقامة فروض الكفايات مثل الأمر بالعروف والنهي عن المنكر، وطلب العلم، والولاية والِإمامة، وعبارة الفقهاء في مثل هذه الفروض: "أنها واجب على الكفاية، فإن قام بها البعض سقط الوجوب عن الآخرين، وإن لم يقم بها أحد أثموا جميعًا، القادرُ: لأنه قصَّر، وغيرُ القادر: لأنه قصَّر فيما يستطيعه، وهو التفتيش عن القادر وحَمْله على العمل، وحثه وتشجيعه، وإعانته على القيام به، بل إجباره على ذلك".', 'علو الهمة', null, 393, '{}', false, 'published'),
  ('d9494958-8b58-49a3-8efb-529adab9d33d', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ولقد تسابق المسلمون في شتى العصور على تشجيع الموهوبين وكبيري الهمة، بكافة صور التشجيع، فكانوا ينفقون الأموال الجزيلة لنفقة النابغين من طلاب العلم، الذين حبسوا أنفسهم على طلبه، كي يغنوهم عن سؤال الناس، أو الاشتغال عن العلم بطلب المعاش.', 'علو الهمة', null, 394, '{}', false, 'published'),
  ('c580bc98-79f9-4524-aac0-ecc9544d42a8', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقد كان ابن شهاب رحمه الله يشجع الأولاد الصغار، ويقول لهم: "لا تحتقروا أنفسكم لحداثة أسنانكم، فإنْ عمر بن الخطاب رضي الله عنه كان إذا نزل به الأمر المعضل، دعا الفتيان فاستشارهم يتبع حدة عقولهم".', 'علو الهمة', null, 396, '{}', false, 'published'),
  ('7b7a8dda-023b-42e3-bae5-5e00da3aac25', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقد بلغ حب بعض الأمراء للعلم والعلماء إلى الحد الذىٍ جعله يعتبر العلماء في رعايته الخاصة، من هؤلاء الأمراء "المعز بن باديس" -أحد أمراء دولة الصهاجين في المغرب الِإسلامي- كان لا يسمع بعالم جليل إلا أحضره إلى حضرته، وجعله من خاصته، وبالغ في إكرامه، وعوَّل على آرائه، ومنحه أسمى الرواتب....', 'علو الهمة', null, 397, '{}', false, 'published'),
  ('1506ee84-1ef7-49ff-852a-f5e8a3d161ee', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وفي القرن السادس عشر قامت محاولة ناجحة في عهد الخلافة العثمانية لتجميع النابغين من جميع الأمصار والقرى، وتوفر الرعاية التي جعلت كل نابغة يعطي ما عنده من فن وعلم، مما ساعد على ازدهار الدولة العثمانية حضاريًّا وعسكريًّا حتى باتت تهدد بغزو أوربا].', 'علو الهمة', null, 398, '{}', false, 'published'),
  ('c85468cf-10b4-4b4a-882d-86b4ac1b0d5b', null, '33333333-3333-4333-8333-000000000002', 'saying', 'أيها المغرور! أبلغَ مِن قدرك أن تصنف، وأنت... وأنت... " ثم أخذ الرسالة فسجَّر بها المدفأة.. فكانت هي أول مصنفات العلامة البخاري وآخرها.', 'علو الهمة', null, 400, '{}', false, 'published'),
  ('b055c0b1-244e-404c-b938-c9e89eefd684', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وكان الأجدر بهم أن يشفقوا على أنفسهم، ويشتغلوا بما يعود عليهم وعلى غيرهم بالنفع، ولم يُرَ أحد من المثبطين قديمًا أو حديثًا أتى بأمرٍ مهم، فينبغي للجرائد الكبيرة، أن تكثر من التنبيه على ضرر هذه العادة والتحذير منها، ليخلص منها من لم تستحكم فيه، وينتبه الناس لأربابها ليخلصوا من ضررهم".', 'علو الهمة', null, 401, '{}', false, 'published'),
  ('28f4b345-190b-41fe-91e1-f988bfa2658f', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وفي علماء القرن الماضي في الشام من ارتقى بالجد والدأب والتشجيع من منوال الحياكة، إلى منصب الإفتاء، وكرسي التدريس تحت القبَّة.', 'علو الهمة', null, 401, '{}', false, 'published'),
  ('d29e97a7-478f-4b55-af68-4f4bbb968533', null, '33333333-3333-4333-8333-000000000002', 'saying', 'إن شاء الله! " وسار في طريقه حتى إذا أبتعد عنهم دار في الأزقة حتى عاد إلى داره، فودع أهله، وأعطاهم نفقتهم، وسافر!', 'علو الهمة', null, 402, '{}', false, 'published'),
  ('0ec832ce-f742-499c-8bac-f8eb48c206a0', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وما زال يفارق بلدًا، ويستقبل بلدًا، حتى دخل القسطنطينية فنزل في خان قريب من دار المشيخة، وكان يجلس على الباب يطالع في كتاب، أو يكتب في صحيفة، فيعرف الناس من زيِّه أنه عربي فيحترمونه ويُجِلُّونه، ولم يكن الترك قد جُنُّوا الجِنَة الكبرى بعدُ... فكانوا يعظمون العربي، لأنه من أمة الرسول الأعظم الذي اهتدوا به، وصاروا به وبقومه ناسًا...', 'علو الهمة', null, 402, '{}', false, 'published'),
  ('12d66be4-5e78-4638-bbb2-d42e2c6bab81', null, '33333333-3333-4333-8333-000000000002', 'saying', 'إن السلطان سأل دار المشيخة عن قضية حيَّرت علماءها، ولم يجدوا لها جوابًا، والسلطان يستحثهم وهم حائرون، فهل لك في أن تراها لعلَّ الله يفتح عليك بالجواب؟', 'علو الهمة', null, 403, '{}', false, 'published'),
  ('cbe41a57-de70-4ae6-bb51-ababb7a6634d', null, '33333333-3333-4333-8333-000000000002', 'saying', 'فدعوه وجعلوا يعلمونه كيف يسلِّم على شيخ الِإسلام، وأن عليه أن يشير بالتحية واضعًا يده على صدره، منحنيًّا، ثم يمشي متباطئًا حتى يقوم بين يديه... إلى غير ذلك من هذه الأعمال الطويلة التي نسيها الشيخ، ولم يحفظ منها شيئًا.', 'علو الهمة', null, 404, '{}', false, 'published'),
  ('94020ae9-c7b1-4b1d-9387-3d5c887d64e4', null, '33333333-3333-4333-8333-000000000002', 'saying', 'فقال الشيخ: "من هنا، من اسطنبول، أتيت بتولية الإفتاء كما أمرتني".', 'علو الهمة', null, 404, '{}', false, 'published'),
  ('4456ac7b-3aca-49f6-9f28-bc65fbd8718f', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ومن هذا الباب قصة الشيخ "على كزبر"، وقد كان خياطًا في سوق المسكية على باب الجامع الأموي، فكان إذا فرغ من عمله ذهب فجلس في الحلقة التي تحت القبة فاستمع إلى الشيخ حتى يقوم فيلحق به فيخدمه، وكان الشيخ يعطف عليه لما يرى من خدمته إياه، فيشجعه ويحثه على القراءة، فقرأ ودأب على المطالعة، حتى صار يقرأ بين يدي الشيخ في الحلقة، ولبث على ذلك أمدًا وهو لا يفارق دكَّانه، ولا يدع عمله، حتى صار مقدمًا في كافة العلوم.', 'علو الهمة', null, 405, '{}', false, 'published'),
  ('26e7acde-bade-4909-abbb-a0f0822ce452', null, '33333333-3333-4333-8333-000000000002', 'saying', 'قالت حفصة بنت سيرين: "يا معشر الشباب اعملوا، فإنما العمل في الشباب}، وقال الأحنف بن قيس: "السودد مع السواد".', 'علو الهمة', null, 407, '{}', false, 'published'),
  ('467256d4-4afd-4b04-a7d3-c591ac6e1e55', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وقال يحيى بن معين لأحمد بن حنبل وقد رآه يمشي خلف بغلة الشافعي: "يا أبا عبد الله تركت حديث سفيان بعلوِّه، وتمشي خلف بغلة هذا الفتى وتسمع منه؟ "، فقال له أحمد: "لو عرفت لكنت تمشي من الجانب الآخر، إنَّ علم سفيان إن فاتني بعُلُوٍّ أدركتُه بنزول، وإن عقل هذا الشاب إن فاتني لم أدركه بِعُلُوٍّ ولا نزول".', 'علو الهمة', null, 407, '{}', false, 'published'),
  ('38a06d74-118d-4bbf-92b3-07bce44f2e53', null, '33333333-3333-4333-8333-000000000002', 'saying', 'قدم وفد على عمر بن عبد العزيز من العراق، فنظر إلى شاب منهم يتحوَّز يريد الكلام، فقال عمر: "كبِّروا كبروا"، فقال الفتى: "يا أمير المؤمنين إن الأمر ليس بالسن، ولو كان كذلك كان في المسلمين من هو أسنُّ منك"، قال: "صدقت، فتكلم".', 'علو الهمة', null, 407, '{}', false, 'published'),
  ('322bab9c-89a9-4bc2-b6a4-ce08764d5862', null, '33333333-3333-4333-8333-000000000002', 'saying', 'قاد الجيوش لسبعَ عشرةَ حِجةً... يا قرب ذلك سُوددًا من مولدِ!', 'علو الهمة', null, 409, '{}', false, 'published'),
  ('45d2ddf0-3ad6-4cb9-aee0-df45c13610ea', null, '33333333-3333-4333-8333-000000000002', 'saying', 'فأمر الحجاج بتعذيبه، حتى انتهى به العذاب إلى أن يشقق له القصب، ثم جعلوه على لحمه وشدوه بالحبال، ثم جعلوا يمدون قصبة قصبة حتى انتحلوا لحمه، فما سمعوه يقول شيئًا، ولا بدا عليه جزع أو ضعف.', 'علو الهمة', null, 409, '{}', false, 'published'),
  ('8229ce5c-f6e3-4637-bce8-81dea2dad1be', null, '33333333-3333-4333-8333-000000000002', 'saying', 'فأخبر الحجاج بأمره، وأنه في الرمق الأخير، فقال: "أخرجوه فارموا به في السوق"، ووقف عليه رجل وهو بين الحياة والموت يسأله: "ألك حاجة؟ " فما كان من "حطيط" إلا أن قال: "ما لي من حاجة في دنياكم إلا شربة ماء"، فأتوه بشربة شربها، ثم مات، وكان ابن ثماني عشرة سنة.', 'علو الهمة', null, 409, '{}', false, 'published'),
  ('d24782f9-6d4c-498e-9a09-bd7fa075f6c3', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وولي عُبيد الله بن زياد خُراسان وهو ابن ثلاث وعشرين سنة، وليها لمعاوية رضي الله عنه - وولي معاذ اليمن وهو ابن أقل من ثلاثين سنة.', 'علو الهمة', null, 410, '{}', false, 'published'),
  ('0f66f083-2ade-4eaf-9edf-bdc5d6be11ee', null, '33333333-3333-4333-8333-000000000002', 'saying', 'إن الشباب هم الشريحة الفعالة في الأمة، وهم عمودها الفِقْرِيُّ، وجهازها العضلي، وروحها الحية، وطليعتها الوثابة، ولا يتصور نجاح دعوة أو حركة لا تقوم على حماس الشباب وقوته.', 'علو الهمة', null, 410, '{}', false, 'published'),
  ('afd38ecd-11ff-41d5-ba19-a034450dac1c', null, '33333333-3333-4333-8333-000000000002', 'saying', 'إن أصحاب الهمة العالية فحسب هم الذين يقوون على البذل في سبيل المقصد الأعلى، وهم الذين يبدلون أفكار العالم، ويغيرون مجرى الحياة بجهادهم وتضحياتهم، ومن ثم فهم القلة التي تنقذ الموقف، وهم الصفوة التي تباشر مهمة "الانتشال السريع" من وحل الوهن، ووهدة الإحباط.', 'علو الهمة', null, 411, '{}', false, 'published'),
  ('435ee9e2-54cd-4bb8-8201-3a2af98fc0da', null, '33333333-3333-4333-8333-000000000002', 'saying', 'وفي جُنْحِ هذا الظلام الحالك والليل الأليل تكاد تفتقد أمتنا البدر المنير، وتترقب مجيء "رجل الساعة"، والمصلح المنتظر، ويحدوها الأمل في طلوع فجر قريب يؤذن ببعث المجدِّد المرتقب الذي بشر به الصادق المصدوق في قوله: "إن الله تعالى يبعث لهذه الأمة على رأس كل مائة سنة مَنْ يجدد لها دينها".', 'علو الهمة', null, 412, '{}', false, 'published'),
  ('3ce06334-9ed0-4d76-a866-6c628f02c7e3', null, '33333333-3333-4333-8333-000000000002', 'saying', 'فيا شباب الِإسلام: قد فتح باب الترشيح، فهيَّا تسابقوا إلى العلا، وتنافسوا في جنة عرضها السماوات والأرض، واختطوا لأنفسكم طريق المجد، فتالله ما ارتفع صوت الحادي يومًا لرفقة أولي صَمَم، ولا ارتفع الفلك الأعلى لغير أهل الشموخ والشَّمَم.', 'علو الهمة', null, 413, '{}', false, 'published'),
  ('c168a00d-aa93-4f59-b5da-db5147cb2b6b', null, '33333333-3333-4333-8333-000000000002', 'saying', 'فمن منكم ينتدب نفسه لهذه المهمة الجسيمة التي قال فيها المجدِّدُ العَلَمُ، والجبل الأشم أمير المؤمنين عمر بن عبد العزيز رحمه الله: "إني أعالج أمرًا لا يُعين عليه إلا الله، قد فني عليه الكبير، وكبر عليه الصغير، وفصُح عليه الأعجمي، وهاجر عليه الأعرابي، حتى حسبوه دينًا لا يرون الحقَّ غيرَه"؟! من منكم -ممن يعرف قدر نفسه بلا وَكْسٍ ولا شطط- يراها أهْلًا لهذه الوظيفة المقدسة؟', 'علو الهمة', null, 413, '{}', false, 'published'),
  ('ba75eb21-c3b5-435d-bddc-7891e96204a8', null, '33333333-3333-4333-8333-000000000002', 'saying', 'ولا يظننَّ ظانٌّ أن حديثنا عن علو همة أسلافنا العظام يعني الانطواء في الماضي وقطع الصلة بالحاضر والمستقبل، وإلا صرنا كالترجُمان الذي يتوقف أمام الآثار ويشيد بالماضي فحسب، دون أن يقدم شيئًا للحاضر بَلْهَ المستقبل.', 'علو الهمة', null, 415, '{}', false, 'published'),
  ('2d798379-3889-40de-a0e3-f65f2bc92250', null, '33333333-3333-4333-8333-000000000002', 'saying', 'إن أمتك المسلمة تترقب منك جذبة "عُمَرِيِّة" توقد في قلبها مصباح الهمة في ديجور هذه الغفلة المدلهمة، وتنتظر منك صيحة "أيوبية" تغرس بذرة الأمل، في بيداء اليأس، وعلى قدر المئونة؛ تأتي من الله المعونة، فاستعن بالله ولا تعجز.', 'علو الهمة', null, 416, '{}', false, 'published')
insert into public.hadiths (id, collection, text, narrator, chapter, number, volume, page, source_id, topic, tags, needs_reference_check, status) values
  ('44444444-4444-4444-8444-000000000001', 'bukhari', 'إِنَّمَا الْأَعْمَالُ بِالنِّيَّاتِ، وَإِنَّمَا لِكُلِّ امْرِئٍ مَا نَوَى، فَمَنْ كَانَتْ هِجْرَتُهُ إِلَى دُنْيَا يُصِيبُهَا، أَوْ إِلَى امْرَأَةٍ يَنْكِحُهَا، فَهِجْرَتُهُ إِلَى مَا هَاجَرَ إِلَيْهِ.', 'عمر بن الخطاب رضي الله عنه', 'كتاب بدء الوحي', 1, 1, 6, '33333333-3333-4333-8333-000000000001', 'فضائل الأعمال', array['النية', 'الإخلاص']::text[], false, 'published'),
  ('44444444-4444-4444-8444-000000000002', 'bukhari', 'من صام رمضان إيماناً واحتساباً، غُفر له ما تقدّم من ذنبه.', 'أبي هريرة رضي الله عنه', 'كتاب الإيمان', 38, 3, 45, '33333333-3333-4333-8333-000000000001', 'فضائل الأعمال', array['الصيام', 'رمضان']::text[], false, 'published'),
  ('44444444-4444-4444-8444-000000000003', 'bukhari', 'من قام ليلة القدر إيماناً واحتساباً، غُفر له ما تقدّم من ذنبه.', 'أبي هريرة رضي الله عنه', 'كتاب صلاة التراويح', 1901, 3, 26, '33333333-3333-4333-8333-000000000001', 'فضائل الأعمال', array['قيام الليل', 'ليلة القدر']::text[], false, 'published'),
  ('44444444-4444-4444-8444-000000000004', 'bukhari', 'من صلّى البَرْدَين دخل الجنة.', 'أبي موسى الأشعري رضي الله عنه', 'كتاب مواقيت الصلاة', 574, 1, 119, '33333333-3333-4333-8333-000000000001', 'فضائل الأعمال', array['الصلاة']::text[], false, 'published'),
  ('44444444-4444-4444-8444-000000000005', 'muslim', 'الصلوات الخمس، والجمعة إلى الجمعة، ورمضان إلى رمضان، مكفّراتٌ ما بينهن إذا اجتُنبت الكبائر.', 'أبي هريرة رضي الله عنه', 'كتاب الطهارة', 233, 1, 209, '33333333-3333-4333-8333-000000000001', 'فضائل الأعمال', array['الصلاة', 'التكفير']::text[], false, 'published'),
  ('44444444-4444-4444-8444-000000000006', 'muslim', 'مَنْ بَنَى مَسْجِدًا لِلَّهِ بَنَى اللَّهُ لَهُ فِي الْجَنَّةِ مِثْلَهُ.', 'عثمان بن عفان رضي الله عنه', 'كتاب المساجد ومواضع الصلاة', 533, 1, 378, '33333333-3333-4333-8333-000000000001', 'فضائل الأعمال', array['الصدقة', 'المساجد']::text[], false, 'published'),
  ('44444444-4444-4444-8444-000000000007', 'bukhari', 'من قال: سبحان الله وبحمده، في يومٍ مائة مرة، حُطّت خطاياه وإن كانت مثل زَبَد البحر.', 'أبي هريرة رضي الله عنه', 'كتاب الدعوات', 6405, 8, 86, '33333333-3333-4333-8333-000000000001', 'فضائل الأعمال', array['الذكر']::text[], false, 'published'),
  ('44444444-4444-4444-8444-000000000008', 'bukhari', 'كلمتان خفيفتان على اللسان، ثقيلتان في الميزان، حبيبتان إلى الرحمن: سبحان الله وبحمده، سبحان الله العظيم.', 'أبي هريرة رضي الله عنه', 'كتاب التوحيد', 7563, 8, 139, '33333333-3333-4333-8333-000000000001', 'فضائل الأعمال', array['الذكر']::text[], false, 'published'),
  ('44444444-4444-4444-8444-000000000009', 'bukhari', 'مَنْ غَدَا إِلَى الْمَسْجِدِ وَرَاحَ، أَعَدَّ اللهُ لَهُ نُزُلَهُ مِنَ الْجَنَّةِ، كُلَّمَا غَدَا أَوْ رَاحَ.', 'أبي هريرة رضي الله عنه', 'كتاب الأذان', 662, 1, 133, '33333333-3333-4333-8333-000000000001', 'فضائل الأعمال', array['الصلاة', 'المساجد']::text[], false, 'published'),
  ('44444444-4444-4444-8444-000000000010', 'bukhari', 'الساعي على الأرملة والمسكين كالمجاهد في سبيل الله.', 'أبي هريرة رضي الله عنه', 'كتاب النفقات', 5353, 8, 9, '33333333-3333-4333-8333-000000000001', 'فضائل الأعمال', array['الصدقة', 'الإحسان']::text[], false, 'published'),
  ('44444444-4444-4444-8444-000000000011', 'muslim', 'من دلّ على خيرٍ فله مثل أجر فاعله.', 'أبي مسعود الأنصاري رضي الله عنه', 'كتاب الإمارة', 1893, 3, 1303, '33333333-3333-4333-8333-000000000001', 'فضائل الأعمال', array['الدعوة', 'الإحسان']::text[], false, 'published'),
  ('44444444-4444-4444-8444-000000000012', 'muslim', 'أَحَبُّ الأَعْمَالِ إِلَى اللَّهِ تَعَالَى أَدْوَمُهَا وَإِنْ قَلَّ.', 'عائشة رضي الله عنها', 'كتاب صلاة المسافرين وقصرها', 783, 1, 541, '33333333-3333-4333-8333-000000000001', 'فضائل الأعمال', array['المداومة']::text[], false, 'published'),
  ('44444444-4444-4444-8444-000000000013', 'muslim', 'من صلّى الصبح فهو في ذمة الله.', 'جندب بن عبد الله رضي الله عنه', 'كتاب المساجد ومواضع الصلاة', 657, 1, 454, '33333333-3333-4333-8333-000000000001', 'فضائل الأعمال', array['الصلاة']::text[], false, 'published'),
  ('44444444-4444-4444-8444-000000000014', 'bukhari', 'من حجّ فلم يرفُث ولم يفسُق، رجع كيوم ولدته أمه.', 'أبي هريرة رضي الله عنه', 'كتاب الحج', 1521, 2, 133, '33333333-3333-4333-8333-000000000001', 'فضائل الأعمال', array['الحج']::text[], false, 'published'),
  ('44444444-4444-4444-8444-000000000015', 'bukhari', 'أفضل الصدقة أن تصدّق وأنت صحيحٌ شحيح، تخشى الفقر وتأمُل الغنى.', 'أبي هريرة رضي الله عنه', 'كتاب الزكاة', 1419, 2, 110, '33333333-3333-4333-8333-000000000001', 'فضائل الأعمال', array['الصدقة']::text[], false, 'published'),
  ('44444444-4444-4444-8444-000000000016', 'muslim', 'ركعتا الفجر خيرٌ من الدنيا وما فيها.', 'عائشة رضي الله عنها', 'كتاب صلاة المسافرين', 725, 1, 501, '33333333-3333-4333-8333-000000000001', 'فضائل الأعمال', array['السنن الرواتب']::text[], false, 'published'),
  ('44444444-4444-4444-8444-000000000017', 'muslim', 'من سلك طريقاً يلتمس فيه علماً، سهّل الله له به طريقاً إلى الجنة.', 'أبي هريرة رضي الله عنه', 'كتاب الذكر والدعاء', 2699, 4, 2074, '33333333-3333-4333-8333-000000000001', 'فضائل الأعمال', array['العلم']::text[], false, 'published'),
  ('44444444-4444-4444-8444-000000000018', 'muslim', 'الطُّهور شطر الإيمان، والحمد لله تملأ الميزان، وسبحان الله والحمد لله تملآن ما بين السماوات والأرض.', 'أبي مالك الأشعري رضي الله عنه', 'كتاب الطهارة', 223, 1, 203, '33333333-3333-4333-8333-000000000001', 'فضائل الأعمال', array['الطهارة', 'الذكر']::text[], false, 'published'),
  ('44444444-4444-4444-8444-000000000019', 'bukhari', 'مَنْ شَهِدَ الجَنَازَةَ حَتَّى يُصَلِّيَ فَلَهُ قِيرَاطٌ، وَمَنْ شَهِدَ حَتَّى تُدْفَنَ كَانَ لَهُ قِيرَاطَانِ. قِيلَ: وَمَا الْقِيرَاطَانِ؟ قَالَ: مِثْلُ الْجَبَلَيْنِ الْعَظِيمَيْنِ.', 'أبي هريرة رضي الله عنه', 'كتاب الجنائز', 1325, 2, 87, '33333333-3333-4333-8333-000000000001', 'فضائل الأعمال', array['الجنائز']::text[], false, 'published'),
  ('44444444-4444-4444-8444-000000000020', 'muslim', 'مَنْ صَلَّى اثْنَتَيْ عَشْرَةَ رَكْعَةً فِي يَوْمٍ وَلَيْلَةٍ، بُنِيَ لَهُ بِهِنَّ بَيْتٌ فِي الْجَنَّةِ.', 'أم حبيبة رضي الله عنها', 'كتاب صلاة المسافرين', 728, 1, 502, '33333333-3333-4333-8333-000000000001', 'فضائل الأعمال', array['السنن الرواتب']::text[], false, 'published'),
  ('e383b7a5-90a0-40e5-9658-8baf124ed9c9', 'bukhari', 'إِذَا قَالَ أَحَدُكُمْ آمِينَ، وَقَالَتِ الْمَلَائِكَةُ فِي السَّمَاءِ آمِينَ، فَوَافَقَتْ إِحْدَاهُمَا الْأُخْرَى، غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ.', 'أبي هريرة رضي الله عنه', 'كتاب الأذان', 781, 1, 156, '33333333-3333-4333-8333-000000000001', 'فضائل الأعمال', '{}', false, 'published'),
  ('0693dbc9-1694-45ec-9858-7e388b834bde', 'bukhari', 'بَيْنَا أَنَا نَائِمٌ، أُتِيتُ بِقَدَحِ لَبَنٍ، فَشَرِبْتُ حَتَّى أَنِّي لَأَرَى الرِّيَّ يَخْرُجُ فِي أَظْفَارِي، ثُمَّ أَعْطَيْتُ فَضْلِي عُمَرَ بْنَ الْخَطَّابِ. قَالُوا: فَمَا أَوَّلْتَهُ يَا رَسُولَ اللهِ؟ قَالَ: الْعِلْمَ.', 'ابن عمر رضي الله عنه', 'كتاب العلم', 82, 1, 27, '33333333-3333-4333-8333-000000000001', 'فضائل الأعمال', '{}', false, 'published'),
  ('6f122b0f-1f53-4d74-886b-f5d874faaf49', 'bukhari', 'أَرَأَيْتُمْ لَوْ أَنَّ نَهَرًا بِبَابِ أَحَدِكُمْ، يَغْتَسِلُ فِيهِ كُلَّ يَوْمٍ خَمْسًا، مَا تَقُولُ: ذَلِكَ يُبْقِي مِنْ دَرَنِهِ. قَالُوا: لَا يُبْقِي مِنْ دَرَنِهِ شَيْئًا، قَالَ: فَذَلِكَ مِثْلُ الصَّلَوَاتِ الْخَمْسِ، يَمْحُو اللهُ بِهِ الْخَطَايَا.', null, 'كتاب مواقيت الصلاة', 528, 1, 112, '33333333-3333-4333-8333-000000000001', 'فضائل الأعمال', '{}', false, 'published'),
  ('dd2b0c41-6270-4f45-96af-fdc5e784dcce', 'bukhari', 'يَتَعَاقَبُونَ فِيكُمْ مَلَائِكَةٌ بِاللَّيْلِ وَمَلَائِكَةٌ بِالنَّهَارِ، وَيَجْتَمِعُونَ فِي صَلَاةِ الْفَجْرِ وَصَلَاةِ الْعَصْرِ، ثُمَّ يَعْرُجُ الَّذِينَ بَاتُوا فِيكُمْ، فَيَسْأَلُهُمْ وَهُوَ أَعْلَمُ بِهِمْ: كَيْفَ تَرَكْتُمْ عِبَادِي؟ فَيَقُولُونَ: تَرَكْنَاهُمْ وَهُمْ يُصَلُّونَ، وَأَتَيْنَاهُمْ وَهُمْ يُصَلُّونَ.', 'أبي هريرة رضي الله عنه', 'كتاب مواقيت الصلاة', 555, 1, 115, '33333333-3333-4333-8333-000000000001', 'فضائل الأعمال', '{}', false, 'published'),
  ('f8fb1845-5ff8-41e8-9053-4d7ff186fe7e', 'bukhari', 'أَنَا وَكَافِلُ الْيَتِيمِ فِي الْجَنَّةِ هَكَذَا وَقَالَ بِإِصْبَعَيْهِ السَّبَّابَةِ وَالْوُسْطَى.', 'سهل بن سعد رضي الله عنه', 'كتاب الأدب', 6005, 8, 9, '33333333-3333-4333-8333-000000000001', 'فضائل الأعمال', '{}', false, 'published'),
  ('7da316cd-21a7-4eba-909e-4a4bcb88b456', 'bukhari', 'مَنْ قَامَ رَمَضَانَ إِيمَانًا وَاحْتِسَابًا، غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ، قَالَ ابْنُ شِهَابٍ: فَتُوُفِّيَ رَسُولُ اللهِ وَالْأَمْرُ عَلَى ذَلِكَ، ثُمَّ كَانَ الْأَمْرُ عَلَى ذَلِكَ فِي خِلَافَةِ أَبِي بَكْرٍ، وَصَدْرًا مِنْ خِلَافَةِ عُمَرَ.', 'أبي هريرة رضي الله عنه', 'كتاب صلاة التراويح', 2009, 3, 44, '33333333-3333-4333-8333-000000000001', 'فضائل الأعمال', '{}', false, 'published'),
  ('a5da9092-7b64-4e4d-98b0-c648738a8a34', 'bukhari', 'مَنْ صَامَ يَوْمًا فِي سَبِيلِ اللهِ بَعَّدَ اللهُ وَجْهَهُ عَنِ النَّارِ سَبْعِينَ خَرِيفًا.', 'أبي سعيد رضي الله عنه', 'كتاب الجهاد والسير', 2840, 4, 26, '33333333-3333-4333-8333-000000000001', 'فضائل الأعمال', '{}', false, 'published'),
  ('f2023bde-fabc-4e53-833a-69bbe7b475db', 'bukhari', 'مَنْ أَنْفَقَ زَوْجَيْنِ فِي سَبِيلِ اللهِ دَعَاهُ خَزَنَةُ الْجَنَّةِ كُلُّ خَزَنَةِ بَابٍ: أَيْ فُلُْ هَلُمَّ. قَالَ أَبُو بَكْرٍ: يَا رَسُولَ اللهِ ذَاكَ الَّذِي لَا تَوَى عَلَيْهِ فَقَالَ النَّبِيُّ: إِنِّي لَأَرْجُو أَنْ تَكُونَ مِنْهُمْ.', 'أبي هريرة رضي الله عنه', 'كتاب الجهاد والسير', 2841, 4, 26, '33333333-3333-4333-8333-000000000001', 'فضائل الأعمال', '{}', false, 'published'),
  ('831d196a-52a9-4579-9324-da789286d7cc', 'bukhari', 'مَنْ جَهَّزَ غَازِيًا فِي سَبِيلِ اللهِ فَقَدْ غَزَا وَمَنْ خَلَفَ غَازِيًا فِي سَبِيلِ اللهِ بِخَيْرٍ فَقَدْ غَزَا.', 'زيد بن خالد رضي الله عنه', 'كتاب الجهاد والسير', 2843, 4, 27, '33333333-3333-4333-8333-000000000001', 'فضائل الأعمال', '{}', false, 'published'),
  ('2644cbae-b083-478b-8a60-e21c6e435772', 'bukhari', 'إِذَا قَالَ الْإِمَامُ: سَمِعَ اللهُ لِمَنْ حَمِدَهُ، فَقُولُوا: اللَّهُمَّ رَبَّنَا لَكَ الْحَمْدُ، فَإِنَّهُ مَنْ وَافَقَ قَوْلُهُ قَوْلَ الْمَلَائِكَةِ، غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ.', 'أبي هريرة رضي الله عنه', 'كتاب الأذان', 796, 1, 158, '33333333-3333-4333-8333-000000000001', 'فضائل الأعمال', '{}', false, 'published'),
  ('0d917609-8562-4f74-b3ca-84f3b92a7e7e', 'bukhari', 'مَا بَيْنَ بَيْتِي وَمِنْبَرِي رَوْضَةٌ مِنْ رِيَاضِ الْجَنَّةِ.', 'عبد الله بن زيد المازني رضي الله عنه', 'كتاب فضل الصلاة في مسجد مكة والمدينة', 1195, 2, 61, '33333333-3333-4333-8333-000000000001', 'فضائل الأعمال', '{}', false, 'published')
insert into public.duas (id, text, narrator, collection, number, volume, page, source_id, source_url, tags, needs_reference_check, sort_order, status) values
  ('b8d7159a-388d-4cb9-96f7-2efd7081db60', 'اللَّهُمَّ رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً، وَفِي الآخِرَةِ حَسَنَةً، وَقِنَا عَذَابَ النَّارِ', 'أنس رضي الله عنه', 'صحيح البخاري', 6389, 8, 83, '33333333-3333-4333-8333-000000000001', 'https://app.turath.io/book/1681/9587', '{}', false, 1, 'published'),
  ('5d706ef1-1bdb-4e3d-9612-51f0c1b581b8', 'لَا إِلَهَ إِلَّا أَنْتَ سُبْحَانَكَ إِنِّي كُنْتُ مِنَ الظَّالِمِينَ', 'سعد بن أبي وقاص رضي الله عنه', 'صحيح الترغيب', 1644, null, null, '33333333-3333-4333-8333-000000000001', null, '{}', false, 2, 'published'),
  ('198f9065-afe5-4701-aff7-deca997894f7', 'اللَّهُمَّ اغْفِرْ لِي، وَارْحَمْنِي، وَعَافِنِي، وَارْزُقْنِي', 'أبو مالك الأشجعي رضي الله عنه', 'صحيح مسلم', 2697, 4, 2073, '33333333-3333-4333-8333-000000000001', 'https://app.turath.io/book/1727/6785', '{}', false, 3, 'published'),
  ('4bee7ca5-6e27-4f5e-afdf-d29cbd01b599', 'اللَّهُمَّ أَعِنَّا عَلَى شُكْرِكَ، وَذِكْرِكَ، وَحُسْنِ عِبَادَتِكَ', 'أبو هريرة رضي الله عنه', 'السلسلة الصحيحة', 844, null, null, '33333333-3333-4333-8333-000000000001', null, '{}', false, 4, 'published'),
  ('43b19d87-657b-43a2-9a2d-153c8d6065eb', 'اللَّهُمَّ إِنِّي أَسْأَلُكَ المُعَافَاةَ فِي الدُّنْيَا وَالآخِرَةِ', 'أبو هريرة رضي الله عنه', 'صحيح الجامع', 5703, null, null, '33333333-3333-4333-8333-000000000001', null, '{}', false, 5, 'published'),
  ('abd4deaf-882c-4237-8fd0-d65d0dd76f4e', 'اللَّهُمَّ أَصْلِحْ لِي دِينِي الَّذِي هُوَ عِصْمَةُ أَمْرِي، وَأَصْلِحْ لِي دُنْيَايَ الَّتِي فِيهَا مَعَاشِي، وَأَصْلِحْ لِي آخِرَتِي الَّتِي فِيهَا مَعَادِي، وَاجْعَلِ الحَيَاةَ زِيَادَةً لِي فِي كُلِّ خَيْرٍ، وَاجْعَلِ المَوْتَ رَاحَةً لِي مِنْ كُلِّ شَرٍّ', 'أبو هريرة رضي الله عنه', 'صحيح مسلم', 2720, 4, 2087, '33333333-3333-4333-8333-000000000001', 'https://app.turath.io/book/1727/6837', '{}', false, 6, 'published'),
  ('95514938-22a1-4617-96ef-620404f5f6b6', 'اللَّهُمَّ إِنِّي أَسْأَلُكَ الهُدَى، وَالتُّقَى، وَالعَفَافَ، وَالغِنَى', 'عبد الله بن مسعود رضي الله عنه', 'صحيح مسلم', 2721, 4, 2087, '33333333-3333-4333-8333-000000000001', 'https://app.turath.io/book/1727/6838', '{}', false, 7, 'published'),
  ('126c0a93-1bd5-46bc-a9d8-f3b6f0a53391', 'يَا مُقَلِّبَ القُلُوبِ ثَبِّتْ قَلْبِي عَلَى دِينِكَ', 'أم سلمة رضي الله عنه', 'السلسلة الصحيحة', 2091, null, null, '33333333-3333-4333-8333-000000000001', null, '{}', false, 8, 'published'),
  ('87ea05a1-8a37-4783-959c-b50338ffe020', 'اللَّهُمَّ مُصَرِّفَ القُلُوبِ صَرِّفْ قُلُوبَنَا عَلَى طَاعَتِكَ', 'عبد الله بن عمرو رضي الله عنه', 'صحيح مسلم', 2654, 4, 2045, '33333333-3333-4333-8333-000000000001', 'https://app.turath.io/book/1727/6685', '{}', false, 9, 'published'),
  ('628f4b71-2bf9-4481-ba2d-325569b8163c', 'اللَّهُمَّ اهْدِنِي وَسَدِّدْنِي', 'علي رضي الله عنه', 'صحيح مسلم', 2725, 4, 2090, '33333333-3333-4333-8333-000000000001', 'https://app.turath.io/book/1727/6845', '{}', false, 10, 'published'),
  ('dd0ac2ec-3995-4c2c-a15d-172a84bb712b', 'اللَّهُمَّ إِنَّكَ عَفُوٌّ تُحِبُّ العَفْوَ فَاعْفُ عَنِّي', 'عائشة رضي الله عنه', 'صحيح ابن ماجه', 3119, null, null, '33333333-3333-4333-8333-000000000001', null, '{}', false, 11, 'published'),
  ('be8626d2-5091-49bd-89fa-cd94d405f192', 'اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ فَضْلِكَ وَرَحْمَتِكَ، فَإِنَّهُ لَا يَمْلِكُهَا إِلَّا أَنْتَ', 'عبد الله بن مسعود رضي الله عنه', 'السلسلة الصحيحة', 1543, null, null, '33333333-3333-4333-8333-000000000001', null, '{}', false, 12, 'published'),
  ('fb3ef276-5f80-403c-a0cb-72cc8c6f6c36', 'اللَّهُمَّ اكْفِنِي بِحَلَالِكَ عَنْ حَرَامِكَ، وَأَغْنِنِي بِفَضْلِكَ عَمَّنْ سِوَاكَ', 'علي رضي الله عنه', 'صحيح الجامع', 2625, null, null, '33333333-3333-4333-8333-000000000001', null, '{}', false, 13, 'published'),
  ('d2a9fee2-a22f-4db9-b605-264e75313b2b', 'اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ مُنْكَرَاتِ الأَخْلَاقِ وَالأَعْمَالِ وَالأَهْوَاءِ', 'قطبة بن مالك رضي الله عنه', 'صحيح الترمذي', 3591, null, null, '33333333-3333-4333-8333-000000000001', null, '{}', false, 14, 'published'),
  ('af12b4ca-25e4-4c37-a519-41197e5a9c9a', 'اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ البَرَصِ وَالجُنُونِ وَالجُذَامِ، وَمِنْ سَيِّئِ الأَسْقَامِ', 'أنس بن مالك رضي الله عنه', 'صحيح الجامع', 1281, null, null, '33333333-3333-4333-8333-000000000001', null, '{}', false, 15, 'published'),
  ('d4857131-67e5-4052-be26-41b165821da2', 'اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ جَارِ السُّوءِ فِي دَارِ المُقَامَةِ، فَإِنَّ جَارَ البَادِيَةِ يَتَحَوَّلُ', 'أبو هريرة رضي الله عنه', 'صحيح الجامع', 1290, null, null, '33333333-3333-4333-8333-000000000001', null, '{}', false, 16, 'published'),
  ('2905c606-1931-4e86-bd8c-53a7e353aade', 'اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ القِلَّةِ وَالفَقْرِ وَالذِّلَّةِ، وَأَعُوذُ بِكَ أَنْ أَظْلِمَ أَوْ أُظْلَمَ', 'أبو هريرة رضي الله عنه', 'صحيح النسائي', 5477, null, null, '33333333-3333-4333-8333-000000000001', null, '{}', false, 17, 'published'),
  ('2ba8926e-d7a3-48d2-b411-7e75f85217bf', 'اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنَ الخَيْرِ كُلِّهِ عَاجِلِهِ وَآجِلِهِ مَا عَلِمْتُ مِنْهُ وَمَا لَمْ أَعْلَمْ، وَأَعُوذُ بِكَ مِنَ الشَّرِّ كُلِّهِ عَاجِلِهِ وَآجِلِهِ مَا عَلِمْتُ مِنْهُ وَمَا لَمْ أَعْلَمْ، اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ خَيْرِ مَا سَأَلَكَ مِنْهُ عَبْدُكَ وَنَبِيُّكَ، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا عَاذَ بِهِ عَبْدُكَ وَنَبِيُّكَ، اللَّهُمَّ إِنِّي أَسْأَلُكَ الجَنَّةَ وَمَا قَرَّبَ إِلَيْهَا مِنْ قَوْلٍ أَوْ عَمَلٍ، وَأَعُوذُ بِكَ مِنَ النَّارِ وَمَا قَرَّبَ إِلَيْهَا مِنْ قَوْلٍ أَوْ عَمَلٍ، وَأَسْأَلُكَ أَنْ تَجْعَلَ كُلَّ قَضَاءٍ قَضَيْتَهُ لِي خَيْرًا', 'عائشة رضي الله عنه', 'السلسلة الصحيحة', 1542, null, null, '33333333-3333-4333-8333-000000000001', null, '{}', false, 18, 'published'),
  ('b2af4508-aae9-497e-808e-69d87c921915', 'اللَّهُمَّ إِنِّي أَسْأَلُكَ الثَّبَاتَ فِي الأَمْرِ، وَالعَزِيمَةَ عَلَى الرُّشْدِ، وَأَسْأَلُكَ مُوجِبَاتِ رَحْمَتِكَ، وَعَزَائِمَ مَغْفِرَتِكَ، وَأَسْأَلُكَ شُكْرَ نِعْمَتِكَ، وَحُسْنَ عِبَادَتِكَ، وَأَسْأَلُكَ قَلْبًا سَلِيمًا، وَلِسَانًا صَادِقًا، وَأَسْأَلُكَ مِنْ خَيْرِ مَا تَعْلَمُ، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا تَعْلَمُ، وَأَسْتَغْفِرُكَ لِمَا تَعْلَمُ؛ إِنَّكَ أَنْتَ عَلَّامُ الغُيُوبِ', 'شداد بن أوس رضي الله عنه', 'السلسلة الصحيحة', 3228, null, null, '33333333-3333-4333-8333-000000000001', null, '{}', false, 19, 'published'),
  ('655be48a-241d-4337-942f-47a639b7bb4b', 'اللَّهُمَّ اقْسِمْ لَنَا مِنْ خَشْيَتِكَ مَا يَحُولُ بَيْنَنَا وَبَيْنَ مَعَاصِيكَ، وَمِنْ طَاعَتِكَ مَا تُبَلِّغُنَا بِهِ جَنَّتَكَ، وَمِنَ اليَقِينِ مَا تُهَوِّنُ بِهِ عَلَيْنَا مُصِيبَاتِ الدُّنْيَا، وَمَتِّعْنَا بِأَسْمَاعِنَا وَأَبْصَارِنَا وَقُوَّتِنَا مَا أَحْيَيْتَنَا، وَاجْعَلْهُ الوَارِثَ مِنَّا، وَاجْعَلْ ثَأْرَنَا عَلَى مَنْ ظَلَمَنَا، وَانْصُرْنَا عَلَى مَنْ عَادَانَا، وَلَا تَجْعَلْ مُصِيبَتَنَا فِي دِينِنَا، وَلَا تَجْعَلِ الدُّنْيَا أَكْبَرَ هَمِّنَا وَلَا مَبْلَغَ عِلْمِنَا، وَلَا تُسَلِّطْ عَلَيْنَا مَنْ لَا يَرْحَمُنَا', 'عبد الله بن عمر رضي الله عنه', 'صحيح الترمذي', 3502, null, null, '33333333-3333-4333-8333-000000000001', null, '{}', false, 20, 'published'),
  ('189c1d5b-1cbe-4306-ae3e-840d746b3d9c', 'اللَّهُمَّ احْفَظْنِي بِالإِسْلَامِ قَائِمًا، وَاحْفَظْنِي بِالإِسْلَامِ قَاعِدًا، وَاحْفَظْنِي بِالإِسْلَامِ رَاقِدًا، وَلَا تُشْمِتْ بِي عَدُوًّا وَلَا حَاسِدًا، اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ كُلِّ خَيْرٍ خَزَائِنُهُ بِيَدِكَ، وَأَعُوذُ بِكَ مِنْ كُلِّ شَرٍّ خَزَائِنُهُ بِيَدِكَ', 'عبد الله بن مسعود رضي الله عنه', 'صحيح الجامع', 1260, null, null, '33333333-3333-4333-8333-000000000001', null, '{}', false, 21, 'published'),
  ('b7e90b97-78f2-4843-b890-543a97aafbb6', 'اللَّهُمَّ بِعِلْمِكَ الغَيْبَ وَقُدْرَتِكَ عَلَى الخَلْقِ، أَحْيِنِي مَا عَلِمْتَ الحَيَاةَ خَيْرًا لِي، وَتَوَفَّنِي إِذَا عَلِمْتَ الوَفَاةَ خَيْرًا لِي، اللَّهُمَّ إِنِّي أَسْأَلُكَ خَشْيَتَكَ فِي الغَيْبِ وَالشَّهَادَةِ، وَأَسْأَلُكَ كَلِمَةَ الحَقِّ فِي الرِّضَا وَالغَضَبِ، وَأَسْأَلُكَ القَصْدَ فِي الفَقْرِ وَالغِنَى، وَأَسْأَلُكَ نَعِيمًا لَا يَنْفَدُ، وَأَسْأَلُكَ قُرَّةَ عَيْنٍ لَا تَنْقَطِعُ، وَأَسْأَلُكَ الرِّضَى بَعْدَ القَضَاءِ، وَأَسْأَلُكَ بَرْدَ العَيْشِ بَعْدَ المَوْتِ، وَأَسْأَلُكَ لَذَّةَ النَّظَرِ إِلَى وَجْهِكَ، وَالشَّوْقَ إِلَى لِقَائِكَ فِي غَيْرِ ضَرَّاءَ مُضِرَّةٍ، وَلَا فِتْنَةٍ مُضِلَّةٍ، اللَّهُمَّ زَيِّنَّا بِزِينَةِ الإِيمَانِ، وَاجْعَلْنَا هُدَاةً مُهْتَدِينَ', 'عمار بن ياسر رضي الله عنه', 'صحيح الكلم الطيب', 106, null, null, '33333333-3333-4333-8333-000000000001', null, '{}', false, 22, 'published'),
  ('ba6985c7-c8fa-4d05-baa3-e34d4e4a405f', 'رَبِّ أَعِنِّي وَلَا تُعِنْ عَلَيَّ، وَانْصُرْنِي وَلَا تَنْصُرْ عَلَيَّ، وَامْكُرْ لِي وَلَا تَمْكُرْ عَلَيَّ، وَاهْدِنِي وَيَسِّرِ الهُدَى لِي، وَانْصُرْنِي عَلَى مَنْ بَغَى عَلَيَّ، رَبِّ اجْعَلْنِي لَكَ شَكَّارًا، لَكَ ذَكَّارًا، لَكَ رَهَّابًا، لَكَ مِطْوَاعًا، لَكَ مُخْبِتًا، إِلَيْكَ أَوَّاهًا مُنِيبًا، رَبِّ تَقَبَّلْ تَوْبَتِي، وَاغْسِلْ حَوْبَتِي، وَأَجِبْ دَعْوَتِي، وَثَبِّتْ حُجَّتِي، وَسَدِّدْ لِسَانِي، وَاهْدِ قَلْبِي، وَاسْلُلْ سَخِيمَةَ صَدْرِي', 'عبد الله بن عباس رضي الله عنه', 'صحيح الترمذي', 3551, null, null, '33333333-3333-4333-8333-000000000001', null, '{}', false, 23, 'published'),
  ('fc1876bd-d89e-4c8a-8647-d79bbf01cecb', 'اللَّهُمَّ حَاسِبْنِي حِسَابًا يَسِيرًا', 'عائشة رضي الله عنه', 'تخريج مشكاة المصابيح', 5495, null, null, '33333333-3333-4333-8333-000000000001', null, '{}', false, 24, 'published'),
  ('1a07f0b7-a14a-4af6-b3da-2ae0fe0355e1', 'اللَّهُمَّ إِنِّي أَسْأَلُكَ فِعْلَ الخَيْرَاتِ، وَتَرْكَ المُنْكَرَاتِ، وَحُبَّ المَسَاكِينِ، وَإِذَا أَرَدْتَ بِعِبَادِكَ فِتْنَةً فَاقْبِضْنِي إِلَيْكَ غَيْرَ مَفْتُونٍ', 'عبد الله بن عباس رضي الله عنه', 'صحيح الترمذي', 3233, null, null, '33333333-3333-4333-8333-000000000001', null, '{}', false, 25, 'published'),
  ('a8056033-719f-45ea-8f62-b313b0a1e755', 'اللَّهُمَّ إِنِّي عَبْدُكَ، وَابْنُ عَبْدِكَ، وَابْنُ أَمَتِكَ، نَاصِيَتِي بِيَدِكَ، مَاضٍ فِيَّ حُكْمُكَ، عَدْلٌ فِيَّ قَضَاؤُكَ، أَسْأَلُكَ بِكُلِّ اسْمٍ هُوَ لَكَ سَمَّيْتَ بِهِ نَفْسَكَ، أَوْ عَلَّمْتَهُ أَحَدًا مِنْ خَلْقِكَ، أَوْ أَنْزَلْتَهُ فِي كِتَابِكَ، أَوِ اسْتَأْثَرْتَ بِهِ فِي عِلْمِ الغَيْبِ عِنْدَكَ، أَنْ تَجْعَلَ القُرْآنَ رَبِيعَ قَلْبِي، وَنُورَ صَدْرِي، وَجَلَاءَ حُزْنِي، وَذَهَابَ هَمِّي', 'عبد الله بن مسعود رضي الله عنه', 'السلسلة الصحيحة', 199, null, null, '33333333-3333-4333-8333-000000000001', null, '{}', false, 26, 'published'),
  ('7c30d9c3-2c7e-4547-8896-688591fd90f6', 'اللَّهُمَّ مَالِكَ المُلْكِ تُؤْتِي المُلْكَ مَنْ تَشَاءُ، وَتَنْزِعُ المُلْكَ مِمَّنْ تَشَاءُ، وَتُعِزُّ مَنْ تَشَاءُ، وَتُذِلُّ مَنْ تَشَاءُ، بِيَدِكَ الخَيْرُ إِنَّكَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، رَحْمَنَ الدُّنْيَا وَالآخِرَةِ وَرَحِيمَهُمَا، تُعْطِيهِمَا مَنْ تَشَاءُ، وَتَمْنَعُ مِنْهُمَا مَنْ تَشَاءُ، ارْحَمْنِي رَحْمَةً تُغْنِينِي بِهَا عَنْ رَحْمَةِ مَنْ سِوَاكَ', 'أنس بن مالك رضي الله عنه', 'صحيح الترغيب', 1821, null, null, '33333333-3333-4333-8333-000000000001', null, '{}', false, 27, 'published'),
  ('db99b3ea-c7e9-45f8-9139-18bb3ed73fe0', 'اللَّهُمَّ رَبَّ السَّمَوَاتِ السَّبْعِ، وَرَبَّ العَرْشِ العَظِيمِ، رَبَّنَا وَرَبَّ كُلِّ شَيْءٍ، مُنْزِلَ التَّوْرَاةِ وَالإِنْجِيلِ وَالقُرْآنِ، فَالِقَ الحَبِّ وَالنَّوَى، أَعُوذُ بِكَ مِنْ شَرِّ كُلِّ شَيْءٍ أَنْتَ آخِذٌ بِنَاصِيَتِهِ، أَنْتَ الأَوَّلُ فَلَيْسَ قَبْلَكَ شَيْءٌ، وَأَنْتَ الآخِرُ فَلَيْسَ بَعْدَكَ شَيْءٌ، وَأَنْتَ الظَّاهِرُ فَلَيْسَ فَوْقَكَ شَيْءٌ، وَأَنْتَ البَاطِنُ فَلَيْسَ دُونَكَ شَيْءٌ، اقْضِ عَنِّي الدَّيْنَ، وَأَغْنِنِي مِنَ الفَقْرِ', 'أبو هريرة رضي الله عنه', 'صحيح الترمذي', 3481, null, null, '33333333-3333-4333-8333-000000000001', null, '{}', false, 28, 'published'),
  ('fc8c737f-0ec3-4f77-8b55-15fbe36c30cb', 'اللَّهُمَّ إِنِّي أَسْأَلُكَ إِيمَانًا لَا يَرْتَدُّ، وَنَعِيمًا لَا يَنْفَدُ، وَمُرَافَقَةَ مُحَمَّدٍ فِي أَعْلَى جَنَّةِ الخُلْدِ', 'عبد الله بن مسعود رضي الله عنه', 'السلسلة الصحيحة', null, 5, 379, '33333333-3333-4333-8333-000000000001', null, '{}', false, 29, 'published'),
  ('be2baf57-7de4-45c1-b949-6fa5d559c3ac', 'اللَّهُمَّ انْفَعْنِي بِمَا عَلَّمْتَنِي، وَعَلِّمْنِي مَا يَنْفَعُنِي، وَارْزُقْنِي عِلْمًا تَنْفَعُنِي بِهِ', 'أنس بن مالك رضي الله عنه', 'السلسلة الصحيحة', 3151, null, null, '33333333-3333-4333-8333-000000000001', null, '{}', false, 30, 'published'),
  ('3a515dd1-d2d7-4440-97dd-a68f2c178153', 'اللَّهُمَّ اجْعَلْ فِي قَلْبِي نُورًا، وَفِي بَصَرِي نُورًا، وَفِي سَمْعِي نُورًا، وَعَنْ يَمِينِي نُورًا، وَعَنْ يَسَارِي نُورًا، وَفَوْقِي نُورًا، وَتَحْتِي نُورًا، وَأَمَامِي نُورًا، وَخَلْفِي نُورًا، وَاجْعَلْ لِي نُورًا', 'عبد الله بن عباس رضي الله عنه', 'صحيح البخاري', 6316, 8, 69, '33333333-3333-4333-8333-000000000001', 'https://app.turath.io/book/1681/9470', '{}', false, 31, 'published'),
  ('bbc49644-711f-47d1-9e68-ed640c9395cb', 'اللَّهُمَّ أَحْيِنِي مِسْكِينًا، وَأَمِتْنِي مِسْكِينًا، وَاحْشُرْنِي فِي زُمْرَةِ المَسَاكِينِ يَوْمَ القِيَامَةِ', 'أنس بن مالك رضي الله عنه', 'صحيح الترمذي', 2352, null, null, '33333333-3333-4333-8333-000000000001', null, '{}', false, 32, 'published'),
  ('4fffb4cd-6d99-4a57-bea1-6fcbcba0ec50', 'اللَّهُمَّ اسْتُرْ عَوْرَتِي، وَآمِنْ رَوْعَتِي، وَاقْضِ عَنِّي دَيْنِي', 'خباب بن الأرت رضي الله عنه', 'صحيح الجامع', 1262, null, null, '33333333-3333-4333-8333-000000000001', null, '{}', false, 33, 'published'),
  ('2533b1ef-1836-4a02-9ac9-2b7dfa0e8cec', 'اللَّهُمَّ إِنِّي ظَلَمْتُ نَفْسِي ظُلْمًا كَثِيرًا، وَلَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ، فَاغْفِرْ لِي مَغْفِرَةً مِنْ عِنْدِكَ، وَارْحَمْنِي إِنَّكَ أَنْتَ الغَفُورُ الرَّحِيمُ', 'أبو بكر الصديق رضي الله عنه', 'صحيح البخاري', 834, 1, 166, '33333333-3333-4333-8333-000000000001', 'https://app.turath.io/book/1681/1370', '{}', false, 34, 'published'),
  ('bb65b16f-1e04-4ffa-bb05-2d44d9fea637', 'اللَّهُمَّ أَنْتَ رَبِّي، لَا إِلَهَ إِلَّا أَنْتَ، خَلَقْتَنِي وَأَنَا عَبْدُكَ، وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ، أَعُوذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ، أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ، وَأَبُوءُ لَكَ بِذَنْبِي، فَاغْفِرْ لِي، فَإِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ', 'شداد بن أوس رضي الله عنه', 'صحيح البخاري', 6306, 8, 67, '33333333-3333-4333-8333-000000000001', 'https://app.turath.io/book/1681/9452', '{}', false, 35, 'published'),
  ('3c51f9a2-17d0-4adc-a700-85e849ee3a80', 'أَسْتَغْفِرُ اللهَ الَّذِي لَا إِلَهَ إِلَّا هُوَ الحَيُّ القَيُّومُ وَأَتُوبُ إِلَيْهِ', 'عبد الله بن مسعود رضي الله عنه', 'صحيح الترغيب', 1623, null, null, '33333333-3333-4333-8333-000000000001', null, '{}', false, 36, 'published'),
  ('6d7a79b7-38f2-42a6-82c6-fe5fa6045363', 'رَبِّ اغْفِرْ لِي خَطِيئَتِي وَجَهْلِي، وَإِسْرَافِي فِي أَمْرِي كُلِّهِ، وَمَا أَنْتَ أَعْلَمُ بِهِ مِنِّي، اللَّهُمَّ اغْفِرْ لِي خَطَايَايَ وَعَمْدِي وَجَهْلِي وَهَزْلِي، وَكُلُّ ذَلِكَ عِنْدِي، اللَّهُمَّ اغْفِرْ لِي مَا قَدَّمْتُ وَمَا أَخَّرْتُ، وَمَا أَسْرَرْتُ وَمَا أَعْلَنْتُ، أَنْتَ المُقَدِّمُ وَأَنْتَ المُؤَخِّرُ، وَأَنْتَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ', 'أبو موسى الأشعري رضي الله عنه', 'صحيح البخاري', 6398, 8, 84, '33333333-3333-4333-8333-000000000001', 'https://app.turath.io/book/1681/9601', '{}', false, 37, 'published'),
  ('6125c2f8-a58e-4553-92aa-81dcf664b5f2', 'اللَّهُمَّ اغْفِرْ لِي ذُنُوبِي وَخَطَايَايَ كُلَّهَا، اللَّهُمَّ أَنْعِشْنِي وَاجْبُرْنِي، وَاهْدِنِي لِصَالِحِ الأَعْمَالِ وَالأَخْلَاقِ؛ فَإِنَّهُ لَا يَهْدِي لِصَالِحِهَا وَلَا يَصْرِفُ سَيِّئَهَا إِلَّا أَنْتَ', 'أبو أمامة الباهلي رضي الله عنه', 'صحيح الجامع', 1266, null, null, '33333333-3333-4333-8333-000000000001', null, '{}', false, 38, 'published'),
  ('219d11a7-0bb5-4c97-b1da-f3f18808ab78', 'اللَّهُمَّ لَكَ أَسْلَمْتُ، وَبِكَ آمَنْتُ، وَعَلَيْكَ تَوَكَّلْتُ، وَإِلَيْكَ أَنَبْتُ، وَبِكَ خَاصَمْتُ، اللَّهُمَّ إِنِّي أَعُوذُ بِعِزَّتِكَ، لَا إِلَهَ إِلَّا أَنْتَ؛ أَلَّا تُضِلَّنِي، أَنْتَ الحَيُّ الَّذِي لَا يَمُوتُ، وَالجِنُّ وَالإِنْسُ يَمُوتُونَ', 'عبد الله بن عباس رضي الله عنه', 'صحيح الجامع', 1309, null, null, '33333333-3333-4333-8333-000000000001', null, '{}', false, 39, 'published'),
  ('ac0396f2-567d-47cb-8544-5ff835881dd2', 'اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ جَهْدِ البَلَاءِ، وَدَرَكِ الشَّقَاءِ، وَسُوءِ القَضَاءِ، وَشَمَاتَةِ الأَعْدَاءِ', 'أبو هريرة رضي الله عنه', 'صحيح البخاري', 6347, 8, 75, '33333333-3333-4333-8333-000000000001', 'https://app.turath.io/book/1681/9519', '{}', false, 40, 'published'),
  ('8e4ce646-65c6-485d-a853-16c7439cd7a3', 'اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الهَمِّ وَالحَزَنِ، وَالعَجْزِ وَالكَسَلِ، وَالبُخْلِ وَالجُبْنِ، وَضَلَعِ الدَّيْنِ، وَغَلَبَةِ الرِّجَالِ', 'أنس رضي الله عنه', 'صحيح البخاري', 2893, 4, 35, '33333333-3333-4333-8333-000000000001', 'https://app.turath.io/book/1681/4590', '{}', false, 41, 'published'),
  ('540746be-4e2b-417d-b63a-b21cacb1e60a', 'اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ شَرِّ مَا عَمِلْتُ، وَمِنْ شَرِّ مَا لَمْ أَعْمَلْ', 'عائشة رضي الله عنه', 'صحيح مسلم', 2716, 4, 2085, '33333333-3333-4333-8333-000000000001', 'https://app.turath.io/book/1727/6829', '{}', false, 42, 'published'),
  ('c4550013-bb31-4e3c-8bda-0b047c644682', 'اللَّهُمَّ أَعُوذُ بِرِضَاكَ مِنْ سَخَطِكَ، وَبِمُعَافَاتِكَ مِنْ عُقُوبَتِكَ، وَأَعُوذُ بِكَ مِنْكَ، لَا أُحْصِي ثَنَاءً عَلَيْكَ أَنْتَ كَمَا أَثْنَيْتَ عَلَى نَفْسِكَ', 'عائشة رضي الله عنه', 'صحيح مسلم', 486, 1, 352, '33333333-3333-4333-8333-000000000001', 'https://app.turath.io/book/1727/1037', '{}', false, 43, 'published'),
  ('ca769cb6-105c-40e8-accc-a32095e87942', 'اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ زَوَالِ نِعْمَتِكَ، وَتَحَوُّلِ عَافِيَتِكَ، وَفُجَاءَةِ نِقْمَتِكَ، وَجَمِيعِ سَخَطِكَ', 'عبد الله بن عمر رضي الله عنه', 'صحيح مسلم', 2739, 4, 2097, '33333333-3333-4333-8333-000000000001', 'https://app.turath.io/book/1727/6877', '{}', false, 44, 'published'),
  ('f4e910cc-1429-42e6-8735-6225e3b009bd', 'اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ البُخْلِ، وَأَعُوذُ بِكَ مِنَ الجُبْنِ، وَأَعُوذُ بِكَ مِنْ أَنْ نُرَدَّ إِلَى أَرْذَلِ العُمُرِ، وَأَعُوذُ بِكَ مِنْ فِتْنَةِ الدُّنْيَا، وَعَذَابِ القَبْرِ', 'سعد بن أبي وقاص رضي الله عنه', 'صحيح البخاري', 6390, 8, 83, '33333333-3333-4333-8333-000000000001', 'https://app.turath.io/book/1681/9589', '{}', false, 45, 'published'),
  ('c12292a1-3b97-4397-9b71-2fae8aaa472a', 'اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ العَجْزِ، وَالكَسَلِ، وَالجُبْنِ، وَالبُخْلِ، وَالهَرَمِ، وَعَذَابِ القَبْرِ، اللَّهُمَّ آتِ نَفْسِي تَقْوَاهَا، وَزَكِّهَا أَنْتَ خَيْرُ مَنْ زَكَّاهَا، أَنْتَ وَلِيُّهَا وَمَوْلَاهَا، اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عِلْمٍ لَا يَنْفَعُ، وَمِنْ قَلْبٍ لَا يَخْشَعُ، وَمِنْ نَفْسٍ لَا تَشْبَعُ، وَمِنْ دَعْوَةٍ لَا يُسْتَجَابُ لَهَا', 'زيد بن أرقم رضي الله عنه', 'صحيح مسلم', 2722, 4, 2088, '33333333-3333-4333-8333-000000000001', 'https://app.turath.io/book/1727/6840', '{}', false, 46, 'published'),
  ('89546025-629d-49f2-bc8e-4d9904986276', 'اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ شَرِّ سَمْعِي، وَمِنْ شَرِّ بَصَرِي، وَمِنْ شَرِّ لِسَانِي، وَمِنْ شَرِّ قَلْبِي، وَمِنْ شَرِّ مَنِيِّي', 'شكل بن حميد العبسي رضي الله عنه', 'صحيح الجامع', 4399, null, null, '33333333-3333-4333-8333-000000000001', null, '{}', false, 47, 'published'),
  ('7c88ed84-81d4-4cec-9a54-9ac93b50162b', 'اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الهَدْمِ، وَأَعُوذُ بِكَ مِنَ التَّرَدِّي، وَأَعُوذُ بِكَ مِنَ الغَرَقِ وَالحَرَقِ وَالهَرَمِ، وَأَعُوذُ بِكَ أَنْ يَتَخَبَّطَنِي الشَّيْطَانُ عِنْدَ المَوْتِ، وَأَعُوذُ بِكَ أَنْ أَمُوتَ فِي سَبِيلِكَ مُدْبِرًا، وَأَعُوذُ بِكَ أَنْ أَمُوتَ لَدِيغًا', 'كعب بن عمرو رضي الله عنه', 'صحيح أبي داود', 1552, null, null, '33333333-3333-4333-8333-000000000001', null, '{}', false, 48, 'published'),
  ('274c67f1-add8-496e-906d-38c3947484c3', 'اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ فِتْنَةِ النَّارِ وَعَذَابِ النَّارِ، وَفِتْنَةِ القَبْرِ وَعَذَابِ القَبْرِ، وَشَرِّ فِتْنَةِ الغِنَى وَشَرِّ فِتْنَةِ الفَقْرِ، اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ شَرِّ فِتْنَةِ المَسِيحِ الدَّجَّالِ، اللَّهُمَّ اغْسِلْ قَلْبِي بِمَاءِ الثَّلْجِ وَالبَرَدِ، وَنَقِّ قَلْبِي مِنَ الخَطَايَا كَمَا نَقَّيْتَ الثَّوْبَ الأَبْيَضَ مِنَ الدَّنَسِ، وَبَاعِدْ بَيْنِي وَبَيْنَ خَطَايَايَ كَمَا بَاعَدْتَ بَيْنَ المَشْرِقِ وَالمَغْرِبِ، اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الكَسَلِ، وَالمَأْثَمِ وَالمَغْرَمِ', 'عائشة رضي الله عنه', 'صحيح البخاري', 6377, 8, 81, '33333333-3333-4333-8333-000000000001', 'https://app.turath.io/book/1681/9568', '{}', false, 49, 'published'),
  ('9c0c8892-0446-47f3-bb2d-1179a95261de', 'اللَّهُمَّ رَبَّ جَبْرَائِيلَ وَمِيكَائِيلَ، وَرَبَّ إِسْرَافِيلَ، أَعُوذُ بِكَ مِنْ حَرِّ النَّارِ، وَمِنْ عَذَابِ القَبْرِ', 'عائشة رضي الله عنه', 'صحيح النسائي', 5534, null, null, '33333333-3333-4333-8333-000000000001', null, '{}', false, 50, 'published')
